if _G.FVLV2Cleanup then
	_G.__FVLReloading = true
	pcall(_G.FVLV2Cleanup)
	_G.__FVLReloading = nil
end

-- ===== Anti Stealer (Inventory Shield) =====
-- Ported from the "MM2 Anti-Stealer / Inventory Shield" script. It is switched on and off by the "Anti Stealer"
-- toggle (Settings > Protection). The hooks are installed once, the first time it is switched on, and do nothing
-- while it is off. It protects you from OTHER scripts you run:
--   * trade remotes (OfferItem / AddItem / AcceptTrade / ConfirmTrade / DropItem ...) fired by a script without you
--     clicking, bursts of OfferItem (weapon dumping) and instant ConfirmTrade (the game has a 3 second timer)
--   * HTTP requests / WebSockets that leak your data: Discord & Telegram webhooks, IP loggers, the server JobId,
--     your name / UserId together with inventory words, and Base64-hidden versions of those
-- Changes from the original: calls made by the GAME itself are left alone (checkcaller), your OWN Discord webhook
-- from this script's Webhook box is always allowed, deleting a stealer's Discord webhook is a separate opt-in
-- switch (off by default), and the messages are in English.
do
	local S = _G.FVLShield

	if type(S) ~= "table" then
		S = {}
		_G.FVLShield = S
	end

	S.on = S.on or false
	S.deleteHooks = S.deleteHooks or false
	S.stats = S.stats or { trades = 0, webhooks = 0 }

	if not S.install then
		local Players = game:GetService("Players")
		local StarterGui = game:GetService("StarterGui")
		local SoundService = game:GetService("SoundService")
		local TweenService = game:GetService("TweenService")
		local UserInputService = game:GetService("UserInputService")
		local Debris = game:GetService("Debris")
		local genv = (getgenv and getgenv()) or _G

		local LocalPlayer = Players.LocalPlayer
		local playerName = LocalPlayer and LocalPlayer.Name or ""
		local userId = LocalPlayer and tostring(LocalPlayer.UserId) or ""
		local currentJobId = tostring(game.JobId)
		local lastPhysicalInputTime = 0

		local function isRecentPhysicalInput()
			return (os.clock() - lastPhysicalInputTime) <= 3.0
		end

		local function showInGameAlert(title, message, isDanger)
			task.spawn(function()
				pcall(function()
					local sound = Instance.new("Sound")

					sound.SoundId = "rbxasset://sounds/bell.wav"
					sound.Volume = 1.0
					sound.Parent = SoundService
					sound:Play()
					Debris:AddItem(sound, 3)
				end)

				pcall(function()
					StarterGui:SetCore("ChatMakeSystemMessage", {
						Text = string.format("[Anti-Stealer]: %s - %s", tostring(title), tostring(message)),
						Color = isDanger and Color3.fromRGB(255, 75, 75) or Color3.fromRGB(60, 230, 110),
						Font = Enum.Font.GothamBold,
						TextSize = 14,
					})
				end)

				pcall(function()
					StarterGui:SetCore("SendNotification", {
						Title = title or "Anti-Stealer",
						Text = message or "",
						Duration = 5,
					})
				end)

				pcall(function()
					local playerGui = LocalPlayer:FindFirstChild("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui", 4)

					if not playerGui then
						return
					end

					local alertGuiName = "MM2ShieldAlertHUD"
					local existing = playerGui:FindFirstChild(alertGuiName)

					if existing then
						existing:Destroy()
					end

					local screenGui = Instance.new("ScreenGui")

					screenGui.Name = alertGuiName
					screenGui.ResetOnSpawn = false
					screenGui.IgnoreGuiInset = true
					screenGui.DisplayOrder = 999999
					screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
					screenGui.Parent = playerGui

					local card = Instance.new("Frame")

					card.Name = "AlertCard"
					card.Size = UDim2.new(0, 420, 0, 80)
					card.Position = UDim2.new(0.5, -210, 0, -110)
					card.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
					card.BorderSizePixel = 0
					card.ZIndex = 1000
					card.Parent = screenGui

					local corner = Instance.new("UICorner")

					corner.CornerRadius = UDim.new(0, 10)
					corner.Parent = card

					local stroke = Instance.new("UIStroke")

					stroke.Color = isDanger and Color3.fromRGB(250, 60, 60) or Color3.fromRGB(40, 200, 95)
					stroke.Thickness = 2
					stroke.Parent = card

					local bar = Instance.new("Frame")

					bar.Size = UDim2.new(0, 6, 1, 0)
					bar.BackgroundColor3 = stroke.Color
					bar.BorderSizePixel = 0
					bar.ZIndex = 1001
					bar.Parent = card

					local barCorner = Instance.new("UICorner")

					barCorner.CornerRadius = UDim.new(0, 10)
					barCorner.Parent = bar

					local icon = Instance.new("TextLabel")

					icon.Size = UDim2.new(0, 50, 1, 0)
					icon.Position = UDim2.new(0, 6, 0, 0)
					icon.BackgroundTransparency = 1
					icon.Text = isDanger and "!" or "OK"
					icon.Font = Enum.Font.GothamBold
					icon.TextColor3 = stroke.Color
					icon.TextSize = 26
					icon.ZIndex = 1001
					icon.Parent = card

					local titleLabel = Instance.new("TextLabel")

					titleLabel.Size = UDim2.new(1, -65, 0, 22)
					titleLabel.Position = UDim2.new(0, 58, 0, 10)
					titleLabel.BackgroundTransparency = 1
					titleLabel.Font = Enum.Font.GothamBold
					titleLabel.TextSize = 14
					titleLabel.TextColor3 = stroke.Color
					titleLabel.TextXAlignment = Enum.TextXAlignment.Left
					titleLabel.Text = title or "Anti-Stealer"
					titleLabel.ZIndex = 1001
					titleLabel.Parent = card

					local descLabel = Instance.new("TextLabel")

					descLabel.Size = UDim2.new(1, -65, 0, 40)
					descLabel.Position = UDim2.new(0, 58, 0, 32)
					descLabel.BackgroundTransparency = 1
					descLabel.Font = Enum.Font.Gotham
					descLabel.TextSize = 12
					descLabel.TextColor3 = Color3.fromRGB(230, 230, 240)
					descLabel.TextWrapped = true
					descLabel.TextXAlignment = Enum.TextXAlignment.Left
					descLabel.TextYAlignment = Enum.TextYAlignment.Top
					descLabel.Text = message or "A hidden threat was blocked."
					descLabel.ZIndex = 1001
					descLabel.Parent = card

					TweenService:Create(
						card,
						TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
						{ Position = UDim2.new(0.5, -210, 0, 48) }
					):Play()

					task.delay(5.5, function()
						if card and card.Parent then
							local tweenOut = TweenService:Create(
								card,
								TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.In),
								{ Position = UDim2.new(0.5, -210, 0, -110) }
							)

							tweenOut:Play()
							tweenOut.Completed:Connect(function()
								screenGui:Destroy()
							end)
						end
					end)
				end)
			end)
		end

		S.alert = showInGameAlert

		-- ---- Base64 (native when the executor has it) ----
		local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local b64lookup = {}

		for i = 1, #b64chars do
			b64lookup[b64chars:sub(i, i)] = i - 1
		end

		local nativeB64Decode = (crypt and (crypt.base64decode or crypt.base64_decode)) or base64_decode

		local function safeBase64Decode(data)
			if type(data) ~= "string" or #data < 4 then
				return ""
			end

			if nativeB64Decode then
				local ok, res = pcall(nativeB64Decode, data)

				if ok and type(res) == "string" then
					return res
				end
			end

			local out, outIdx, i = {}, 1, 1

			while i <= #data do
				local c1 = b64lookup[data:sub(i, i)]
				local c2 = b64lookup[data:sub(i + 1, i + 1)]
				local c3 = b64lookup[data:sub(i + 2, i + 2)]
				local c4 = b64lookup[data:sub(i + 3, i + 3)]

				i = i + 4

				if c1 and c2 then
					out[outIdx] = string.char((c1 * 4) + math.floor(c2 / 16))
					outIdx = outIdx + 1

					if c3 then
						out[outIdx] = string.char(((c2 % 16) * 16) + math.floor(c3 / 4))
						outIdx = outIdx + 1

						if c4 then
							out[outIdx] = string.char(((c3 % 4) * 64) + c4)
							outIdx = outIdx + 1
						end
					end
				end
			end

			return table.concat(out)
		end

		-- ---- trade remotes ----
		local CRITICAL_INVENTORY_REMOTES = {
			"offeritem",
			"additem",
			"accepttrade",
			"confirmtrade",
			"dropitem",
			"gettradestatus",
		}

		local function isCriticalTradeRemote(instance)
			if not instance or typeof(instance) ~= "Instance" then
				return false
			end

			local className = instance.ClassName

			if className ~= "RemoteEvent" and className ~= "RemoteFunction" and className ~= "UnreliableRemoteEvent" then
				return false
			end

			local nameLower = string.lower(instance.Name)

			for i = 1, #CRITICAL_INVENTORY_REMOTES do
				if string.find(nameLower, CRITICAL_INVENTORY_REMOTES[i], 1, true) then
					return true
				end
			end

			return false
		end

		local lastOfferTime, offerCountInWindow, lastAcceptTradeTime = 0, 0, 0

		local function isAutomatedBurst(remoteInstance)
			local n = string.lower(remoteInstance.Name)

			if n == "offeritem" or n == "additem" then
				local now = os.clock()

				if (now - lastOfferTime) < 1.0 then
					offerCountInWindow = offerCountInWindow + 1

					if offerCountInWindow > 3 then
						return true
					end
				else
					lastOfferTime = now
					offerCountInWindow = 1
				end
			end

			return false
		end

		-- returns true = block this call
		local function handleTradeInterception(remoteInstance, method)
			local isHuman = isRecentPhysicalInput()
			local remoteNameLower = string.lower(remoteInstance.Name)
			local now = os.clock()

			-- MM2 has a mandatory ~3 second gap between Accept and Confirm; a human cannot confirm sooner than ~2.5 s,
			-- so an instant Confirm is a stealer bot
			if string.find(remoteNameLower, "confirmtrade", 1, true) then
				if (now - lastAcceptTradeTime) < 2.5 then
					S.stats.trades = S.stats.trades + 1
					warn(string.format("[Anti-Stealer]: Blocked an instant ConfirmTrade (%.2fs after Accept)!", now - lastAcceptTradeTime))
					showInGameAlert(
						"TRADE BOT DETECTED!",
						"A script tried to confirm a trade instantly, skipping MM2's timer. Attack blocked.",
						true
					)

					return true
				end
			end

			if string.find(remoteNameLower, "accepttrade", 1, true) then
				lastAcceptTradeTime = now
			end

			if isHuman then
				if isAutomatedBurst(remoteInstance) then
					S.stats.trades = S.stats.trades + 1
					warn("[Anti-Stealer]: Blocked an automatic weapon dump (burst)!")
					showInGameAlert(
						"TRADE BOT DETECTED!",
						"A script tried to dump your weapons quickly. Auto-withdraw stopped.",
						true
					)

					return true
				end

				return false
			end

			S.stats.trades = S.stats.trades + 1

			local remoteName = tostring(remoteInstance.Name)

			warn(string.format("[Anti-Stealer]: Blocked a hidden trade remote: %s (%s)", remoteName, method))
			showInGameAlert(
				"ATTEMPTED WEAPON THEFT!",
				"A running script secretly tried to hand your knives over through a trade (" .. remoteName .. "). Blocked.",
				true
			)

			return true
		end

		-- ---- data leaks ----
		local SAFE_DOMAINS = {
			"roblox.com",
			"roproxy.com",
			"rbxcdn.com",
			"github.com",
			"githubusercontent.com",
			"pastebin.com",
			"gitlab.com",
		}

		local function isSafeDomain(url)
			if type(url) ~= "string" then
				return false
			end

			local host = string.match(string.lower(url), "^%a+://([^/]+)") or string.match(string.lower(url), "^([^/]+)")

			if not host then
				return false
			end

			host = string.match(host, "^([^:]+)") or host

			for i = 1, #SAFE_DOMAINS do
				local safeDom = SAFE_DOMAINS[i]

				if host == safeDom or string.sub(host, -#safeDom - 1) == "." .. safeDom then
					return true
				end
			end

			return false
		end

		local MALICIOUS_TARGETS = {
			"api/webhooks",
			"discordapp.com/api",
			"discord.com/api/webhooks",
			"webhook",
			"project-reverse.org",
			"iplogger",
			"grabber",
			"2no.co",
			"blasze",
			"rip/trade",
			"inventory-logger",
			"api.telegram.org/bot",
			"webhook.site",
			"pipedream.net",
		}

		local function safeUrlDecode(str)
			if type(str) ~= "string" or not string.find(str, "%", 1, true) then
				return str
			end

			local ok, res = pcall(function()
				return string.gsub(str, "%%(%x%x)", function(hex)
					return string.char(tonumber(hex, 16))
				end)
			end)

			return (ok and res) or str
		end

		local INVENTORY_KEYWORDS = {
			"inventory",
			"godly",
			"ancient",
			"chroma",
			"vintage",
			"harvester",
			"corrupt",
			"candleflame",
			"swirly",
			"bat",
			"knife",
			"gun",
			"weapons",
			"iceflake",
			"trade",
			"potassium",
			"stealer",
		}

		local function jobIdIn(text)
			if #currentJobId <= 5 then
				return false
			end

			local lowerJobId = string.lower(currentJobId)
			local noHyphens = string.gsub(lowerJobId, "%-", "")

			return string.find(text, lowerJobId, 1, true) ~= nil
				or (#noHyphens >= 30 and string.find(text, noHyphens, 1, true) ~= nil)
		end

		local function isMaliciousExfiltration(url, rawBody)
			local lowerUrl = type(url) == "string" and string.lower(url) or ""
			local lowerBody = type(rawBody) == "string" and string.lower(rawBody) or ""
			local decodedBody = safeUrlDecode(lowerBody)
			local fullPayload = lowerUrl .. " " .. decodedBody

			-- 1. known C2 / webhook addresses
			for i = 1, #MALICIOUS_TARGETS do
				if string.find(lowerUrl, MALICIOUS_TARGETS[i], 1, true) then
					return true, "Discord / C2 webhook"
				end
			end

			-- 2. trusted domains (Roblox API, RoProxy, GitHub, CDN) are never blocked past this point
			if isSafeDomain(lowerUrl) then
				return false, nil
			end

			-- 3. the server JobId (with or without hyphens) going to a third-party host
			if jobIdIn(fullPayload) then
				return true, "Server JobId leak (C2 tracking)"
			end

			-- 4. inventory words together with your name or UserId
			if #decodedBody > 0 then
				local lowerName = string.lower(playerName)
				local hasIdentity = (lowerName ~= "" and string.find(fullPayload, lowerName, 1, true))
					or (userId ~= "" and string.find(fullPayload, userId, 1, true))

				if hasIdentity then
					for _, kw in ipairs(INVENTORY_KEYWORDS) do
						if string.find(fullPayload, kw, 1, true) then
							return true, "Inventory leak signature"
						end
					end
				end
			end

			-- 5. hidden Base64 payloads (URL and body)
			local rawCombined = (type(rawBody) == "string" and rawBody or "") .. " " .. lowerUrl

			for token in string.gmatch(rawCombined, "([A-Za-z0-9+/=]+)") do
				if #token >= 16 then
					local decoded = safeBase64Decode(token):lower()

					if #decoded > 5 then
						if jobIdIn(decoded) then
							return true, "Base64 JobId leak"
						end

						for _, kw in ipairs(INVENTORY_KEYWORDS) do
							if string.find(decoded, kw, 1, true) then
								return true, "Base64 inventory leak"
							end
						end
					end
				end
			end

			return false, nil
		end

		-- ---- Discord webhook clean-up (opt-in) ----
		local origRequest = nil
		local nukedWebhooks = {}

		local function cleanDiscordWebhookUrl(rawUrl)
			if type(rawUrl) ~= "string" then
				return nil
			end

			local unescaped = string.gsub(rawUrl, "\\/", "/")
			local domain, id, token = string.match(unescaped, "(discord[%w%.]*/api/webhooks)/(%d+)/([^%s%?\"'%&<>]+)")

			if domain and id and token and #token >= 10 then
				return "https://" .. domain .. "/" .. id .. "/" .. token
			end

			return nil
		end

		-- your own webhook (set in this script) must never be touched
		local function isOwnUrl(url)
			local own = S.ownUrl and S.ownUrl() or ""

			if type(url) ~= "string" or own == "" then
				return false
			end

			if url:sub(1, #own) == own then
				return true
			end

			local a, b = cleanDiscordWebhookUrl(url), cleanDiscordWebhookUrl(own)

			return a ~= nil and a == b
		end

		local function deleteDiscordWebhook(targetUrl, onResult)
			local cleanUrl = cleanDiscordWebhookUrl(targetUrl)

			if not cleanUrl or not origRequest or isOwnUrl(cleanUrl) then
				if onResult then
					onResult(false)
				end

				return
			end

			if nukedWebhooks[cleanUrl] then
				if onResult then
					onResult(true)
				end

				return
			end

			task.spawn(function()
				local ok, res = pcall(function()
					return origRequest({
						Url = cleanUrl,
						Method = "DELETE",
						Headers = { ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" },
					})
				end)

				local statusCode = (ok and type(res) == "table" and res.StatusCode) or 0
				local isDeleted = (statusCode == 204 or statusCode == 200 or statusCode == 404)

				if isDeleted then
					nukedWebhooks[cleanUrl] = true
					warn(string.format("[Anti-Stealer]: Stealer webhook deleted (Discord HTTP %d): %s", statusCode, cleanUrl))
				else
					warn(string.format("[Anti-Stealer]: Discord answered the webhook delete with HTTP %s: %s", tostring(statusCode), cleanUrl))
				end

				if onResult then
					onResult(isDeleted)
				end
			end)
		end

		local function findWebhooks(text)
			local found = {}

			if type(text) ~= "string" then
				return found
			end

			local unescaped = string.gsub(text, "\\/", "/")

			for hook in string.gmatch(unescaped, "https?://[^%s\"'<>]+discord[%.%w]*/api/webhooks/%d+/[^%s%?\"'%&<>]+") do
				local clean = cleanDiscordWebhookUrl(hook)

				if clean then
					found[#found + 1] = clean
				end
			end

			return found
		end

		local function safeRequest(requestData, ...)
			if S.on and type(requestData) == "table" then
				local url = requestData.Url or requestData.url or requestData.URL
				local body = requestData.Body or requestData.body or ""

				-- your own webhook (Discord Sender / farm reports) always goes through
				if not isOwnUrl(url) then
					local isMalicious, reason = isMaliciousExfiltration(url, body)

					if isMalicious then
						S.stats.webhooks = S.stats.webhooks + 1
						warn(string.format("[Anti-Stealer]: Blocked a data leak (%s): %s", tostring(reason), tostring(url)))

						local targets = {}
						local direct = cleanDiscordWebhookUrl(url)

						if direct then
							targets[1] = direct
						end

						for _, hook in ipairs(findWebhooks(body)) do
							targets[#targets + 1] = hook
						end

						if S.deleteHooks and #targets > 0 then
							deleteDiscordWebhook(targets[1], function(success)
								if success then
									showInGameAlert(
										"Stealer webhook deleted",
										"The stealer's Discord webhook was confirmed and deleted from Discord!",
										true
									)
								else
									showInGameAlert(
										"STEALER DETECTED!",
										"A script you ran tried to leak your inventory to a webhook! Attack blocked.",
										true
									)
								end
							end)

							for i = 2, #targets do
								deleteDiscordWebhook(targets[i])
							end
						else
							showInGameAlert(
								"STEALER DETECTED!",
								"A script you ran tried to leak data (" .. tostring(reason) .. ")! Attack blocked.",
								true
							)
						end

						-- the script gets a fake "success" so it does not retry or crash
						return {
							StatusCode = 200,
							StatusMessage = "OK",
							Success = true,
							Body = '{"status":"ok","message":"Protected"}',
							Headers = {
								["content-type"] = "application/json",
								["server"] = "MM2-Shield",
							},
						}
					end
				end
			end

			if origRequest then
				return origRequest(requestData, ...)
			end
		end

		-- ---- install the hooks (once) ----
		S.install = function()
			if S.installed then
				return
			end

			S.installed = true

			pcall(function()
				UserInputService.InputBegan:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						lastPhysicalInputTime = os.clock()
					end
				end)
			end)

			local hookmeta = hookmetamethod
			local getnamecall = getnamecallmethod or function()
				return ""
			end
			local newcc = newcclosure or function(f)
				return f
			end
			-- calls made by the game's own scripts are not ours to judge; only calls from the executor are
			local fromExecutor = checkcaller or function()
				return true
			end

			local oldNamecall = nil
			local namecallOk, fireServerOk, requestHooked = false, false, false

			if hookmeta then
				local ok = pcall(function()
					oldNamecall = hookmeta(game, "__namecall", newcc(function(self, ...)
						local method = getnamecall()

						if
							S.on
							and (method == "FireServer" or method == "InvokeServer" or method == "fireServer" or method == "invokeServer")
							and fromExecutor()
							and isCriticalTradeRemote(self)
						then
							if handleTradeInterception(self, method) then
								return nil
							end
						end

						return oldNamecall(self, ...)
					end))
				end)

				namecallOk = ok and (oldNamecall ~= nil)
			end

			if hookfunction then
				fireServerOk = pcall(function()
					local dummyEvent = Instance.new("RemoteEvent")
					local origFireServer = dummyEvent.FireServer

					hookfunction(origFireServer, newcc(function(self, ...)
						if S.on and typeof(self) == "Instance" and fromExecutor() and isCriticalTradeRemote(self) then
							if handleTradeInterception(self, "Direct-FireServer") then
								return nil
							end
						end

						return origFireServer(self, ...)
					end))
					dummyEvent:Destroy()
				end)
			end

			local rawReq = request or http_request

			if rawReq and hookfunction then
				local ok, hookedOrig = pcall(function()
					return hookfunction(rawReq, newcc(safeRequest))
				end)

				if ok and hookedOrig then
					origRequest = hookedOrig
					requestHooked = true
				else
					origRequest = rawReq
				end
			else
				origRequest = rawReq
			end

			local wrapped = newcc(safeRequest)

			pcall(function()
				genv.request = wrapped
				genv.http_request = wrapped
			end)

			if type(syn) == "table" and type(syn.request) == "function" and hookfunction then
				pcall(function()
					hookfunction(syn.request, wrapped)
				end)
			end

			if type(http) == "table" and type(http.request) == "function" and hookfunction then
				pcall(function()
					hookfunction(http.request, wrapped)
				end)
			end

			local rawWsConnect = (WebSocket and WebSocket.connect)
				or (type(syn) == "table" and type(syn.websocket) == "table" and syn.websocket.connect)

			if rawWsConnect and hookfunction then
				pcall(function()
					hookfunction(rawWsConnect, newcc(function(url, ...)
						if S.on then
							local lowerUrl = type(url) == "string" and string.lower(url) or ""

							for i = 1, #MALICIOUS_TARGETS do
								if string.find(lowerUrl, MALICIOUS_TARGETS[i], 1, true) and not isOwnUrl(url) then
									S.stats.webhooks = S.stats.webhooks + 1
									warn("[Anti-Stealer]: Blocked a dangerous WebSocket connection: " .. tostring(url))
									showInGameAlert(
										"STEALER DETECTED!",
										"A script tried to open a WebSocket channel to a scammer's server. Connection blocked.",
										true
									)

									return nil
								end
							end
						end

						return rawWsConnect(url, ...)
					end))
				end)
			end

			S.status = {
				namecall = namecallOk,
				fireServer = fireServerOk,
				request = requestHooked or origRequest ~= nil,
			}

			if not ((namecallOk or fireServerOk) and (requestHooked or origRequest ~= nil)) then
				warn("[Anti-Stealer]: some hooks are not supported by your executor - protection may be partial.")
				showInGameAlert("Anti-Stealer", "Your executor limited some hooks - protection may be partial.", true)
			end
		end

		pcall(function()
			genv.ShieldStats = function()
				print(string.format("[Anti-Stealer]: trades blocked: %d | leaks blocked: %d", S.stats.trades, S.stats.webhooks))
			end
		end)
	end
end

-- ===== Imported Movement features (merged from source) =====
do
	pcall(function()
		if _G.FVLImp and _G.FVLImp.cleanup then
			_G.FVLImp.cleanup()
		end
	end)

	local Imp_RS = game:GetService("RunService")
	local Imp_Players = game:GetService("Players")
	local Imp_LP = Imp_Players.LocalPlayer
	local Imp_WS = workspace

	local Imp = { conns = {} }
	_G.FVLImp = Imp

	local function Imp_track(conn)
		Imp.conns[#Imp.conns + 1] = conn
		return conn
	end

	Imp.cleanup = function()
		for _, c in ipairs(Imp.conns) do
			pcall(function()
				if c and c.Disconnect then
					c:Disconnect()
				end
			end)
		end
		Imp.conns = {}
		pcall(function()
			if Imp.sg then
				Imp.sg.setOn(false)
			end
		end)
		pcall(function()
			if Imp.grav then
				Imp.grav.setOn(false)
			end
		end)
		pcall(function()
			if Imp.hip then
				Imp.hip.setOn(false)
			end
		end)
		pcall(function()
			if Imp.orbit then
				Imp.orbit.setOn(false)
			end
		end)
		pcall(function()
			if Imp.camNoclip then
				Imp.camNoclip.setOn(false)
			end
		end)
	end

	-- Speed Glitch (ported from source; includes Gradual ramp + Instant modes)
	local Imp_sg = { on = false, max = 120, accel = 60, cur = 0, landAt = 0, air = false, mode = "Gradual", conn = nil }
	Imp.sg = Imp_sg

	local function Imp_sgReset()
		Imp_sg.cur = 0
		Imp_sg.air = false
	end

	local function Imp_sgHeartbeat(dt)
		if not Imp_sg.on then
			Imp_sgReset()
			return
		end
		local char = Imp_LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not (hum and root and hum.Health > 0) then
			Imp_sgReset()
			return
		end
		local st = hum:GetState()
		if st == Enum.HumanoidStateType.Climbing or st == Enum.HumanoidStateType.Swimming or st == Enum.HumanoidStateType.Seated or st == Enum.HumanoidStateType.Dead then
			Imp_sgReset()
			return
		end
		dt = math.min(dt or 0.0167, 0.1)
		local now = os.clock()
		local inAir = st == Enum.HumanoidStateType.Freefall or st == Enum.HumanoidStateType.Jumping
		local moveDir = hum.MoveDirection
		local flatMove = Vector3.new(moveDir.X, 0, moveDir.Z)
		local moving = flatMove.Magnitude > 0.1
		local vel = root.AssemblyLinearVelocity
		local flatVel = Vector3.new(vel.X, 0, vel.Z)
		local curSpd = flatVel.Magnitude
		if inAir then
			Imp_sg.air = true
			if moving then
				if Imp_sg.cur < hum.WalkSpeed then
					Imp_sg.cur = hum.WalkSpeed
				end
				if curSpd > Imp_sg.cur and curSpd <= Imp_sg.max then
					Imp_sg.cur = curSpd
				end
				if Imp_sg.mode == "Instant" then
					Imp_sg.cur = Imp_sg.max
				elseif Imp_sg.cur < Imp_sg.max then
					Imp_sg.cur = math.min(Imp_sg.max, Imp_sg.cur + Imp_sg.accel * dt)
				end
			end
		else
			if Imp_sg.air then
				Imp_sg.air = false
				Imp_sg.landAt = now
			end
			if now - Imp_sg.landAt > 0.3 then
				Imp_sg.cur = 0
			end
		end
		if Imp_sg.cur > Imp_sg.max then
			Imp_sg.cur = Imp_sg.max
		end
		if Imp_sg.cur > 0 and moving and (inAir or now - Imp_sg.landAt <= 0.25) then
			if curSpd < Imp_sg.cur + 1 then
				local target = flatMove.Unit * Imp_sg.cur
				if (flatVel - target).Magnitude > 0.5 then
					root.AssemblyLinearVelocity = Vector3.new(target.X, vel.Y, target.Z)
				end
			end
		end
	end

	function Imp_sg.setOn(v)
		Imp_sg.on = v and true or false
		if v then
			if not Imp_sg.conn then
				Imp_sg.conn = Imp_track(Imp_RS.Heartbeat:Connect(Imp_sgHeartbeat))
			end
		else
			Imp_sgReset()
			if Imp_sg.conn then
				Imp_sg.conn:Disconnect()
				Imp_sg.conn = nil
			end
		end
	end

	-- Gravity (+ Gravity Value)
	local Imp_grav = { on = false, value = 196, orig = nil }
	Imp.grav = Imp_grav

	function Imp_grav.apply()
		if Imp_grav.on then
			if Imp_grav.orig == nil then
				Imp_grav.orig = Imp_WS.Gravity
			end
			if math.abs(Imp_WS.Gravity - Imp_grav.value) > 0.01 then
				Imp_WS.Gravity = Imp_grav.value
			end
		elseif Imp_grav.orig ~= nil then
			Imp_WS.Gravity = Imp_grav.orig
			Imp_grav.orig = nil
		end
	end

	function Imp_grav.setOn(v)
		Imp_grav.on = v and true or false
		Imp_grav.apply()
	end

	-- Hip Height (+ Hip Height Value)
	local Imp_hip = { on = false, value = 4, hum = nil, orig = nil, conn = nil }
	Imp.hip = Imp_hip

	local function Imp_hipApply()
		local char = Imp_LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if Imp_hip.on and hum then
			if Imp_hip.hum ~= hum then
				Imp_hip.hum = hum
				Imp_hip.orig = hum.HipHeight
			end
			if math.abs(hum.HipHeight - Imp_hip.value) > 0.01 then
				hum.HipHeight = Imp_hip.value
			end
		elseif not Imp_hip.on then
			if Imp_hip.hum and Imp_hip.orig ~= nil then
				pcall(function()
					Imp_hip.hum.HipHeight = Imp_hip.orig
				end)
			end
			Imp_hip.hum = nil
			Imp_hip.orig = nil
		end
	end

	function Imp_hip.setOn(v)
		Imp_hip.on = v and true or false
		Imp_hipApply()
		if v and not Imp_hip.conn then
			Imp_hip.conn = Imp_track(Imp_RS.Heartbeat:Connect(function()
				pcall(Imp_hipApply)
			end))
		elseif not v and Imp_hip.conn then
			Imp_hip.conn:Disconnect()
			Imp_hip.conn = nil
		end
	end

	-- Orbit (adapted standalone: orbits your character around the spot where enabled)
	local Imp_orbit = { on = false, radius = 8, speed = 2, angle = 0, center = nil, conn = nil }
	Imp.orbit = Imp_orbit

	local function Imp_orbitHeartbeat(dt)
		if not Imp_orbit.on then
			return
		end
		local char = Imp_LP.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		if not Imp_orbit.center then
			Imp_orbit.center = Vector3.new(root.Position.X, root.Position.Y, root.Position.Z)
			Imp_orbit.angle = 0
		end
		Imp_orbit.angle = Imp_orbit.angle + Imp_orbit.speed * dt
		local c = Imp_orbit.center
		local target = Vector3.new(c.X + math.cos(Imp_orbit.angle) * Imp_orbit.radius, c.Y, c.Z + math.sin(Imp_orbit.angle) * Imp_orbit.radius)
		pcall(function()
			root.CFrame = CFrame.new(target, c)
			local v = root.AssemblyLinearVelocity
			root.AssemblyLinearVelocity = Vector3.new(0, v.Y, 0)
		end)
	end

	function Imp_orbit.setOn(v)
		Imp_orbit.on = v and true or false
		if v then
			Imp_orbit.center = nil
			Imp_orbit.angle = 0
			if not Imp_orbit.conn then
				Imp_orbit.conn = Imp_track(Imp_RS.Heartbeat:Connect(Imp_orbitHeartbeat))
			end
		else
			if Imp_orbit.conn then
				Imp_orbit.conn:Disconnect()
				Imp_orbit.conn = nil
			end
			Imp_orbit.center = nil
		end
	end

	-- Camera Noclip (ported from source createCameraNoclip; hook popper, fallback Invisicam)
	local Imp_cn = { on = false, hooked = false, mode = nil, origOcclusion = nil, hookOrig = nil }
	Imp.camNoclip = Imp_cn

	local function Imp_cnFindPopper()
		local ps = Imp_LP:FindFirstChild("PlayerScripts")
		local pm = ps and ps:FindFirstChild("PlayerModule")
		local cm = pm and pm:FindFirstChild("CameraModule")
		local zc = cm and cm:FindFirstChild("ZoomController")
		local popper = zc and zc:FindFirstChild("Popper")
		if not popper then
			return nil
		end
		if type(getgc) == "function" then
			local fn = popper:GetFullName()
			for _, f in ipairs(getgc(false)) do
				if type(f) == "function" and (type(islclosure) ~= "function" or islclosure(f)) then
					local ok, src, nparams = pcall(debug.info, f, "sa")
					if ok and type(src) == "string" and (src == fn or src:sub(-#popper.Name - 1) == "." .. popper.Name) then
						if nparams == 3 then
							local nm = debug.info(f, "n")
							if nm == nil or nm == "" or string.lower(nm) == "popper" then
								return f
							end
						end
					end
				end
			end
		end
		local ok, res = pcall(require, popper)
		if ok and type(res) == "function" then
			return res
		end
		return nil
	end

	local function Imp_cnTryHook()
		if Imp_cn.hooked then
			return true
		end
		if type(hookfunction) ~= "function" then
			return false
		end
		local popperFn = Imp_cnFindPopper()
		if not popperFn then
			return false
		end
		local ok, orig = pcall(function()
			return hookfunction(popperFn, function(self, dist, ignore)
				if Imp_cn.on and Imp_cn.mode == "hook" and type(dist) == "number" then
					return dist
				end
				if Imp_cn.hookOrig then
					return Imp_cn.hookOrig(self, dist, ignore)
				end
				return dist
			end)
		end)
		if ok and orig then
			Imp_cn.hookOrig = orig
			Imp_cn.hooked = true
			return true
		end
		return false
	end

	function Imp_cn.setOn(v)
		Imp_cn.on = v and true or false
		if Imp_cn.on then
			if Imp_cnTryHook() then
				Imp_cn.mode = "hook"
			else
				Imp_cn.mode = "invisicam"
				pcall(function()
					if Imp_cn.origOcclusion == nil then
						Imp_cn.origOcclusion = Imp_LP.DevCameraOcclusionMode
					end
					Imp_LP.DevCameraOcclusionMode = Enum.DevCameraOcclusionMode.Invisicam
				end)
			end
		else
			if Imp_cn.mode == "invisicam" and Imp_cn.origOcclusion ~= nil then
				pcall(function()
					Imp_LP.DevCameraOcclusionMode = Imp_cn.origOcclusion
				end)
				Imp_cn.origOcclusion = nil
			end
			Imp_cn.mode = nil
		end
	end

	-- Wall Hop Flick companion (target's Wall Hop already exists; these control its flick)
	Imp.wallFlickAngle = 60
	Imp.wallCamFlick = false
end
-- ===== End imported Movement features =====

-- ===== Imported Autofarm features v2 (Auto Prestige + Auto Equip Toy) =====
do
	pcall(function()
		if _G.FVLImp and _G.FVLImp.afCleanup then
			_G.FVLImp.afCleanup()
		end
	end)

	local Imp = _G.FVLImp or {}
	_G.FVLImp = Imp

	local Imp_Players = game:GetService("Players")
	local Imp_LP = Imp_Players.LocalPlayer
	local Imp_RSstore = game:GetService("ReplicatedStorage")

	local running = { threads = {} }

	local function Imp_stopAll()
		if Imp.autoPrestige then
			Imp.autoPrestige.on = false
		end
		if Imp.autoEquipToy then
			Imp.autoEquipToy.on = false
		end
		for _, t in ipairs(running.threads) do
			pcall(function()
				task.cancel(t)
			end)
		end
		running.threads = {}
	end

	Imp.afCleanup = Imp_stopAll

	local _oldCleanup = Imp.cleanup
	Imp.cleanup = function()
		pcall(Imp_stopAll)
		if _oldCleanup then
			pcall(_oldCleanup)
		end
	end

	-- Auto Prestige (ported from source; fires ReplicatedStorage.Remotes.Inventory.Prestige at level >= 100)
	local AF_pres = { on = false, level = nil, pres = nil, last = 0, done = 0, thread = nil }
	Imp.autoPrestige = AF_pres

	local function AF_presGet()
		local lm, pd
		pcall(function()
			local modules = Imp_RSstore:WaitForChild("Modules", 5)
			lm = require(modules:WaitForChild("LevelModule", 5))
			pd = require(modules:WaitForChild("ProfileData", 5))
		end)
		if not (lm and pd) then
			return nil, nil
		end
		local ok, lvl = pcall(lm.GetLevel, pd.NewXP)
		return ok and tonumber(lvl) or nil, tonumber(pd.Prestige) or 0
	end

	function AF_pres.setOn(v)
		AF_pres.on = v and true or false
		if AF_pres.on and not AF_pres.thread then
			AF_pres.thread = task.spawn(function()
				while AF_pres.on do
					task.wait(2)
					pcall(function()
						local lvl, pres = AF_presGet()
						if lvl then
							AF_pres.level = lvl
							AF_pres.pres = pres
							if AF_pres.on and lvl >= 100 and (pres or 0) < 10 then
								if os.clock() - AF_pres.last > 15 then
									local remotes = Imp_RSstore:FindFirstChild("Remotes")
									local inv = remotes and remotes:FindFirstChild("Inventory")
									local pr = inv and inv:FindFirstChild("Prestige")
									if pr and pr:IsA("RemoteEvent") then
										AF_pres.last = os.clock()
										pr:FireServer()
										AF_pres.done = AF_pres.done + 1
									end
								end
							end
						end
					end)
				end
				AF_pres.thread = nil
			end)
			running.threads[#running.threads + 1] = AF_pres.thread
		end
	end

	-- Auto Equip Toy (ported from source; invokes ReplicatedStorage.Remotes.Extras.ReplicateToy)
	local AF_toy = { on = false, sel = {}, rep = {}, spawnAt = 0, thread = nil }
	Imp.autoEquipToy = AF_toy

	local function AF_toyList()
		local bp = Imp_LP:FindFirstChildOfClass("Backpack")
		local toysFolder = bp and bp:FindFirstChild("Toys")
		local names, seen = {}, {}
		if toysFolder then
			for _, ch in ipairs(toysFolder:GetChildren()) do
				if ch:IsA("Tool") and not seen[ch.Name] then
					seen[ch.Name] = true
					names[#names + 1] = ch.Name
				end
			end
		end
		return names
	end

	Imp.autoEquipToy.list = AF_toyList

	local function AF_toyEquip(name)
		local char = Imp_LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not (char and hum and hum.Health > 0) then
			return
		end
		local bp = Imp_LP:FindFirstChildOfClass("Backpack")
		local inChar = char:FindFirstChild(name)
		if inChar and inChar:IsA("Tool") then
			return
		end
		if bp and bp:FindFirstChild(name) then
			return
		end
		if os.clock() - (AF_toy.rep[name] or 0) < 3 then
			return
		end
		AF_toy.rep[name] = os.clock()
		local remotes = Imp_RSstore:FindFirstChild("Remotes")
		local extras = remotes and remotes:FindFirstChild("Extras")
		local rep = extras and extras:FindFirstChild("ReplicateToy")
		if not rep then
			return
		end
		local ok, result = pcall(function()
			return rep:InvokeServer(name)
		end)
		if ok and typeof(result) == "Instance" and result:IsA("Tool") then
			pcall(function()
				if result.Parent ~= bp and result.Parent ~= char then
					result.Parent = bp
				end
			end)
		end
	end

	function AF_toy.setOn(v)
		AF_toy.on = v and true or false
		if AF_toy.on and not AF_toy.thread then
			AF_toy.spawnAt = os.clock()
			AF_toy.thread = task.spawn(function()
				while AF_toy.on do
					task.wait(0.5)
					if AF_toy.on and type(AF_toy.sel) == "table" and #AF_toy.sel > 0 and os.clock() - AF_toy.spawnAt > 1.2 then
						for _, name in ipairs(AF_toy.sel) do
							if not AF_toy.on then
								break
							end
							if name == "All Owned Toys" then
								for _, n in ipairs(AF_toyList()) do
									pcall(AF_toyEquip, n)
								end
							else
								pcall(AF_toyEquip, name)
							end
						end
					end
				end
				AF_toy.thread = nil
			end)
			running.threads[#running.threads + 1] = AF_toy.thread
		end
	end
end
-- ===== End imported Autofarm features v2 =====

do
