	-- ===== ESP role resolver: ONE place decides how a player is shown (chams, boxes, tracers, dots, ...) =====
	-- espRole(player) returns  class, realRole
	--   class:    "Murderer" / "Sheriff" / "Zombie" / "Survivor" / "Innocent"
	--   realRole: the role underneath ("Murderer", "Sheriff", "Innocent", ...)
	list2.espCache = setmetatable({}, { __mode = "k" })

	list2.espRole = function(player)
		local now = os.clock()
		local cached = list2.espCache[player]

		if cached and now - cached.t < 0.15 then
			return cached.cls, cached.real
		end

		local real = nil
		local okRole, roleValue = pcall(list2.getPlayerRole, player)

		if okRole then
			real = roleValue
		end

		real = real or "Innocent"

		local cls = real

		if cls ~= "Murderer" and cls ~= "Sheriff" and cls ~= "Zombie" and cls ~= "Survivor" then
			cls = "Innocent"
		end

		list2.espCache[player] = { t = now, cls = cls, real = real }

		return cls, real
	end

	list2.espColorOfClass = function(cls)
		if cls == "Murderer" then
			return espColors.murderer
		elseif cls == "Sheriff" then
			return espColors.sheriff
		elseif cls == "Zombie" then
			return espColors.zombie
		elseif cls == "Survivor" then
			return espColors.survivor
		elseif cls == "Hero" then
			return espColors.hero
		end

		return espColors.innocent
	end

	-- ===== Star Hub ESP additions: role switches, Hero, Style, Fill Strength, Tracer Origin, Coin ESP =====
	-- (everything hangs on list2 / small tables: this block sits close to Lua's 200-locals limit)
	list2.espRoleOn = { Murderer = true, Sheriff = true, Hero = true, Innocent = true }
	list2.espStyle = "Classic" -- Classic / Pulse / Neon
	list2.espFillStrength = 0.25 -- Full Body ESP: 0.25 = the look it always had

	-- Murderer / Sheriff / Hero / Innocent  (Zombie counts as Murderer, Survivor as Sheriff).
	-- Hero = a second player carrying the sheriff's gun: the first sheriff of the round is the real sheriff.
	-- ---- Hero tracking (same idea as the Marbeg script: the dropped gun + whoever grabs it) ----
	-- heroSet:     players we saw pick up the dropped gun this round
	-- gunDropSeen: a GunDrop appeared this round = the real sheriff is dead, so any LIVING player holding a Gun is a Hero
	list2.heroSet = setmetatable({}, { __mode = "k" })
	list2.gunDropSeen = false

	-- the role string exactly as the game sends it (not normalised: "Hero" stays "Hero")
	list2.rawRole = function(player)
		local rec = type(list2.liveData) == "table" and list2.liveData[player.Name] or nil

		if type(rec) == "table" and rec.Role ~= nil then
			return tostring(rec.Role)
		end

		local okRoster, roster = pcall(list2.roundRoster)
		rec = okRoster and type(roster) == "table" and roster[player.Name] or nil

		if type(rec) == "table" and rec.Role ~= nil then
			return tostring(rec.Role)
		end

		return nil
	end

	list2.isAliveChar = function(player)
		local char = player and player.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")

		return hum ~= nil and hum.Health > 0
	end

	-- the gun on the floor was picked up: the closest living player who now holds a Gun is the Hero
	list2.heroOnPickup = function(drop)
		local okPos, pos = pcall(function()
			if drop:IsA("BasePart") then
				return drop.Position
			end

			return drop:GetPivot().Position
		end)

		if not okPos or not pos then
			return
		end

		task.delay(0.4, function()
			local best, bestDist = nil, 14

			for _, pl in ipairs(Players:GetPlayers()) do
				local root = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")

				if root and list2.isAliveChar(pl) and list2.holdsTool(pl, "Gun") then
					local dist = (root.Position - pos).Magnitude

					if dist < bestDist then
						best, bestDist = pl, dist
					end
				end
			end

			if best then
				list2.heroSet[best] = true
				list2.espCache = setmetatable({}, { __mode = "k" })
				pcall(list2.espRecolourSoon)
			end
		end)
	end

	list2.espKey = function(player)
		local cls = list2.espRole(player)

		if cls == "Murderer" or cls == "Zombie" then
			return "Murderer"
		elseif cls == "Survivor" then
			return "Sheriff"
		elseif cls == "Sheriff" then
			-- 1) we saw this player grab the dropped gun, or the game itself calls him "Hero"
			if list2.heroSet[player] or list2.rawRole(player) == "Hero" then
				return "Hero"
			end

			-- 2) the gun was dropped this round (= the real sheriff died), so a LIVING player holding a Gun is the Hero
			if list2.gunDropSeen and list2.isAliveChar(player) and list2.holdsTool(player, "Gun") then
				return "Hero"
			end

			-- Hero = somebody ELSE picked up the gun after the real sheriff was gone. So a Sheriff-class player is only
			-- a Hero when we know who the real sheriff is AND that player is really dead / left. Anything unclear
			-- (lobby, stale data from the last round, the first seconds of a round, two sheriffs and nobody dead)
			-- stays "Sheriff", so the real sheriff is never shown as a Hero.
			local function gone(pl)
				if not pl or not pl.Parent then
					return true
				end

				local char = pl.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")

				-- real Humanoid state only: the "Dead" flags in the game data can still be left over from the last round
				return hum ~= nil and hum.Health <= 0
			end

			-- a new round just started: the data is still settling, nobody can be a Hero yet
			if list2.roundStart and os.clock() - list2.roundStart < 5 then
				return "Sheriff"
			end

			local orig = list2.espOrig

			if orig == nil then
				for _, pl in ipairs(Players:GetPlayers()) do
					if list2.rawRole(pl) == "Sheriff" then
						orig = pl
						list2.espOrig = pl -- the game data names the real sheriff (even after he died)
						break
					end
				end
			end

			if orig == nil then
				local cands = {}

				for _, pl in ipairs(Players:GetPlayers()) do
					if list2.espRole(pl) == "Sheriff" then
						cands[#cands + 1] = pl
					end
				end

				if #cands == 1 then
					orig = cands[1]
				elseif #cands > 1 then
					-- two sheriff-class players: the one that is already dead is the real sheriff
					for _, pl in ipairs(cands) do
						if gone(pl) then
							orig = pl
							break
						end
					end
				end

				-- only remember it when it is certain; otherwise ask again next time
				list2.espOrig = orig
			end

			if orig == nil or orig == player or not gone(orig) then
				return "Sheriff"
			end

			return "Hero"
		end

		return "Innocent"
	end

	list2.espAllowed = function(player)
		local ok, key = pcall(list2.espKey, player)
		return not ok or list2.espRoleOn[key] ~= false
	end

	list2.espColor = function(player)
		local ok, key = pcall(list2.espKey, player)

		if ok and key == "Hero" then
			return espColors.hero
		end

		return list2.espColorOfClass((list2.espRole(player)))
	end

	-- Style "Pulse": the outline (or the fill, when Full Body ESP is on) breathes
	list2.espPulseConn = nil

	list2.espPulseSync = function()
		if list2.espStyle == "Pulse" and not list2.liteMode then
			if not list2.espPulseConn then
				list2.espPulseConn = RunService.Heartbeat:Connect(function()
					local group = obj4 and obj4.Groups and obj4.Groups.players

					if not group then
						return
					end

					local k = 0.5 + 0.5 * math.sin(os.clock() * 4)

					for _, inst in ipairs(group) do
						if inst:IsA("Highlight") and inst.Parent then
							local baseFill = inst:GetAttribute("BaseFill")
							local baseLine = inst:GetAttribute("BaseLine")

							if baseFill and baseFill < 1 then
								inst.FillTransparency = math.clamp(baseFill + 0.45 * k, 0, 1)
							elseif baseLine and baseLine < 1 then
								inst.OutlineTransparency = math.clamp(baseLine + 0.45 * k, 0, 1)
							end
						end
					end
				end)

				list2.conns[#list2.conns + 1] = list2.espPulseConn
			end
		elseif list2.espPulseConn then
			pcall(function()
				list2.espPulseConn:Disconnect()
			end)

			list2.espPulseConn = nil
		end
	end

	-- Coin ESP (Star Hub "World > Coins"): gold highlight on the coins closest to you.
	-- Roblox only draws ~31 highlights at once and the players already use up to 12, so the 12 closest coins get a
	-- Highlight. Every other coin inside the ESP range (up to the whole map) gets a small gold sphere marker instead
	-- (adornments have no limit). C.range = distance in studs, math.huge = whole map.
	list2.coinEsp = { on = false, token = 0, hl = {}, mk = {}, max = 12, range = math.huge }

	list2.coinEsp.clear = function()
		for coin, h in pairs(list2.coinEsp.hl) do
			pcall(function()
				h:Destroy()
			end)

			list2.coinEsp.hl[coin] = nil
		end

		for coin, m in pairs(list2.coinEsp.mk) do
			pcall(function()
				m:Destroy()
			end)

			list2.coinEsp.mk[coin] = nil
		end
	end

	list2.coinEsp.visual = function(coin)
		for _, d in ipairs(coin:GetDescendants()) do
			if d:IsA("BasePart") and d.Transparency < 1 then
				return d
			end
		end

		if coin.Transparency < 1 then
			return coin
		end

		return nil
	end

	list2.coinEsp.step = function(gui)
		local C = list2.coinEsp
		local container = C.container

		if not container or not container.Parent then
			container = Workspace:FindFirstChild("CoinContainer", true)
			C.container = container
		end

		for coin, h in pairs(C.hl) do
			if not coin.Parent or not coin.CanTouch or coin:GetAttribute("Collected") or not h.Parent or not h.Adornee or not h.Adornee.Parent then
				pcall(function()
					h:Destroy()
				end)

				C.hl[coin] = nil
			end
		end

		for coin, m in pairs(C.mk) do
			if not coin.Parent or not coin.CanTouch or coin:GetAttribute("Collected") or not m.Parent then
				pcall(function()
					m:Destroy()
				end)

				C.mk[coin] = nil
			end
		end

		if not container then
			return
		end

		local cam = Workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position or Vector3.new(0, 0, 0)
		local range = C.range or math.huge
		local list = {}

		for _, d in ipairs(container:GetDescendants()) do
			if d.Name == "Coin_Server" and d:IsA("BasePart") and d.CanTouch and not d:GetAttribute("Collected") then
				local dist = (d.Position - camPos).Magnitude

				if dist <= range then
					list[#list + 1] = { coin = d, dist = dist }
				end
			end
		end

		table.sort(list, function(a, b)
			return a.dist < b.dist
		end)

		-- the closest C.max coins get a Highlight, the rest of the coins in range get a marker
		local keep, keepMk = {}, {}

		for i = 1, #list do
			if i <= C.max then
				keep[list[i].coin] = true
			else
				keepMk[list[i].coin] = true
			end
		end

		for coin, h in pairs(C.hl) do
			if not keep[coin] then
				pcall(function()
					h:Destroy()
				end)

				C.hl[coin] = nil
			end
		end

		for coin, m in pairs(C.mk) do
			if not keepMk[coin] then
				pcall(function()
					m:Destroy()
				end)

				C.mk[coin] = nil
			end
		end

		for coin in pairs(keep) do
			if not C.hl[coin] then
				local vis = C.visual(coin)

				if vis then
					local h = Instance.new("Highlight")
					h.Name = "FVLCoin"
					h.FillColor = Color3.fromRGB(255, 200, 0)
					h.OutlineColor = Color3.fromRGB(255, 235, 120)
					h.FillTransparency = 0
					h.OutlineTransparency = 0
					h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
					h.Adornee = vis
					h.Parent = gui
					C.hl[coin] = h
				end
			end
		end

		for coin in pairs(keepMk) do
			if not C.mk[coin] then
				local m = Instance.new("SphereHandleAdornment")
				m.Name = "FVLCoinMarker"
				m.Color3 = Color3.fromRGB(255, 200, 0)
				m.Radius = 1.4
				m.Transparency = 0.15
				m.AlwaysOnTop = true
				m.ZIndex = 1
				m.Adornee = coin
				m.Parent = gui
				C.mk[coin] = m
			end
		end
	end

	list2.coinEsp.set = function(on)
		local C = list2.coinEsp
		C.on = on and true or false
		C.token = C.token + 1

		if not C.on then
			C.clear()
			return
		end

		local mine = C.token

		task.spawn(function()
			while C.on and C.token == mine do
				local gui = obj4 and obj4.ScreenGui

				if not gui or not gui.Parent then
					break
				end

				pcall(C.step, gui)
				task.wait(0.5)
			end

			if C.token == mine then
				C.clear()
			end
		end)
	end

	local function func24(list4)
		for _, descendant in ipairs(list4:GetDescendants()) do
			if descendant:IsA("BasePart") and descendant.Name ~= "HumanoidRootPart" and descendant.Transparency >= 1 then
				func23(descendant)

				if list2.revealed[descendant] == nil then
					list2.revealed[descendant] = descendant.Transparency
				end

				descendant.Transparency = 0.9
			end
		end
	end

	ROLEBOX = { conns = {} }

	ROLEBOX.hide = function(obj)
		if not obj:IsA("BoxHandleAdornment") then
			return
		end
		obj.Visible = false

		table.insert(ROLEBOX.conns, obj:GetPropertyChangedSignal("Visible"):Connect(function()
			if obj.Visible then
				obj.Visible = false
			end
		end))
	end

	ROLEBOX.watch = function(obj)
		for _, descendant in ipairs(obj:GetDescendants()) do
			ROLEBOX.hide(descendant)
		end

		table.insert(ROLEBOX.conns, obj.DescendantAdded:Connect(ROLEBOX.hide))
	end

	ROLEBOX.start = function()
		for _, player in ipairs(Players:GetPlayers()) do
			if player.Character then
				ROLEBOX.watch(player.Character)
			end

			table.insert(ROLEBOX.conns, player.CharacterAdded:Connect(ROLEBOX.watch))
		end

		table.insert(ROLEBOX.conns, Players.PlayerAdded:Connect(function(player)
			table.insert(ROLEBOX.conns, player.CharacterAdded:Connect(ROLEBOX.watch))
		end))
	end

	ROLEBOX.stop = function()
		for _, conn in ipairs(ROLEBOX.conns) do
			pcall(function()
				conn:Disconnect()
			end)
		end

		ROLEBOX.conns = {}

		for _, player in ipairs(Players:GetPlayers()) do
			if player.Character then
				for _, descendant in ipairs(player.Character:GetDescendants()) do
					if descendant:IsA("BoxHandleAdornment") then
						descendant.Visible = true
					end
				end
			end
		end
	end

	ROLEBOX.start()

	func17 = function()
		return flag18 or flag19 or flag20 or (list2.espAvatar and not list2.liteMode)
	end

	func18 = function()
		obj4:RemoveGroup("players")
		if not func17() then
			return
		end
		local n = 1

		if flag19 then
			n = 1 - math.clamp(list2.espFillStrength or 0.25, 0, 1) -- Star Hub "Fill Strength"
		end

		local n2 = 1

		if flag18 then
			n2 = 0.1
		end

		local lite = list2.liteMode == true -- Lite Mode: no avatar, no Neon look
		local neon = list2.espStyle == "Neon" and not lite

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= localPlayer and player.Character and list2.espAllowed(player) then
				func24(player.Character)
				local innocent = list2.espColor(player) -- Murderer / Sheriff / Hero / Innocent
				local lineColor = innocent

				if neon then
					-- Star Hub "Neon": brighter, whitened glow
					innocent = innocent:Lerp(Color3.new(1, 1, 1), 0.12)
					lineColor = innocent:Lerp(Color3.new(1, 1, 1), 0.6)
				end

				obj4:Add(player.Character, {
					Color = innocent,
					OutlineColor = lineColor,
					GroupName = "players",
					FillTransparency = n,
					OutlineTransparency = n2,
					Label = (flag20 and player.DisplayName) or ((list2.espAvatar and not lite) and "" or nil),
					AvatarUserId = (list2.espAvatar and not lite) and player.UserId or nil,
					LabelAdornee = player.Character:FindFirstChild("Head"),
					LabelMaxDistance = 300,
				})
			end
		end
	end

	local function func25(param17)
		obj4:Add(param17, {
			Color = espColors.gun,
			GroupName = "gun",
			Label = "Gun",
			FillTransparency = 0.5,
			OutlineTransparency = 0,
		})
	end

	local function func26(param18)
		func23(param18)

		pcall(function()
			param18.Transparency = 0
		end)

		obj4:Add(param18, {
			Color = espColors.trap,
			GroupName = "trap",
			Label = "Trap",
			FillTransparency = 0.5,
			OutlineTransparency = 0,
		})
	end

	func19 = function()
		obj4:RemoveGroup("gun")
		if not flag21 then
			return
		end

		for _, descendant in ipairs(Workspace:GetDescendants()) do
			if descendant.Name == "GunDrop" and (descendant:IsA("BasePart") or descendant:IsA("Model")) then
				func25(descendant)
			end
		end
	end

	func20 = function()
		obj4:RemoveGroup("trap")
		if not flag22 then
			return
		end

		for _, descendant in ipairs(Workspace:GetDescendants()) do
			if descendant.Name == "Trap" and descendant.Parent and (descendant.Parent:IsA("Folder") or descendant.Parent:IsA("Model")) then
				func26(descendant)
			end
		end
	end

	local n = 0

	list2.espRecolourSoon = function()
		if not func17() then
			return
		end
		pcall(func18)

		for _, item9 in ipairs({ 0.1, 0.3, 0.6 }) do
			task.delay(item9, function()
				if func17() then
					pcall(func18)
				end
			end)
		end
	end

	-- somebody died -> refresh the colours right away instead of waiting for the next 1 s refresh
	list2.hookEspDeath = function(player)
		local function onChar(char)
			local hum = char:WaitForChild("Humanoid", 5)

			if hum then
				hum.Died:Connect(function()
					list2.espCache[player] = nil
					list2.espRecolourSoon()
				end)
			end
		end

		if player.Character then
			task.spawn(onChar, player.Character)
		end

		list2.conns[#list2.conns + 1] = player.CharacterAdded:Connect(onChar)
	end

	for _, pl in ipairs(Players:GetPlayers()) do
		list2.hookEspDeath(pl)
	end

	list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(list2.hookEspDeath)

	pcall(function()
		list2.conns[#list2.conns + 1] = Workspace.DescendantAdded:Connect(function(descendant)
			if flag22 and descendant.Name == "Trap" and descendant.Parent and (descendant.Parent:IsA("Folder") or descendant.Parent:IsA("Model")) then
				func26(descendant)
			end

			-- Gun = new sheriff / survivor, Knife = a player just got infected and became a zombie
			if (descendant.Name == "Gun" or descendant.Name == "Knife") and descendant:IsA("Tool") then
				if descendant.Parent and Players:GetPlayerFromCharacter(descendant.Parent) then
					list2.espRecolourSoon()
				end
			end

			-- a player just got a Gun after the sheriff died = Hero
			if descendant.Name == "Gun" and descendant:IsA("Tool") and list2.gunDropSeen then
				local holder = descendant.Parent and Players:GetPlayerFromCharacter(descendant.Parent)

				if holder then
					list2.heroSet[holder] = true
				end
			end

			if descendant.Name == "GunDrop" and (descendant:IsA("BasePart") or descendant:IsA("Model")) then
				list2.gunDropSeen = true
				list2.espCache = setmetatable({}, { __mode = "k" })

				if flag21 then
					func25(descendant)
				end

				if tick() - n > 3 then
					n = tick()
					list2.playSfx("gun")

					obj2:Notify({
						Title = "Gun Dropped!",
						Content = "The sheriff died — the gun is on the floor.",
						Duration = 5,
						Icon = "crosshair",
					})
				end
			end
		end)

		list2.conns[#list2.conns + 1] = Workspace.DescendantRemoving:Connect(function(descendant)
			if flag21 and descendant.Name == "GunDrop" then
				task.defer(func19)
			end

			if flag22 and descendant.Name == "Trap" then
				task.defer(func20)
			end

			if descendant.Name == "GunDrop" then
				pcall(list2.heroOnPickup, descendant)
				task.defer(list2.espRecolourSoon)
			end
		end)
	end)

	local flag25 = false

	func21 = function()
		if flag25 then
			return
		end
		flag25 = true

		task.spawn(function()
			-- FAST role watcher: every 0.2 s check whether anybody's ESP class changed (e.g. a survivor just got infected
			-- and became a Zombie) and redraw right away. The full redraw still happens every 1 s as before.
			-- (Before, a role change that came without a PlayerDataChanged event / equipped knife could wait up to 1 s.)
			local lastCls = setmetatable({}, { __mode = "k" })
			local ticks = 0

			while flag25 do
				task.wait(0.2)
				ticks += 1

				if func17() then
					local changed = false

					if ticks % 3 == 0 and list2.pollPlayerData then
						list2.pollPlayerData()
					end

					for _, player in ipairs(Players:GetPlayers()) do
						if player ~= localPlayer then
							local okCls, cls = pcall(list2.espRole, player)

							if okCls and lastCls[player] ~= cls then
								lastCls[player] = cls
								changed = true
							end
						end
					end

					if changed or ticks % 5 == 0 then
						pcall(func18)
					end
				end
			end
		end)
	end

	func22 = function()
		flag25 = false
	end

	list2.tr = {
		lines = false,
		dist = false,
		arrows = false,
		origin = "Bottom", -- Star Hub "Tracer Origin": Bottom / Center / Top
		parts = {},
		murd = nil,
		sher = nil,
		roleAt = 0,
		conn = nil,
	}

	list2.tr.any = function()
		return list2.tr.lines or list2.tr.dist or list2.tr.arrows
	end

	list2.tr.colorOf = function(flag26)
		return list2.espColor(flag26) -- Murderer / Sheriff / Innocent
	end

	list2.tr.slot = function(param19)
		local flag27 = list2.tr.parts[param19]
		if flag27 and flag27.line and flag27.line.Parent then
			return flag27
		end
		local screenGui = obj4 and obj4.ScreenGui
		if not screenGui or not screenGui.Parent then
			return nil
		end
		local tbl17 = { line = Instance.new("Frame") }
		tbl17.line.Name = "FVLTracer"
		tbl17.line.AnchorPoint = Vector2.new(0.5, 0.5)
		tbl17.line.BorderSizePixel = 0
		tbl17.line.Visible = false
