					flag30.line.Size = UDim2.fromOffset(2, math.sqrt(n6 * n6 + n7 * n7))
					flag30.line.Position = UDim2.fromOffset(n2 + n6 * 0.5, y + n7 * 0.5)
					flag30.line.Rotation = math.deg(math.atan2(n7, n6)) - 90
					flag30.line.Visible = true
				else
