TeleportService = game:GetService("TeleportService")
local flag33, func27, flag34, func28, func29, func30, func31, func32, func33

do
	local placeId = game.PlaceId
	local jobId = game.JobId
	flag33 = false

	-- Fling, three modes (Fling Mode in the Fling tab; the third one, Slam (Head) v2, is defined just above func27):
	--   Slam (Head): lands on the other player's head every frame (twice per frame) with a huge velocity pointing DOWN.
	--   Spin (Other Script): the other script's method. Your character is stood on the target again and again
	--   with a huge velocity and spin (alternating above / below them, turning every step).
	-- Both keep the camera on the target, stop as soon as they are thrown, then put you back where you were.
	-- ===== Slam (Head) v2 =====
	-- Ported from the "Fling Panel" of the other script (the fling it fires when you tap a player in the panel).
	-- It stands on the target the whole time with a huge DOWNWARD velocity, leads a moving target with a short
	-- prediction (4-step lead pattern, wall-checked), follows a target that is being teleported / spoofing its
	-- velocity, and stops by itself the moment the target is pushed under the map ("down" / "falling") or is gone.
	-- Like the panel, one tap keeps trying for up to 10 seconds until the target is down.
	local slamV2 = { busy = false, fpdh = nil }
	local SLAMV2_DOWN_V = 120000 -- downward velocity while standing on the target
	local SLAMV2_SPIN = 60000 -- spin while the target is moving
	local SLAMV2_MAX_STEP = 20 -- studs/second we may slide sideways while the target stands still

	-- ===== OFF THE MAP (shared by every fling mode) =====
	-- A fling only counts when the target ends up OFF THE MAP: under it, or past its edge (or dead).
	-- Flinging "up and away" is not enough, the target just lands again. So every mode (1) aims the launch OUTWARD,
	-- away from the middle of the map, (2) watches where the target ends up and (3) launches it again if it landed
	-- back on the map. The map = the model that holds the coins; its box is cached per map.
	list2.offMap = { map = nil, cf = nil, size = nil }

	list2.offMap.box = function()
		local om = list2.offMap

		if not (om.map and om.map.Parent) then
			om.map, om.cf, om.size = nil, nil, nil

			for _, child in ipairs(Workspace:GetChildren()) do
				if child:IsA("Model") and (child:FindFirstChild("CoinContainer") or child:FindFirstChild("CoinAreas")) then
					om.map = child
					break
				end
			end
		end

		if om.map and not om.cf then
			local ok, cf, size = pcall(function()
				return om.map:GetBoundingBox()
			end)

			if ok and cf then
				om.cf, om.size = cf, size
			end
		end

		return om.cf, om.size
	end

	-- true when a position is off the map (voidY = the real FallenPartsDestroyHeight, if you have it)
	list2.offMap.isOff = function(pos, voidY)
		if type(voidY) ~= "number" or voidY ~= voidY then
			voidY = Workspace.FallenPartsDestroyHeight

			if type(voidY) ~= "number" or voidY ~= voidY then
				voidY = -500
			end
		end

		if pos.Y < voidY + 60 then
			return true
		end

		local cf, size = list2.offMap.box()

		if cf and size then
			local rel = cf:PointToObjectSpace(pos)

			if math.abs(rel.X) > size.X / 2 + 40 or math.abs(rel.Z) > size.Z / 2 + 40 or rel.Y < -size.Y / 2 - 40 then
				return true
			end
		end

		return false
	end

	-- flat unit direction pointing from the middle of the map out through `pos` (straight to the nearest edge)
	list2.offMap.outward = function(pos)
		local cf = list2.offMap.box()
		local center = cf and cf.Position or Vector3.new(0, 0, 0)
		local d = Vector3.new(pos.X - center.X, 0, pos.Z - center.Z)

		if d.Magnitude < 1 then
			local a = math.random() * math.pi * 2
			d = Vector3.new(math.cos(a), 0, math.sin(a))
		end

		return d.Unit
	end

	-- "thrown" = the target has been launched away from where we started on it (fast AND far, or just very far).
	-- The other modes stop on velocity > 500; here the distance is checked too, because a target that spoofs its
	-- velocity also reads as very fast but stays where it is.
	local function slamV2Thrown(origin, pos, vel)
		if not origin then
			return false
		end

		local moved = (pos - origin).Magnitude

		return (moved > 40 and vel.Magnitude > 500) or moved > 150
	end

	local function slamV2Down(targetChar, maxTime, home, origin)
		if slamV2.busy then
			return false, "busy"
		end

		if not (targetChar and targetChar.Parent) then
			return false, "no-target"
		end

		local tHum = targetChar:FindFirstChildOfClass("Humanoid")
		local tRoot = targetChar:FindFirstChild("HumanoidRootPart") or targetChar:FindFirstChild("Head")

		if not (tHum and tRoot) or tHum.Health <= 0 then
			return false, "dead"
		end

		local myChar = localPlayer.Character
		local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
		local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

		if not (myHum and myRoot) or myHum.Health <= 0 then
			return false, "me"
		end

		local RunService = game:GetService("RunService")
		local camera = Workspace.CurrentCamera

		slamV2.busy = true
		maxTime = tonumber(maxTime) or 0.8

		if slamV2.fpdh == nil then
			slamV2.fpdh = Workspace.FallenPartsDestroyHeight
		end

		home = home or myRoot.CFrame

		local oldSubject = camera and camera.CameraSubject
		local oldSeated, oldPlatformStand = true, false

		pcall(function()
			oldSeated = myHum:GetStateEnabled(Enum.HumanoidStateType.Seated)
		end)
		pcall(function()
			oldPlatformStand = myHum.PlatformStand
		end)
		pcall(function()
			Workspace.FallenPartsDestroyHeight = 0 / 0
		end)
		pcall(function()
			myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
		end)
		pcall(function()
			if camera then
				camera.CameraSubject = tHum
			end
		end)

		-- the target must not block us: switch its collisions off while we are on it (restored afterwards)
		local collide = {}

		pcall(function()
			for _, inst in ipairs(targetChar:GetDescendants()) do
				if inst:IsA("BasePart") then
					collide[#collide + 1] = { inst, inst.CanCollide }
				end
			end
		end)

		local function noCollide()
			for i = 1, #collide do
				local part = collide[i][1]

				if part.Parent and part.CanCollide then
					pcall(function()
						part.CanCollide = false
					end)
				end
			end
		end

		noCollide()

		local ping = 0.08
		pcall(function()
			ping = tonumber(localPlayer:GetNetworkPing()) or 0.08
		end)

		local y0 = tRoot.Position.Y
		local lead = math.clamp(0.16 + ping * 2 + 0.05, 0.15, 0.6)
		local offsets = { 1.4, 0.5, 2.3, 0.9 } -- height above the target while it stands still
		local mults = { 0, 0.3, 0.55, 0.8 } -- how far ahead of a moving target we land (x its velocity)
		local spoof = 0 -- the target is flinging / spoofing its velocity: use its real (position based) speed
		local zeroVec = Vector3.zero

		local tvOk, tvSpeed = pcall(function()
			return tHum.MoveDirection.Magnitude * tHum.WalkSpeed
		end)

		local startVel = tRoot.AssemblyLinearVelocity

		if startVel.Magnitude > 1500 then
			spoof = 1
			startVel = Vector3.zero
		end

		local startFlat = Vector3.new(startVel.X, 0, startVel.Z).Magnitude
		local duration = maxTime

		-- a moving target needs longer
		if (tvOk and tvSpeed > 2) or startFlat > 3 or spoof > 0 then
			duration = math.max(maxTime, 1.2)
		end

		local frame = 0
		local done = false
		local reason = "timeout"
		local minVelY, minPosY = 0, y0
		local lastGood = tRoot.Position -- last trusted position of the target
		local jumpStart = nil -- when the target first "teleported"
		local samples = {} -- recent {time, position} (speed from position when it spoofs velocity)
		local myLastPos, lastPlaced, lastStepT, firstPos, predPos = nil, nil, nil, nil, nil
		local tpMe = false
		local started = os.clock()

		local rayParams = RaycastParams.new()
		rayParams.FilterType = Enum.RaycastFilterType.Exclude
		rayParams.FilterDescendantsInstances = { myChar, targetChar }

		pcall(function()
			rayParams.RespectCanCollide = true
		end)

		local stepConn = RunService.Stepped:Connect(function()
			if done then
				return
			end

			pcall(function()
				myRoot.AssemblyLinearVelocity = zeroVec
				myRoot.AssemblyAngularVelocity = zeroVec
			end)

			noCollide()
		end)

		local beatConn = RunService.Heartbeat:Connect(function()
			if done then
				return
			end

			frame += 1

			if not (targetChar.Parent and tRoot.Parent and tHum.Health > 0) then
				done, reason = true, "gone"

				return
			end

			if not (myRoot.Parent and myHum.Health > 0) then
				done, reason = true, "me"

				return
			end

			local tPos, tVel, now = tRoot.Position, tRoot.AssemblyLinearVelocity, os.clock()

			-- flung away: stop right here (same idea as the other modes)
			if slamV2Thrown(origin, tPos, tVel) then
				done, reason = true, "thrown"

				return
			end

			if tVel.Magnitude > 1500 then
				spoof += 1
			end

			local goodPos

			if (tPos - lastGood).Magnitude > 60 then
				if spoof == 0 then
					done, reason = true, "tp-target"

					return
				end

				jumpStart = jumpStart or now

				if now - jumpStart > 0.35 then
					if tPos.Y < y0 - 25 then
						done, reason = true, "down"

						return
					end

					if (tPos - lastGood).Magnitude > 300 then
						done, reason = true, "tp-target"

						return
					end

					lastGood, jumpStart, goodPos = tPos, nil, tPos
				else
					goodPos = lastGood
				end
			else
				jumpStart, lastGood, goodPos = nil, tPos, tPos
			end

			samples[#samples + 1] = { now, goodPos }

			while #samples > 2 and now - samples[1][1] > 0.25 do
				table.remove(samples, 1)
			end

			local vel

			if spoof > 0 then
				local dt = now - samples[1][1]

				vel = dt > 0.06 and (goodPos - samples[1][2]) / dt or Vector3.zero
			else
				vel = tVel
			end

			if myLastPos and (myRoot.Position - myLastPos).Magnitude > 30 then
