			beatConn:Disconnect()
		end)
		pcall(function()
			stepConn:Disconnect()
		end)

		-- ---- back to where we were (only when it is safe to stand there) ----
		local function hasGround(pos)
			local ok, res = pcall(function()
				local rp = RaycastParams.new()

				rp.FilterType = Enum.RaycastFilterType.Exclude
				rp.FilterDescendantsInstances = { myChar, targetChar }

				return Workspace:Raycast(pos + Vector3.new(0, 2, 0), Vector3.new(0, -90, 0), rp) ~= nil
			end)

