		end)
		local goHome

		if tpMe then
			goHome = false
		elseif posOk and (curPos - home.Position).Magnitude > 35 and hasGround(curPos) then
			goHome = false
		elseif hasGround(home.Position) then
			goHome = true
		elseif posOk then
			goHome = not hasGround(curPos)
		else
			goHome = true
		end

		local homeStart, stable = os.clock(), 0

		while goHome and os.clock() - homeStart < 1.5 do
			if not myRoot.Parent then
				break
			end

			pcall(function()
				myRoot.AssemblyLinearVelocity = zeroVec
				myRoot.AssemblyAngularVelocity = zeroVec
				myRoot.CFrame = home
			end)

			RunService.Heartbeat:Wait()

			local dOk, dist = pcall(function()
				return (myRoot.Position - home.Position).Magnitude
			end)

			if dOk and dist > 20 then
				break
			end

			stable = (dOk and dist < 3) and stable + 1 or 0

			if stable >= 3 then
				break
			end
		end

		pcall(function()
			myRoot.AssemblyLinearVelocity = zeroVec
			myRoot.AssemblyAngularVelocity = zeroVec
		end)
		pcall(function()
			myHum.PlatformStand = oldPlatformStand
		end)
		pcall(function()
			if myHum.Health > 0 then
				myHum:ChangeState(Enum.HumanoidStateType.GettingUp)
			end
		end)
		pcall(function()
			myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, oldSeated)
		end)
		pcall(function()
			if camera then
				camera.CameraSubject = oldSubject or myHum
			end
		end)

		for i = 1, #collide do
			local part, was = collide[i][1], collide[i][2]

			if part.Parent and part.CanCollide ~= was then
				pcall(function()
					part.CanCollide = was
				end)
			end
		end

		if slamV2.fpdh ~= nil then
			local fpdh = slamV2.fpdh

			slamV2.fpdh = nil

			pcall(function()
				Workspace.FallenPartsDestroyHeight = fpdh
			end)
		end

		slamV2.busy = false

		return reason == "down" or reason == "falling" or reason == "gone" or reason == "thrown", reason
	end

	-- one tap = keep trying for up to 10 seconds, until the target is down / gone / dead (same as the panel)
	local function slamV2Persist(targetPlayer, home)
		local char = targetPlayer and targetPlayer.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")

		if not root then
			return false, "no-target"
		end

		local startY = root.Position.Y
		local origin = root.Position -- where the target was when we started
		local lowSince = nil

		local function stillThere()
			local c = targetPlayer.Character
			local hum = c and c:FindFirstChildOfClass("Humanoid")
			local r = c and c:FindFirstChild("HumanoidRootPart")

			if not (targetPlayer.Parent and c == char and hum and r) or hum.Health <= 0 then
				return nil, "gone"
			end

			if slamV2Thrown(origin, r.Position, r.AssemblyLinearVelocity) then
				-- launched: it only counts once the target is really OFF the map; if it is still over the map
				-- we start again from where it is now
				if list2.offMap.isOff(r.Position, slamV2.fpdh) then
					return nil, "thrown"
				end

				origin = r.Position
				startY = r.Position.Y
				lowSince = nil
			end

			if r.Position.Y < startY - 25 then
				lowSince = lowSince or os.clock()

				if os.clock() - lowSince >= 0.25 then
					return nil, "down"
				end
			else
				lowSince = nil
			end

			return c
		end

		local t0 = os.clock()
		local text = "timeout"

		while os.clock() - t0 < 10 do
			if not flag33 then
				text = "cancel"

				break
			end

			local c, why = stillThere()

			if not c then
				text = why

				break
			end

			local myChar = localPlayer.Character
			local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")

			if not myHum or myHum.Health <= 0 then
				text = "me"

				break
			end

			local ok, err = pcall(slamV2Down, c, 0.8, home, origin)

			if not ok then
				-- never leave the map / camera / collisions in a broken state if a pass errors
				slamV2.busy = false

				if slamV2.fpdh ~= nil then
					Workspace.FallenPartsDestroyHeight = slamV2.fpdh
					slamV2.fpdh = nil
				end

				warn("[Slam (Head) v2] " .. tostring(err))

				text = "error"

				break
			end

			local waited = os.clock()

			while os.clock() - waited < 0.3 do
				task.wait(0.05)

				if not stillThere() then
					break
				end
			end
		end

		return text == "gone" or text == "down" or text == "thrown", text
	end

	func27 = function(player2)
		if flag33 then
			obj2:Notify({
				Title = "Fling Active!",
				Content = "Wait for the current fling to finish!",
				Duration = 1.5,
				Icon = "clock",
			})

			return
		end

		if not player2 or not player2.Character then
			obj2:Notify({ Title = "Error!", Content = "Could not find that player!", Duration = 1.5, Icon = "x" })

			return
		end

		if not player2.Character:FindFirstChildOfClass("Humanoid") then
			return
		end

		local character = localPlayer.Character
		if not character then
			return
		end

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return
		end

		local rootPart = humanoid.RootPart
		if not rootPart then
			return
		end

		local character2 = player2.Character
		local humanoid2 = character2:FindFirstChildOfClass("Humanoid")
		local rootPart2 = humanoid2 and humanoid2.RootPart
		local head = character2:FindFirstChild("Head")
		local accessory = character2:FindFirstChildOfClass("Accessory")
		accessory = accessory and accessory:FindFirstChild("Handle")

		if humanoid2 and humanoid2.Sit then
			return
		end

		flag33 = true

		local health = humanoid.Health
		local fallenPartsDestroyHeight = Workspace.FallenPartsDestroyHeight

		-- remember where we were (not while we are already flying around)
		if rootPart.Velocity.Magnitude < 50 then
			list2.flingOldPos = rootPart.CFrame
		end

		local oldPos = list2.flingOldPos or rootPart.CFrame
		local camera = Workspace.CurrentCamera
		local slam = list2.flingMode ~= "Spin"
		local finalState -- "off" / "gone" / "on": where the target ended up

		local function reportResult()
			if humanoid.Health <= 0 then
				obj2:Notify({
					Title = "Fling Backfired",
					Content = player2.Name .. " killed you mid-fling.",
					Duration = 3,
					Icon = "x",
				})
			elseif humanoid.Health < health then
				obj2:Notify({
					Title = "Flinged!",
