						child.RotVelocity = Vector3.zero
					end
				end

				task.wait()

				if (rootPart.Position - oldPos.p).Magnitude < 25 then
					break
				end
			end
		end)

		Workspace.FallenPartsDestroyHeight = fallenPartsDestroyHeight
		flag33 = false

		reportResult()
	end

