	-- ===== Farm Run Animation (from Star Hub) =====
	-- _G.__FarmRunAnim(humanoid, hrp, playing [, speed]) plays or stops a looping run animation on the character.
	-- _G.__FarmRunTrack    = the loaded AnimationTrack
	-- _G.__FarmRunAnimator = the Animator that track was loaded on (a new track is made after a respawn)
	-- speed is optional: without it the speed is read from hrp.AssemblyLinearVelocity.
	_G.__FarmRunAnim = function(humanoid, hrp, playing, speed)
		local track = _G.__FarmRunTrack

		if not playing then
			if track then
				pcall(function()
					track:Stop(0.2)
				end)
			end

			return
		end

		if not humanoid or not hrp then
			return
		end

		local animator = humanoid:FindFirstChildWhichIsA("Animator")

		if not animator then
			return
		end

		if not track or _G.__FarmRunAnimator ~= animator then
			if track then
				pcall(function()
					track:Stop(0)
					track:Destroy()
				end)
			end

			local animation = Instance.new("Animation")
			animation.AnimationId = humanoid.RigType == Enum.HumanoidRigType.R6 and "rbxassetid://180426354" or "rbxassetid://507767714"

			local ok, loaded = pcall(function()
				return animator:LoadAnimation(animation)
			end)

			if not ok or not loaded then
				return
			end

			track = loaded
			track.Priority = Enum.AnimationPriority.Action4
			track.Looped = true
			_G.__FarmRunTrack = track
			_G.__FarmRunAnimator = animator
		end

		if not track.IsPlaying then
			track:Play(0.15)
		end

		if not speed then
			local velocity = hrp.AssemblyLinearVelocity
			speed = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
		end

		track:AdjustSpeed(math.clamp(speed / 16, 0.7, 1.7))
	end

