	-- Moves the root every frame with a smoothed velocity, so changing coins never stops the motion.
	list2.glideStart = function()
		if list2.glideConn then
			return
		end

		list2.glideVel = Vector3.zero

		list2.glideConn = RunService.Heartbeat:Connect(function(dt)
			if not flag48 then
				list2.glideStop()
				return
			end

			local root = func47(localPlayer)
			if not root then
				return
			end

			local target = list2.glideTarget
			local goal = nil

			if target and target.Parent and not target:GetAttribute("Collected") then
				goal = target.Position
			end

			if goal then
				local delta = goal - root.Position
				local dist = delta.Magnitude
				local desired = Vector3.zero

				if dist > 0.05 then
					-- cruise at the Farm Speed, ease off over the last stretch for a soft arrival
					desired = delta.Unit * math.min(n2, dist * 6)
				end

				-- exponential smoothing = acceleration / braking without jerks
				list2.glideVel = list2.glideVel:Lerp(desired, 1 - math.exp(-9 * dt))
			else
				-- no target for a moment (coin just got picked): keep drifting and slow down gently
				list2.glideVel = list2.glideVel * math.exp(-2 * dt)
			end

			local step = list2.glideVel * dt

			if goal and step.Magnitude > (goal - root.Position).Magnitude then
				step = goal - root.Position
			end

			if step.Magnitude > 1e-4 then
				root.CFrame = root.CFrame + step
			end

			root.AssemblyLinearVelocity = Vector3.zero

			-- Farm Run Animation: runs while the glide is really moving, fades out when it slows to a halt
			local planar = Vector3.new(list2.glideVel.X, 0, list2.glideVel.Z)
			local planarSpeed = planar.Magnitude
			local moving = planarSpeed > (list2.runAnimOn and 1.5 or 3)

			if moving then
				local now = os.clock()

				if now - list2.runAnimAt > 0.1 then
					list2.runAnimAt = now
					list2.runAnimOn = true

					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if humanoid then
						pcall(_G.__FarmRunAnim, humanoid, root, true, planarSpeed)
					end

					-- turn to face the way we are moving (yaw only), so the run does not look sideways
					local torso = character and character:FindFirstChild("UpperTorso")
					local gyro = torso and torso:FindFirstChild("ODH Auto Farm BodyGyro")

					if gyro then
						gyro.CFrame = CFrame.new(root.Position, root.Position + planar)
					end
				end
			elseif list2.runAnimOn then
				list2.runAnimOn = false
				pcall(_G.__FarmRunAnim, nil, nil, false)
			end
		end)
	end

