		local active = 0

		for _, on in pairs(list2.boxOn) do
			if on then
				active = active + 1
			end
		end

		local statusLine

		if active == 0 then
			statusLine = stat.error or "Idle"
		else
			statusLine = stat.status or "Starting..."

			if active > 1 then
				statusLine = statusLine .. string.format("  (%d boxes running)", active)
			end
		end

		local lastLine = "-"

		if stat.last then
			lastLine = stat.last.name .. (stat.last.rarity and (" (" .. stat.last.rarity .. ")") or "") .. " from " .. stat.last.box
		end

		local text = string.format("Status: %s\nOpened this session: %d\nLast reward: %s", statusLine, stat.opened, lastLine)
		local breakdown = {}

		for _, boxe in ipairs(list2.BOXES) do
			local count = stat.perBox[boxe[1]]

			if count and count > 0 then
				breakdown[#breakdown + 1] = boxe[2] .. " x" .. count
			end
		end

