	-- ===== WHEN THE BAG IS FULL: Shoot Murderer -> Fling Murderer -> Reset Character =====
	-- The three switches (Farm tab) can be combined. When the bag fills up, every switch that is ON runs
	-- one after the other, automatically, in this order:
	--   1. Shoot Murderer  (only when you hold the gun)
	--   2. Fling Murderer  (only when you are not the murderer)
	--   3. Reset Character (kills your character, so you respawn with an empty bag)
	-- A step that cannot run (no gun, no murderer, you are the murderer...) is skipped and the next one goes on.
	list2.bagShoot = false
	list2.bagFling = false
	list2.bagReset = false
	list2.bagSeqBusy = false
	list2.bagSeqFired = false
	list2.bagSeqLoop = false

	list2.bagSeqNotify = function(title, text, icon)
		pcall(function()
			obj2:Notify({ Title = title, Content = text, Duration = 2.5, Icon = icon })
		end)
	end

	-- false once the script was closed / reloaded, so the loops below stop on their own
	list2.bagSeqAlive = function()
		return _G.FVLV2 == obj3
	end

	list2.bagSeqAnyOn = function()
		return list2.bagShoot or list2.bagFling or list2.bagReset
	end

	-- step 1: shoot the murderer until he is down (max 25 s)
	list2.bagSeqShoot = function()
		if func16() ~= localPlayer then
			return false, "You do not hold the gun"
		end

		local murderer = func15()

		if not murderer or murderer == localPlayer or not murderer.Character then
			return false, "No murderer to shoot"
		end

		local shots = 0
		local deadline = os.clock() + 25

		while os.clock() < deadline and list2.bagSeqAlive() and list2.bagShoot do
			murderer = func15()

			if not murderer or not murderer.Character or list2.isPlayerDead(murderer) then
				return true, "Murderer down after " .. shots .. " shot(s)"
			end

			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")

			if not humanoid or humanoid.Health <= 0 or func16() ~= localPlayer then
				break
			end

			local gun = character:FindFirstChild("Gun")

			if not gun then
				local backpack = localPlayer:FindFirstChildOfClass("Backpack")
				local tool = backpack and backpack:FindFirstChild("Gun")

				if tool then
					pcall(function()
						humanoid:EquipTool(tool)
					end)
					task.wait(0.1)
					gun = character:FindFirstChild("Gun")
				end
			end

			local shoot = gun and gun:FindFirstChild("Shoot")
			local fired = false

			if shoot and shoot:IsA("RemoteEvent") and list2.saShoot then
				-- follows the Silent Aim Type; after 3 shots that did not kill, it also shoots through walls
				local ok, result = pcall(list2.saShoot, shoot, character, murderer, {
					wallbang = list2.wallbang or shots >= 3,
				})

				fired = ok and result == true
			end

			if fired then
				shots = shots + 1
				task.wait(1)
			else
				task.wait(0.4)
			end
		end

		murderer = func15()

		if not murderer or not murderer.Character or list2.isPlayerDead(murderer) then
			return true, "Murderer down after " .. shots .. " shot(s)"
		end

		return false, shots > 0 and "Shot fired, murderer still alive" or "Could not land a shot"
	end

	-- step 2: fling the murderer (waits for a fling that is already running)
	list2.bagSeqFlingMurderer = function()
		local murderer = func15()

		if not murderer or murderer == localPlayer or not murderer.Character or list2.isPlayerDead(murderer) then
			return false, "No murderer to fling"
		end

		local waited = tick()

		while flag33 and tick() - waited < 12 do
			task.wait(0.1)
		end

		murderer = func15()

		if not murderer or murderer == localPlayer or not murderer.Character then
			return false, "No murderer to fling"
		end

		pcall(func27, murderer)

		local started = tick()

		task.wait(0.15)

		while flag33 and list2.bagSeqAlive() and tick() - started < 12 do
			task.wait(0.1)
		end

		return true, "Flung " .. murderer.Name
	end

	-- step 3: reset the character
	list2.bagSeqResetCharacter = function()
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")

		if not humanoid or humanoid.Health <= 0 then
			return false, "Already dead"
		end

		pcall(function()
			humanoid.PlatformStand = false
		end)
		pcall(function()
			humanoid.Health = 0
		end)

		if humanoid.Health > 0 then
			pcall(function()
				character:BreakJoints()
			end)
		end

		return true, "Character reset"
	end

	-- runs every enabled step in order
	list2.bagSeqRun = function()
		list2.bagSeqBusy = true

		local report = {}

		-- the older "Fling Murderer When Done" must not fling a second time
		if list2.bagFling then
			list2.flingDoneFired = true
		end

		local function runStep(enabled, title, icon, fn)
			if not enabled() or not list2.bagSeqAlive() then
				return
			end

			local ok, done, message = pcall(fn)

			if not ok then
				message = done
				done = false
			end

			list2.bagSeqNotify(title, tostring(message or ""), done and icon or "x")
			report[#report + 1] = list2.fld((title:gsub("^Bag Full: ", "")), (done and "Done - " or "Skipped - ") .. tostring(message or ""), false)
			task.wait(0.3)
		end

		runStep(function()
			return list2.bagShoot
		end, "Bag Full: Shoot Murderer", "crosshair", list2.bagSeqShoot)

		runStep(function()
			return list2.bagFling
		end, "Bag Full: Fling Murderer", "flame", list2.bagSeqFlingMurderer)

		runStep(function()
			return list2.bagReset and not list2.inLobbyNow()
		end, "Bag Full: Reset Character", "rotate-ccw", list2.bagSeqResetCharacter)

		-- tell the Discord webhook (when one is set up) what happened
		if #report > 0 and list2.whReady and list2.whReady() then
			report[#report + 1] = list2.fld("Mode", tostring(list2.farmMode or "Coins"))

			pcall(list2.whPost, {
				title = "Bag Full - Auto Actions",
				body = "The bag filled up and the actions you enabled ran in order.",
				fields = report,
			})
		end

		list2.bagSeqBusy = false
	end

	-- Is the bag full right now? Reads the game's own "full bag" icon first (the same thing the game shows
	-- on screen), then falls back to the bag counter the farm uses.
	list2.bagIsFull = function()
		if list2.inLobbyNow() then
			return false
		end

		local full = false

		pcall(function()
			local container = localPlayer.PlayerGui.MainGUI.Game.CoinBags.Container

			for _, child in ipairs(container:GetChildren()) do
				local icon = child:FindFirstChild("FullBagIcon")

				if icon and icon.Visible then
					full = true
					return
				end

				local fullLabel = child:FindFirstChild("Full")

				if fullLabel and fullLabel.Visible and child:IsA("GuiObject") and child.Visible then
					full = true
					return
				end
			end
		end)

		if full then
			return true
		end

		local ok, held = pcall(func57)

		return ok and type(held) == "number" and held > 0 and held >= list2.bagLimit()
	end

	-- starts the sequence once per full bag (called by the watcher below AND by the farm's own "bag is full" branch)
	list2.bagSeqTrigger = function()
		if not list2.bagSeqAnyOn() or list2.bagSeqFired or list2.bagSeqBusy then
			return
		end

		if os.clock() < (list2.bagSeqCooldown or 0) then
			return
		end

		local humanoid = localPlayer.Character and localPlayer.Character:FindFirstChildOfClass("Humanoid")

		if not humanoid or humanoid.Health <= 0 then
			return
		end

		list2.bagSeqFired = true

		local names = {}

		if list2.bagShoot then
			names[#names + 1] = "Shoot"
		end

		if list2.bagFling then
			names[#names + 1] = "Fling"
		end

		if list2.bagReset then
			names[#names + 1] = "Reset"
		end

		list2.bagSeqNotify("Bag Full!", table.concat(names, " > "), "backpack")

		task.spawn(function()
			local ok, err = pcall(list2.bagSeqRun)

			if not ok then
				warn("[Bag Full] " .. tostring(err))
				list2.bagSeqBusy = false
			end

			list2.bagSeqCooldown = os.clock() + 5
		end)
	end

	-- watcher (works with or without the autofarm): re-arms when the bag is empty again / in the lobby
	list2.bagSeqStart = function()
		if list2.bagSeqLoop then
			return
		end

		list2.bagSeqLoop = true

		task.spawn(function()
			while list2.bagSeqAlive() and list2.bagSeqAnyOn() do
				task.wait(0.3)

				local ok, err = pcall(function()
					if list2.bagIsFull() then
						list2.bagSeqTrigger()
					else
						list2.bagSeqFired = false
					end
				end)

				if not ok and err ~= list2.bagSeqLastErr then
					list2.bagSeqLastErr = err
					warn("[Bag Full] watcher: " .. tostring(err))
				end
			end

			list2.bagSeqLoop = false
		end)
	end
end

local flag78
flag78 = false
list2.wallbang = false

-- Every gun shot goes through these two. The bullet always LEAVES THE GUN: it starts at the gun's muzzle (the
-- GunRaycastAttachment on your root part, or your right hand if there is none). When a shot has to start somewhere
-- else (through walls / right beside the target) the muzzle itself is moved there first, so the bullet still
-- comes out of the gun, then the muzzle is put back.
list2.gunMuzzle = function(character)
	local hrp = character and character:FindFirstChild("HumanoidRootPart")

	if not hrp then
		return nil
	end

	local attachment = hrp:FindFirstChild("GunRaycastAttachment")

	if attachment then
		return attachment.WorldCFrame, attachment
	end

	local hand = character:FindFirstChild("RightHand")

	return CFrame.new(hand and hand.Position or hrp.Position), nil
end

-- Always-hit-murderer: returns the (lead-predicted) point on the murderer's body, or nil when there is no
-- valid murderer (no round / you are the murderer / he is dead), in which case the original aim is kept.
-- how far (studs) the script will shoot the murderer from. math.huge = no limit.
list2.shootRange = math.huge

-- ===== Whitelist =====
-- white = players that Auto Shoot, Silent Aim (every auto-aimed shot), Triggerbot and Kill Aura never attack
-- Everything lives in list2.wb so it costs no extra locals.
list2.wb = { white = {}, friends = false, friendCache = {}, friendBusy = {} }

-- matches the account name or the display name
list2.wb.has = function(set, player)
	if not player then
		return false
	end

	return set[player.Name:lower()] == true or set[tostring(player.DisplayName or ""):lower()] == true
end

list2.wb.active = function()
	local wb = list2.wb

	return wb.friends or next(wb.white) ~= nil
end

-- asks Roblox once per player (it yields), so the loops below only ever read the cache
list2.wb.queryFriend = function(player)
	local wb = list2.wb

	if not player or player == localPlayer or wb.friendCache[player.UserId] ~= nil or wb.friendBusy[player.UserId] then
		return
	end

	wb.friendBusy[player.UserId] = true

	task.spawn(function()
		local ok, result = pcall(function()
			return localPlayer:IsFriendsWith(player.UserId)
		end)

		wb.friendCache[player.UserId] = ok and result == true
		wb.friendBusy[player.UserId] = nil
	end)
end

list2.wb.isWhite = function(player)
	local wb = list2.wb

	if not player or player == localPlayer then
		return false
	end

	if wb.has(wb.white, player) then
		return true
	end

	if wb.friends then
		local cached = wb.friendCache[player.UserId]

		if cached == nil then
			wb.queryFriend(player)

			return true -- not known yet: protect them until Roblox answers
		end

		return cached
	end

	return false
end

-- Who the gun features shoot. Normally that is the murderer (func15); in Zombie rounds it is one of many zombies.
--   * white-listed players are never returned (nil = nobody to shoot, the shot stays a normal shot)
--   * otherwise the usual pick is kept
-- Innocents are never picked: shooting them would only hurt you.
list2.gunTarget = function()
	local default = func15 and func15() or nil
	local wb = list2.wb

	if not wb.active() or default == localPlayer then
		return default
	end

	local pool = {}

	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= localPlayer and list2.isMurderer(player) and not wb.isWhite(player) then
			local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")

			if humanoid and humanoid.Health > 0 then
				pool[#pool + 1] = player
			end
		end
	end

	if #pool == 0 then
		return nil
	end

	for _, player in ipairs(pool) do
		if player == default then
			return default
		end
	end

	local myRoot = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
	local best, bestDist = nil, math.huge

	for _, player in ipairs(pool) do
		local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
		local dist = (myRoot and root) and (root.Position - myRoot.Position).Magnitude or math.huge

		if not best or dist < bestDist then
			best, bestDist = player, dist
		end
	end

	return best
end

list2.murdererAimPoint = function()
	local ok, point = pcall(function()
		local murderer
		if list2.gunTarget then
			murderer = list2.gunTarget()
		else
			murderer = func15 and func15()
		end

		if not murderer or murderer == localPlayer or not murderer.Character then
			return nil
		end

		local humanoid = murderer.Character:FindFirstChildOfClass("Humanoid")

		if not humanoid or humanoid.Health <= 0 then
			return nil
		end

		local root = murderer.Character:FindFirstChild("HumanoidRootPart")

		if not root then
			return nil
		end

		return list2.aimAt(murderer, root) or root.Position
	end)

	return ok and point or nil
end

-- When you stand pressed against a wall the gun's muzzle (GunRaycastAttachment / hand) sits INSIDE the wall, so the
-- bullet hits the wall the moment it leaves the gun, even though the murderer can be seen. If the muzzle is
-- blocked but a spot on your own body has a clear line to the murderer, the shot starts from that spot instead.
-- Returns nil when nothing needs changing (muzzle already clear) or when the murderer really is behind a wall.
list2.freeStart = function(character, startCF)
	local ok, result = pcall(function()
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		local murderer
		if list2.gunTarget then
			murderer = list2.gunTarget()
		else
			murderer = func15 and func15()
		end
		local mChar = murderer and murderer.Character
		local tHrp = mChar and mChar:FindFirstChild("HumanoidRootPart")

		if not hrp or not tHrp or not startCF then
			return nil
		end

		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { character, mChar }
		params.RespectCanCollide = true
		params.IgnoreWater = true

		local targetPos = tHrp.Position

		local function blocked(from)
			local delta = targetPos - from

			if delta.Magnitude < 0.5 then
				return false
			end

			return workspace:Raycast(from, delta, params) ~= nil
		end

		if not blocked(startCF.Position) then
			return nil
		end

		local base = hrp.Position
		local away = Vector3.new(base.X - targetPos.X, 0, base.Z - targetPos.Z)
		local back = away.Magnitude > 0.1 and away.Unit or Vector3.zero

		local candidates = {
			base,
			base + Vector3.new(0, 1.5, 0),
			base + Vector3.new(0, -1.2, 0),
			base + back * 1,
			base + Vector3.new(0, 1.5, 0) + back * 1,
		}

		for _, point in ipairs(candidates) do
			if not blocked(point) then
				return CFrame.new(point)
			end
		end

		return nil
	end)

	return ok and result or nil
end

list2.fireGun = function(shoot, character, aimPos, startCF, ownOrigin)
	local origAim, origStart = aimPos, startCF -- untouched copies, used when AimBot Type = Flick Shot
	local muzzle, attachment = list2.gunMuzzle(character)
	startCF = startCF or muzzle

	-- every gun shot (Shoot Murderer, Silent Aim, Triggerbot, Auto Shoot, TP Shoot, buttons, keybinds)
	-- passes through here, so overriding the aim point here makes ALL of them hit the murderer directly
	-- ESP dot menu shoots a chosen player, so it switches the murderer redirect off for its own shots
	local murdererPoint = (not list2.fireNoOverride) and list2.murdererAimPoint() or nil

	if murdererPoint then
		aimPos = murdererPoint

		local sa = list2.sa

		-- ownOrigin = the caller (TP Shoot) already chose where the shot starts, so the shared Silent Aim
		-- "Piercing" origin must not replace it
		if not ownOrigin and sa and ((sa.ignoresWalls and sa.ignoresWalls()) or (sa.usesOrigin and sa.usesOrigin())) and sa.origin and os.clock() - sa.originT < 0.25 then
			startCF = sa.origin
		end
	end

	if not shoot or not startCF or not aimPos then
		return false
	end

	-- AimBot Type = Flick Shot: the camera / mouse flicks to the murderer, THEN the shot is fired, then it returns.
	-- TP Shoot and the Rage burst (ownOrigin) keep firing directly.
	local flick = list2.flick
	if murdererPoint and not ownOrigin and flick and flick.type == "Flick Shot" and not flick.bypass then
		if flick.active and os.clock() - flick.startedAt > 1.5 then
			flick.active = false -- watchdog: a flick that never finished must not block every later shot
		end
		if flick.active then
			return false
		end
		return flick.run(shoot, character, origAim or aimPos, origStart)
	end

	-- standing flush against a wall: the muzzle is inside it, so start the bullet from a clear spot on the body
	if startCF == muzzle and not list2.fireNoOverride then
		local clearCF = list2.freeStart(character, startCF)

		if clearCF then
			startCF = clearCF
		end
	end

	local moved = attachment and startCF ~= muzzle
	local original = attachment and attachment.CFrame

	if moved then
		pcall(function()
			attachment.WorldCFrame = startCF
		end)
	end

	local ok = pcall(function()
		shoot:FireServer(startCF, CFrame.new(aimPos))
	end)

	if moved then
		task.delay(0.15, function()
			pcall(function()
				attachment.CFrame = original
			end)
		end)
	end

	return ok
end


-- ============================================================================
-- AimBot Type: Classic / Flick Shot (ported from Qwern X)
--   Classic    = unchanged: the shot is fired straight away (Silent Aim / Aimlock as before)
--   Flick Shot = the view flicks onto the murderer, the shot is fired, then the view goes back
--   Flick Speed (1-10) sets how fast, Flick With Mouse moves the real mouse (mousemoverel) instead of the
--   camera, Flick Return % says how much of the flick is undone afterwards.
-- ============================================================================
list2.flick = {
	type = "Classic",
	speed = 6,
	mouse = true,
	returnPct = 100,
	active = false,
	startedAt = 0,
	bypass = false,
}

do
	local flick = list2.flick

	flick.duration = function()
		return math.clamp(0.35 - flick.speed * 0.032, 0.02, 0.35)
	end

	-- keeps following the murderer's predicted point while the flick is in progress
	flick.target = function(fallback)
		local ok, point = pcall(list2.murdererAimPoint)
		if ok and point then
			return point
		end
		return fallback
	end

	flick.sequence = function(shoot, character, aimPos, startCF, state)
		local camera = workspace.CurrentCamera
		if not camera then
			return
		end
		local dur = flick.duration()
		local retFrac = math.clamp(flick.returnPct / 100, 0, 1)
		local uis = game:GetService("UserInputService")

		local function alive()
			local hum = character and character.Parent and character:FindFirstChildOfClass("Humanoid")
			return hum ~= nil and hum.Health > 0
		end

		local function fire()
			if state.fired then
				return
			end
			state.fired = true
			flick.bypass = true
			pcall(list2.fireGun, shoot, character, aimPos, startCF)
			flick.bypass = false
		end

		-- ---------------- mouse flick (needs mousemoverel) ----------------
		if flick.mouse and type(mousemoverel) == "function" then
			local inset = Vector2.new(0, 36)
			pcall(function()
				inset = game:GetService("GuiService"):GetGuiInset()
			end)

			local function crosshair()
				if uis.MouseBehavior == Enum.MouseBehavior.LockCenter then
					local size = camera.ViewportSize
					return size.X * 0.5, size.Y * 0.5
				end
				local m = uis:GetMouseLocation()
				return m.X, m.Y - inset.Y
			end

			local sumX, sumY = 0, 0
			local t0, frame = os.clock(), 1 / 60

			while alive() do
				local viewport, onScreen = camera:WorldToViewportPoint(flick.target(aimPos))
				if not onScreen then
					break
				end
				local cx, cy = crosshair()
				local framesLeft = math.max(1, math.ceil((dur - (os.clock() - t0)) / frame))
				local dx, dy = (viewport.X - cx) / framesLeft, (viewport.Y - cy) / framesLeft
				sumX += dx
				sumY += dy
				pcall(mousemoverel, dx, dy)
				frame = math.max(RunService.RenderStepped:Wait(), 1 / 240)
				if framesLeft <= 1 then
					break
				end
			end

			if alive() then
				fire()
			end

			if retFrac > 0 and (sumX ~= 0 or sumY ~= 0) then
				local steps = math.max(1, math.ceil(dur * 60))
				local backX, backY = -sumX * retFrac / steps, -sumY * retFrac / steps
				for _ = 1, steps do
					if not alive() then
						break
					end
					pcall(mousemoverel, backX, backY)
					RunService.RenderStepped:Wait()
				end
			end
			return
		end

		-- ---------------- camera flick ----------------
		local name = "FVLFlickShot"
		local startLook = camera.CFrame.LookVector
		local phase, t0, t3, holdLook = 1, os.clock(), 0, startLook

		local function rot(pos, look)
			return CFrame.lookAt(pos, pos + look)
		end

		RunService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 1, function()
			local cam = workspace.CurrentCamera
			if not cam then
				return
			end
			local pos = cam.CFrame.Position
			if phase == 1 then
				local p = math.clamp((os.clock() - t0) / dur, 0, 1)
				local tp = flick.target(aimPos)
				local look = (tp - pos).Magnitude > 0.05 and (tp - pos).Unit or holdLook
				holdLook = look
				cam.CFrame = rot(pos, startLook):Lerp(rot(pos, look), p)
			elseif phase == 2 then
				cam.CFrame = rot(pos, holdLook)
			else
				local p = math.clamp((os.clock() - t3) / dur, 0, 1)
				local back = rot(pos, holdLook):Lerp(rot(pos, startLook), retFrac)
				cam.CFrame = rot(pos, holdLook):Lerp(back, p)
			end
		end)

		while alive() and os.clock() - t0 < dur do
			RunService.RenderStepped:Wait()
		end
		phase = 2
		RunService.RenderStepped:Wait()
		if alive() then
			fire()
		end
		if retFrac > 0 and alive() then
			t3 = os.clock()
			phase = 3
			while alive() and os.clock() - t3 < dur do
				RunService.RenderStepped:Wait()
			end
		end
		pcall(function()
			RunService:UnbindFromRenderStep(name)
		end)
	end

	-- starts the flick and returns at once (callers only need "was a shot started")
	flick.run = function(shoot, character, aimPos, startCF)
		flick.active = true
		flick.startedAt = os.clock()
		local myStart = flick.startedAt
		task.spawn(function()
			local state = { fired = false }
			pcall(flick.sequence, shoot, character, aimPos, startCF, state)
			pcall(function()
				RunService:UnbindFromRenderStep("FVLFlickShot")
			end)
			-- the flick failed before shooting: never lose the click, fire normally
			if not state.fired and character and character.Parent then
				flick.bypass = true
				pcall(list2.fireGun, shoot, character, aimPos, startCF)
				flick.bypass = false
			end
			if flick.startedAt == myStart then
				flick.active = false
			end
		end)
		return true
	end
end

list2.velTrack = {}
list2.aimLead = 0.16

list2.startVelTracker = function()
	if list2.velConn then
		return
	end

	list2.velConn = RunService.Heartbeat:Connect(function()
		local now = os.clock()

		for _, player in ipairs(Players:GetPlayers()) do
			local humanoidRootPart = player.Character and player.Character:FindFirstChild("HumanoidRootPart")

			if not humanoidRootPart then
				list2.velTrack[player] = nil
			else
				local num13 = list2.velTrack[player]

				if not num13 then
					list2.velTrack[player] = { p = humanoidRootPart.Position, t = now, v = Vector3.zero }
				elseif now - num13.t >= 0.03 then
					num13.v = (humanoidRootPart.Position - num13.p) / (now - num13.t)
					num13.p = humanoidRootPart.Position
					num13.t = now
				end
			end
		end

		if list2.sa then
			pcall(list2.sa.sample)
		end
	end)
end

list2.stopVelTracker = function()
	if list2.velConn then
		pcall(function()
			list2.velConn:Disconnect()
		end)
	end

	list2.velConn = nil
	list2.velTrack = {}
end

list2.leadTime = function()
	local aimLead = tonumber(_G.__FVL_AIMLEAD) or list2.aimLead

	local ok, result = pcall(function()
		return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
	end)

	local flag79 = ok and type(result) == "number" and result > 0 and result < 1
	local n3 = 0.04

	if flag79 then
		n3 = result
	end

	return math.clamp(n3 + aimLead, 0, 0.3)
end

list2.aimAt = function(obj, part3)
	local humanoid = obj.Character and obj.Character:FindFirstChildOfClass("Humanoid")
	local n3

	if humanoid and humanoid.MoveDirection.Magnitude > 0.1 then
		n3 = humanoid.MoveDirection.Unit * humanoid.WalkSpeed
	else
		n3 = part3.AssemblyLinearVelocity or Vector3.zero

		if n3.Magnitude < 0.5 then
			local flag80 = list2.velTrack[obj]

			if flag80 and flag80.v.Magnitude >= 0.5 then
				n3 = flag80.v
			end
		end
	end

	if n3.Magnitude < 0.5 then
		return part3.Position
	end
	local num14 = list2.leadTime()
	local n4 = part3.Position + Vector3.new(n3.X, 0, n3.Z) * num14
	local n5 = n4 - part3.Position

	if n5.Magnitude > 8 then
		n4 = part3.Position + n5.Unit * 8
	end

	_G.__FVL_AIM = { aim = n4, targetPos = part3.Position, vel = n3, lead = num14, t = os.clock() }
	return n4
end

-- ============================================================================
-- Silent Aim Type (ported from snpware): Piercing only (Default / Dynamic / Rage removed)
--   Default  = simple velocity lead
--   Dynamic  = ping + intent + turn aware prediction (default)
--   Piercing = Dynamic prediction, but the shot starts BEHIND the target
--   Rage     = Rage Shoot (from Star Hub): Dynamic prediction, the shot starts right next to the target
--              (walls ignored) and fires up to 4 shots, each at a different body part, until he is down
-- list2.aimAt below uses this; the old lead logic stays as a fallback.
-- ============================================================================
list2.sa = {
	-- Piercing and Rage both start the shot somewhere else than the muzzle and skip the wall check
	ignoresWalls = function()
		local t = list2.sa.type
		return t == "Piercing" or t == "Rage"
	end,
	modes = { "Piercing", "Rail Lead", "Direct Lock", "Adaptive Resolver", "Qwern X" },
	legacy = { Pro = "Piercing", ["Dynamic 1"] = "Piercing", Hacker = "Piercing", Default = "Piercing", Dynamic = "Piercing", Rage = "Piercing" },
	type = "Piercing",
	hist = {},
	lastUserId = nil,
	lastVel = Vector3.zero,
	lastJumpTick = 0,
	origin = nil,
	originT = 0,
	overshoot = 4,
	piercingBack = 4,
	rageShots = 4,
	rageDelay = 0.22,
	rageLift = 1.5,
	rageBusy = false,
	-- Wall Resolver (Star Hub): when the predicted point is hidden behind a wall, aim at a body part you can see
	wallResolve = true,
	resolveParts = { "UpperTorso", "Head", "HumanoidRootPart", "Torso", "LowerTorso", "RightUpperArm", "LeftUpperArm", "RightHand", "LeftHand", "RightUpperLeg", "LeftUpperLeg", "RightLowerLeg", "LeftLowerLeg" },
	rageBody = { "UpperTorso", "HumanoidRootPart", "Torso", "Head", "LowerTorso", "RightUpperArm", "LeftUpperArm", "RightUpperLeg", "LeftUpperLeg" },
	TURN_WINDOW = 0.12,
	TURN_MIN_SPEED = 1.5,
	HIST_SPAN = 1,
	tune = {
		pingScale = 1, base = 0.113, minLead = 0.02, maxLead = 0.6,
		airExtra = 0, turnBoost = 0, turnGate = 0.15,
		intentBlend = 0.85, intentBlendAir = 0.5,
		straightScale = 1, turnScale = 1,
		airAimHeight = 5, fallMargin = 2, gravityScale = 1, yBias = 0, floorClamp = 1.2,
		predExtra = 0, -- Prediction (ms) slider: extra lead in seconds, added on top of every Silent Aim Type
	},
	predictors = {},
}

do
	local sa = list2.sa

	local function flat(v)
		return Vector3.new(v.X, 0, v.Z)
	end

	local function safeUnit(v)
		if v.Magnitude < 0.001 then
			return Vector3.zero
		end
		return v.Unit
	end

	sa.normalize = function(v)
		if type(v) == "table" then
			v = v[1] or v.Value
		end
		if type(v) ~= "string" then
			return "Piercing"
		end
		if sa.legacy[v] then
			return sa.legacy[v]
		end
		for _, m in ipairs(sa.modes) do
			if v == m then
				return v
			end
		end
		return "Piercing"
	end

	local function turnBetween(a, b)
		if a.Magnitude < sa.TURN_MIN_SPEED or b.Magnitude < sa.TURN_MIN_SPEED then
			return 0
		end
		return 1 - math.clamp(a.Unit:Dot(b.Unit), -1, 1)
	end

	local function velAgo(dt)
		local h = sa.hist
		if #h == 0 then
			return nil
		end
		local now = os.clock()
		if sa.TURN_WINDOW < now - h[#h][1] then
			return nil
		end
		local want = now - dt
		for i = #h, 1, -1 do
			if h[i][1] <= want then
				return Vector3.new(h[i][2], h[i][3], h[i][4])
			end
		end
		return Vector3.new(h[1][2], h[1][3], h[1][4])
	end

	-- called every Heartbeat (from the velocity tracker) to keep the murderer's recent velocity
	sa.sample = function()
		local m = func15 and func15()
		if not m or m == localPlayer then
			return
		end
		local root = m.Character and m.Character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local vel = root.AssemblyLinearVelocity
		if sa.lastUserId ~= m.UserId then
			sa.lastUserId = m.UserId
			table.clear(sa.hist)
			sa.lastVel = vel
		end
		if sa.lastVel.Y <= 1 and vel.Y > 20 then
			sa.lastJumpTick = tick()
		end
		sa.lastVel = vel
		local now = os.clock()
		local histVel = vel
		if sa.resolver then
			local mHum = m.Character:FindFirstChildOfClass("Humanoid")
			histVel = sa.resolveVelocity(m, vel, mHum ~= nil and mHum.FloorMaterial == Enum.Material.Air)
		end
		table.insert(sa.hist, { now, histVel.X, histVel.Y, histVel.Z })
		while #sa.hist > 0 and now - sa.hist[1][1] > sa.HIST_SPAN do
			table.remove(sa.hist, 1)
		end
	end


	-- ===== Resolver (ported from Qwern X): the target's REAL velocity from his position history =====
	-- The replicated AssemblyLinearVelocity can be faked (velocity spoof, desync, jitter). With Resolver on, the
	-- velocity used by every Silent Aim Type comes from a least-squares fit of his last ~0.4s of positions
	-- (outlier samples thrown away), so the lead follows where he really goes, not what the game reports.
	sa.resolver = false
	sa.posHist = {}
	sa.RESOLVER_WINDOW = 0.4
	sa.RESOLVER_KEEP = 1.2

	sa.setResolver = function(on)
		on = on and true or false
		sa.resolver = on
		if on and not sa.resolverConn then
			sa.resolverConn = RunService.Heartbeat:Connect(function()
				local now = os.clock()
				for _, plr in ipairs(Players:GetPlayers()) do
					if plr ~= localPlayer then
						local root = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
						local h = sa.posHist[plr.UserId]
						if root then
							if not h then
								h = {}
								sa.posHist[plr.UserId] = h
							end
							local last = h[#h]
							local pos = root.Position
							-- only keep real changes (replication repeats positions); a refresh every 0.2s
							-- while he stands still so a standing target fits to zero speed
							if not last or pos ~= last.p or now - last.t > 0.2 then
								h[#h + 1] = { t = now, p = pos }
							end
							while #h > 0 and now - h[1].t > sa.RESOLVER_KEEP do
								table.remove(h, 1)
							end
						elseif h then
							sa.posHist[plr.UserId] = nil
						end
					end
				end
			end)
			list2.conns[#list2.conns + 1] = sa.resolverConn
		elseif not on then
			if sa.resolverConn then
				pcall(function()
					sa.resolverConn:Disconnect()
				end)
				sa.resolverConn = nil
			end
			table.clear(sa.posHist)
		end
	end

	-- least squares: position = base + vel * (t - now)
	sa.regress = function(h, list, now)
		local n, st, stt = #list, 0, 0
		local sp, spt = Vector3.zero, Vector3.zero
		for _, i in ipairs(list) do
			local dt = h[i].t - now
			st += dt
			stt += dt * dt
			sp += h[i].p
			spt += h[i].p * dt
		end
		local den = n * stt - st * st
		local vel = den > 1e-9 and (spt * n - sp * st) / den or Vector3.zero
		return (sp - vel * st) / n, vel
	end

	-- returns the resolved velocity, or the replicated one when there is not enough history yet
	sa.resolveVelocity = function(player, replicated, air)
		local h = player and sa.posHist[player.UserId]
		if not h or #h < 6 then
			return replicated
		end
		local now = os.clock()
		local list = {}
		for i = #h, 1, -1 do
			if now - h[i].t > sa.RESOLVER_WINDOW then
				break
			end
			table.insert(list, 1, i)
		end
		if #list < 6 then
			return replicated
		end
		local base, vel = sa.regress(h, list, now)
		-- drop samples far from the fitted line (teleports / desync spikes) and fit again
		local res, sorted = {}, {}
		for k, i in ipairs(list) do
			res[k] = (h[i].p - (base + vel * (h[i].t - now))).Magnitude
			sorted[k] = res[k]
		end
		table.sort(sorted)
		local median = sorted[math.ceil(#sorted / 2)] or 0
		local kept = {}
		for k, i in ipairs(list) do
			if res[k] <= median * 3 + 3 then
				kept[#kept + 1] = i
			end
		end
		if #kept >= 6 and #kept < #list then
			base, vel = sa.regress(h, kept, now)
		end
		local horizontal = Vector3.new(vel.X, 0, vel.Z)
		if horizontal.Magnitude > 150 then
			horizontal = horizontal.Unit * 150
		end
		return Vector3.new(horizontal.X, air and math.clamp(vel.Y, -60, 60) or 0, horizontal.Z)
	end

	local function buildState(player, myChar)
		local char = player and player.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not (root and hum) then
			return nil
		end
		local vel = root.AssemblyLinearVelocity
		local jumpAge = tick() - sa.lastJumpTick
		local recentJump = jumpAge < 0.18
		local okState, state = pcall(function()
			return hum:GetState()
		end)
		local inAir = okState and (state == Enum.HumanoidStateType.Jumping or state == Enum.HumanoidStateType.Freefall)

		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { char, myChar or localPlayer.Character }
		params.IgnoreWater = true
		local hit = workspace:Raycast(root.Position, Vector3.new(0, -80, 0), params)
		local velPast = velAgo(sa.TURN_WINDOW) or vel
		local standHeight = math.clamp(hum.HipHeight + root.Size.Y * 0.5, 0.5, 8)

		-- Humanoid state / FloorMaterial are unreliable for other players' characters (a murderer standing still
		-- is often reported as "in the air"), so trust the real distance to the floor and the real velocity too.
		local airborne = inAir or hum.FloorMaterial == Enum.Material.Air or recentJump
		local grounded = hit ~= nil and (root.Position.Y - hit.Position.Y) <= standHeight + 1.5 and math.abs(vel.Y) < 8 and not recentJump

		if grounded then
			airborne = false
		end

		-- Resolver: trust where he really moved (position history), not the replicated velocity. If he is not
		-- really moving, his MoveDirection (the 'intent' part of Dynamic) is ignored too.
		local moveDir = hum.MoveDirection
		if sa.resolver then
			vel = sa.resolveVelocity(player, vel, airborne)
			if flat(vel).Magnitude < 1.5 then
				moveDir = Vector3.zero
			end
		end

		return {
			pos = root.Position,
			vel = vel,
			moveDir = moveDir,
			walkSpeed = hum.WalkSpeed,
			jumpPower = hum.UseJumpPower and hum.JumpPower or (hum.JumpHeight * 2 * workspace.Gravity) ^ 0.5,
			speed = flat(vel).Magnitude,
			look = flat(root.CFrame.LookVector),
			turn = turnBetween(flat(vel), flat(velPast)),
			jumpAge = jumpAge,
			air = airborne,
			sitting = hum.Sit or hum.PlatformStand,
			floorY = hit and hit.Position.Y or nil,
			standHeight = standHeight,
			ping = localPlayer:GetNetworkPing(),
		}
	end

	sa.predictors.Default = function(st, tune)
		if st.vel.Magnitude == 0 then
			return st.pos, 0
		end
		local d = st.vel / 16.5
		-- Prediction (ms) slider: extra horizontal lead on top of the original lead (which stays exactly as it was)
		local extra = st.vel * ((tune or sa.tune).predExtra or 0)
		local y = math.clamp(d.Y, -2, 2.65)
		return st.pos + Vector3.new(d.X + extra.X, y, d.Z / 1.25 + extra.Z), 0
	end

	sa.predictors.Dynamic = function(st, tune)
		tune = tune or sa.tune
		if st.sitting then
			return st.pos, 0
		end
		-- standing still: nothing to predict, aim exactly at him (never above his head)
		if not st.air and st.speed < 0.5 and math.abs(st.vel.Y) < 1 then
			return st.pos, 0
		end
		local lead = st.ping * tune.pingScale + tune.base
		if st.air then
			lead += tune.airExtra
		end
		if tune.turnGate < st.turn then
			lead += st.turn * tune.turnBoost
		end
		lead = math.clamp(lead, tune.minLead, tune.maxLead)
		lead += tune.predExtra or 0 -- Prediction (ms) slider, on top of the clamped lead

		local intent = st.moveDir * (st.walkSpeed > 0 and st.walkSpeed or 16)
		local blend = st.air and tune.intentBlendAir or tune.intentBlend
		local turnT = math.clamp((st.turn - tune.turnGate) / math.max(0.001, 1 - tune.turnGate), 0, 1)
		local scale = tune.straightScale + (tune.turnScale - tune.straightScale) * turnT
		local move = flat(st.vel):Lerp(flat(intent), blend) * lead * scale

		local gravity = workspace.Gravity
		local floorY = st.floorY and (st.floorY + (st.standHeight or 3)) or (st.pos.Y - tune.floorClamp)
		local jp = (st.jumpPower or 0) > 0 and st.jumpPower or 50
		local maxRise = jp * jp / (2 * gravity)
		local y
		if not st.air then
			y = st.pos.Y
		elseif maxRise + tune.fallMargin < st.pos.Y - floorY then
			y = math.max(st.pos.Y + st.vel.Y * lead - 0.5 * gravity * tune.gravityScale * lead * lead, floorY)
		else
			y = floorY + tune.airAimHeight
		end
		return Vector3.new(st.pos.X + move.X, y + tune.yBias, st.pos.Z + move.Z), lead
	end

	sa.predictors.Piercing = function(st, tune)
		return sa.predictors.Dynamic(st, tune)
	end

	sa.predictors.Rage = function(st, tune)
		return sa.predictors.Dynamic(st, tune)
	end

	local function piercingOrigin(st)
		local dir = flat(st.vel)
		if dir.Magnitude < 1 then
			dir = flat(st.moveDir)
		end
		-- Standing still: velocity and move direction are both zero, which used to put the start of the shot
		-- exactly ON the target (start == aim point = a zero-length shot, so no bullet came out). Use the
		-- direction he is facing instead so the shot always starts a few studs behind him.
		if dir.Magnitude < 0.1 then
			dir = st.look
		end
		if dir.Magnitude < 0.1 then
			dir = Vector3.new(0, 0, -1)
		end
		return CFrame.new(st.pos - safeUnit(dir) * sa.piercingBack)
	end

	local function extend(from, to)
		local d = to - from
		if d.Magnitude <= 0.001 then
			return to
		end
		return from + d + d.Unit * sa.overshoot
	end

	-- returns the aim point for the current Silent Aim Type (nil = let the old logic handle it)
	sa.resolve = function(obj, part3)
		local mode = sa.type

		-- Rail Lead / Direct Lock / Adaptive Resolver / Qwern X (ported from Pulse); if one cannot give a point yet
		-- (still warming up, no data) the normal Dynamic prediction below is used for that shot
		if sa.pulseModes and sa.pulseModes[mode] then
			local okP, aimP = pcall(sa.pulseResolve, mode, obj, part3)
			if okP and aimP then
				return aimP
			end
			sa.origin = nil
			mode = "Dynamic"
		end
		local myChar = localPlayer.Character
		local st = buildState(obj, myChar)
		if not st then
			return nil
		end
		local muzzle = list2.gunMuzzle(myChar)
		if not muzzle then
			return nil
		end
		local pred, lead = (sa.predictors[mode] or sa.predictors.Dynamic)(st, sa.tune)

		-- Wall Resolver: the middle of him is behind a wall but an arm / leg / the head sticks out -> shoot that
		-- part instead (same lead as the prediction). Piercing / Rage start the shot elsewhere, so they skip it.
		local targetChar = obj and obj.Character

		if sa.wallResolve and targetChar and not sa.ignoresWalls() then
			local rayParams = RaycastParams.new()
			rayParams.FilterType = Enum.RaycastFilterType.Exclude
			rayParams.FilterDescendantsInstances = { myChar }
			rayParams.IgnoreWater = true

			local from = muzzle.Position

			local function seen(point)
				local hit = workspace:Raycast(from, point - from, rayParams)

				return not hit
					or hit.Instance:IsDescendantOf(targetChar)
					or hit.Instance.Transparency > 0.5
					or hit.Instance.CanCollide == false
			end

			if not seen(pred) then
				local leadVec = pred - st.pos
				local moving = leadVec.Magnitude > 0.05
				local found

				for _, name in ipairs(sa.resolveParts) do
					local part = targetChar:FindFirstChild(name)

					if part and part:IsA("BasePart") then
						local right, up = part.CFrame.RightVector, part.CFrame.UpVector

						for _, offset in ipairs({
							Vector3.zero,
							up * (part.Size.Y * 0.3),
							up * (-part.Size.Y * 0.3),
							right * (part.Size.X * 0.32),
							right * (-part.Size.X * 0.32),
						}) do
							local base = part.Position + offset

							if moving and seen(base + leadVec) then
								found = base + leadVec
								break
							end

							if seen(base) then
								found = base
								break
							end
						end
					end

					if found then
						break
					end
				end

				if found then
					pred = found
				end
			end
		end

		local origin = muzzle
		sa.origin = nil
		if mode == "Piercing" then
			origin = piercingOrigin(st)
			sa.origin = origin
			sa.originT = os.clock()
		end
		local aim = extend(origin.Position, pred)
		-- never send a shot whose start and aim point are the same spot: it has no direction, so no bullet
		if (aim - origin.Position).Magnitude < 1 then
			local fwd = safeUnit(pred - origin.Position)
			if fwd == Vector3.zero then
				fwd = safeUnit(st.look)
			end
			if fwd == Vector3.zero then
				fwd = Vector3.new(0, 0, -1)
			end
			aim = origin.Position + fwd * (sa.overshoot + 1)
		end
		if mode == "Rage" then
			-- Rage Shoot: the bullet starts right next to the target, so walls in between don't matter
			origin = CFrame.new(aim + Vector3.new(0, sa.rageLift, 0))
			sa.origin = origin
			sa.originT = os.clock()
		end
		_G.__FVL_AIM = { aim = aim, targetPos = st.pos, vel = st.vel, lead = lead or 0, t = os.clock() }
		return aim
	end
end

list2.aimAtClassic = list2.aimAt

list2.aimAt = function(obj, part3)
	local ok, point = pcall(list2.sa.resolve, obj, part3)
	if ok and point then
		return point
	end
	list2.sa.origin = nil
	return list2.aimAtClassic(obj, part3)
end

-- Rage burst (Rage Shoot, now a Silent Aim Type): up to sa.rageShots shots through walls, each one at a
-- different body part, until the murderer is down. You don't move.
list2.sa.rageBurst = function(shoot, character, murderer)
	local sa = list2.sa

	if sa.rageBusy or list2.tpShootBusy then
		return false, "busy"
	end

	sa.rageBusy = true

	local gun = shoot.Parent
	local enabledOk, gunWasEnabled = pcall(function()
		return gun.Enabled
	end)

	if not enabledOk then
		gunWasEnabled = true
	end

	-- the gun tool also shoots by itself towards a touching finger and that eats the cooldown: switch it off meanwhile
	pcall(function()
		gun.Enabled = false
	end)

	if list2.gunInputBlock then
		pcall(list2.gunInputBlock, character)
	end

	-- our own aim point per body part must win over the shared murderer redirect inside fireGun
	local prevNoOverride = list2.fireNoOverride
	list2.fireNoOverride = true

	local fired, down = 0, false

	pcall(function()
		for i = 1, sa.rageShots do
			local char = murderer.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			local root = char and char:FindFirstChild("HumanoidRootPart")

			if not root or (hum and hum.Health <= 0) then
				down = true
				break
			end

			-- a different body part for every shot, with the usual Dynamic lead on a moving target
			local part = char:FindFirstChild(sa.rageBody[((i - 1) % #sa.rageBody) + 1]) or root
			local aim = (list2.aimAt(murderer, root) or root.Position) + (part.Position - root.Position)

			-- the bullet starts right next to the target, so walls in between don't matter
			if list2.fireGun(shoot, character, aim, CFrame.new(aim + Vector3.new(0, sa.rageLift, 0)), true) then
				fired = fired + 1
			end

			task.wait(sa.rageDelay)

			local after = murderer.Character
			local afterHum = after and after:FindFirstChildOfClass("Humanoid")

			if not after or (afterHum and afterHum.Health <= 0) then
				down = true
				break
			end
		end
	end)

	list2.fireNoOverride = prevNoOverride

	pcall(function()
		gun.Enabled = gunWasEnabled
	end)

	if list2.gunInputRestore then
		pcall(list2.gunInputRestore)
	end

	task.delay(0.3, function()
		sa.rageBusy = false
	end)

	return fired > 0, nil
end

-- One shared shot path for "Shoot Murderer" (button / keybind) and "Auto Shoot".
-- Both follow the Silent Aim Type dropdown (list2.sa.type) exactly like Silent Aim does:
--   Default / Dynamic : aim point from that predictor, shot starts at the muzzle, wall rules apply
--   Piercing          : Dynamic aim point, shot starts BEHIND the target, wall check is skipped
-- opts.isClear(tHrp)  -> true when nothing blocks the shot (skipped for Piercing / wallbang / force)
-- opts.wallbang       -> start the shot just above the target (same as the Wallbang toggle)
-- opts.force + opts.forceStart(aim) -> Force Shoot origin (Auto Shoot); Piercing origin wins over it
list2.saShoot = function(shoot, character, murderer, opts)
	opts = opts or {}
	local sa = list2.sa
	local myHrp = character and character:FindFirstChild("HumanoidRootPart")
	local tHrp = murderer and murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart")

	if not (shoot and myHrp and tHrp) then
		return false, "missing"
	end

	local piercing = sa.ignoresWalls()

	-- Rage: burst of up to 4 shots at different body parts (from Rage Shoot), unless the caller wants one shot
	if sa.type == "Rage" and not opts.single then
		return sa.rageBurst(shoot, character, murderer)
	end

	-- Qwern X: the controller times and fires the shot itself (it keeps its own wall rules)
	if sa.type == "Qwern X" and not opts.single and sa.qwernShoot then
		if opts.isClear and not (opts.wallbang or opts.force) and not opts.isClear(tHrp) then
			return false, "wall"
		end
		local handled = sa.qwernShoot(shoot, character, murderer, opts)
		if handled ~= nil then
			return handled == true, nil
		end
	end

	if opts.isClear and not (piercing or opts.wallbang or opts.force) and not opts.isClear(tHrp) then
		return false, "wall"
	end

	-- aim point comes from the selected Silent Aim Type (this also refreshes sa.origin for Piercing)
	local aim = list2.aimAt(murderer, tHrp) or tHrp.Position

	local startCF
	if (piercing or (sa.usesOrigin and sa.usesOrigin())) and sa.origin and os.clock() - sa.originT < 0.25 then
		startCF = sa.origin
	elseif opts.force and opts.forceStart then
		startCF = opts.forceStart(aim)
	elseif opts.wallbang then
		startCF = CFrame.new(aim + Vector3.new(0, 1.5, 0))
	end

	return list2.fireGun(shoot, character, aim, startCF) == true, nil
end

-- ============================================================================
-- Silent Aim Type: modes ported from the Pulse / Qwern X "Aim Version" (V1 - V4)
--   Rail Lead         (Pulse V1)  = predicted point + a clear "rail" start point next to him (checked with raycasts)
--   Direct Lock       (Pulse V2)  = shoots his real position, no prediction (Wallbang: starts right behind him)
--   Adaptive Resolver (Pulse V3)  = Rail Lead + ping / jitter / jump / turn aware lead and a desync resolver
--   Qwern X           (Pulse V4)  = the Qwern X controller: tracks him, scores the shot and fires at the best moment
-- Everything lives in list2.sa.pulse so it costs no extra locals in the main chunk.
-- ============================================================================
list2.sa.pulseInit = function()
	local sa = list2.sa
	local P = {
		pconns = {},
		token = nil,
		plan = nil,
		vel = nil,
		qwern = nil,
		qwernReady = false,
		qwernBuilding = false,
		lastPlan = nil,
		rolesCache = {},
		rolesAt = 0,
	}
	sa.pulse = P

	local function notify(msg)
		pcall(function()
			list2.notifyNow({ Title = "Silent Aim Type", Content = msg, Duration = 5, Icon = "x" })
		end)
	end

	-- settings table the ported code reads (settings.sheriff.*); the live values come from this script
	P.settings = {
		sheriff = setmetatable({
			silentAim = true,
			autoShoot = true,
			aimType = "Universal",
			resolver = true,
			pblank = false,
			fov = { on = false, size = 220 },
			flickSpeed = 6,
			flickMouse = true,
			flickReturn = 100,
		}, {
			__index = function(_, key)
				if key == "wallbang" then
					return list2.wallbang == true
				elseif key == "predEx" then
					return tonumber(sa.tune.predExtra) or 0
				elseif key == "aimVer" then
					if sa.type == "Adaptive Resolver" then
						return "V3"
					elseif sa.type == "Qwern X" then
						return "V4"
					end
					return "V1"
				end
				return nil
			end,
		}),
	}

	-- role table the ported code reads: only the current gun target is "Murderer" (respects the whitelist / zombie pick)
	P.roles = function()
		local now = os.clock()
		if now - P.rolesAt < 0.05 then
			return P.rolesCache
		end
		local t = {}
		local okT, target = pcall(function()
			if list2.gunTarget then
				return list2.gunTarget()
			end
			return nil
		end)
		if okT and target and target ~= game:GetService("Players").LocalPlayer then
			t[target.Name] = { Role = "Murderer", Dead = false, Killed = false }
		end
		P.rolesCache, P.rolesAt = t, now
		return t
	end

	-- ===== Rail Lead (V1) / Adaptive Resolver (V3): the Pulse shot planner =====
	P.buildPlanner = function()
		local token = {}
		P.token = token
		local Players = game:GetService("Players")
		local replicatedStorage = game:GetService("ReplicatedStorage")
		local playersService = Players
		local localPlayer = Players.LocalPlayer
		local settings = P.settings
		local getgenv = getgenv or function() return _G end
		local function PulseFC(instance, name, recursive) return instance:FindFirstChild(name, recursive) end
		local function PulseFCC(instance, name) return instance:FindFirstChildOfClass(name) end
		local function PulsePlayers() return Players:GetPlayers() end
		local function PULSE_NV(callback) return callback end
		local packValues = table.pack
		local unpackValues = table.unpack or unpack
		local function unpackTuple(values) return unpackValues(values, 1, values.n) end
		local function appendValues(destination, offset, ...)
			local values = packValues(...)
			table.move(values, 1, values.n, offset + 1, destination)
		end
		local isActive = P.roles
		local function isActive2() return P.token == token end
		local function connectSignal(signal, fn)
			local c = signal:Connect(fn)
			P.pconns[#P.pconns + 1] = c
			return c
		end
		local runService = game:GetService("RunService")
		local workspace2 = game:GetService("Workspace")
		local requireResult
		pcall(function()
			requireResult = require(replicatedStorage.Modules.CurrentRoundClient)
		end)
-- >>> ported from Pulse (aim version V1 / V3): tracker, ping model, resolver and shot planner
            local function isActive3()
                local character = localPlayer.Character
                local pulseFCResult = character and PulseFC(character, "Gun")
                if pulseFCResult then
                    return pulseFCResult
                end
                pulseFCResult = PulseFC(localPlayer, "Backpack")
                return pulseFCResult and PulseFC(pulseFCResult, "Gun")
            end
            local function isActive4()
                local character = localPlayer.Character
                return character and (character:FindFirstChild("HumanoidRootPart"))
            end
            local function isActive5()
                return isActive()
            end
            local function isActive6()
                local pulseDuel = getgenv().__pulseDuel
                if pulseDuel then
                    if pulseDuel.on then
                        return pulseDuel.pick()
                    end
                end
                pulseDuel = isActive5()
                for key, localPlayer2 in ipairs(PulsePlayers()) do
                    key = pulseDuel[localPlayer2.Name]
                    if key then
                        if key.Role == "Murderer" then
                            if key.Dead ~= true then
                                if key.Killed ~= true then
                                    local character = localPlayer2.Character
                                    local calculatedValue = character and (character:FindFirstChildOfClass("Humanoid"))
                                    if character then
                                        if calculatedValue then
                                            if calculatedValue.Health > 0 then
                                                return localPlayer2, character
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                return nil
            end
            local stats = game:GetService("Stats")
            local function isActive7()
                local success, result = pcall(function()
                    return stats.Network.ServerStatsItem["Data Ping"]:GetValue()
                end)
                if success then
                    if result then
                        if result == result then
                            return math.clamp(result / 1000, 0, 1)
                        end
                    end
                end
                return 0.1
            end
            do
                local runService2, entries =
                    game:GetService("RunService"),
                    {
                        rtt = 0.1,
                        jit = 0.01,
                        interp = 0.08,
                        wire = 0,
                        up = 0.05,
                        n = 0,
                        lastL = 0,
                        hbias = 0,
                        hn = 0,
                        tHist = {},
                        mHist = {},
                        rawHist = {},
                        char = nil,
                        pend = nil,
                    }
                local function callback(argument2, argument3, argument4)
                    return argument2 + (argument3 - argument2) * argument4
                end
                local function isActive8()
                    return math.max(entries.rtt, entries.wire)
                end
                local function isActive9()
                    local success, result = pcall(function()
                        return localPlayer:GetNetworkPing()
                    end)
                    local value, result2, value2 =
                        if success
                            then if type(result) == "number"
                                then if result == result
                                    then if result >= 0 then if result < 2 then result else nil else nil
                                    else nil
                                else nil
                            else nil,
                        pcall(function()
                            return stats.Network.ServerStatsItem["Data Ping"]:GetValue()
                        end)
                    return if result2
                        then if type(value2) == "number"
                            then if value2 == value2
                                then if value2 >= 0
                                    then if value2 < 2000
                                        then value and math.max(value, value2 / 1000) or value2 / 1000
                                        else value
                                    else value
                                else value
                            else value
                        else value
                end
                local pulseAimV3 = {
                    leadT = function()
                        local clamp, calculatedValue =
                            math.clamp,
                            isActive8() + entries.interp + math.clamp(entries.hbias, -0.08, 0.2) + (tonumber(
                                settings.sheriff.predEx
                            ) or 0)
                        return clamp(calculatedValue, 0.02, 0.6)
                    end,
                    jitter = function()
                        return entries.jit
                    end,
                    uplink = function()
                        return entries.up
                    end,
                }
                pulseAimV3.stats = function()
                    return {
                        rtt = entries.rtt,
                        wire = entries.wire,
                        jit = entries.jit,
                        interp = entries.interp,
                        up = entries.up,
                        n = entries.n,
                        hbias = entries.hbias,
                        hn = entries.hn,
                        lead = pulseAimV3.leadT(),
                    }
                end
                pulseAimV3.note = function(o, argument2, char, argument3)
                    local calculatedValue = argument2 - o
                    if calculatedValue.Magnitude < 0.5 then
                        entries.pend = nil
                        return
                    end
                    entries.pend = {
                        t = os.clock(),
                        o = o,
                        u = calculatedValue.Unit,
                        char = char,
                        v = argument3 or Vector3.new(0, 0, 0),
                        rh = entries.rawHist,
                        base = isActive8() + entries.interp,
                    }
                end
                pulseAimV3.onFired = function(startP, endP, argument2)
                    local pend = entries.pend
                    if not pend then
                        return
                    end
                    if typeof(startP) == "Vector3" then
                        pend.startP = startP
                    end
                    if
                        typeof(endP) == "Vector3"
                        and typeof(argument2) == "Instance"
                        and pend.char
                        and argument2:IsDescendantOf(pend.char)
                    then
                        pend.endP = endP
                        local calculatedValue = 0.5
                        pcall(function()
                            local transform, size = argument2.CFrame, argument2.Size
                            calculatedValue = 0.5
                                * (
                                    math.abs(transform.RightVector:Dot(pend.u)) * size.X
                                    + math.abs(transform.UpVector:Dot(pend.u)) * size.Y
                                    + math.abs(transform.LookVector:Dot(pend.u)) * size.Z
                                )
                        end)
                        pend.hw = math.clamp(calculatedValue, 0.2, 1.2)
                    end
                    startP = os.clock() - pend.t
                    if startP > 0.005 then
                        if startP < 1.2 then
                            if entries.wire > 0 then
                                entries.jit = callback(entries.jit, math.abs(startP - entries.wire), 0.2)
                            end
                            entries.wire = entries.wire > 0 and callback(entries.wire, startP, 0.25) or startP
                        end
                    end
                end
                local function callback2(calculatedValue, argument2, calculatedValue2, argument3)
                    local calculatedValue3, entry
                    for index = argument2, 1, -1 do
                        calculatedValue3 = calculatedValue3
                            or (
                                if calculatedValue[argument2].t - calculatedValue[index].t >= calculatedValue2
                                    then calculatedValue[index]
                                    else calculatedValue3
                            )
                        if calculatedValue3 and calculatedValue3.t - calculatedValue[index].t >= argument3 then
                            entry = calculatedValue[index]
                            break
                        end
                    end
                    if entry then
                        if not calculatedValue3 then
                            return nil
                        end
                    else
                        return nil
                    end
                    calculatedValue2 = calculatedValue3.t - entry.t
                    if calculatedValue2 < 0.03 then
                        return nil
                    end
                    calculatedValue = (calculatedValue3.p - entry.p) / calculatedValue2
                    return Vector3.new(calculatedValue.X, 0, calculatedValue.Z), (calculatedValue3.t + entry.t) * 0.5
                end
                pulseAimV3.turnRate = function()
                    local unit = entries.tHist
                    local unit2 = #unit
                    if unit2 < 5 then
                        return 0
                    end
                    local calculatedValue, value = callback2(unit, unit2, 0, 0.12)
                    local position, value2 = callback2(unit, unit2, 0.12, 0.12)
                    if calculatedValue then
                        if position then
                            if value then
                                if not value2 then
                                    return 0
                                end
                            else
                                return 0
                            end
                        else
                            return 0
                        end
                    else
                        return 0
                    end
                    if calculatedValue.Magnitude < 4 then
                        return 0
                    elseif position.Magnitude < 4 then
                        return 0
                    end
                    unit, unit2 = position.Unit, calculatedValue.Unit
                    position = Vector3.new(-unit.Z, 0, unit.X)
                    local atan2Result, calculatedValue2 = math.atan2(position:Dot(unit2), unit:Dot(unit2)), value - value2
                    if calculatedValue2 < 0.03 then
                        return 0
                    end
                    calculatedValue = atan2Result / calculatedValue2
                    if calculatedValue ~= calculatedValue then
                        return 0
                    end
                    return math.clamp(calculatedValue, -6, 6)
                end
                pulseAimV3.arcLead = function(argument2, argument3)
                    local magnitude = argument2.Magnitude
                    if magnitude < 0.001 or argument3 <= 0 then
                        return Vector3.new(0, 0, 0), argument2
                    end
                    local unit, turnRateResult = argument2.Unit, pulseAimV3.turnRate()
                    if math.abs(turnRateResult) < 0.35 then
                        return argument2 * argument3, argument2
                    end
                    local position, calculatedValue, clampedValue =
                        Vector3.new(-unit.Z, 0, unit.X),
                        magnitude / turnRateResult,
                        math.clamp(turnRateResult * argument3, -1, 1)
                    return unit * (calculatedValue * math.sin(clampedValue)) + position * (calculatedValue * (1 - math.cos(
                        clampedValue
                    ))),
                        (unit * math.cos(clampedValue) + position * math.sin(clampedValue)) * magnitude
                end
                local entries2 =
                    { HumanoidRootPart = true, UpperTorso = true, LowerTorso = true, Torso = true, Head = true }
                pulseAimV3.bestPart = function(argument2, transform)
                    if argument2 then
                        if typeof(transform) ~= "Vector3" then
                            return nil, 0
                        elseif transform.Magnitude < 0.001 then
                            return nil, 0
                        end
                    else
                        return nil, 0
                    end
                    local unit = transform.Unit
                    transform = math.abs(unit.Y) > 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
                    local unit2 = unit:Cross(transform)
                    if unit2.Magnitude < 0.001 then
                        return nil, 0
                    end
                    unit2 = unit2.Unit
                    local unit3, unit4, unit5 = unit:Cross(unit2).Unit
                    for unused, instance in ipairs(argument2:GetChildren()) do
                        if instance:IsA("BasePart") then
                            if entries2[instance.Name] then
                                if instance.Transparency < 1 then
                                    transform, unit = instance.CFrame, instance.Size
                                    local calculatedValue, calculatedValue2, calculatedValue3, rightVector, upVector, lookVector =
                                        unit.X * 0.5,
                                        unit.Y * 0.5,
                                        unit.Z * 0.5,
                                        transform.RightVector,
                                        transform.UpVector,
                                        transform.LookVector
                                    local calculatedValue4, calculatedValue5 =
                                        calculatedValue * math.abs(rightVector:Dot(unit2)) + calculatedValue2 * math.abs(
                                            upVector:Dot(unit2)
                                        ) + calculatedValue3 * math.abs(
                                            lookVector:Dot(unit2)
                                        ),
                                        calculatedValue * math.abs(rightVector:Dot(unit3)) + calculatedValue2 * math.abs(
                                            upVector:Dot(unit3)
                                        ) + calculatedValue3 * math.abs(
                                            lookVector:Dot(unit3)
                                        )
                                    upVector = math.min(calculatedValue4, calculatedValue5)
                                    if unit4 then
                                        if upVector > unit4 then
                                            unit4, unit5 = upVector, instance
                                        else
                                        end
                                    else
                                        unit4, unit5 = upVector, instance
                                    end
                                else
                                end
                            else
                            end
                        else
                        end
                    end
                    return unit5, unit4 or 0
                end
                pulseAimV3.bestAxis = function(instance, unit)
                    local calculatedValue = instance
                        and (instance:FindFirstChild("HumanoidRootPart") or instance:FindFirstChild("Torso"))
                    if not calculatedValue then
                        return nil, nil, 0
                    end
                    local transform = calculatedValue.CFrame
                    local entries2 = {
                        Vector3.new(transform.LookVector.X, 0, transform.LookVector.Z),
                        Vector3.new(transform.RightVector.X, 0, transform.RightVector.Z),
                    }
                    if unit then
                        if unit.Magnitude > 0.1 then
                            entries2[#entries2 + 1] = Vector3.new(unit.X, 0, unit.Z)
                        end
                    end
                    local value, value2, value3
                    for bestPartResult, item in ipairs(entries2) do
                        if item.Magnitude > 0.1 then
                            unit = item.Unit
                            bestPartResult, transform = pulseAimV3.bestPart(instance, unit)
                            if bestPartResult then
                                if value then
                                    if transform > value then
                                        value, value2, value3 = transform, unit, bestPartResult
                                    else
                                    end
                                else
                                    value, value2, value3 = transform, unit, bestPartResult
                                end
                            else
                            end
                        else
                        end
                    end
                    return value2, value3, value or 0
                end
                local function callback2(argument2, calculatedValue, argument3)
                    local entries2, entries3, entries4 = {}, {}, {}
                    for index = calculatedValue, argument3, 1 do
                        local p = argument2[index].p
                        entries2[#entries2 + 1] = p.X
                        entries3[#entries3 + 1] = p.Y
                        entries4[#entries4 + 1] = p.Z
                    end
                    if #entries2 == 0 then
                        return nil
                    end
                    table.sort(entries2)
                    table.sort(entries3)
                    table.sort(entries4)
                    calculatedValue = math.floor(#entries2 / 2) + 1
                    return Vector3.new(entries2[calculatedValue], entries3[calculatedValue], entries4[calculatedValue])
                end
                pulseAimV3.jumpCycle = function()
                    local rawHist = entries.rawHist
                    local count = #rawHist
                    if count < 8 then
                        return false, 0
                    end
                    local t, calculatedValue = rawHist[count].t, 1
                    for index = count, 1, -1 do
                        if t - rawHist[index].t > 0.6 then
                            calculatedValue = index + 1
                            break
                        end
                    end
                    if count - calculatedValue + 1 < 8 then
                        return false, 0
                    end
                    local huge, value, counter, counter2 = math.huge, -math.huge, 0, 0
                    for index = calculatedValue + 1, count, 1 do
                        t = rawHist[index].p.Y
                        huge, value = if t < huge then t else huge, if t > value then t else value
                        local calculatedValue2 = t - rawHist[index - 1].p.Y
                        if math.abs(calculatedValue2) > 0.05 then
                            index = calculatedValue2 > 0 and 1 or -1
                            counter, counter2 =
                                index,
                                if counter ~= 0 then if index ~= counter then counter2 + 1 else counter2 else counter2
                        else
                        end
                    end
                    t = value - huge
                    return t > 4 and counter2 >= 2, t
                end
                pulseAimV3.resolve = function()
                    local rawHist = entries.rawHist
                    local count = #rawHist
                    if count < 6 then
                        return nil, "none"
                    end
                    local t, calculatedValue = rawHist[count].t, 1
                    for index = count, 1, -1 do
                        if t - rawHist[index].t > 0.35 then
                            calculatedValue = index + 1
                            break
                        end
                    end
                    if count - calculatedValue + 1 < 5 then
                        return nil, "none"
                    end
                    t = callback2(rawHist, calculatedValue, count)
                    if not t then
                        return nil, "none"
                    end
                    local calculatedValue2, calculatedValue3, counter, counter2 = 0, 0, 0, 0
                    for index = calculatedValue, count, 1 do
                        local magnitude = (rawHist[index].p - t).Magnitude
                        calculatedValue2, calculatedValue3, counter, counter2 =
                            calculatedValue2 + magnitude,
                            calculatedValue3 + 1,
                            if magnitude > counter then magnitude else counter,
                            if magnitude > 50 then counter2 + 1 else counter2
                    end
                    local calculatedValue4 = calculatedValue3 > 0 and calculatedValue2 / calculatedValue3 or 0
                    if counter2 > 0 and counter > 100 then
                        local entries2 = {}
                        for index = calculatedValue, count, 1 do
                            if (rawHist[index].p - t).Magnitude <= 25 then
                                entries2[#entries2 + 1] = rawHist[index]
                            end
                        end
                        if #entries2 >= 3 then
                            return callback2(entries2, 1, #entries2), "blink"
                        end
                        return nil, "none"
                    end
                    local magnitude = (rawHist[count].p - rawHist[calculatedValue].p).Magnitude
                    if calculatedValue4 > 3 then
                        if magnitude < calculatedValue4 * 1.5 then
                            return t, "jitter"
                        end
                    end
                    return nil, "clean"
                end
                getgenv().__pulseAimV3 = pulseAimV3
                task.spawn(function()
                    local calculatedValue = 0
                    while isActive2() do
                        runService2.Heartbeat:Wait()
                        local sheriff = settings.sheriff
                        if
                            sheriff
                            and sheriff.aimVer == "V3"
                            and (sheriff.silentAim or sheriff.autoShoot or sheriff.aimType == "Flick Shot")
                        then
                            local now = os.clock()
                            if now >= calculatedValue then
                                calculatedValue = now + 0.25
                                local value = isActive9()
                                if value then
                                    entries.jit = callback(entries.jit, math.abs(value - entries.rtt), 0.15)
                                    entries.rtt = callback(entries.rtt, value, 0.25)
                                end
                            else
                            end
                            pcall(function()
                                local unused, char = isActive6()
                                if entries.char ~= char then
                                    entries.char = char
                                    entries.tHist = {}
                                    entries.rawHist = {}
                                end
                                local mHist = char and (char:FindFirstChild("HumanoidRootPart"))
                                if mHist then
                                    local tHist, maximumValue = entries.tHist, 12
                                    if #tHist >= 2 then
                                        char = math.max(tHist[#tHist].t - tHist[#tHist - 1].t, 0.016666666666666666)
                                        local calculatedValue = (tHist[#tHist].p - tHist[#tHist - 1].p).Magnitude / char
                                        maximumValue = math.max(
                                            12,
                                            calculatedValue * math.max(now - tHist[#tHist].t, 0.016666666666666666) * 3 + 8
                                        )
                                    else
                                    end
                                    if #tHist > 0 then
                                        if (mHist.Position - tHist[#tHist].p).Magnitude > maximumValue then
                                            local tHist2 = {}
                                            entries.tHist = tHist2
                                            tHist = tHist2
                                        else
                                        end
                                    else
                                    end
                                    tHist[#tHist + 1] = { t = now, p = mHist.Position }
                                    while #tHist > 2 and now - tHist[1].t > 1.1 do
                                        table.remove(tHist, 1)
                                    end
                                    local rawHist = entries.rawHist
                                    rawHist[#rawHist + 1] = { t = now, p = mHist.Position }
                                    while #rawHist > 2 and now - rawHist[1].t > 0.6 do
                                        table.remove(rawHist, 1)
                                    end
                                end
                                char = isActive4()
                                if char then
                                    mHist = entries.mHist
                                    mHist[#mHist + 1] = { t = now, p = char.Position }
                                    while #mHist > 2 and now - mHist[1].t > 1.1 do
                                        table.remove(mHist, 1)
                                    end
                                end
                            end)
                        else
                            if entries.char or #entries.tHist > 0 then
                                entries.tHist = {}
                                entries.mHist = {}
                                entries.char = nil
                                entries.pend = nil
                            end
                        end
                    end
                end)
                task.spawn(function()
                    while isActive2() do
                        runService2.Heartbeat:Wait()
                        local pend = entries.pend
                        if pend and os.clock() - pend.t > 0.7 then
                            entries.pend = nil
                            pcall(function()
                                if typeof(pend.startP) == "Vector3" then
                                    local value, value2
                                    local enabled = false
                                    for key, item in ipairs(entries.mHist) do
                                        key = item.t - pend.t
                                        if key >= -0.02 then
                                            if key <= 0.5 then
                                                local magnitude = (item.p - pend.startP).Magnitude
                                                if value then
                                                    if magnitude < value then
                                                        value, value2 = magnitude, key
                                                    else
                                                    end
                                                else
                                                    value, value2 = magnitude, key
                                                end
                                            else
                                            end
                                        else
                                        end
                                        enabled = if math.abs(item.t - pend.t) < 0.4
                                            then if (item.p - pend.startP).Magnitude > 4 then true else enabled
                                            else enabled
                                    end
                                    if value2 then
                                        if value then
                                            if value < 2 then
                                                if enabled then
                                                    entries.up = callback(entries.up, math.clamp(value2, 0, 0.5), 0.2)
                                                end
                                            end
                                        end
                                    end
                                end
                                if typeof(pend.endP) == "Vector3" and pend.rh then
                                    local rh, counter, value, value2 = pend.rh, 0
                                    for key, item in ipairs(rh) do
                                        local calculatedValue = item.t - pend.t
                                        if calculatedValue >= 0.01 then
                                            if calculatedValue <= 0.65 then
                                                local calculatedValue2, magnitude =
                                                    counter + 1, (item.p - pend.endP).Magnitude
                                                if value then
                                                    if magnitude < value then
                                                        value, value2 = magnitude, key
                                                    else
