                                0.5
                            )
                            pulseAimX.Lnrsd = math.clamp(
                                pulseAimX.Lnrsd + (math.abs(calculatedValue2) - pulseAimX.Lnrsd) * 0.2,
                                0.03,
                                0.12
                            )
                        elseif calculatedValue4 and not pending.anom then
                            pulseAimX.calib = (pulseAimX.calib or 0) + 1
                        end
                        if pending.vsSign then
                            pulseAimX.vsLock = pending.vsSign
                            pulseAimX.vsNext = nil
                            pulseAimX.vsMiss = 0
                            pulseAimX.say(string.format("  spoof resolver: sign %d confirmed", pending.vsSign))
                        end
                        pulseAimX.saveState()
                        pulseAimX.record(pending, "hit", argument4, argument5.Name)
                        pulseAimX.say(
                            string.format(
                                "HIT %s part=%s lat=%.0fms mode=%s tau=%s L=%.3f Lnr=%.3f lag=%.3f ping=%.3f",
                                pending.kind,
                                argument5.Name,
                                calculatedValue * 1000,
                                tostring(pending.mode),
                                value and string.format("%.3f", value) or "?",
                                pulseAimX.L,
                                pulseAimX.Lnr,
                                (pending.lag or 0) + pulseAimX.lagRef,
                                localPlayer2:GetNetworkPing()
                            )
                        )
                    else
                        pulseAimX.stats.miss += 1
                        if pending.vsSign then
                            if pulseAimX.vsLock then
                                pulseAimX.vsMiss = (pulseAimX.vsMiss or 0) + 1
                                if pulseAimX.vsMiss >= 3 then
                                    pulseAimX.vsLock = nil
                                    pulseAimX.vsMiss = 0
                                    pulseAimX.vsNext = -pending.vsSign
                                    pulseAimX.saveState()
                                end
                            else
                                pulseAimX.vsNext = -pending.vsSign
                            end
                        end
                        pulseAimX.record(
                            pending,
                            "miss",
                            argument4,
                            typeof(argument5) == "Instance" and argument5:GetFullName() or "nil"
                        )
                        pulseAimX.say(
                            string.format(
                                "MISS %s score=%.3f hit=%s lat=%.0fms",
                                pending.kind,
                                pending.score or -1,
                                typeof(argument5) == "Instance" and argument5:GetFullName() or "nil",
                                calculatedValue * 1000
                            )
                        )
                        task.delay(0.7, function()
                            if not pending.anom then
                                if (pending.mvPath or 0) < (pulseAimX.tauMissMaxV or 60) then
                                    local success, result, result2 =
                                        pcall(pulseAimX.tauEvidence, pending, false, argument4, nil)
                                    if success then
                                        if pulseAimX.tauShots then
                                            pulseAimX.saveState()
                                            pulseAimX.say(
                                                string.format(
                                                    "  tau window %s..%s -> L=%.3f sd=%.3f (shots %d)",
                                                    result and string.format("%.2f", result) or "-",
                                                    result2 and string.format("%.2f", result2) or "-",
                                                    pulseAimX.L,
                                                    pulseAimX.Lsd,
                                                    pulseAimX.tauShots
                                                )
                                            )
                                        end
                                    end
                                end
                            end
                            local shotTrajResult, unit2, value, value2 =
                                pulseAimX.shotTraj(pending), (pending.e - pending.o).Unit
                            for index = 0, 0.6, 0.01 do
                                local posAtResult = pulseAimX.posAt(shotTrajResult, pending.t + index)
                                if posAtResult then
                                    local calculatedValue = posAtResult + Vector3.new(0, 0.5, 0) - pending.o
                                    local magnitude = (calculatedValue - unit2 * calculatedValue:Dot(unit2)).Magnitude
                                    if value then
                                        if magnitude < value then
                                            value, value2 = magnitude, index
                                        else
                                        end
                                    else
                                        value, value2 = magnitude, index
                                    end
                                else
                                end
                            end
                            pulseAimX.say(
                                string.format(
                                    "  miss: closest lateral=%.2f at tau=%.2f top=%s %s",
                                    value or -1,
                                    value2 or -1,
                                    tostring(pending.top),
                                    tostring(pending.info)
                                )
                            )
                            if pending.pred then
                                local entries3, entries4 = {}, { 0, 0.05, 0.1 }
                                for key, item in ipairs(entries4) do
                                    local posAtResult, entry =
                                        pulseAimX.posAt(shotTrajResult, pending.t + item), pending.pred[key]
                                    if posAtResult then
                                        if entry then
                                            entries3[#entries3 + 1] = string.format(
                                                "t%.2f dXZ=%.2f dY=%.2f",
                                                item,
                                                Vector3.new(posAtResult.X - entry.X, 0, posAtResult.Z - entry.Z).Magnitude,
                                                posAtResult.Y - entry.Y
                                            )
                                        end
                                    end
                                end
                                pulseAimX.say("  miss pred-vs-actual " .. table.concat(entries3, " | "))
                            end
                        end)
                    end
                end)
                pulseAimX.shotTraj = function(argument2)
                    local entries3 = {}
                    for unused, item in ipairs(argument2.pre or {}) do
                        entries3[#entries3 + 1] = item
                    end
                    local t = entries3[#entries3] and entries3[#entries3].t or -math.huge
                    for unused, item in ipairs(argument2.post or {}) do
                        if item.t > t then
                            entries3[#entries3 + 1] = item
                            t = item.t
                        else
                        end
                    end
                    return entries3
                end
                pulseAimX.tauGridMin = -0.05
                pulseAimX.tauGridStep = 0.01
                pulseAimX.tauGridN = 51
                pulseAimX.tauInit = function()
                    if type(pulseAimX.tauLog) == "table" then
                        if #pulseAimX.tauLog == pulseAimX.tauGridN then
                            return
                        end
                    end
                    pulseAimX.tauLog = {}
                    local l, maximumValue = pulseAimX.L, math.max(pulseAimX.Lsd * 1.5, 0.05)
                    for index = 1, pulseAimX.tauGridN, 1 do
                        local calculatedValue = pulseAimX.tauGridMin + (index - 1) * pulseAimX.tauGridStep
                        pulseAimX.tauLog[index] = -0.5 * ((calculatedValue - l) / maximumValue) ^ 2
                    end
                end
                pulseAimX.tauApply = function()
                    local calculatedValue, entries3, value = 0.12 + (pulseAimX.pingCal or 0.05), {}, -math.huge
                    for key, item in ipairs(pulseAimX.tauLog) do
                        entries3[key] = item
                            - 0.5 * ((pulseAimX.tauGridMin + (key - 1) * pulseAimX.tauGridStep - calculatedValue) / 0.05) ^ 2
                        value = if entries3[key] > value then entries3[key] else value
                    end
                    local entries4, counter = {}, 0
                    for key, item in ipairs(entries3) do
                        entries4[key] = math.exp(item - value)
                        counter += entries4[key]
                    end
                    local counter2, counter3, calculatedValue2 = 0, 0
                    for index = 1, pulseAimX.tauGridN, 1 do
                        calculatedValue = pulseAimX.tauGridMin + (index - 1) * pulseAimX.tauGridStep
                        counter2 += calculatedValue * entries4[index] / counter
                        counter3 += entries4[index] / counter
                        calculatedValue2 = calculatedValue2
                            or (if counter3 >= 0.5 then calculatedValue else calculatedValue2)
                    end
                    entries3 = 0
                    for index = 1, pulseAimX.tauGridN, 1 do
                        entries3 += (pulseAimX.tauGridMin + (index - 1) * pulseAimX.tauGridStep - counter2) ^ 2 * entries4[index] / counter
                    end
                    pulseAimX.L = math.clamp(calculatedValue2 or counter2, -0.05, 0.45)
                    pulseAimX.Lsd = math.clamp(math.sqrt(entries3), 0.035, 0.09)
                end
                pulseAimX.tauEvidence = PULSE_NV(function(argument2, argument3, posAtResult, shotTrajResult)
                    if argument2.mode == "nr" then
                        return nil
                    elseif argument2.body then
                        if argument2.offLine then
                            return nil
                        end
                    else
                        return nil
                    end
                    shotTrajResult = pulseAimX.shotTraj(argument2)
                    if #shotTrajResult < 6 then
                        return nil
                    end
                    pulseAimX.tauInit()
                    local calculatedValue = argument2.e - argument2.o
                    local unit, calculatedValue2, huge = calculatedValue.Unit, calculatedValue.Magnitude + 400, math.huge
                    huge = if argument3
                        then huge
                        else if typeof(posAtResult) == "Vector3"
                            then (posAtResult - argument2.o).Magnitude + 0.5
                            else huge
                    local t, t2, calculatedValue3, calculatedValue4, value =
                        shotTrajResult[1].t,
                        shotTrajResult[#shotTrajResult].t,
                        (argument2.pingS or 0) + (argument2.shift or 0)
                    for index = 1, pulseAimX.tauGridN, 1 do
                        calculatedValue = pulseAimX.tauGridMin + (index - 1) * pulseAimX.tauGridStep
                        local calculatedValue5, calculatedValue6 = argument2.t + calculatedValue + calculatedValue3
                        if calculatedValue5 < t or calculatedValue5 > t2 then
                            calculatedValue6 = argument3 and 0.6 or 1
                        else
                            posAtResult = pulseAimX.posAt(shotTrajResult, calculatedValue5)
                            local hitsBodyResult, hitsBodyResult2 =
                                pulseAimX.hitsBody(argument2.body, posAtResult, argument2.o, unit, calculatedValue2)
                            local calculatedValue7 = hitsBodyResult ~= nil and hitsBodyResult < huge
                            calculatedValue6 = if argument3
                                then calculatedValue7 and 1 or 0.1
                                else hitsBodyResult2 and hitsBodyResult2 < huge and (pulseAimX.missCoreLike or 0.3)
                                    or (calculatedValue7 and (pulseAimX.missLike or 0.7) or 1)
                            if calculatedValue7 then
                                calculatedValue4, value = calculatedValue4 or calculatedValue, calculatedValue
                            else
                            end
                        end
                        pulseAimX.tauLog[index] = pulseAimX.tauLog[index] * 0.97 + math.log(calculatedValue6)
                    end
                    pulseAimX.tauApply()
                    pulseAimX.tauShots = (pulseAimX.tauShots or 0) + 1
                    return calculatedValue4, value
                end)
                pulseAimX.meJson = function(argument2)
                    if not argument2 then
                        return "null"
                    end
                    local function callback5(argument3)
                        return typeof(argument3) == "Vector3"
                                and string.format("[%.3f,%.3f,%.3f]", argument3.X, argument3.Y, argument3.Z)
                            or "null"
                    end
                    return string.format(
                        '{"hp":%s,"hl":%s,"hd":%s,"mz":%s,"cp":%s,"cl":%s}',
                        callback5(argument2.hp),
                        callback5(argument2.hl),
                        callback5(argument2.hd),
                        callback5(argument2.mz),
                        callback5(argument2.cp),
                        (callback5(argument2.cl))
                    )
                end
                pulseAimX.record = function(argument2, argument3, argument4, argument5)
                    task.delay(0.7, function()
                        pcall(function()
                            local entries3 = {}
                            for key, item in ipairs((pulseAimX.shotTraj(argument2))) do
                                if item.t >= argument2.t - 0.6 then
                                    if item.t <= argument2.t + 0.65 then
                                        key = typeof(item.v) == "Vector3" and item.v or Vector3.zero
                                        entries3[#entries3 + 1] = string.format(
                                            "[%.4f,%.3f,%.3f,%.3f,%.2f,%.2f,%.1f,%d,%s,%s,%.1f,%.1f,%.1f]",
                                            item.t - argument2.t,
                                            item.p.X,
                                            item.p.Y,
                                            item.p.Z,
                                            item.md.X,
                                            item.md.Z,
                                            item.ws,
                                            item.st.Value,
                                            item.air and "1" or "0",
                                            item.jump and "1" or "0",
                                            key.X,
                                            key.Y,
                                            key.Z
                                        )
                                    end
                                end
                            end
                            local formatResult = string.format(
                                '{"t":%.3f,"kind":"%s","score":%.3f,"res":"%s","part":"%s","o":[%.3f,%.3f,%.3f],"e":[%.3f,%.3f,%.3f],"end":%s,"L":%.3f,"D":%.3f,"k":%.2f,"emd":%.2f,"ecv":%.2f,"reason":"%s","ping":%.3f,"mz":"%s","mv":%.1f,"me":%s,"rows":[%s]}',
                                argument2.t,
                                tostring(argument2.kind),
                                argument2.score or -1,
                                argument3,
                                tostring(argument5),
                                argument2.o.X,
                                argument2.o.Y,
                                argument2.o.Z,
                                argument2.e.X,
                                argument2.e.Y,
                                argument2.e.Z,
                                typeof(argument4) == "Vector3"
                                        and string.format("[%.3f,%.3f,%.3f]", argument4.X, argument4.Y, argument4.Z)
                                    or "null",
                                pulseAimX.L,
                                pulseAimX.D,
                                pulseAimX.k,
                                pulseAimX.err.md,
                                pulseAimX.err.cv,
                                tostring(argument2.reason),
                                localPlayer2:GetNetworkPing(),
                                tostring(argument2.mz),
                                argument2.mvPath or -1,
                                pulseAimX.meJson(argument2.me),
                                table.concat(entries3, ",")
                            )
                            if isfile("PulseHub/aimx_shots.jsonl") then
                                appendfile("PulseHub/aimx_shots.jsonl", formatResult .. "\n")
                            else
                                writefile("PulseHub/aimx_shots.jsonl", formatResult .. "\n")
                            end
                        end)
                    end)
                end
                pulseAimX.stop = function()
                    pulseAimX.alive = false
                    for unused, item in ipairs(pulseAimX.conns) do
                        pcall(function()
                            item:Disconnect()
                        end)
                    end
                end
                pulseAimX.start = function(connectSignal2)
                    pulseAimX.loadState()
                    pcall(function()
                        if isfolder then
                            if makefolder then
                                if not (isfolder("PulseHub")) then
                                    makefolder("PulseHub")
                                end
                            end
                        end
                    end)
                    pulseAimX.logFile = "PulseHub/aimx_log.txt"
                    local clientServices = replicatedStorage:WaitForChild("ClientServices", 10)
                    clientServices = clientServices and (clientServices:WaitForChild("WeaponService", 10))
                    clientServices = clientServices and (clientServices:WaitForChild("GunFired", 10))
                    if clientServices then
                        pulseAimX.conns[#pulseAimX.conns + 1] = connectSignal2(clientServices.OnClientEvent, function(...)
                            if pulseAimX.alive then
                                pcall(pulseAimX.onFired, ...)
                            end
                        end)
                    end
                    local counter, counter2, counter3 = 0, 0, 0
                    pulseAimX.conns[#pulseAimX.conns + 1] = connectSignal2(runService2.Heartbeat, function()
                        if not pulseAimX.alive then
                            return
                        end
                        if not (pulseAimX.forced or pulseAimX.queued) then
                            local enabled = false
                            pcall(function()
                                local character, backpack =
                                    localPlayer2.Character, localPlayer2:FindFirstChildOfClass("Backpack")
                                local calculatedValue = character ~= nil and character:FindFirstChild("Gun") ~= nil
                                    or backpack ~= nil and backpack:FindFirstChild("Gun") ~= nil
                                enabled = calculatedValue
                            end)
                            if not enabled then
                                local now = os.clock()
                                if now - counter3 < 0.1 then
                                    return
                                end
                                counter3 = now
                            end
                        end
                        pcall(pulseAimX.track)
                        local now = os.clock()
                        pcall(pulseAimX.spTick, now)
                        local spArm = pulseAimX.spArm
                        if spArm then
                            if spArm.c then
                                if spArm.c.Parent then
                                    local calculatedValue, calculatedValue2 = pulseAimX.target == spArm.c
                                        and not pulseAimX.queued
                                        and #pulseAimX.hist >= 8
                                    if calculatedValue then
                                        local spActiveResult = pulseAimX.spActive(spArm.c)
                                        calculatedValue2 = if spActiveResult then now > spArm.untilT else not spActiveResult
                                    else
                                        calculatedValue2 = calculatedValue
                                    end
                                    if calculatedValue2 then
                                        pulseAimX.spArm = nil
                                        pulseAimX.say(
                                            pulseAimX.spActive(spArm.c) and "SPOOF no window, plain shot"
                                                or "SPOOF window, armed click fires"
                                        )
                                        pulseAimX.spPassUntil = now + 0.6
                                        pcall(pulseAimX.fireFor, spArm.c, true, spArm.needLos)
                                    end
                                else
                                    pulseAimX.spArm = nil
                                end
                            else
                                pulseAimX.spArm = nil
                            end
                        end
                        spArm = pulseAimX.dsArm
                        if spArm then
                            if now > spArm.untilT then
                                pulseAimX.dsArm = nil
                            elseif spArm.c then
                                if spArm.c.Parent then
                                    if pulseAimX.target == spArm.c then
                                        if pulseAimX.dsHot(spArm.c) then
                                            if #pulseAimX.hist >= 8 then
                                                if not pulseAimX.queued then
                                                    pulseAimX.dsArm = nil
                                                    pulseAimX.say("DESYNC window, armed click fires")
                                                    pcall(pulseAimX.fireFor, spArm.c, true, spArm.needLos)
                                                end
                                            end
                                        end
                                    end
                                else
                                    pulseAimX.dsArm = nil
                                end
                            else
                                pulseAimX.dsArm = nil
                            end
                        end
                        if pulseAimX.hbLast then
                            pulseAimX.frameDt = (pulseAimX.frameDt or 0.017)
                                + (math.clamp(now - pulseAimX.hbLast, 0.004, 0.2) - (pulseAimX.frameDt or 0.017)) * 0.1
                        end
                        pulseAimX.hbLast = now
                        if pulseAimX.btCo then
                            pulseAimX.btT = os.clock()
                            if coroutine.resume(pulseAimX.btCo) then
                                if coroutine.status(pulseAimX.btCo) == "dead" then
                                    pulseAimX.btCo = nil
                                    pulseAimX.btSlice = false
                                end
                            else
                                pulseAimX.btCo = nil
                                pulseAimX.btSlice = false
                            end
                        elseif pulseAimX.target and now - counter > 0.1 then
                            counter = now
                            local cloneResult = table.clone(pulseAimX.hist)
                            local moveParamsResult = pulseAimX.moveParams()
                            pulseAimX.btCo = coroutine.create(function()
                                pulseAimX.btSlice = true
                                pcall(pulseAimX.backtest, cloneResult, moveParamsResult)
                                pulseAimX.btSlice = false
                            end)
                            pulseAimX.btT = os.clock()
                            if coroutine.resume(pulseAimX.btCo) then
                                if coroutine.status(pulseAimX.btCo) == "dead" then
                                    pulseAimX.btCo = nil
                                    pulseAimX.btSlice = false
                                end
                            else
                                pulseAimX.btCo = nil
                                pulseAimX.btSlice = false
                            end
                        end
                        if pulseAimX.target then
                            if now - counter2 > 0.5 then
                                counter2 = now
                                local success, result = pcall(pulseAimX.speedFactor, pulseAimX.hist)
                                if success then
                                    pulseAimX.k = result
                                end
                            end
                        end
                        if pulseAimX.queued then
                            pcall(pulseAimX.flushQueue)
                        end
                        if pulseAimX.autoRotateRestore then
                            if now > (pulseAimX.autoRotateUntil or 0) then
                                pcall(function()
                                    pulseAimX.autoRotateRestore.AutoRotate = true
                                end)
                                pulseAimX.autoRotateRestore = nil
                            end
                        end
                        spArm = pulseAimX.pending
                        if spArm then
                            if not spArm.dead then
                                if
                                    now - spArm.t > math.max(
                                        0.28,
                                        pulseAimX.echo * 2.5,
                                        localPlayer2:GetNetworkPing() * 2.2 + 0.15
                                    )
                                then
                                    spArm.dead = true
                                    local calculatedValue, calculatedValue2 =
                                        spArm.t - (pulseAimX.trueAccepted or 0),
                                        localPlayer2.Character ~= nil
                                            and localPlayer2.Character:FindFirstChild("Gun") ~= nil
                                    if calculatedValue2 then
                                        if calculatedValue < pulseAimX.cooldown + 0.6 then
                                            if not spArm.anom then
                                                if calculatedValue > 2.4 then
                                                    pulseAimX.cdLo = math.max(pulseAimX.cdLo or 0, calculatedValue + 0.03)
                                                end
                                                pulseAimX.cooldown = math.clamp(
                                                    math.max(pulseAimX.cooldown + 0.1, pulseAimX.cdLo or 0),
                                                    pulseAimX.cdFloor,
                                                    5.5
                                                )
                                                pulseAimX.lastAccepted =
                                                    math.max(pulseAimX.lastAccepted, now - pulseAimX.cooldown + 0.12)
                                            end
                                        end
                                    end
                                    pulseAimX.say(
                                        string.format(
                                            "DROP %s cooldown=%.2f since=%.2f held=%s",
                                            tostring(spArm.kind),
                                            pulseAimX.cooldown,
                                            calculatedValue,
                                            tostring(calculatedValue2)
                                        )
                                    )
                                    if spArm.manual then
                                        if spArm.tries < 3 then
                                            if spArm.c then
                                                if spArm.c.Parent then
                                                    spArm.retry = true
                                                    pulseAimX.queued = {
                                                        c = spArm.c,
                                                        needLos = false,
                                                        clickAt = now,
                                                        waitFrom = now,
                                                        manual = true,
                                                        hardUntil = now + 0.25,
                                                    }
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if pulseAimX.forced then
                            if pulseAimX.forced.Parent then
                                if now - (pulseAimX.forcedAt or now) > 5 then
                                    pulseAimX.forced = nil
                                end
                            else
                                pulseAimX.forced = nil
                            end
                        end
                    end)
                    pulseAimX.say(string.format("start L=%.3f sd=%.3f D=%.3f", pulseAimX.L, pulseAimX.Lsd, pulseAimX.D))
                end
                pulseAimX.start(connectSignal)
            end
-- <<< end of ported Qwern X controller
	end

	P.stopQwern = function()
		local q = P.qwern
		P.qwernReady = false
		P.qwern = nil
		if q and q.stop then
			pcall(q.stop)
		end
	end

	-- Qwern X waits for the game's GunFired remote, so it is built in the background
	P.ensureQwern = function()
		if P.qwernReady or P.qwernBuilding then
			return
		end
		P.qwernBuilding = true
		task.spawn(function()
			local ok, err = pcall(P.buildQwern)
			P.qwernBuilding = false
			local q = rawget(getgenv(), "__pulseAimX")
			if ok and q and q.alive then
				pcall(function()
					q.logFile = nil -- no log file spam
				end)
				if sa.type == "Qwern X" then
					P.qwern = q
					P.qwernReady = true
				else
					pcall(q.stop)
				end
			else
				notify("Qwern X could not start: " .. tostring(err))
			end
		end)
	end

	P.stopAll = function()
		P.stopPlanner()
		P.stopQwern()
	end
	sa.pulseStop = P.stopAll

	-- called when the dropdown changes: start what the chosen type needs, stop the rest
	sa.onType = function()
		local t = sa.type
		if t == "Rail Lead" or t == "Adaptive Resolver" then
			if not P.token then
				local ok, err = pcall(P.buildPlanner)
				if not ok then
					P.stopPlanner()
					notify("Planner could not start: " .. tostring(err))
				end
			end
		else
			P.stopPlanner()
		end
		if t == "Qwern X" then
			P.ensureQwern()
		else
			P.stopQwern()
		end
	end

	sa.pulseModes = {
		["Rail Lead"] = true,
		["Direct Lock"] = true,
		["Adaptive Resolver"] = true,
		["Qwern X"] = true,
	}

	-- these types start the shot from the point they chose (sa.origin) instead of the muzzle
	sa.usesOrigin = function()
		local t = sa.type
		if t == "Direct Lock" then
			return list2.wallbang == true
		end
		return t == "Rail Lead" or t == "Adaptive Resolver" or t == "Qwern X"
	end

	local function setOrigin(origin, aim)
		if (aim - origin).Magnitude < 0.1 then
			sa.origin = CFrame.new(origin)
		else
			sa.origin = CFrame.new(origin, aim)
		end
		sa.originT = os.clock()
	end

	-- aim point (and shot start in sa.origin) for the Pulse types; nil = let the normal prediction handle it
	sa.pulseResolve = function(mode, obj, part3)
		local char = obj and obj.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return nil
		end
		sa.origin = nil

		if mode == "Direct Lock" then
			local pos = hrp.Position
			local vel = hrp.AssemblyLinearVelocity
			if list2.wallbang then
				local off = vel.Magnitude > 1.5 and -vel.Unit * 2 or Vector3.new(0, 1.25, 0)
				sa.origin = CFrame.lookAt(pos + off, pos)
				sa.originT = os.clock()
			end
			_G.__FVL_AIM = { aim = pos, targetPos = pos, vel = vel, lead = 0, t = os.clock() }
			return pos
		end

		if mode == "Rail Lead" or mode == "Adaptive Resolver" then
			if not (P.token and P.plan) then
				sa.onType()
				return nil
			end
			local plan = P.plan(char, true)
			if type(plan) ~= "table" then
				return nil
			end
			local aim = plan.aim
			if plan.ok and typeof(aim) == "Vector3" and typeof(plan.origin) == "Vector3" then
				setOrigin(plan.origin, aim)
				P.lastPlan = { origin = plan.origin, aim = aim, char = char, t = os.clock() }
			else
				aim = plan.P
			end
			if typeof(aim) ~= "Vector3" then
				return nil
			end
			_G.__FVL_AIM = { aim = aim, targetPos = hrp.Position, vel = hrp.AssemblyLinearVelocity, lead = 0, t = os.clock() }
			return aim
		end

		if mode == "Qwern X" then
			local q = P.qwern
			if not (P.qwernReady and q and q.alive) then
				P.ensureQwern()
				return nil
			end
			if q.target ~= char then
				return nil
			end
			local ok, plan = pcall(q.plan, char, not list2.wallbang)
			if ok and type(plan) == "table" and typeof(plan.o) == "Vector3" and typeof(plan.e) == "Vector3" then
				setOrigin(plan.o, plan.e)
				_G.__FVL_AIM = { aim = plan.e, targetPos = hrp.Position, vel = hrp.AssemblyLinearVelocity, lead = 0, t = os.clock() }
				return plan.e
			end
			return nil
		end

		return nil
	end

	-- Qwern X fires the shot itself (its own timing / cooldown / queue). Returns nil when it cannot, so the
	-- caller falls back to the normal shot.
	sa.qwernShoot = function(shoot, character, murderer, opts)
		local q = P.qwern
		local char = murderer and murderer.Character
		if not (P.qwernReady and q and q.alive and char) then
			P.ensureQwern()
			return nil
		end
		local manual = not (opts and opts.auto)
		local ok, result = pcall(q.fireFor, char, manual, not list2.wallbang)
		if ok then
			return result and true or false
		end
		return nil
	end

	-- Adaptive Resolver learns from its own shots: tell it where the shot went once it was fired
	local origFire = list2.fireGun
	list2.fireGun = function(shoot, character, aimPos, startCF, ownOrigin)
		local fired = origFire(shoot, character, aimPos, startCF, ownOrigin)
		if fired and sa.type == "Adaptive Resolver" then
			local lp = P.lastPlan
			P.lastPlan = nil
			if lp and os.clock() - lp.t < 0.5 then
				pcall(function()
					local v3 = rawget(getgenv(), "__pulseAimV3")
					if v3 and v3.note then
						v3.note(lp.origin, lp.aim, lp.char, P.vel and P.vel(lp.char) or Vector3.zero)
					end
				end)
			end
		end
		return fired
	end

	-- start whatever the saved / default type needs
	pcall(sa.onType)
end
