	local function func114()
		return list2.hasGun()
	end

	-- 1x1 fully transparent PNG, used to hide the game's own Shift Lock / gun reticle (Mouse.Icon)
	local blankIconPath = nil
	local function getBlankIcon()
		if blankIconPath then
			return blankIconPath
		end

		pcall(function()
			if writefile and getcustomasset then
				local file = "FVLV2_blank_cursor.png"
				writefile(file, "\137\080\078\071\013\010\026\010\000\000\000\013\073\072\068\082\000\000\000\001\000\000\000\001\008\006\000\000\000\031\021\196\137\000\000\000\011\073\068\065\084\120\156\099\096\000\002\000\000\005\000\001\122\094\171\063\000\000\000\000\073\069\078\068\174\066\096\130")
				local asset = getcustomasset(file)
				if type(asset) == "string" and asset ~= "" then
					blankIconPath = asset
				end
			end
		end)

		blankIconPath = blankIconPath or "rbxasset://textures/blank.png"
		return blankIconPath
	end

	local lastReticleScan = 0
	local reticleBlanked = false
	local savedMouseIcon, savedUISIcon = nil, nil
	local hiddenReticles = {}

	-- puts the game's own Shift Lock reticle back exactly how the game had it
	local function restoreReticle()
		if not reticleBlanked then
			return
		end

		reticleBlanked = false

		for img, transparency in pairs(hiddenReticles) do
			pcall(function()
				if img.Parent then
					img.ImageTransparency = transparency
				end
			end)
		end

		hiddenReticles = {}

		pcall(function()
			UserInputService.MouseIcon = savedUISIcon or ""
		end)

		pcall(function()
			mouse.Icon = savedMouseIcon or (func114() and MM2_GUN_ICON or "")
		end)

		savedMouseIcon, savedUISIcon = nil, nil
	end

	flag135.restoreReticle = restoreReticle

	local function func115()
		restoreReticle()
		flag135.shapeParts = nil

		if connection5 then
			pcall(function()
				connection5:Disconnect()
			end)

			connection5 = nil
		end

		if value131 then
			pcall(function()
				value131:Destroy()
			end)

			value131 = nil
		end

		value130 = nil
		UserInputService.MouseIconEnabled = mouseIconEnabled

		pcall(function()
			UserInputService.MouseIcon = ""
		end)

		pcall(function()
			mouse.Icon = func114() and MM2_GUN_ICON or ""
		end)
	end

	func111 = function()
		func115()
		if flag135.style == "Default" or not CURSORS[flag135.style] then
			return
		end
		local screenGui = Instance.new("ScreenGui")
		screenGui.Name = "FVLCrosshair"
		screenGui.ResetOnSpawn = false
		screenGui.IgnoreGuiInset = true
		screenGui.DisplayOrder = 10000
		screenGui.Parent = (gethui and gethui()) or CoreGui
		local imageLabel = Instance.new("ImageLabel")
		imageLabel.AnchorPoint = Vector2.new(0.5, 0.5)
		imageLabel.BackgroundTransparency = 1
		imageLabel.Image = CURSORS[flag135.style] or CURSORS.Paw
		imageLabel.Size = UDim2.fromOffset(flag135.size, flag135.size)
		imageLabel.ScaleType = Enum.ScaleType.Stretch
		imageLabel.Parent = screenGui
		value131 = screenGui
		value130 = imageLabel

		-- vector shapes (Dot, Ring, Cross ...) are drawn with frames inside the label instead of an image
		if flag135.isShape and flag135.isShape(flag135.style) then
			imageLabel.Image = ""
			flag135.shapeParts = flag135.drawShape(imageLabel, flag135.style, flag135.size, flag135.currentShapeColor())
		end

		connection5 = RunService.RenderStepped:Connect(function(deltaTime)
			if not imageLabel.Parent then
				return
			end

			if flag135.spin then
				imageLabel.Rotation = (imageLabel.Rotation + deltaTime * flag135.spinSpeed) % 360
			elseif imageLabel.Rotation ~= 0 then
				imageLabel.Rotation = 0
			end

			if flag135.shapeParts and flag135.shapeRainbow then
				flag135.paintShape(flag135.shapeParts, flag135.currentShapeColor())
			end

			local visible = not flag135.onlyWithGun or func114()
			imageLabel.Visible = visible

			if visible then
				UserInputService.MouseIconEnabled = false
			else
				UserInputService.MouseIconEnabled = mouseIconEnabled
			end

			if visible then
				local currentCamera = workspace.CurrentCamera
				-- Mode picked in the Crosshair tab:
				--   Center = pinned to the middle of the screen, game reticle hidden
				--   Finger = follows the finger / mouse, original Shift Lock reticle is back
				if flag135.mode ~= "Finger" and currentCamera then
					local centre = currentCamera.ViewportSize / 2
					imageLabel.Position = UDim2.fromOffset(centre.X, centre.Y)

					-- Shift Lock draws its own centre reticle through Mouse.Icon (and MM2 puts the gun icon there too).
					-- Blank it every frame so only the chosen crosshair is left in the centre of the screen.
					local blank = getBlankIcon()
					reticleBlanked = true

					pcall(function()
						local cur = mouse.Icon

						if cur ~= blank then
							savedMouseIcon = cur
							mouse.Icon = blank
						end
					end)

					pcall(function()
						local cur = UserInputService.MouseIcon

						if cur ~= blank then
							savedUISIcon = cur
							UserInputService.MouseIcon = blank
						end
					end)

					-- in case the reticle is a normal GUI image instead of the mouse icon, make it invisible
					if os.clock() - lastReticleScan > 2 then
						lastReticleScan = os.clock()

						pcall(function()
							for _, root in ipairs({ localPlayer:FindFirstChildOfClass("PlayerGui"), CoreGui }) do
								for _, d in ipairs(root:GetDescendants()) do
									if d:IsA("ImageLabel") and d ~= imageLabel and type(d.Image) == "string"
										and d.Image:find("MouseLockedCursor", 1, true) then
										if hiddenReticles[d] == nil and d.ImageTransparency < 1 then
											hiddenReticles[d] = d.ImageTransparency
										end

										d.ImageTransparency = 1
									end
								end
							end
						end)
					end
				else
					-- finger mode: give the original Shift Lock reticle back (only does work once, right after switching)
					restoreReticle()

					local mouseLocation = UserInputService:GetMouseLocation()
					imageLabel.Position = UDim2.fromOffset(mouseLocation.X, mouseLocation.Y)
				end
			end
		end)
	end

	flag136 = false

	func112 = function(callback3)
		return function(...)
			if not flag136 then
				return
			end
			return callback3(...)
		end
	end

	func113 = function()
		flag135.style = "Default"
		func115()
	end
end

-- ===== Vector crosshair shapes (from the other hub's cursor): Dot, Ring, Cross, Gap Cross, Gap Dot, Ring Dot,
-- Diagonal, Brackets, Tri, Diamond, Square, Heart, PP. They are drawn with frames (not images) so they stay sharp at
-- any size and can be recoloured / made rainbow. They show up in the Crosshair grid like every other crosshair.
do
	local SHAPES = {
		["Shape Dot"] = "Dot",
		["Shape Ring"] = "Ring",
		["Shape Cross"] = "Crosshair",
		["Shape Gap Cross"] = "Gap",
		["Shape Gap Dot"] = "GapDot",
		["Shape Ring Dot"] = "RingDot",
		["Shape Diagonal"] = "Diag",
		["Shape Brackets"] = "Brackets",
		["Shape Tri"] = "Tri",
		["Shape Diamond"] = "Diamond",
		["Shape Square"] = "Square",
		["Shape Heart"] = "Heart",
		["Shape PP"] = "PP",
	}

	flag135.SHAPE_ORDER = {
		"Shape Dot", "Shape Ring", "Shape Cross", "Shape Gap Cross", "Shape Gap Dot", "Shape Ring Dot",
		"Shape Diagonal", "Shape Brackets", "Shape Tri", "Shape Diamond", "Shape Square", "Shape Heart", "Shape PP",
	}

	-- an empty image so the existing "is this a crosshair" checks keep working
	for name in pairs(SHAPES) do
		CURSORS[name] = ""
	end

	flag135.shapeColor = Color3.new(1, 1, 1)
	flag135.shapeRainbow = false
	flag135.shapeOutline = true

	local DESIGN = 32 -- shapes are designed on a 32 x 32 box and scaled to the crosshair size

	flag135.isShape = function(name)
		return SHAPES[name] ~= nil
	end

	flag135.currentShapeColor = function()
		if flag135.shapeRainbow then
			return Color3.fromHSV(os.clock() * 0.18 % 1, 0.8, 1)
		end

		return flag135.shapeColor
	end

	local function el(parent, k, x, y, w, h, rot, corner, z)
		local frame = Instance.new("Frame")
		frame.BorderSizePixel = 0
		frame.AnchorPoint = Vector2.new(0.5, 0.5)
		frame.Position = UDim2.new(0.5, x * k, 0.5, y * k)
		frame.Size = UDim2.fromOffset(w * k, h * k)
		frame.Rotation = rot or 0
		frame.ZIndex = z or 3

		if corner then
			local uiCorner = Instance.new("UICorner")
			uiCorner.CornerRadius = corner
			uiCorner.Parent = frame
		end

		frame.Parent = parent
		return frame
	end

	flag135.paintShape = function(parts, color)
		if not parts then
			return
		end

		local outline = flag135.shapeOutline ~= false

		for _, item in ipairs(parts) do
			if item.k == "fill" then
				item.i.BackgroundColor3 = color
				item.i.BackgroundTransparency = 0

				if item.o then
					item.o.Visible = outline
					item.o.BackgroundTransparency = 0.4
				end
			else
				item.s.Color = color
				item.s.Transparency = 0
				item.o.Visible = outline
				item.os.Transparency = 0.4
			end
		end
	end

	-- draws the shape `name` inside `parent` (a label), scaled to a `box` x `box` square; returns the parts
	flag135.drawShape = function(parent, name, box, color)
		for _, child in ipairs(parent:GetChildren()) do
			if child:IsA("Frame") then
				child:Destroy()
			end
		end

		local kind = SHAPES[name]
		local parts = {}

		if not kind then
			return parts
		end

		local k = box / DESIGN

		local function fill(x, y, w, h, rot, corner, noOutline)
			local cornerRadius = corner and UDim.new(corner, 0) or nil
			local outline

			if not noOutline then
				outline = el(parent, k, x, y, w + 2, h + 2, rot, cornerRadius, 2)
				outline.BackgroundColor3 = Color3.new(0, 0, 0)
			end

			parts[#parts + 1] = { k = "fill", i = el(parent, k, x, y, w, h, rot, cornerRadius, 3), o = outline }
		end

		local function ring(x, y, d, thickness, rot, square)
			local cornerRadius = (not square) and UDim.new(0.5, 0) or nil
			local outer = el(parent, k, x, y, d - 2, d - 2, rot, cornerRadius, 2)
			outer.BackgroundTransparency = 1
			local outerStroke = Instance.new("UIStroke")
			outerStroke.Color = Color3.new(0, 0, 0)
			outerStroke.Thickness = (thickness + 2) * k
			outerStroke.Parent = outer
			local inner = el(parent, k, x, y, d, d, rot, cornerRadius, 3)
			inner.BackgroundTransparency = 1
			local stroke = Instance.new("UIStroke")
			stroke.Thickness = thickness * k
			stroke.Parent = inner
			parts[#parts + 1] = { k = "ring", i = inner, s = stroke, o = outer, os = outerStroke }
		end

		if kind == "Dot" then
			fill(0, 0, 6, 6, 0, 0.5)
		elseif kind == "Ring" then
			ring(0, 0, 14, 2)
		elseif kind == "Crosshair" then
			fill(0, 0, 18, 2)
			fill(0, 0, 2, 18)
		elseif kind == "Gap" or kind == "GapDot" then
			fill(7, 0, 8, 2)
			fill(-7, 0, 8, 2)
			fill(0, 7, 2, 8)
			fill(0, -7, 2, 8)

			if kind == "GapDot" then
				fill(0, 0, 2, 2)
			end
		elseif kind == "RingDot" then
			ring(0, 0, 16, 2)
			fill(0, 0, 4, 4, 0, 0.5)
		elseif kind == "Diag" then
			fill(5, 5, 8, 2, 45)
			fill(-5, -5, 8, 2, 45)
			fill(5, -5, 8, 2, -45)
			fill(-5, 5, 8, 2, -45)
		elseif kind == "Brackets" then
			for _, sx in ipairs({ -1, 1 }) do
				for _, sy in ipairs({ -1, 1 }) do
					fill(sx * 7, sy * 9, 6, 2)
					fill(sx * 9, sy * 7, 2, 6)
				end
			end

			fill(0, 0, 2, 2)
		elseif kind == "Tri" then
			fill(0, -8, 8, 2, 90)
			fill(7, 4, 8, 2, 30)
			fill(-7, 4, 8, 2, 150)
		elseif kind == "Diamond" then
			ring(0, 0, 12, 2, 45, true)
		elseif kind == "Square" then
			ring(0, 0, 14, 2, 0, true)
			fill(0, 0, 2, 2)
		elseif kind == "Heart" then
			fill(-4, -3, 10, 10, 0, 0.5, true)
			fill(4, -3, 10, 10, 0, 0.5, true)
			fill(0, 2, 12, 12, 45, nil, true)
		elseif kind == "PP" then
			fill(0, -2, 8, 22, 0, 1, true)
			fill(0, -14, 10, 10, 0, 1, true)
			fill(-5, 10, 8, 8, 0, 1, true)
			fill(5, 10, 8, 8, 0, 1, true)
		end

		flag135.paintShape(parts, color or Color3.new(1, 1, 1))
		return parts
	end

	flag135.redrawShape = function()
		if value130 and value130.Parent and flag135.isShape(flag135.style) then
			flag135.shapeParts = flag135.drawShape(value130, flag135.style, flag135.size, flag135.currentShapeColor())
		end
	end

	flag135.repaintShape = function()
		if flag135.shapeParts then
			flag135.paintShape(flag135.shapeParts, flag135.currentShapeColor())
		end
	end
end

