		-- Round Start Alert (from Star Hub): when a round starts, tells you which role YOU got.
		-- (Notify: Roles above is a different thing: it announces who the murderer / sheriff are.)
		-- EDIT: it now shows BEFORE the round starts (as soon as the map is loaded / your role is handed out, while the
		-- round timer is still not running). roundBegin (timer running) stays as a fallback. One alert per round.
		X.nRoundStart = true

		local lastRoundAlert = 0
		local announced = false -- the alert of the current round was already shown
		local alertAlive = true

		-- is a round's map in the world? (same signal the Map Picker uses)
		local function mapLoaded()
			for _, child in ipairs(workspace:GetChildren()) do
				if child:IsA("Model") and child.Name ~= "RegularLobby" and child.Name ~= "Lobby"
					and (child:FindFirstChild("CoinContainer") or child:FindFirstChild("CoinAreas") or child:FindFirstChild("Spawns")) then
					return true
				end
			end

			return false
		end

		local function announceRound(early, since)
			if early then
				-- before the round starts: wait for the FRESH role data of the new round (so the role of the last round is
				-- never shown), then let it settle
				for _ = 1, 32 do
					if (list2.liveAt or 0) >= (since or 0) and list2.getPlayerRole(localPlayer) ~= nil then
						break
					end

					task.wait(0.25)
				end

				task.wait(0.3)
			else
				-- the role data of the new round arrives a moment after the timer starts: let it settle, then read it
				task.wait(0.8)
			end

			local myRole = nil

			for _ = 1, 20 do
				myRole = list2.getPlayerRole(localPlayer)

				if myRole ~= nil then
					break
				end

				task.wait(0.25)
			end

			task.wait(0.4)
			myRole = list2.getPlayerRole(localPlayer) or myRole or "Innocent"

			local m, s = func15(), func16()

			-- Zombie / Survivor rounds have many of these: only name them in a normal round
			if m and list2.isRole(m, "Zombie") then
				m = nil
			end

			if s and list2.isRole(s, "Survivor") then
				s = nil
			end

			local lines = {}

			if m and m ~= localPlayer then
				lines[#lines + 1] = "Murderer: " .. m.DisplayName
			end

			if s and s ~= localPlayer then
				lines[#lines + 1] = "Sheriff: " .. s.DisplayName
			end

			local icon = "user"

			if myRole == "Murderer" or myRole == "Zombie" then
				icon = "skull"
			elseif myRole == "Sheriff" or myRole == "Survivor" then
				icon = "shield"
			end

			obj2:Notify({
				Title = (early and "Round starting  -  you are " or "Round started  -  you are ") .. tostring(myRole),
				Content = #lines > 0 and table.concat(lines, "\n") or "Good luck!",
				Duration = 6,
				Icon = icon,
			})
		end

		tbl43.esp:Toggle({
			Title = "Round Start Alert", Flag = "Toggle_Extra_RoundStartAlert",
			Desc = "Before the round starts (map loaded, timer not running yet), tells you which role you got (Murderer, Sheriff, Innocent...) and who the others are",
			Type = "Toggle", Value = true,
			Callback = function(v) X.nRoundStart = v end,
		})

		local function triggerAlert(early)
			if announced or not X.nRoundStart then
				return
			end

			announced = true
			lastRoundAlert = os.clock()
			local since = os.clock() - 2

			task.spawn(function()
				pcall(announceRound, early, since)
			end)
		end

		-- 1) BEFORE the round starts: the map is put into the world while the round timer is still not running
		list2.conns[#list2.conns + 1] = workspace.DescendantAdded:Connect(function(item)
			if announced or list2.roundLive then
				return
			end

			if item.Name == "CoinContainer" or item.Name == "CoinAreas" then
				triggerAlert(true)
			end
		end)

		-- 2) BEFORE the round starts: the game hands out the roles (map loaded, timer still not running)
		pcall(function()
			local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
			remotes = remotes and remotes:FindFirstChild("Gameplay")
			local pdc = remotes and remotes:FindFirstChild("PlayerDataChanged")

			if pdc and pdc:IsA("RemoteEvent") then
				list2.conns[#list2.conns + 1] = pdc.OnClientEvent:Connect(function(data)
					if announced or list2.roundLive or type(data) ~= "table" then
						return
					end

					local rec = data[localPlayer.Name]

					if type(rec) == "table" and rec.Role ~= nil and mapLoaded() then
						triggerAlert(true)
					end
				end)
			end
		end)

		-- 3) fallback: the round timer started and nothing above fired yet
		local origRoundBegin = list2.roundBegin
		local hookedRoundBegin

		hookedRoundBegin = function(...)
			origRoundBegin(...)
			triggerAlert(false)
		end

		list2.roundBegin = hookedRoundBegin

		-- arm the alert again once the round is over and its map is gone
		task.spawn(function()
			while alertAlive and list2.current() do
				if announced and not list2.roundLive and not mapLoaded() then
					announced = false
				end

				task.wait(1)
			end
		end)

		list2.conns[#list2.conns + 1] = {
			Disconnect = function()
				X.nRoundStart = false
				alertAlive = false

				if list2.roundBegin == hookedRoundBegin then
					list2.roundBegin = origRoundBegin
				end
			end,
		}
	end

	installExtras()
end

-- ===================== CHAMS (Self / Tool) (ported) =====================
-- Chams: styles, animations, second colour, speed and transparency for your own character and your held tool.
do
	local function installChamsAndTextures()
		local RS = game:GetService("RunService")
		local genv = (getgenv and getgenv()) or _G

		local function alive()
			return _G.FVLV2 == obj3
		end

		local function conn(c)
			list2.conns[#list2.conns + 1] = c
			return c
		end

		local function pick(v)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			return v and tostring(v) or nil
		end

		local function notify(title, text, icon)
			pcall(function()
				obj2:Notify({ Title = title, Content = text, Duration = 6, Icon = icon or "x" })
			end)
		end

		----------------------------------------------------------------
		-- CHAMS
		----------------------------------------------------------------
		local M = Enum.Material
		local WHITE = Color3.new(1, 1, 1)

		local STYLES = {
			ForceField = { m = M.ForceField },
			Hologram = { m = M.ForceField, clean = true, edge = true },
			Flat = { m = M.SmoothPlastic, clean = true },
			Neon = { m = M.Neon, clean = true },
			Glow = { m = M.Neon, clean = true, edge = true },
			Glass = { m = M.Glass, clean = true, r = 0.25, t = 0.35 },
			Crystal = { m = M.Glass, clean = true, r = 0.5, t = 0.55, edge = true },
			Chrome = { m = M.SmoothPlastic, clean = true, r = 0.6 },
			Metallic = { m = M.Foil, clean = true, r = 0.3 },
			Ice = { m = M.Ice, clean = true, r = 0.2, t = 0.15 },
			Lava = { m = M.CrackedLava, clean = true },
			Ghost = { m = M.SmoothPlastic, clean = true, r = 0.1, t = 0.6, edge = true },
			Wireframe = { m = M.ForceField, clean = true, t = 0.85, wire = true },
			Silhouette = { fill = 0, edge = true },
			Tint = { fill = 0.5 },
			Outline = { edge = true },
		}

		local STYLE_LIST = {
			"ForceField", "Hologram", "Flat", "Neon", "Glow", "Glass", "Crystal", "Chrome",
			"Metallic", "Ice", "Lava", "Ghost", "Wireframe", "Silhouette", "Tint", "Outline",
		}

		local ANIM_LIST = { "None", "Pulse", "Breathe", "Fade", "Flash", "Rainbow", "Wave", "Gradient" }

		local cfg = {}
		for _, kind in ipairs({ "self", "tool" }) do
			cfg[kind] = {
				on = false,
				col = Color3.fromRGB(0, 200, 255),
				col2 = Color3.new(1, 1, 1),
				style = "ForceField",
				anim = "None",
				speed = 100,
				alpha = 0,
			}
		end

		local saved, hls, boxes = {}, {}, {}
		local tgtMat, tgtHL, tgtWire = {}, {}, {}
		local folder = nil
		local animating = false
		local clockStart = os.clock()
		local lastFrame = 0

		local function near(a, b)
			if typeof(a) == "Color3" and typeof(b) == "Color3" then
				return math.abs(a.R - b.R) < 0.004 and math.abs(a.G - b.G) < 0.004 and math.abs(a.B - b.B) < 0.004
			end

			if type(a) == "number" and type(b) == "number" then
				return math.abs(a - b) < 0.002
			end

			return a == b
		end

		local function setProp(inst, prop, value)
			if not near(inst[prop], value) then
				inst[prop] = value
			end
		end

		-- write `want` to inst[prop], remembering the original value; if the game changed the prop meanwhile, adopt that as the new original
		local function track(inst, st, prop, want)
			local cur, wrote = inst[prop], st.w[prop]

			if wrote == nil then
				st.o[prop] = cur
			elseif not near(cur, wrote) then
				st.o[prop] = cur
			end

			if type(want) == "function" then
				want = want(st.o[prop])
			end

			if want == nil then
				st.w[prop] = nil
				return
			end

			if not near(cur, want) then
				inst[prop] = want
			end

			st.w[prop] = want
		end

		local function restoreItem(inst, st)
			if st.cloth then
				if inst.Parent == nil and st.par and st.par.Parent then
					inst.Parent = st.par
				end
				return
			end

			if not inst.Parent then
				return
			end

			for prop, orig in pairs(st.o) do
				local wrote = st.w[prop]

				if wrote ~= nil then
					pcall(function()
						if near(inst[prop], wrote) then
							inst[prop] = orig
						end
					end)
				end
			end
		end

		local function getFolder()
			local cam = workspace.CurrentCamera

			if folder and folder.Parent == cam then
				return folder
			end

			if folder then
				pcall(function()
					folder:Destroy()
				end)
			end

			folder = Instance.new("Folder")
			folder.Name = "FVLSelfChams"
			folder.Parent = cam
			return folder
		end

		-- returns colour + extra transparency for the current animation frame
		local function animColor(entry, elapsed, yOff)
			local col, col2, anim = entry.col, entry.col2, entry.anim
			local t = elapsed * entry.speed / 100

			if anim == "Pulse" then
				local h, s, v = col:ToHSV()
				return Color3.fromHSV(h, s, v * (0.35 + 0.65 * (0.5 + 0.5 * math.sin(t * 4)))), 0
			elseif anim == "Breathe" then
				return col, 0.7 * (0.5 - 0.5 * math.cos(t * 3))
			elseif anim == "Fade" then
				return col:Lerp(col2, 0.5 - 0.5 * math.cos(t * 2.5)), 0
			elseif anim == "Flash" then
				return (math.floor(t * 5) % 2 == 0) and col or col2, 0
			elseif anim == "Rainbow" or anim == "Wave" then
				local _, s, v = col:ToHSV()
				local hue = (anim == "Wave") and (t * 0.35 - yOff * 0.08) or (t * 0.25)
				return Color3.fromHSV(hue % 1, math.max(s, 0.55), math.max(v, 0.8)), 0
			elseif anim == "Gradient" then
				return col2:Lerp(col, 0.5 + 0.5 * math.sin(t * 2.2 - yOff * 0.8)), 0
			end

			return col, 0
		end

		local function alphaMix(base, styleT, entry, extra)
			return 1 - (1 - base) * (1 - (styleT or 0)) * (1 - entry.alpha / 100) * (1 - extra)
		end

		local function visible(inst)
			if inst:IsA("BasePart") then
				return inst.Transparency < 0.99 and inst.LocalTransparencyModifier < 0.99
			end

			return true
		end

		local function collect(root, kind, style, isSelf)
			local function visit(inst)
				if inst:GetAttribute("FVLVFX") or string.sub(inst.Name, 1, 3) == "FVL" then
					return
				end

				if inst:IsA("BasePart") then
					if inst.Name == "HumanoidRootPart" then
						return
					end

					if style.m then
						if saved[inst] or inst.Transparency < 0.99 then
							tgtMat[inst] = kind
						end
					end

					if style.wire and inst.Transparency < 0.99 then
						tgtWire[inst] = kind
					end
				elseif style.clean then
					if inst:IsA("Decal") or inst:IsA("SpecialMesh") then
						tgtMat[inst] = kind
					elseif isSelf and (inst:IsA("Clothing") or inst:IsA("ShirtGraphic")) then
						tgtMat[inst] = kind
					end
				end
			end

			visit(root)

			for _, d in ipairs(root:GetDescendants()) do
				visit(d)
			end
		end

		-- the knife / gun shown on your character while it is holstered (MM2 keeps a pointer to it on the character)
		local function displayRefs(char)
			local out = {}

			for _, n in ipairs({ "DisplayRefKnife", "DisplayRefGun" }) do
				local ov = char:FindFirstChild(n)
				local v = ov and ov:IsA("ObjectValue") and ov.Value

				if v and v.Parent then
					out[#out + 1] = v
				end
			end

			return out
		end

		local function collectTargets()
			tgtMat, tgtHL, tgtWire = {}, {}, {}

			local char = localPlayer.Character

			if not char then
				return
			end

			local s, t = cfg.self, cfg.tool

			if s.on then
				local st = STYLES[s.style]

				for _, ch in ipairs(char:GetChildren()) do
					if not ch:IsA("Tool") then
						collect(ch, "self", st, true)
					end
				end

				if st.fill or st.edge then
					tgtHL[char] = "self"

					-- a see-through highlight on the tool stops the character's highlight from covering it
					for _, ch in ipairs(char:GetChildren()) do
						if ch:IsA("Tool") then
							tgtHL[ch] = "block"
						end
					end
				end
			end

			if t.on then
				local st = STYLES[t.style]

				for _, ch in ipairs(char:GetChildren()) do
					if ch:IsA("Tool") then
						collect(ch, "tool", st, false)

						if st.fill or st.edge then
							tgtHL[ch] = "tool"
						end
					end
				end

				for _, item in ipairs(displayRefs(char)) do
					if visible(item) then
						collect(item, "tool", st, false)

						if st.fill or st.edge then
							tgtHL[item] = "tool"
						end
					end
				end
			end
		end

		local function syncTargets()
			for inst, item in pairs(saved) do
				local keep = tgtMat[inst] == item.kind

				if not keep and item.cloth then
					local e = cfg[item.kind]
					keep = e.on and STYLES[e.style].clean == true and item.par ~= nil and item.par.Parent ~= nil
				end

				if not keep then
					saved[inst] = nil
					pcall(restoreItem, inst, item)
				end
			end

			for inst, kind in pairs(tgtMat) do
				if not saved[inst] then
					local st = { kind = kind, o = {}, w = {} }

					if inst:IsA("Clothing") or inst:IsA("ShirtGraphic") then
						st.cloth, st.par = true, inst.Parent
						saved[inst] = st

						pcall(function()
							inst.Parent = nil
						end)
					else
						st.part = inst:IsA("BasePart")
						st.mp = inst:IsA("MeshPart")
						st.decal = inst:IsA("Decal")
						st.mesh = inst:IsA("SpecialMesh")
						saved[inst] = st
					end
				end
			end

			for adornee, item in pairs(hls) do
				if tgtHL[adornee] ~= item.kind or not adornee.Parent then
					hls[adornee] = nil

					pcall(function()
						item.h:Destroy()
					end)
				end
			end

			for adornee, kind in pairs(tgtHL) do
				if not hls[adornee] then
					local h = Instance.new("Highlight")
					h.Name = "FVLChamsHL"
					h.DepthMode = Enum.HighlightDepthMode.Occluded
					h.FillTransparency = 1
					h.OutlineTransparency = 1
					h.Adornee = adornee
					h.Parent = getFolder()
					hls[adornee] = { h = h, kind = kind }
				end
			end

			for adornee, item in pairs(boxes) do
				if tgtWire[adornee] ~= item.kind or not adornee.Parent then
					boxes[adornee] = nil

					pcall(function()
						item.b:Destroy()
					end)
				end
			end

			for adornee, kind in pairs(tgtWire) do
				if not boxes[adornee] then
					local b = Instance.new("SelectionBox")
					b.Name = "FVLChamsWire"
					b.LineThickness = 0.025
					b.SurfaceTransparency = 1
					b.Transparency = 1
					b.Adornee = adornee
					b.Parent = getFolder()
					boxes[adornee] = { b = b, kind = kind }
				end
			end
		end

		-- applyAll = true  : full pass (every property, decals, meshes)
		-- applyAll = false : cheap animation frame (only colour / transparency)
		local function update(applyAll)
			local elapsed = os.clock() - clockStart
			local char = localPlayer.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			local rootY = root and root.Position.Y or nil

			for inst, item in pairs(saved) do
				local e = cfg[item.kind]
				local style = STYLES[e.style]

				if item.part then
					if inst.Parent and style.m and (applyAll or e.anim ~= "None") then
						pcall(function()
							local col, extra = animColor(e, elapsed, rootY and inst.Position.Y - rootY or 0)

							track(inst, item, "Material", style.m)
							track(inst, item, "Color", col)
							track(inst, item, "Reflectance", style.r or 0)

							if applyAll and style.clean and item.mp then
								track(inst, item, "TextureID", "")
							end

							local styleT = style.t or 0

							if styleT > 0 or e.alpha > 0 or extra > 0 or item.w.Transparency ~= nil then
								track(inst, item, "Transparency", function(orig)
									if orig >= 0.99 then
										return nil
									end
									return alphaMix(orig, styleT, e, extra)
								end)
							end
						end)
					end
				elseif applyAll and inst.Parent then
					if item.decal then
						pcall(track, inst, item, "Transparency", 1)
					elseif item.mesh then
						pcall(track, inst, item, "TextureId", "")
					end
				end
			end

			for adornee, item in pairs(hls) do
				local e = cfg[item.kind]

				if item.kind == "block" then
					pcall(function()
						setProp(item.h, "FillTransparency", 1)
						setProp(item.h, "OutlineTransparency", 1)

						if not item.h.Enabled then
							item.h.Enabled = true
						end
					end)
				else
					pcall(function()
						local style = STYLES[e.style]
						local col, extra = animColor(e, elapsed, 0)
						local h, hide = item.h, 0

						-- your own head fades out in first person: fade the highlight with it
						if adornee == char then
							local head = adornee:FindFirstChild("Head")

							if head and head:IsA("BasePart") then
								hide = head.LocalTransparencyModifier
							end
						end

						setProp(h, "FillColor", col)
						setProp(h, "OutlineColor", (style.fill == 0) and col:Lerp(WHITE, 0.4) or col)
						setProp(h, "FillTransparency",
							style.fill and (1 - (1 - alphaMix(0, style.fill, e, extra)) * (1 - hide)) or 1)
						setProp(h, "OutlineTransparency",
							style.edge and (1 - (1 - alphaMix(0, 0, e, extra)) * (1 - hide)) or 1)

						local on = hide < 0.95 and visible(adornee)

						if h.Enabled ~= on then
							h.Enabled = on
						end
					end)
				end
			end

			for adornee, item in pairs(boxes) do
				local e = cfg[item.kind]

				pcall(function()
					local col, extra = animColor(e, elapsed, rootY and adornee.Position.Y - rootY or 0)
					local b, hide = item.b, adornee.LocalTransparencyModifier

					setProp(b, "Color3", col)
					setProp(b, "Transparency", 1 - (1 - alphaMix(0, 0, e, extra)) * (1 - hide))

					local show = hide < 0.95 and adornee.Transparency < 0.99

					if b.Visible ~= show then
						b.Visible = show
					end
				end)
			end
		end

		local function apply()
			animating = (cfg.self.on and cfg.self.anim ~= "None") or (cfg.tool.on and cfg.tool.anim ~= "None")
			pcall(collectTargets)
			pcall(syncTargets)
			pcall(update, true)
		end

		local function clearKind(kind)
			for inst, item in pairs(saved) do
				if item.kind == kind then
					saved[inst] = nil
					pcall(restoreItem, inst, item)
				end
			end

			for adornee, item in pairs(hls) do
				if item.kind == kind or (kind == "self" and item.kind == "block") then
					hls[adornee] = nil

					pcall(function()
						item.h:Destroy()
					end)
				end
			end

			for adornee, item in pairs(boxes) do
				if item.kind == kind then
					boxes[adornee] = nil

					pcall(function()
						item.b:Destroy()
					end)
				end
			end
		end

		local function chamsShutdown()
			cfg.self.on, cfg.tool.on = false, false
			clearKind("self")
			clearKind("tool")

			if folder then
				pcall(function()
					folder:Destroy()
				end)
				folder = nil
			end
		end

		task.spawn(function()
			while alive() do
				task.wait(0.4)

				if cfg.self.on or cfg.tool.on or next(saved) or next(hls) or next(boxes) then
					apply()
				end
			end

			pcall(chamsShutdown)
		end)

		conn(RS.RenderStepped:Connect(function()
			if not alive() then
				return
			end

			if not animating and not next(hls) and not next(boxes) then
				return
			end

			local now = os.clock()

			if now - lastFrame < 1 / 30 then
				return
			end

			lastFrame = now
			pcall(update, false)
		end))

		conn({ Disconnect = function() pcall(chamsShutdown) end })

		----------------------------------------------------------------
		-- UI (Visuals tab)
		----------------------------------------------------------------
		local function buildChamsUI(kind, label)
			local e = cfg[kind]
			local fl = (kind == "self") and "Self" or "Tool"

			tbl43.visuals:Section({ Title = label .. " Chams" })

			tbl43.visuals:Toggle({
				Title = label .. " Chams", Flag = "Toggle_Chams_" .. fl, Type = "Toggle", Value = false,
				Desc = (kind == "self") and "Restyles your own character." or "Restyles the tool in your hand (and your holstered knife / gun).",
				Callback = function(v)
					e.on = v and true or false
					apply()
				end,
			})

			tbl43.visuals:Colorpicker({
				Title = label .. " Chams Color", Flag = "Colorpicker_Chams_" .. fl, Default = e.col,
				Callback = function(c)
					if typeof(c) ~= "Color3" then
						return
					end

					e.col = c
					pcall(update, true)
				end,
			})

			tbl43.visuals:Dropdown({
				Title = label .. " Chams Style", Flag = "Dropdown_Chams_Style_" .. fl, Multi = false, Value = "ForceField",
				Values = STYLE_LIST,
				Callback = function(v)
					local s = pick(v)

					if not s or not STYLES[s] or s == e.style then
						return
					end

					e.style = s
					clearKind(kind)
					apply()
				end,
			})

			tbl43.visuals:Dropdown({
				Title = label .. " Chams Animation", Flag = "Dropdown_Chams_Anim_" .. fl, Multi = false, Value = "None",
				Values = ANIM_LIST,
				Callback = function(v)
					local a = pick(v)

					if not a or not table.find(ANIM_LIST, a) or a == e.anim then
						return
					end

					e.anim = a
					apply()
				end,
			})

			tbl43.visuals:Slider({
				Title = label .. " Animation Speed", Flag = "Slider_Chams_Speed_" .. fl, Step = 5,
				Value = { Min = 10, Max = 300, Default = 100 },
				Callback = function(v)
					e.speed = math.clamp(tonumber(v) or 100, 10, 300)
				end,
			})

			tbl43.visuals:Colorpicker({
				Title = label .. " Chams Second Color", Flag = "Colorpicker_Chams_Second_" .. fl, Default = e.col2,
				Callback = function(c)
					if typeof(c) ~= "Color3" then
						return
					end

					e.col2 = c
					pcall(update, true)
				end,
			})

			tbl43.visuals:Slider({
				Title = label .. " Chams Transparency", Flag = "Slider_Chams_Alpha_" .. fl, Step = 1,
				Value = { Min = 0, Max = 90, Default = 0 },
				Callback = function(v)
					e.alpha = math.clamp(tonumber(v) or 0, 0, 90)
					pcall(update, true)
				end,
			})
		end

		buildChamsUI("self", "Self")
		buildChamsUI("tool", "Tool")
	end

	local ok, err = pcall(installChamsAndTextures)

	if not ok then
		warn("[F$VL] Chams failed to load: " .. tostring(err))
	end
end


-- ===================== WORLD EFFECTS + DEATH EFFECTS =====================
do
	local function installFx()
		local RS = game:GetService("RunService")
		local TweenService = game:GetService("TweenService")
		local Debris = game:GetService("Debris")

		local F = {
			world = false,
			worldType = "Snow",
			worldColor = Color3.fromRGB(150, 200, 255),
			worldRate = 250,
			mOn = false,
			pOn = false,
			pSelf = false,
			mode = "Custom Aura",
			auraScale = 1,
			color = Color3.fromRGB(255, 60, 60),
			duration = 2,
		}

		local function pick(v)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			return v and tostring(v) or nil
		end

		----------------------------------------------------------------
		-- World effects (snow / sakura around the camera)
		----------------------------------------------------------------
		local SPAN, TALL = 260, 140
		local wPart, wEmitter, wConn = nil, nil, nil

		local function styleEmitter()
			local e = wEmitter
			if not e then
				return
			end

			e.Texture = "rbxasset://textures/particles/smoke_main.dds"
			e.LightInfluence = 0
			e.LightEmission = 0.4
			e.Drag = 0
			e.EmissionDirection = Enum.NormalId.Bottom
			e.Rate = F.worldRate
			e.Color = ColorSequence.new(F.worldColor)
			e.Rotation = NumberRange.new(0, 360)

			if F.worldType == "Snow" then
				e.Lifetime = NumberRange.new(4, 6)
				e.Speed = NumberRange.new(6, 12)
				e.Acceleration = Vector3.new(2, -6, 1)
				e.SpreadAngle = Vector2.new(35, 35)
				e.RotSpeed = NumberRange.new(-40, 40)
				e.Squash = NumberSequence.new(0)
				e.Size = NumberSequence.new(0.55)
				e.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.2),
					NumberSequenceKeypoint.new(0.8, 0.3),
					NumberSequenceKeypoint.new(1, 1),
				})
			else
				-- Sakura: slower, drifting petals
				e.Lifetime = NumberRange.new(5, 7)
				e.Speed = NumberRange.new(5, 10)
				e.Acceleration = Vector3.new(4, -5, 2)
				e.SpreadAngle = Vector2.new(40, 40)
				e.RotSpeed = NumberRange.new(-80, 80)
				e.Squash = NumberSequence.new(1.4)
				e.Size = NumberSequence.new(0.5)
				e.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.15),
					NumberSequenceKeypoint.new(0.85, 0.25),
					NumberSequenceKeypoint.new(1, 1),
				})
			end
		end

		local function burstWorld()
			if wEmitter then
				wEmitter:Emit(math.clamp(math.floor(F.worldRate * 0.16), 30, 140))
			end
		end

		local function stopWorld()
			if wConn then
				pcall(function()
					wConn:Disconnect()
				end)
				wConn = nil
			end
			if wPart then
				pcall(function()
					wPart:Destroy()
				end)
				wPart = nil
			end
			wEmitter = nil
		end

		local function startWorld()
			stopWorld()

			wPart = Instance.new("Part")
			wPart.Name = "WorldFX"
			wPart.Anchored = true
			wPart.CanCollide = false
			wPart.CanQuery = false
			wPart.CanTouch = false
			wPart.Transparency = 1
			wPart.Size = Vector3.new(SPAN, TALL, SPAN)
			wPart.Parent = workspace

			wEmitter = Instance.new("ParticleEmitter")
			pcall(function()
				wEmitter.Shape = Enum.ParticleEmitterShape.Box
				wEmitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume
			end)
			wEmitter.Parent = wPart
			styleEmitter()

			wConn = RS.RenderStepped:Connect(function()
				local cam = workspace.CurrentCamera
				if not (wPart and wPart.Parent and cam) then
					return
				end

				local cf = cam.CFrame
				local look = cf.LookVector
				local flat = Vector3.new(look.X, 0, look.Z)
				flat = flat.Magnitude < 0.05 and Vector3.new(0, 0, -1) or flat.Unit
				wPart.CFrame = CFrame.new(cf.Position + flat * (SPAN * 0.22) + Vector3.new(0, TALL * 0.5 - 26, 0))
			end)

			burstWorld()
		end

		----------------------------------------------------------------
		-- Death effects
		----------------------------------------------------------------
		local ghosts, folders = {}, {}

		local function ghostClone(char)
			char.Archivable = true
			local ok, clone = pcall(function()
				return char:Clone()
			end)
			if not ok or not clone then
				return
			end

			for _, d in ipairs(clone:GetDescendants()) do
				if d:IsA("BasePart") then
					d.Anchored = true
					d.CanCollide = false
					d.CanQuery = false
					d.CanTouch = false

					if d.Name == "HumanoidRootPart" then
						d.Transparency = 1
					else
						d.Material = Enum.Material.ForceField
						d.Color = F.color
					end
				elseif d:IsA("Humanoid") or d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("SurfaceAppearance")
					or d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Highlight") or d:IsA("Light") then
					pcall(function()
						d:Destroy()
					end)
				end
			end

			clone.Name = "DeathGhost"
			clone.Parent = workspace
			ghosts[#ghosts + 1] = clone

			local life = F.duration
			task.delay(math.max(life - 1, 0.2), function()
				if not clone.Parent then
					return
				end
				for _, d in ipairs(clone:GetDescendants()) do
					if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart" then
						pcall(function()
							TweenService:Create(d, TweenInfo.new(1, Enum.EasingStyle.Linear), { Transparency = 1 }):Play()
						end)
					end
				end
			end)

			task.delay(life, function()
				for i = #ghosts, 1, -1 do
					if ghosts[i] == clone then
						table.remove(ghosts, i)
					end
				end
				if clone.Parent then
					clone:Destroy()
				end
			end)
		end

		local function orbBurst(char)
			local folder = Instance.new("Folder")
			folder.Name = "DeathOrbs"
			folder.Parent = workspace
			folders[#folders + 1] = folder

			local rnd = math.random
			local made = 0

			for _, part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and made < 120 then
					for _ = 1, 8 do
						local s = part.Size
						local pos = part.CFrame:PointToWorldSpace(Vector3.new(
							(rnd() - 0.5) * s.X * 1.3,
							(rnd() - 0.5) * s.Y * 1.3,
							(rnd() - 0.5) * s.Z * 1.3
						))
						local d = 0.12 + rnd() * 0.12
						local ball = Instance.new("Part")
						ball.Shape = Enum.PartType.Ball
						ball.Material = Enum.Material.Neon
						ball.Color = F.color
						ball.Size = Vector3.new(0.02, 0.02, 0.02)
						ball.Position = pos
						ball.Anchored = true
						ball.CanCollide = false
						ball.CanQuery = false
						ball.CanTouch = false
						ball.CastShadow = false
						ball.Transparency = 0.1
						ball.Parent = folder
						made += 1

						TweenService:Create(ball, TweenInfo.new(0.2, Enum.EasingStyle.Sine), {
							Size = Vector3.new(d, d, d),
						}):Play()

						local rise = F.duration * 0.6
						task.delay(F.duration * 0.3, function()
							if ball.Parent then
								TweenService:Create(ball, TweenInfo.new(rise, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {
									Position = pos + Vector3.new((rnd() - 0.5) * 2, 2 + rnd() * 3, (rnd() - 0.5) * 2),
									Transparency = 1,
									Size = Vector3.new(0.02, 0.02, 0.02),
								}):Play()
							end
						end)
					end
				end
			end

			Debris:AddItem(folder, F.duration + 0.5)
		end

		local function sparkBurst(char)
			local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildWhichIsA("BasePart")
			if not root then
				return
			end

			local p = Instance.new("Part")
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Transparency = 1
			p.Size = Vector3.new(1, 1, 1)
			p.CFrame = CFrame.new(root.Position)
			p.Parent = workspace

			local e = Instance.new("ParticleEmitter")
			e.Rate = 0
			e.Texture = "rbxasset://textures/particles/sparkles_main.dds"
			e.Color = ColorSequence.new(F.color)
			e.LightEmission = 1
			e.LightInfluence = 0
			e.Speed = NumberRange.new(15, 30)
			e.Lifetime = NumberRange.new(0.6, math.max(F.duration * 0.6, 0.7))
			e.SpreadAngle = Vector2.new(360, 360)
			e.Drag = 3
			e.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.6), NumberSequenceKeypoint.new(1, 0) })
			e.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
			e.Parent = p
			e:Emit(50)

			Debris:AddItem(p, F.duration + 1)
		end

		-- Custom aura (asset 96578040525953) played at the body when someone dies
		-- Auras you can pick in the "Death Effect Type" dropdown (name -> asset id)
		-- NOTE: the first aura has no name from you yet, rename "Custom Aura" below if you want
		local AURAS = {
			{ name = "Custom Aura", id = 96578040525953 },
			{ name = "Energy Aura", id = 11760581403 },
			{ name = "Dacknest Aura", id = 80145706481445 },
		}
		local AURA_BY_NAME = {}
		local AURA_NAMES = {}
		for _, a in ipairs(AURAS) do
			AURA_BY_NAME[a.name] = a
			AURA_NAMES[#AURA_NAMES + 1] = a.name
		end

		local auraTemplates = {}

		local function loadAura(aura)
			local cached = auraTemplates[aura.id]
			if cached then
				return cached
			end

			-- executor loader first, InsertService as a fallback
			local ok, objs = pcall(function()
				return game:GetObjects("rbxassetid://" .. aura.id)
			end)
			if ok and type(objs) == "table" and objs[1] then
				auraTemplates[aura.id] = objs[1]
				return objs[1]
			end

			local ok2, model = pcall(function()
				return game:GetService("InsertService"):LoadAsset(aura.id)
			end)
			if ok2 and model then
				auraTemplates[aura.id] = model
				return model
			end
		end

		-- preload all auras so the first death doesn't lag
		task.spawn(function()
			for _, a in ipairs(AURAS) do
				pcall(loadAura, a)
			end
		end)

		local function auraBurst(char, aura)
			local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildWhichIsA("BasePart")
			if not root then
				return
			end

			local origin = root.CFrame
			local life = F.duration

			local holder = Instance.new("Folder")
			holder.Name = "DeathAura_" .. aura.name:gsub("%s", "")
			holder.Parent = workspace
			folders[#folders + 1] = holder

			local tpl = loadAura(aura)
			if tpl then
				local obj = tpl:Clone()
				local model = Instance.new("Model")
				model.Name = "AuraModel"

				-- if LoadAsset returned a wrapper model, take its children
				if tpl:IsA("Model") and #tpl:GetChildren() > 0 and not tpl:FindFirstChildWhichIsA("BasePart") then
					for _, c in ipairs(obj:GetChildren()) do
						c.Parent = model
					end
					obj:Destroy()
				else
					obj.Parent = model
				end

				local all = model:GetDescendants()
				for _, d in ipairs(all) do
					if d:IsA("BaseScript") then
						pcall(function()
							d:Destroy()
						end)
					elseif d:IsA("BasePart") then
						d.Anchored = true
						d.CanCollide = false
						d.CanQuery = false
						d.CanTouch = false
						d.Massless = true
					end
				end

				model.Parent = holder

				-- normalise to a medium size: about 1.3x the player's height, times the Aura Size slider
				pcall(function()
					local charH = math.max(char:GetExtentsSize().Y, 3)
					local ext = model:GetExtentsSize()
					local biggest = math.max(ext.X, ext.Y, ext.Z)
					if biggest > 0.05 then
						model:ScaleTo(model:GetScale() * (charH * 1.3 * F.auraScale) / biggest)
					end
				end)

				pcall(function()
					model:PivotTo(origin)
				end)

				local emitters = {}
				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("ParticleEmitter") then
						d.Enabled = true
						pcall(function()
							d:Emit(d:GetAttribute("EmitCount") or 15)
						end)
						emitters[#emitters + 1] = d
					elseif d:IsA("Beam") or d:IsA("Trail") or d:IsA("Light") then
						d.Enabled = true
					end
				end

				-- stop emitting near the end so it fades out naturally
				task.delay(math.max(life * 0.7, 0.3), function()
					for _, e in ipairs(emitters) do
						pcall(function()
							e.Enabled = false
						end)
					end
				end)
			else
				-- fallback: asset is an image/texture, so use it as a particle
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.Transparency = 1
				p.Size = Vector3.new(1, 1, 1)
				p.CFrame = origin
				p.Parent = holder

				local e = Instance.new("ParticleEmitter")
				e.Rate = 0
				e.Texture = "rbxassetid://" .. aura.id
				e.Color = ColorSequence.new(F.color)
				e.LightEmission = 1
				e.LightInfluence = 0
				e.Speed = NumberRange.new(1, 4)
				e.Lifetime = NumberRange.new(math.max(life * 0.6, 0.6), math.max(life, 0.8))
				e.SpreadAngle = Vector2.new(25, 25)
				e.EmissionDirection = Enum.NormalId.Top
				e.Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 2.5 * F.auraScale),
					NumberSequenceKeypoint.new(1, 4.5 * F.auraScale),
				})
				e.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.2),
					NumberSequenceKeypoint.new(1, 1),
				})
				e.Parent = p
				e:Emit(6)
			end

			Debris:AddItem(holder, life + 1.5)
		end

		-- ===== Death Dissolve (from Star Hub): the body turns into a glowing shell that burns away from the feet up =====
		local function shellCopy(part, scale)
			local ok, copy = pcall(function()
				local was = part.Archivable
				part.Archivable = true
				local c = part:Clone()
				part.Archivable = was
				return c
			end)

			if not ok or not copy then
				return nil
			end

			local mesh

			for _, child in ipairs(copy:GetChildren()) do
				if child:IsA("SpecialMesh") then
					mesh = child
				else
					child:Destroy()
				end
			end

			copy.Name = "FVLDissolveShell"
			copy.Material = Enum.Material.Neon
			copy.Anchored = true
			copy.CanCollide = false
			copy.CanQuery = false
			copy.CanTouch = false
			copy.CastShadow = false
			copy.Massless = true

			pcall(function()
				copy.TextureID = ""
			end)

			if mesh then
				mesh.TextureId = ""

				if mesh.MeshType == Enum.MeshType.FileMesh then
					mesh.Scale = mesh.Scale * scale
				else
					copy.Size = copy.Size * scale
				end
			else
				copy.Size = copy.Size * scale
			end

			return copy
		end

		local function dissolve(char)
			local TweenService = game:GetService("TweenService")
			local parts = {}
			local lowY, highY = math.huge, -math.huge

			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart" and d.Transparency < 0.9 then
					parts[#parts + 1] = d
					lowY = math.min(lowY, d.Position.Y)
					highY = math.max(highY, d.Position.Y)
				elseif d:IsA("Decal") then
					d.LocalTransparencyModifier = 1
				end
			end

			if #parts == 0 then
				return
			end

			local root = char:FindFirstChild("HumanoidRootPart")
			local centre = root and root.Position or parts[1].Position
			local foot = Vector3.new(centre.X, lowY - 0.4, centre.Z)
			local base = F.color
			local tint = base:Lerp(Color3.new(1, 1, 1), 0.75)
			local tex = {
				spark = "rbxasset://textures/particles/fire_sparks_main.dds",
				ember = "rbxasset://textures/particles/sparkles_main.dds",
				glow = "rbxasset://textures/particles/forcefield_glow_main.dds",
				ring = "rbxasset://textures/particles/explosion01_shockwave_main.dds",
			}

			local folder = Instance.new("Folder")
			folder.Name = "FVLDissolve"
			folder.Parent = workspace
			Debris:AddItem(folder, 3.5)

			local function anchorPart(cf, size)
				local p = Instance.new("Part")
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.Transparency = 1
				p.Size = size or Vector3.new(0.2, 0.2, 0.2)
				p.CFrame = cf
				p.Parent = folder
				return p
			end

			local function emitter(parent, props, count)
				local e = Instance.new("ParticleEmitter")
				e.LightEmission = 1
				e.LightInfluence = 0
				e.Rate = 0

				for k, v in pairs(props) do
					e[k] = v
				end

				e.Parent = parent

				if count then
					e:Emit(count)
				end

				return e
			end

			local function fade(a, b)
				return NumberSequence.new({ NumberSequenceKeypoint.new(0, a), NumberSequenceKeypoint.new(1, b) })
			end

			-- flash on the body + shock ring on the floor + a thin beam shooting up
			local flash = anchorPart(CFrame.new(centre))
			local light = Instance.new("PointLight")
			light.Color = base
			light.Range = 11
			light.Brightness = 3.5
			light.Parent = flash
			TweenService:Create(light, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Brightness = 0 }):Play()

			emitter(flash, {
				Texture = tex.glow,
				Color = ColorSequence.new(tint, base),
				Size = fade(1.2, 4.5),
				Transparency = fade(0.4, 1),
				Lifetime = NumberRange.new(0.45),
				Speed = NumberRange.new(0),
			}, 2)

			emitter(anchorPart(CFrame.new(foot)), {
				Texture = tex.ring,
				Color = ColorSequence.new(tint, base),
				Orientation = Enum.ParticleOrientation.VelocityPerpendicular,
				EmissionDirection = Enum.NormalId.Top,
				Speed = NumberRange.new(0.01),
				Size = fade(1, 16),
				Transparency = fade(0.1, 1),
				Lifetime = NumberRange.new(0.6),
			}, 1)

			local beam = Instance.new("Part")
			beam.Anchored = true
			beam.CanCollide = false
			beam.CanQuery = false
			beam.CanTouch = false
			beam.CastShadow = false
			beam.Material = Enum.Material.Neon
			beam.Color = tint
			beam.Transparency = 0.15
			beam.Size = Vector3.new(0.35, 0.1, 0.35)
			beam.CFrame = CFrame.new(foot)
			beam.Parent = folder
			TweenService:Create(beam, TweenInfo.new(0.7, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
				Size = Vector3.new(0.12, 30, 0.12),
				CFrame = CFrame.new(foot + Vector3.new(0, 15, 0)),
				Transparency = 1,
				Color = base,
			}):Play()

			-- every body part: hidden, replaced by a neon shell that burns away from the feet up
			local span = math.max(highY - lowY, 0.5)
			local info = TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.In)

			for _, part in ipairs(parts) do
				part.LocalTransparencyModifier = 1

				local shell = shellCopy(part, 1.03)

				if shell then
					shell.Color = tint
					shell.Transparency = 0
					shell.CFrame = part.CFrame
					shell.Parent = folder
				end

				local cf, size = part.CFrame, part.Size

				task.delay(0.05 + (part.Position.Y - lowY) / span * 0.5, function()
					if not folder.Parent then
						return
					end

					if shell then
						TweenService:Create(shell, info, { Color = base, Transparency = 1, Size = shell.Size * 0.55 }):Play()
					end

					local spot = anchorPart(cf, size)

					emitter(spot, {
						Texture = tex.spark,
						Color = ColorSequence.new(tint, base),
						Size = fade(0.3, 0),
						Transparency = fade(0, 1),
						Lifetime = NumberRange.new(0.35, 0.7),
						Speed = NumberRange.new(5, 11),
						SpreadAngle = Vector2.new(180, 180),
						Drag = 4,
						Acceleration = Vector3.new(0, -6, 0),
						Shape = Enum.ParticleEmitterShape.Box,
						ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
					}, 10)

					emitter(spot, {
						Texture = tex.ember,
						Color = ColorSequence.new(base:Lerp(Color3.new(1, 1, 1), 0.4), base),
						Size = fade(0.55, 0),
						Transparency = fade(0.15, 1),
						Lifetime = NumberRange.new(1, 2),
						Speed = NumberRange.new(0.5, 2.5),
						SpreadAngle = Vector2.new(180, 180),
						Drag = 1.5,
						Acceleration = Vector3.new(0, 6, 0),
						RotSpeed = NumberRange.new(-90, 90),
						Shape = Enum.ParticleEmitterShape.Box,
						ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
					}, 5)
				end)
			end
		end

		local function trigger(char)
			local mode = F.mode
			if mode == "Ghost Clone" or mode == "All" then
				ghostClone(char)
			end
			if mode == "Orb Burst" or mode == "All" then
				orbBurst(char)
			end
			if mode == "Spark Burst" or mode == "All" then
				sparkBurst(char)
			end
			if mode == "Death Dissolve" or mode == "All" then
				pcall(dissolve, char)
			end
			if mode == "All" then
				for _, a in ipairs(AURAS) do
					auraBurst(char, a)
				end
			elseif AURA_BY_NAME[mode] then
				auraBurst(char, AURA_BY_NAME[mode])
			end
		end

		local function hookPlayer(p)
			local function onChar(char)
				local hum = char:WaitForChild("Humanoid", 5)
				if not hum then
					return
				end

				hum.Died:Connect(function()
					local isMurd = p == func15()
					local want = (F.mOn and isMurd) or (F.pOn and (p ~= localPlayer or F.pSelf))
					if want then
						pcall(trigger, char)
					end
				end)
			end

			if p.Character then
				task.spawn(onChar, p.Character)
			end
			list2.conns[#list2.conns + 1] = p.CharacterAdded:Connect(onChar)
		end

		for _, p in ipairs(Players:GetPlayers()) do
			hookPlayer(p)
		end
		list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(hookPlayer)

		list2.conns[#list2.conns + 1] = {
			Disconnect = function()
				F.world, F.mOn, F.pOn = false, false, false
				stopWorld()
				for _, g in ipairs(ghosts) do
					pcall(function()
						g:Destroy()
					end)
				end
				ghosts = {}
				for _, f in ipairs(folders) do
					pcall(function()
						f:Destroy()
					end)
				end
				folders = {}
			end,
		}

		----------------------------------------------------------------
		-- UI (Visuals tab)
		----------------------------------------------------------------
		tbl43.visuals:Section({ Title = "World Effects" })

		tbl43.visuals:Toggle({
			Title = "World Effects", Flag = "Toggle_Fx_World", Desc = "Snow or sakura petals falling around you",
			Type = "Toggle", Value = false,
			Callback = function(v)
				F.world = v
				if v then startWorld() else stopWorld() end
			end,
		})

		tbl43.visuals:Dropdown({
			Title = "World Effect Type", Flag = "Dropdown_Fx_WorldType", Multi = false, Value = "Snow",
			Values = { "Snow", "Sakura" },
			Callback = function(v)
				F.worldType = pick(v) or "Snow"
				if F.world then
					styleEmitter()
					burstWorld()
				end
			end,
		})

		tbl43.visuals:Colorpicker({
			Title = "World Effect Colour", Flag = "Colorpicker_Fx_World", Default = F.worldColor,
			Callback = function(c)
				F.worldColor = c
				if wEmitter then wEmitter.Color = ColorSequence.new(c) end
			end,
		})

		tbl43.visuals:Slider({
			Title = "World Effect Amount", Flag = "Slider_Fx_World_Amount", Step = 10,
			Value = { Min = 20, Max = 900, Default = 250 },
			Callback = function(v)
				F.worldRate = tonumber(v) or 250
				if wEmitter then
					styleEmitter()
					burstWorld()
				end
			end,
		})

		tbl43.visuals:Section({ Title = "Death Effects" })

		tbl43.visuals:Toggle({
			Title = "Murderer Death Effect", Flag = "Toggle_Fx_MurdDeath", Desc = "Plays the effects below when the murderer dies",
			Type = "Toggle", Value = false,
			Callback = function(v) F.mOn = v end,
		})

		tbl43.visuals:Toggle({
			Title = "Player Death Effect", Flag = "Toggle_Fx_PlayerDeath", Desc = "Plays the effects below when any player dies",
			Type = "Toggle", Value = false,
			Callback = function(v) F.pOn = v end,
		})

		tbl43.visuals:Toggle({
			Title = "Include Yourself", Flag = "Toggle_Fx_DeathSelf", Desc = "Also play it when you die (Player Death Effect)",
			Type = "Toggle", Value = false,
			Callback = function(v) F.pSelf = v end,
		})

		local typeValues = {}
		for _, n in ipairs(AURA_NAMES) do
			typeValues[#typeValues + 1] = n
		end
		for _, n in ipairs({ "Ghost Clone", "Orb Burst", "Spark Burst", "Death Dissolve", "All" }) do
			typeValues[#typeValues + 1] = n
		end

		tbl43.visuals:Dropdown({
			Title = "Death Effect Type", Flag = "Dropdown_Fx_DeathType", Multi = false, Value = "Custom Aura",
			Values = typeValues,
			Callback = function(v) F.mode = pick(v) or "Custom Aura" end,
		})

		tbl43.visuals:Slider({
			Title = "Aura Size", Flag = "Slider_Fx_Aura_Size", Step = 0.1,
			Value = { Min = 0.5, Max = 3, Default = 1 },
			Callback = function(v) F.auraScale = tonumber(v) or 1 end,
		})

		tbl43.visuals:Colorpicker({
			Title = "Death Effect Colour", Flag = "Colorpicker_Fx_Death", Default = F.color,
			Callback = function(c) F.color = c end,
		})

		tbl43.visuals:Slider({
			Title = "Death Effect Duration", Flag = "Slider_Fx_Death_Duration", Step = 0.1,
			Value = { Min = 0.5, Max = 6, Default = 2 },
			Callback = function(v) F.duration = tonumber(v) or 2 end,
		})

		tbl43.visuals:Button({
			Title = "Preview Death Effect",
			Desc = "Plays the chosen Death Effect Type on a copy of your character, a few studs in front of you.",
			Callback = function()
				local char = localPlayer.Character
				local root = char and char:FindFirstChild("HumanoidRootPart")

				if not char or not root then
					return
				end

				char.Archivable = true
				local ok, clone = pcall(function()
					return char:Clone()
				end)

				if not ok or not clone then
					return
				end

				for _, d in ipairs(clone:GetDescendants()) do
					if d:IsA("BasePart") then
						d.Anchored = true
						d.CanCollide = false
					elseif d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Humanoid") then
						d:Destroy()
					end
				end

				clone:PivotTo(root.CFrame * CFrame.new(0, 0, -8) * CFrame.Angles(0, math.pi, 0))
				clone.Parent = workspace
				Debris:AddItem(clone, F.duration + 3.5)

				trigger(clone)
			end,
		})
	end

	installFx()
end

-- ===================== LOCAL: Korblox / Backtrack / Movement Graph / Pixel Surf =====================
do
	local function installLocal()
		local RS = game:GetService("RunService")
		local Stats = game:GetService("Stats")
		local ws = workspace

		local function pingSec()
			local ok, v = pcall(function()
				return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
			end)
			return ok and v / 1000 or 0.12
		end

		local function charParts()
			local c = localPlayer.Character
			return c and c:FindFirstChild("HumanoidRootPart"), c, c and c:FindFirstChildOfClass("Humanoid")
		end

		----------------------------------------------------------------
		-- Fake Korblox (right leg, R15 only, local only)
		----------------------------------------------------------------
		local K = { on = false, backup = {} }
		local KORBLOX = {
			RightUpperLeg = { MeshId = "rbxassetid://902942096", TextureID = "rbxassetid://902843398" },
			RightLowerLeg = { MeshId = "rbxassetid://902942093", Transparency = 1 },
			RightFoot = { MeshId = "rbxassetid://902942089", Transparency = 1 },
		}

		local function korbloxRestore()
			local c = localPlayer.Character
			if c then
				for name, b in pairs(K.backup) do
					local p = c:FindFirstChild(name)
					if p then
						pcall(function()
							p.MeshId = b.MeshId
							if b.TextureID then
								p.TextureID = b.TextureID
							end
							p.Transparency = b.Transparency
						end)
					end
				end
			end
			K.backup = {}
		end

		local function korbloxApply()
			if not K.on then
				return
			end
			local c = localPlayer.Character
			local ru = c and c:FindFirstChild("RightUpperLeg")
			if not ru or not ru:IsA("MeshPart") then
				return
			end

			for name, def in pairs(KORBLOX) do
				local p = c:FindFirstChild(name)
				if p and p:IsA("MeshPart") then
					if not K.backup[name] then
						K.backup[name] = { MeshId = p.MeshId, TextureID = p.TextureID, Transparency = p.Transparency }
					end
					if p.MeshId ~= def.MeshId then
						pcall(function()
							p.MeshId = def.MeshId
							if def.TextureID then
								p.TextureID = def.TextureID
							end
							if def.Transparency then
								p.Transparency = def.Transparency
							end
						end)
					end
				end
			end
		end

		list2.conns[#list2.conns + 1] = localPlayer.CharacterAdded:Connect(function()
			K.backup = {}
			task.wait(1)
			korbloxApply()
		end)

		----------------------------------------------------------------
		-- Backtrack (ghost showing where the server sees you: delayed by ping)
		----------------------------------------------------------------
		local B = { on = false, color = Color3.fromRGB(255, 60, 60), model = nil, pairs = {}, char = nil, hist = {}, ping = 0.12, pingAt = 0 }

		local function btDestroy()
			if B.model then
				pcall(function()
					B.model:Destroy()
				end)
			end
			B.model, B.pairs, B.char, B.hist = nil, {}, nil, {}
		end

		local function btBuild()
			btDestroy()
			local hrp, char = charParts()
			if not hrp then
				return
			end

			char.Archivable = true
			local ok, m = pcall(function()
				return char:Clone()
			end)
			if not ok or not m then
				return
			end

			local real = {}
			for _, d in ipairs(char:GetDescendants()) do
				if d:IsA("BasePart") then
					real[#real + 1] = d
				end
			end

			local i = 0
			for _, d in ipairs(m:GetDescendants()) do
				if d:IsA("BaseScript") or d:IsA("Decal") or d:IsA("Texture") or d:IsA("SurfaceAppearance")
					or d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") or d:IsA("Light") or d:IsA("Sound") then
					pcall(function()
						d:Destroy()
					end)
				elseif d:IsA("BasePart") then
					i += 1
					local rp = real[i]
					d.Anchored = true
					d.CanCollide = false
					d.CanQuery = false
					d.CanTouch = false
					d.Massless = true
					d.CastShadow = false

					if d.Name == "HumanoidRootPart" or (rp and rp.Transparency > 0.95) then
						d.Transparency = 1
					else
						d.Material = Enum.Material.ForceField
						d.Color = B.color
						d.Transparency = 0
					end

					B.pairs[#B.pairs + 1] = { d, rp }
				end
			end

			local hum = m:FindFirstChildOfClass("Humanoid")
			if hum then
				pcall(function()
					hum:Destroy()
				end)
			end

			m.Name = "BacktrackGhost"
			m.Parent = ws
			B.model, B.char = m, char
		end

		local function btStep(now)
			if not B.on then
				return
			end

			local hrp, char = charParts()
			if not hrp then
				return
			end

			if not B.model or B.char ~= char or not B.model.Parent then
				btBuild()
				if not B.model then
					return
				end
			end

			if now - B.pingAt > 0.25 then
				B.pingAt = now
				B.ping = math.clamp(pingSec(), 0.05, 0.6)
			end

			local hist = B.hist
			hist[#hist + 1] = { now, hrp.CFrame }
			while #hist > 2 and hist[1][1] < now - 1.5 do
				table.remove(hist, 1)
			end

			local target = now - B.ping
			local dcf = hist[1][2]
			for i = #hist, 1, -1 do
				if hist[i][1] <= target then
					dcf = hist[i][2]
					break
				end
			end

			local inv = hrp.CFrame
			for _, pr in ipairs(B.pairs) do
				local part, rp = pr[1], pr[2]
				if part.Parent and rp and rp.Parent then
					part.CFrame = dcf * inv:ToObjectSpace(rp.CFrame)
				end
			end
		end

		list2.conns[#list2.conns + 1] = RS.Heartbeat:Connect(function()
			pcall(btStep, os.clock())
			if K.on then
				pcall(korbloxApply)
			end
		end)

		----------------------------------------------------------------
		-- Movement graph (speed over time, Drawing)
		----------------------------------------------------------------
		local hasDrawing = false
		pcall(function()
			local t = Drawing.new("Line")
			t:Remove()
			hasDrawing = true
		end)

		local G = {
			on = false, color = Color3.fromRGB(242, 242, 242),
			w = 280, h = 72, y = 105,
			N = 84, step = 1 / 30, acc = 0, samples = {}, lines = {}, text = nil,
		}

		local function hSpeed()
			local hrp = charParts()
			if not hrp then
				return 0
			end
			local v = hrp.AssemblyLinearVelocity
			return Vector3.new(v.X, 0, v.Z).Magnitude
		end

		local function graphClear()
			for _, l in ipairs(G.lines) do
				pcall(function()
					l:Remove()
				end)
			end
			G.lines = {}
			if G.text then
				pcall(function()
					G.text:Remove()
				end)
				G.text = nil
			end
			G.samples, G.acc = {}, 0
		end

		local function graphStart()
			graphClear()
			local s = hSpeed()
			for i = 1, G.N do
				G.samples[i] = s
			end
		end

		local function graphStep(dt)
			if not G.on or not hasDrawing then
				return
			end

			local cam = ws.CurrentCamera
			if not cam or #G.samples == 0 then
				return
			end

			G.acc += dt
			while G.acc >= G.step do
				G.acc -= G.step
				table.remove(G.samples, 1)
				G.samples[#G.samples + 1] = hSpeed()
			end

			local _, _, hum = charParts()
			local ref = math.max(1, hum and hum.WalkSpeed or 16)
			local vp = cam.ViewportSize
			local w = math.min(G.w, math.max(120, vp.X - 48))
			local h = math.min(G.h, math.max(36, vp.Y - 32))
			local left = math.floor(vp.X * 0.5 - w * 0.5)
			local center = math.clamp(vp.Y * 0.5 + G.y, h * 0.5 + 8, vp.Y - h * 0.5 - 8)
			local n = #G.samples

			local function yOf(v)
				return center - math.clamp(v / ref - 1, -1, 1) * h * 0.44
			end

			for i = 1, n - 1 do
				local ln = G.lines[i]
				if not ln then
					ln = Drawing.new("Line")
					ln.Thickness = 1.5
					ln.ZIndex = 902
					G.lines[i] = ln
				end

				local ap, bp = (i - 1) / (n - 1), i / (n - 1)
				ln.Color = G.color
				ln.From = Vector2.new(left + ap * w, yOf(G.samples[i]))
				ln.To = Vector2.new(left + bp * w, yOf(G.samples[i + 1]))
				ln.Transparency = math.clamp(math.min(bp * 6, (1 - ap) * 6), 0, 1)
				ln.Visible = true
			end

			if not G.text then
				G.text = Drawing.new("Text")
				G.text.Size = 13
				G.text.Outline = true
				G.text.ZIndex = 904
			end
			G.text.Color = G.color
			G.text.Text = tostring(math.floor(G.samples[n] + 0.5))
			G.text.Position = Vector2.new(left + w + 8, center - 7)
			G.text.Visible = true
		end

		list2.conns[#list2.conns + 1] = RS.RenderStepped:Connect(function(dt)
			pcall(graphStep, dt)
		end)

		----------------------------------------------------------------
		-- Pixel Surf (glide along ledges / wall seams)
		----------------------------------------------------------------
		local S = {
			on = false, speed = 34, active = false, sign = 0, seen = 0,
			lock = nil, part = nil, solid = nil,
		}
		local sParams = RaycastParams.new()
		sParams.FilterType = Enum.RaycastFilterType.Exclude
		sParams.IgnoreWater = true

		local RANGE, LEN, DEPTH, THICK, UP, DOWN = 5, 11, 2.6, 1.6, 2.9, 2.4
		local ANG = { 0, 0.3, -0.3, 0.62, -0.62, 0.95, -0.95 }
		local OFF = { -0.35, -0.15, 0.06, 0.26, 0.5, 0.85, 1.25 }
		local DROP = Vector3.new(0, -(UP + DOWN + 0.2), 0)
		local GROUND = Vector3.new(0, -(DOWN + 4), 0)

		local function flatUnit(v)
			local f = Vector3.new(v.X, 0, v.Z)
			return f.Magnitude > 1e-3 and f.Unit or Vector3.zero
		end

		local function sPlatform()
			if not S.part then
				local p = Instance.new("Part")
				p.Name = "PixelStep"
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.Transparency = 1
				p.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 100, 1)
				p.Size = Vector3.new(LEN, THICK, DEPTH)
				S.part = p
			end
			if S.part.Parent ~= ws then
				S.part.Parent = ws
			end
			return S.part
		end

		local function sHide()
			if S.part then
				if S.part.Parent then
					S.part.Parent = nil
				end
				S.part.CanCollide = false
			end
			S.solid, S.sign, S.lock, S.active = nil, 0, nil, false
		end

		local function sCast(origin, dir)
			sParams.FilterDescendantsInstances = { localPlayer.Character, S.part }
			return ws:Raycast(origin, dir, sParams)
		end

		local function sYaw(v, a)
			local c, s = math.cos(a), math.sin(a)
			return Vector3.new(v.X * c + v.Z * s, 0, v.Z * c - v.X * s)
		end

		local function sProbe(origin, feet, dir)
			local hit = sCast(origin, dir)
			if hit and math.abs(hit.Normal.Y) < 0.45 then
				return hit
			end
			hit = sCast(Vector3.new(origin.X, feet + 0.8, origin.Z), dir)
			if hit and math.abs(hit.Normal.Y) < 0.45 then
				return hit
			end
		end

		local function sWall(hrp, feet, move, look)
			for pass = 1, 2 do
				local base = pass == 1 and move or look
				if base ~= Vector3.zero and (pass == 1 or move == Vector3.zero or move:Dot(look) < 0.99) then
					for i = 1, #ANG do
						local hit = sProbe(hrp.Position, feet, sYaw(base, ANG[i]) * RANGE)
						if hit then
							return hit
						end
					end
				end
			end
		end

		local function sScan(hrp, hum, move, look, hold)
			local feet = hum.HipHeight > 0 and (hrp.Position.Y - hrp.Size.Y * 0.5 - hum.HipHeight) or (hrp.Position.Y - 3)
			local wall = sWall(hrp, feet, move, look)
			if not wall then
				return
			end

			local n = flatUnit(wall.Normal)
			if n == Vector3.zero then
				return
			end

			local ground = sCast(hrp.Position, GROUND)
			local gy = ground and ground.Position.Y or -1e9
			local best, top, tp

			for i = 1, #OFF do
				local o = wall.Position + n * OFF[i]
				local hit = sCast(Vector3.new(o.X, feet + UP, o.Z), DROP)
				if hit and hit.Normal.Y > 0.35 then
					local y = hit.Position.Y
					if y > gy + 0.75 and y < feet + UP - 0.25 and y > feet - DOWN then
						local score
						if hold then
							score = math.abs(y - hold)
						elseif y >= feet - 0.3 then
							score = y - feet
						else
							score = 1000 - y
						end
						if not best or score < best then
							best, top, tp = score, y, hit.Position
						end
					end
				end
			end

			if not top then
				return
			end
			return Vector3.new(tp.X, top, tp.Z), n, feet
		end

		local function surfStep(dt)
			if not S.on then
				return
			end

			local hrp, char, hum = charParts()
			if not hrp or not hum or hum.Health <= 0 then
				sHide()
				return
			end

			local cam = ws.CurrentCamera
			local move = flatUnit(hum.MoveDirection)
			local look = cam and flatUnit(cam.CFrame.LookVector) or Vector3.zero
			local pos, n, feet = sScan(hrp, hum, move, look, S.active and S.lock and S.lock.Y or nil)

			if not pos then
				if os.clock() - S.seen > 0.3 then
					sHide()
				end
				return
			end

			local tangent = flatUnit(n:Cross(Vector3.yAxis))
			if tangent == Vector3.zero then
				return
			end

			local hp = hrp.Position
			local dx, dz = pos.X - hp.X, pos.Z - hp.Z
			local dist = math.sqrt(dx * dx + dz * dz)
			local push = move ~= Vector3.zero and move:Dot(n) or 0

			if S.active then
				if dist > 4.5 or push > 0.5 then
					sHide()
					return
				end
			elseif hum.FloorMaterial ~= Enum.Material.Air or dist > 2.8 or move == Vector3.zero or push > -0.15 then
				if os.clock() - S.seen > 0.3 then
					sHide()
				end
				return
			end

			S.seen = os.clock()
			local step = math.min(dt or 0.016, 0.1)

			if S.lock and (S.lock - pos).Magnitude < 2 then
				pos = S.lock:Lerp(pos, 1 - math.exp(-16 * step))
			end
			S.lock = pos

			local p = sPlatform()
			local center = pos + n * (DEPTH * 0.5 - 0.45) - Vector3.new(0, THICK * 0.5 + 0.02, 0)
			p.CFrame = CFrame.lookAt(center, center - n)

			local solid = S.solid
			if feet >= pos.Y - 0.06 then
				solid = true
			elseif feet < pos.Y - 0.55 then
				solid = false
			end
			if S.solid ~= solid then
				S.solid = solid
				p.CanCollide = solid
			end

			S.active = true

			local along = move:Dot(tangent)
			if math.abs(along) > 0.35 then
				S.sign = along > 0 and 1 or -1
			elseif S.sign == 0 then
				S.sign = (look:Dot(tangent) < 0) and -1 or 1
			end

			local v = hrp.AssemblyLinearVelocity
			local err = pos.Y - feet
			local vy
			if err > 0.05 then
				vy = math.min(err * 14 + 1.5, 34)
			elseif err < -0.4 then
				vy = math.max(v.Y, err * 8)
			elseif v.Y > 0 then
				vy = v.Y
			else
				vy = err * 8
			end

			local blend = 1 - math.exp(-14 * step)
			local cur = v.X * tangent.X + v.Z * tangent.Z
			local speed = cur + (S.speed * S.sign - cur) * blend
			local gap = (hp.X - pos.X) * n.X + (hp.Z - pos.Z) * n.Z
			local hug = math.clamp((0.75 - gap) * 9, -9, 9)
			local glide = tangent * speed + n * hug

			hrp.AssemblyLinearVelocity = Vector3.new(glide.X, vy, glide.Z)
		end

		list2.conns[#list2.conns + 1] = RS.Stepped:Connect(function(_, dt)
			pcall(surfStep, dt)
		end)

		list2.conns[#list2.conns + 1] = {
			Disconnect = function()
				K.on, B.on, G.on, S.on = false, false, false, false
				korbloxRestore()
				btDestroy()
				graphClear()
				sHide()
				if S.part then
					pcall(function()
						S.part:Destroy()
					end)
					S.part = nil
				end
			end,
		}

		----------------------------------------------------------------
		-- UI
		----------------------------------------------------------------
		-- Fake Korblox lives in the Troll & Fun tab (built together with Fake Headless)
		list2.mkKorblox = function()
		tbl43.troll:Toggle({
			Title = "Fake Korblox", Flag = "Toggle_Local_Korblox",
			Desc = "Korblox right leg (R15 only, only you see it)",
			Type = "Toggle", Value = false,
			Callback = function(v)
				K.on = v
				if v then korbloxApply() else korbloxRestore() end
			end,
		})
		end

		----------------------------------------------------------------
		-- Bomb Boost: use a real bomb and get launched by its explosion
		----------------------------------------------------------------
		local BB = { power = 120, busy = false }

		local function findBomb()
			local backpack = localPlayer:FindFirstChild("Backpack")
			for _, holder in ipairs({ localPlayer.Character, backpack }) do
				if holder then
					for _, child in ipairs(holder:GetChildren()) do
						local name = string.lower(child.Name)
						if child:IsA("Tool") and string.find(name, "bomb", 1, true) and not string.find(name, "fake", 1, true) then
							return child
						end
					end
				end
			end
			return nil
		end

		local function bombBoost()
			if BB.busy then
				return false, "Already boosting"
			end

			local root, char, hum = charParts()
			if not root or not hum or hum.Health <= 0 then
				return false, "No character"
			end

			local bomb = findBomb()
			if not bomb then
				return false, "No bomb in inventory"
			end

			BB.busy = true
			local launched = false

			local function launch()
				if launched then
					return
				end
				launched = true
				pcall(function()
					hum:ChangeState(Enum.HumanoidStateType.Jumping)
					local vel = root.AssemblyLinearVelocity
					root.AssemblyLinearVelocity = Vector3.new(vel.X, BB.power, vel.Z)
				end)
			end

			-- launch the moment an explosion goes off next to you
			local conn = ws.DescendantAdded:Connect(function(d)
				if d:IsA("Explosion") and root.Parent and (d.Position - root.Position).Magnitude <= 30 then
					launch()
				end
			end)

			pcall(function()
				if bomb.Parent ~= char then
					hum:EquipTool(bomb)
					task.wait(0.15)
				end
				bomb:Activate()
			end)

			-- fallback: boost anyway if the explosion event never shows up
			task.delay(0.35, function()
				launch()
				conn:Disconnect()
				task.wait(0.4)
				BB.busy = false
			end)

			return true, "Boosting"
		end

