			Frost = {foot = {{color = {{255, 255, 255}, {160, 220, 255}}, life = {0.7, 1.2}, par = true, rate = 12, size = {0.22, 0.08}, speed = {1.4, 2.6}, spread = 25, tex = "rbxassetid://7016382152"}, {color = {{230, 245, 255}}, le = 0.3, life = {1, 1.6}, rate = 6, size = {0.8, 2}, speed = {0.2, 0.5}, spread = 80, tex = "rbxasset://textures/particles/smoke_main.dds", tr = 0.7}}, rib = {{255, 255, 255}, {170, 225, 255}, {110, 180, 255}}, ribLife = 1, step = {{color = {{200, 236, 255}}, life = 1.1, n = 1, size = {0.4, 3.4}, tex = "rbxassetid://12403112662"}}, sw = {{230, 248, 255}, {110, 190, 255}}, width = 0.5},
