		function GameEffects.Kill.loadTextures(state)
			local environment = state.context.environment
			if not environment or type(environment.writefile) ~= "function" or type(environment.getcustomasset) ~= "function" then return end

			for _, key in {"cracks", "ringEdge", "vortex", "star", "bolt", "burn"} do
				local path = "PulseHub/killfx_" .. key .. "_v2.png"
				local ok, asset = pcall(environment.getcustomasset, path)
				if ok and type(asset) == "string" and asset ~= "" then state.textures[key] = asset end
			end
		end

		function GameEffects.Kill.create(context)
			local state = {context = context, on = false, knife = "Slash", gun = "Headshot", mine = false, sound = true, shake = true, volume = 60,
				alive = true, showing = false, speed = 1, hooked = {}, connections = {}, characterConnections = {}, effects = {},
				shots = {}, blades = {}, ragdolls = {}, originals = {}, taken = {}, contexts = {}, shakes = {}, textures = {}, brightTextures = {}}
			state.textures = table.clone(GameEffects.Kill.textureDefaults)
			for _, key in {"cracks", "ringEdge", "vortex", "star", "bolt"} do state.brightTextures[state.textures[key]] = true end
			GameEffects.Kill.loadTextures(state)
			state.effects.Slash = function(effect) GameEffects.Kill.slash(state, effect) end
			state.effects.Sever = function(effect) GameEffects.Kill.sever(state, effect) end
			state.effects.Shred = function(effect) GameEffects.Kill.shred(state, effect) end
			state.effects.Execution = function(effect) GameEffects.Kill.execution(state, effect) end
			state.effects.Blood = function(effect) GameEffects.Kill.blood(state, effect) end
			state.effects.Reaper = function(effect) GameEffects.Kill.reaper(state, effect) end
			state.effects.Crows = function(effect) GameEffects.Kill.crows(state, effect) end
			state.effects.Soul = function(effect) GameEffects.Kill.soul(state, effect) end
			state.effects.Shatter = function(effect) GameEffects.Kill.shatter(state, effect) end
