			local attachment = environment.Instance.new("Attachment")
			attachment.Parent = anchor

			local emitter = GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
				Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 0, 25), environment.Color3.fromRGB(100, 0, 10)),
				Size = GameEffects.Kill.numberSequence(state, 0, 0.38, 1, 0.15), Lifetime = environment.NumberRange.new(0.5, 0.8),
				Speed = environment.NumberRange.new(9, 15), SpreadAngle = environment.Vector2.new(18, 18),
				Acceleration = environment.Vector3.new(0, -55, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 12)
			emitter.Rate, emitter.Enabled = 70, true

			GameEffects.Kill.animate(state, 1.2, function(progress)
				if body.torso.Parent then anchor.CFrame = body.torso.CFrame * environment.CFrame.new(0, body.torso.Size.Y / 2, 0) end
				emitter.Rate = 70 * (1 - progress)
			end, function() emitter.Enabled = false end)
			GameEffects.Kill.delay(state, 0.7, function()
				local position = body.torso.Parent and body.torso.Position or effect.root
				GameEffects.Kill.splat(state, position, 4, environment.Color3.fromRGB(125, 0, 12), 2.8, effect.ignore, 1.2)
