		function GameEffects.Kill.headshotLabel(state, anchor, color, white)
			local environment = state.context.environment
			local billboard = environment.Instance.new("BillboardGui")
			billboard.Size, billboard.AlwaysOnTop, billboard.LightInfluence = environment.UDim2.fromOffset(260, 60), true, 0
			billboard.StudsOffsetWorldSpace, billboard.Adornee, billboard.Parent = environment.Vector3.new(0, 1.8, 0), anchor, anchor
			pcall(function() environment.getgenv().__pulseBBMirror.add(billboard) end)

			local label = environment.Instance.new("TextLabel")
			label.BackgroundTransparency, label.Size, label.Text = 1, environment.UDim2.fromScale(1, 1), "HEADSHOT"
			label.FontFace = environment.Font.new("rbxasset://fonts/families/GothamSSm.json", environment.Enum.FontWeight.Heavy, environment.Enum.FontStyle.Italic)
			label.TextScaled, label.TextColor3, label.Parent = true, white, billboard

			local stroke = environment.Instance.new("UIStroke")
			stroke.Color, stroke.Thickness, stroke.Parent = environment.Color3.fromRGB(200, 30, 40), 3, label
			local gradient = environment.Instance.new("UIGradient")
			gradient.Color, gradient.Rotation, gradient.Parent = environment.ColorSequence.new(white, color), 90, label
			local scale = environment.Instance.new("UIScale")
			scale.Scale, scale.Parent = 0.3, label

			GameEffects.Kill.tween(state, scale, 0.18, {Scale = 1.15}, environment.Enum.EasingStyle.Back)
			GameEffects.Kill.delay(state, 0.18, function()
				if scale.Parent then GameEffects.Kill.tween(state, scale, 0.2, {Scale = 1}) end
			end)
			GameEffects.Kill.tween(state, billboard, 1.2, {StudsOffsetWorldSpace = environment.Vector3.new(0, 3.2, 0)}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.delay(state, 0.8, function()
				if not label.Parent then return end
				GameEffects.Kill.tween(state, label, 0.4, {TextTransparency = 1})
				GameEffects.Kill.tween(state, stroke, 0.4, {Transparency = 1})
			end)
		end

