			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke,
				Color = environment.ColorSequence.new(environment.Color3.fromRGB(70, 72, 80), environment.Color3.fromRGB(30, 30, 34)),
				Size = GameEffects.Kill.numberSequence(state, 0, 1.5, 1, 4), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.4, 1, 1),
				Lifetime = environment.NumberRange.new(1, 1.5), Speed = environment.NumberRange.new(1, 3), Acceleration = environment.Vector3.new(0, 3, 0),
				Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 8)
