			local color, white = environment.Color3.fromRGB(150, 220, 255), environment.Color3.new(1, 1, 1)
			local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Glass, color = color, transparency = 0.25})
