			local white = environment.Color3.new(1, 1, 1)
			local layers = {
				GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(255, 40, 80), transparency = 0.35}),
				GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(40, 220, 255), transparency = 0.35}),
