			local camera = state.context.workspace.CurrentCamera
			local right = camera and camera.CFrame.RightVector or environment.Vector3.new(1, 0, 0)
			GameEffects.Kill.glitchLayers(state, layers, right)

			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.6, 5, 2.6))
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.glitch, Color = environment.ColorSequence.new(white, white),
				Size = GameEffects.Kill.numberSequence(state, 0, 1.6, 1, 0.8), Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 1, 0.6),
				Lifetime = environment.NumberRange.new(0.08, 0.16), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 4, ZOffset = 1}, 14)
			for index = 1, 5 do
				GameEffects.Kill.delay(state, index * 0.1, function()
					if anchor.Parent then anchor:FindFirstChildWhichIsA("ParticleEmitter"):Emit(6) end
				end)
			end
			GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(200, 80, 255), 5, 14, 0.7)
