		function GameEffects.Kill.materialCopy(state, part, material, color, reflectance, transparency, keepDecals)
			local ok, clone = pcall(function() return part:Clone() end)
			if not ok or not clone then return nil end
			if type(color) == "function" then color = color() end
			for _, child in clone:GetChildren() do
				if child:IsA("SpecialMesh") then child.TextureId = ""; continue end
				if keepDecals and child:IsA("Decal") then continue end
				child:Destroy()
			end
			pcall(function() if clone:IsA("MeshPart") then clone.TextureID = "" end end)
			clone.Material, clone.Color, clone.Transparency = material, color, transparency or 0
			if reflectance ~= false then clone.Reflectance = reflectance or 0 end
			clone.Parent = GameEffects.Kill.folder(state)
			return clone
		end

		function GameEffects.Kill.transmute(state, parts, material, color, duration, reflectance, keepDecals)
			local environment = state.context.environment
			local result = {}
			for _, part in parts do
				local clone = GameEffects.Kill.materialCopy(state, part, material, color, reflectance, 1, keepDecals)
				if clone then
					clone.Anchored, clone.CanCollide, clone.CanQuery, clone.CanTouch = true, false, false, false
					table.insert(result, clone)
					GameEffects.Kill.tween(state, clone, duration, {Transparency = 0}, environment.Enum.EasingStyle.Quad)
				end
				GameEffects.Kill.tween(state, part, duration, {Transparency = 1}, environment.Enum.EasingStyle.Quad)
				for _, child in part:GetChildren() do
					if child:IsA("Decal") then GameEffects.Kill.tween(state, child, duration, {Transparency = 1}) end
				end
			end
			return result
		end

		function GameEffects.Kill.smoke(state, position, color, count, speed, size)
			local environment = state.context.environment
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 0.5, 2))
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
				FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = environment.ColorSequence.new(color, color),
				Size = GameEffects.Kill.numberSequence(state, 0, (size or 2) * 0.6, 1, (size or 2) * 1.6),
				Transparency = GameEffects.Kill.numberSequence(state, 0, 0.2, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.3),
				Speed = environment.NumberRange.new(speed * 0.4, speed), SpreadAngle = environment.Vector2.new(85, 85), Drag = 3,
				Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, count)
			GameEffects.Kill.destroyLater(state, anchor, 2.5)
			return anchor
		end

		function GameEffects.Kill.frostBite(state, effect)
			local environment = state.context.environment
			local color, white = environment.Color3.fromRGB(160, 225, 255), environment.Color3.new(1, 1, 1)
			local body = GameEffects.Kill.staticBody(state, effect)
			GameEffects.Kill.hideEffectBody(state, effect.char)
			GameEffects.Kill.arc(state, effect.chest, 30, 3.4, 1.05, color, 0.8, 0.07, 0.08, -10)
			GameEffects.Kill.delay(state, 0.08, function() GameEffects.Kill.arc(state, effect.chest, 150, 3.4, 1.05, color, 0.8, 0.07, 0.08, 10) end)
			local ice = GameEffects.Kill.transmute(state, body, environment.Enum.Material.Ice, color, 0.25, 0.25)
			local spikes = {}
			GameEffects.Kill.delay(state, 0.2, function()
				for _ = 1, 10 do
					local part = ice[math.random(1, math.max(1, #ice))]
					if not part then continue end
					local direction = environment.Vector3.new(math.random() - 0.5, math.random() * 0.8, math.random() - 0.5).Unit
					local pieces = GameEffects.Kill.spike(state, part.Position, part.Position + direction * (0.9 + math.random() * 0.8), 0.14, 0.2,
						white:Lerp(color, 0.5), environment.Enum.Material.Glass)
					for _, piece in pieces do piece.Transparency = 0.2; table.insert(spikes, piece) end
				end
			end)
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.6, 5, 2))
			local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
				Size = GameEffects.Kill.numberSequence(state, 0, 0.25, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.3),
				Speed = environment.NumberRange.new(0.5, 1.5), Acceleration = environment.Vector3.new(0, -3, 0),
				Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, Brightness = 2}, 0)
			emitter.Rate, emitter.Enabled = 40, true
			GameEffects.Kill.smoke(state, effect.root - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(220, 235, 255), 8, 3, 2.5)
			GameEffects.Kill.delay(state, 0.95, function()
				emitter.Enabled = false
				for _, group in {ice, body, spikes} do for _, part in group do pcall(function() part:Destroy() end) end end
				GameEffects.Kill.fragments(state, effect.chest, 28, color, environment.Enum.Material.Ice, 0.4, 16, 1.8)
				local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
					Size = GameEffects.Kill.numberSequence(state, 0, 1.2, 1, 3.5), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.3, 1, 1),
					Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 12), SpreadAngle = environment.Vector2.new(180, 180),
					Drag = 3, LightEmission = 0.3, Brightness = 2}, 20)
				GameEffects.Kill.flash(state, effect.chest, color, 10, 4)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceShatter, 1, 1.1)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceCrack, 0.7, 1.3, nil, 1.5)
				GameEffects.Kill.shakeCamera(state, effect.chest, 0.7, 0.25)
			end)
			GameEffects.Kill.light(state, anchor, color, 4, 14, 1.2)
			GameEffects.Kill.destroyLater(state, anchor, 2.4)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshQuick, 0.9, 1.2)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceCrack, 1, 1, nil, 1.5)
		end

		function GameEffects.Kill.rainbow(state, effect)
			local environment = state.context.environment
			local colors = {environment.Color3.fromRGB(255, 60, 70), environment.Color3.fromRGB(255, 150, 40),
				environment.Color3.fromRGB(255, 230, 60), environment.Color3.fromRGB(80, 230, 100),
				environment.Color3.fromRGB(70, 150, 255), environment.Color3.fromRGB(170, 90, 255)}
			local white = environment.Color3.new(1, 1, 1)
			local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
			local colorSequence = function(first, second) return environment.ColorSequence.new(first, second or first) end
			local direction = GameEffects.Kill.direction(state, effect)
			local body = GameEffects.Kill.body(state, effect, direction * 26 + environment.Vector3.new(0, 60, 0), GameEffects.Kill.randomVector(state, 4), 3.2)
			GameEffects.Kill.hideEffectBody(state, effect.char)
			if body and body.torso then
				local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(body.torso.Position), environment.Vector3.new(0.2, 0.2, 0.2))
				local trails = {}
				for index, color in colors do
					local first, second = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
					first.Position, first.Parent = environment.Vector3.new(0, (3.5 - index) * 0.36 + 0.18, 0), anchor
					second.Position, second.Parent = environment.Vector3.new(0, (3.5 - index) * 0.36 - 0.18, 0), anchor
					local trail = environment.Instance.new("Trail")
					trail.Attachment0, trail.Attachment1 = first, second
					trail.Color, trail.Transparency = colorSequence(color), sequence(0, 0.1, 1, 1)
					trail.Lifetime, trail.LightEmission, trail.FaceCamera, trail.Parent = 1.1, 0.6, true, anchor
					table.insert(trails, trail)
				end
				local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star, Color = colorSequence(white, colors[3]),
					Size = sequence(0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(1, 3),
					SpreadAngle = environment.Vector2.new(180, 180), Brightness = 4}, 0)
				emitter.Rate, emitter.Enabled = 30, true
				GameEffects.Kill.animate(state, 1.7, function()
					if body.torso.Parent then anchor.CFrame = environment.CFrame.new(body.torso.Position) end
				end, function()
					emitter.Enabled = false
					for _, trail in trails do trail.Enabled = false end
					local _, attachment = GameEffects.Kill.effectAttachment(state, anchor.Position)
					GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star4, Color = colorSequence(white, colors[3]),
						Size = sequence(0, 0, 0.3, 2, 1, 0), Lifetime = environment.NumberRange.new(0.5), Speed = environment.NumberRange.new(6, 12),
						SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Brightness = 6}, 14)
					GameEffects.Kill.destroyLater(state, anchor, 1.3)
					GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.6, 1.5)
				end)
			end
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root), environment.Vector3.new(2, 1, 2))
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colorSequence(white), Size = sequence(0, 1.5, 1, 4),
				Transparency = sequence(0, 0.1, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 12),
				SpreadAngle = environment.Vector2.new(85, 85), Drag = 4, Shape = environment.Enum.ParticleEmitterShape.Box,
				LightEmission = 0, LightInfluence = 0.8, Brightness = 1.3}, 16)
			GameEffects.Kill.destroyLater(state, anchor, 1.5)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.slideWhistle, 0.6, 1.2)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.partyHorn2, 0.6, 1.1)
			for index = 0, 2 do
				GameEffects.Kill.delay(state, 0.25 + index * 0.09, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.4, 1.2 + index * 0.25) end)
			end
		end

		function GameEffects.Kill.inferno(state, effect)
			local environment = state.context.environment
			local color = environment.Color3.fromRGB(255, 120, 30)
			local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
			local height = ground and ground.Y or effect.root.Y - 3
			local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon,
				color = environment.Color3.fromRGB(255, 150, 60), transparency = 0})
			GameEffects.Kill.hideEffectBody(state, effect.char)
			for _, part in parts do
				GameEffects.Kill.tween(state, part, 0.9, {Color = environment.Color3.fromRGB(28, 14, 8)}, environment.Enum.EasingStyle.Quad)
			end
			GameEffects.Kill.delay(state, 1, function()
				for _, part in parts do
					if not part.Parent then continue end
					local offset = math.max(0, part.Position.Y - (height + 0.3)) * 0.85
					GameEffects.Kill.tween(state, part, 0.55, {CFrame = part.CFrame - environment.Vector3.new(0, offset, 0), Size = part.Size * 0.55,
						Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
					GameEffects.Kill.destroyLater(state, part, 0.6)
				end
			end)

			local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
			local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest - environment.Vector3.new(0, 0.6, 0)), environment.Vector3.new(2.4, 4.4, 1.6))
			local flame = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.flame,
				Color = environment.ColorSequence.new({environment.ColorSequenceKeypoint.new(0, environment.Color3.fromRGB(255, 240, 170)),
					environment.ColorSequenceKeypoint.new(0.35, environment.Color3.fromRGB(255, 130, 30)),
					environment.ColorSequenceKeypoint.new(1, environment.Color3.fromRGB(200, 30, 10))}),
				Size = sequence(0, 0.8, 0.3, 1.8, 1, 0.2), Transparency = sequence(0, 0.6, 0.15, 0.05, 0.8, 0.4, 1, 1),
				Lifetime = environment.NumberRange.new(0.45, 0.8), Speed = environment.NumberRange.new(2, 5), Acceleration = environment.Vector3.new(0, 9, 0),
				SpreadAngle = environment.Vector2.new(15, 15), Rotation = environment.NumberRange.new(-15, 15), Shape = environment.Enum.ParticleEmitterShape.Box,
				ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 3, ZOffset = 1}, 30)
			flame.Rate, flame.Enabled = 110, true
			GameEffects.Kill.delay(state, 1.25, function() if flame.Parent then flame.Enabled = false end end)
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsparks, Color = colors(environment.Color3.fromRGB(255, 220, 120), color),
				Size = sequence(0, 0.35, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.4), Speed = environment.NumberRange.new(2, 6),
				Acceleration = environment.Vector3.new(0, 6, 0), SpreadAngle = environment.Vector2.new(50, 50), Shape = environment.Enum.ParticleEmitterShape.Box,
				Brightness = 4}, 30, 0.3)
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = colors(environment.Color3.fromRGB(80, 75, 70), environment.Color3.fromRGB(30, 28, 26)),
				Size = sequence(0, 0.2, 1, 0.08), Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(0.5, 2),
				Acceleration = environment.Vector3.new(0, -4, 0), Drag = 1, Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-200, 200),
				Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 50, 1)
			local attachment = environment.Instance.new("Attachment")
			attachment.Parent = anchor
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = colors(environment.Color3.fromRGB(255, 230, 160), color),
				Size = sequence(0, 2, 1, 7), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.35),
				Rotation = environment.NumberRange.new(0, 360), Brightness = 4}, 2)
			local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), environment.Vector3.new(1, 0.2, 1))
			GameEffects.Kill.groundRing(state, floor, state.textures.ringEdge, color, 2, 11, 0.55, 3)
			local light = environment.Instance.new("PointLight")
			light.Color, light.Range, light.Shadows, light.Brightness, light.Parent = color, 16, false, 0, anchor
			GameEffects.Kill.animate(state, 1.7, function(progress) light.Brightness = (1 - progress) * (4 + math.noise(progress * 22, 0.37) * 4) end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball, 0.45, 0.55, anchor)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireWhoosh, 0.6, 0.5, anchor)
			GameEffects.Kill.destroyLater(state, anchor, 3)
			GameEffects.Kill.destroyLater(state, floor, 1.5)
		end

		function GameEffects.Kill.highlight(state, model, color, outline, transparency, outlineTransparency)
			local environment = state.context.environment
			local highlight = environment.Instance.new("Highlight")
			highlight.FillColor, highlight.OutlineColor = color, outline or color
			highlight.FillTransparency, highlight.OutlineTransparency = transparency or 0.5, outlineTransparency or 0
			highlight.DepthMode = environment.Enum.HighlightDepthMode.Occluded
			highlight.Adornee, highlight.Parent = model, model
			return highlight
		end

		function GameEffects.Kill.crystalPrison(state, effect)
			local environment = state.context.environment
			local color, white = environment.Color3.fromRGB(170, 90, 255), environment.Color3.new(1, 1, 1)
			local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
			local height = ground and ground.Y or effect.root.Y - 3
			local body, model = GameEffects.Kill.staticBody(state, effect)
			GameEffects.Kill.hideEffectBody(state, effect.char)
			if model then GameEffects.Kill.highlight(state, model, color, environment.Color3.fromRGB(230, 200, 255), 0.45, 0) end

			local crystals = {}
			local top = effect.head + environment.Vector3.new(0, 1.2, 0)
			for index = 1, 9 do
				local angle, radius = index / 9 * 6.283 + math.random() * 0.3, 2.2 + math.random() * 0.6
				local start = environment.Vector3.new(effect.root.X + math.cos(angle) * radius, height - 0.2, effect.root.Z + math.sin(angle) * radius)
				local finish = top + environment.Vector3.new(math.cos(angle) * 0.4, math.random() * 0.8, math.sin(angle) * 0.4)
				local parts, direction, length = GameEffects.Kill.spike(state, start, finish, 0.45, 0.6 + math.random() * 0.25,
					color:Lerp(white, math.random() * 0.3), environment.Enum.Material.Glass)
				for _, part in parts do
					part.Transparency, part.Reflectance = 0.2, 0.3
					local frame = part.CFrame
					part.CFrame = frame - direction * (length + 0.3)
					GameEffects.Kill.delay(state, index * 0.035, function()
						if part.Parent then GameEffects.Kill.tween(state, part, 0.3, {CFrame = frame}, environment.Enum.EasingStyle.Back) end
					end)
					table.insert(crystals, part)
				end
			end

			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(4, 5, 4))
			local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, color),
				Size = GameEffects.Kill.numberSequence(state, 0, 0, 0.5, 0.9, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.5),
				Rotation = environment.NumberRange.new(0, 90), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5, ZOffset = 1}, 0)
			emitter.Rate, emitter.Enabled = 14, true
			GameEffects.Kill.light(state, anchor, color, 5, 16, 1.4)
			GameEffects.Kill.destroyLater(state, anchor, 3)
			GameEffects.Kill.delay(state, 1.15, function()
				emitter.Enabled = false
				for _, part in crystals do pcall(function() part:Destroy() end) end
				for _, part in body do pcall(function() part:Destroy() end) end
				GameEffects.Kill.fragments(state, effect.chest, 26, color, environment.Enum.Material.Glass, 0.45, 18, 1.6)
				GameEffects.Kill.flash(state, effect.chest, color, 12, 5)
				GameEffects.Kill.sparks(state, effect.chest, color, 30, 30, state.textures.shards)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glassSmash2, 1, 0.8)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceFreeze, 0.6, 0.7, nil, 1.6)
				GameEffects.Kill.shakeCamera(state, effect.chest, 0.9, 0.3)
			end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceFreeze, 0.8, 0.6, nil, 1.6)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthSpark, 0.4, 1.6)
		end

		function GameEffects.Kill.spike(state, start, finish, width, depth, color, material)
			local environment = state.context.environment
			local offset = finish - start
			local length, direction = offset.Magnitude, offset.Unit
			local reference = math.abs(direction.Z) < 0.9 and environment.Vector3.new(0, 0, 1) or environment.Vector3.new(1, 0, 0)
			local frame = environment.CFrame.fromMatrix(start, direction:Cross(reference).Unit, direction)
			local parts = {}
			for index = 0, 3 do
				local part = environment.Instance.new("WedgePart")
				part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
				part.Material, part.Color, part.Reflectance = material, color, 0.15
				part.Size = environment.Vector3.new(width, length, depth)
				part.CFrame = frame * environment.CFrame.Angles(0, index * math.pi / 2, 0) * environment.CFrame.new(0, length / 2, -depth / 2)
				part.Parent = GameEffects.Kill.folder(state)
				table.insert(parts, part)
			end
			return parts, direction, length
		end

		function GameEffects.Kill.fragments(state, position, count, color, material, size, speed, lifetime)
			local context, environment = state.context, state.context.environment
			local parts = {}
			for _ = 1, count do
				local part = environment.Instance.new("Part")
				local scale = size * (0.5 + math.random())
				part.Size = environment.Vector3.new(scale, scale * (0.6 + math.random() * 0.6), scale * (0.7 + math.random() * 0.5))
				part.Material, part.Color = material or environment.Enum.Material.Slate, color
				part.CanQuery, part.CanTouch = false, false
				pcall(function() part.CollisionGroup = "Ragdolls" end)
				local offset = environment.Vector3.new((math.random() - 0.5) * 1.5, math.random() * 0.8, (math.random() - 0.5) * 1.5)
				part.CFrame = environment.CFrame.new(position + offset) * environment.CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6)
				part.Parent = GameEffects.Kill.bodiesFolder(state)
				table.insert(parts, part)
				local duration = (lifetime or 2) + math.random() * 0.6
				GameEffects.Kill.delay(state, duration, function()
					if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Size = part.Size * 0.2, Transparency = 1}) end
				end)
				GameEffects.Kill.destroyLater(state, part, duration + 0.5)
			end

			local function launch()
				for _, part in parts do
					if not part.Parent then continue end
					local direction = environment.Vector3.new(math.random() - 0.5, 0, math.random() - 0.5)
					direction = direction.Magnitude > 0.05 and direction.Unit or environment.Vector3.new(1, 0, 0)
					part.AssemblyLinearVelocity = direction * speed * (0.4 + math.random() * 0.6) + environment.Vector3.new(0, speed * (0.6 + math.random() * 0.6), 0)
					part.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8)
				end
			end
			launch()
			local connection
			connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
			return parts
		end

		function GameEffects.Kill.flash(state, position, color, size, brightness)
			local environment = state.context.environment
			local anchor, attachment = GameEffects.Kill.effectAttachment(state, position)
			local white = environment.Color3.new(1, 1, 1)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = environment.ColorSequence.new(white, color),
				Size = GameEffects.Kill.numberSequence(state, 0, size * 0.2, 1, size), Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 1, 1),
				Lifetime = environment.NumberRange.new(0.35), Rotation = environment.NumberRange.new(0, 360), Brightness = brightness or 5, ZOffset = 1}, 2)
			GameEffects.Kill.light(state, anchor, color, 10, math.min(60, size * 3), 0.5)
			return anchor, attachment
		end

		function GameEffects.Kill.sparks(state, position, color, count, speed, texture)
			local environment = state.context.environment
			local anchor, attachment = GameEffects.Kill.effectAttachment(state, position)
			local white = environment.Color3.new(1, 1, 1)
			GameEffects.Kill.particle(state, attachment, {Texture = texture or state.textures.fsparks, Color = environment.ColorSequence.new(white, color),
				Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.7),
				Speed = environment.NumberRange.new(speed * 0.5, speed), SpreadAngle = environment.Vector2.new(180, 180), Drag = 3,
				Acceleration = environment.Vector3.new(0, -25, 0), Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, count)
			return anchor, attachment
		end

		function GameEffects.Kill.track(state, signal, callback)
			local connection = signal:Connect(callback)
			table.insert(state.connections, connection)
			return connection
		end

		function GameEffects.Kill.observeCharacter(state, player, character)
			if state.hooked[character] then return end
			state.hooked[character] = true

			state.context.environment.task.spawn(function()
				local humanoid = character:WaitForChild("Humanoid", 8)
				if not humanoid or not state.alive then return end

				local handled, connections = false, {}
				local function onDeath()
					if handled then return end
					handled = true
					GameEffects.Kill.onDeath(state, player, character)
				end

				table.insert(connections, humanoid.Died:Connect(onDeath))
				table.insert(connections, humanoid.HealthChanged:Connect(function(health)
					if health <= 0 then onDeath() end
				end))
				table.insert(connections, character.AncestryChanged:Connect(function(_, parent)
					if parent then return end
					for _, connection in connections do connection:Disconnect() end
					state.characterConnections[character], state.hooked[character] = nil, nil
				end))
				state.characterConnections[character] = connections
			end)
		end

		function GameEffects.Kill.observePlayer(state, player)
			if player == state.context.player then return end
			if player.Character then GameEffects.Kill.observeCharacter(state, player, player.Character) end
			GameEffects.Kill.track(state, player.CharacterAdded, function(character)
				GameEffects.Kill.observeCharacter(state, player, character)
			end)
		end

		function GameEffects.Kill.observeBlade(state, blade)
			if blade.Name ~= "ThrowingKnife" then return end
			local environment = state.context.environment

			environment.task.spawn(function()
				local part = blade:FindFirstChild("BladePosition") or blade:WaitForChild("BladePosition", 1)
				if not part and blade:IsA("BasePart") then part = blade end

				local started = environment.os.clock()
				while part and part.Parent and blade.Parent and state.alive and environment.os.clock() - started < 6 do
					GameEffects.Kill.recordBlade(state, part.Position)
					environment.task.wait(0.03)
				end
			end)
		end

		function GameEffects.Kill.observe(state)
			local context, environment = state.context, state.context.environment
			for _, player in context.players:GetPlayers() do GameEffects.Kill.observePlayer(state, player) end

			GameEffects.Kill.track(state, context.players.PlayerAdded, function(player) GameEffects.Kill.observePlayer(state, player) end)
			GameEffects.Kill.track(state, context.workspace.DescendantAdded, function(model) GameEffects.Kill.recordRagdoll(state, model) end)
			GameEffects.Kill.track(state, context.workspace.ChildAdded, function(blade) GameEffects.Kill.observeBlade(state, blade) end)

			environment.task.spawn(function()
				local services = context.storage:WaitForChild("ClientServices", 30)
				local weapons = services and services:WaitForChild("WeaponService", 30)
				local fired = weapons and weapons:WaitForChild("GunFired", 30)
				if not state.alive or not fired or not fired:IsA("RemoteEvent") then return end

				GameEffects.Kill.track(state, fired.OnClientEvent, function(shooter, _, position, hit)
					GameEffects.Kill.recordShot(state, shooter, position, hit)
				end)
			end)
		end

		function GameEffects.Kill.stop(state)
			state.alive = false
			state.showing = false
			GameEffects.Kill.resetShake(state)

			for _, connection in state.connections do pcall(function() connection:Disconnect() end) end
			for _, connections in state.characterConnections do
				for _, connection in connections do pcall(function() connection:Disconnect() end) end
			end

			table.clear(state.connections)
			table.clear(state.characterConnections)
			if state.folder then pcall(function() state.folder:Destroy() end); state.folder = nil end
		end

		function GameEffects.Kill.preview(state, name, options, title, generation)
			local context, environment = state.context, state.context.environment
			environment.task.spawn(function()
				local camera = context.workspace.CurrentCamera
				if not camera then return end

				if not state.dummyDescription then
					pcall(function() state.dummyDescription = context.players:GetHumanoidDescriptionFromUserId(context.player.UserId) end)
				end
				if not state.dummyDescription then return end

				local ok, model = pcall(function()
					return context.players:CreateHumanoidModelFromDescription(state.dummyDescription, environment.Enum.HumanoidRigType.R15)
				end)
				if not ok or not model then return end

				model.Name = "PulseKillPreview"
				local frame = camera.CFrame
				local direction = environment.Vector3.new(frame.LookVector.X, 0, frame.LookVector.Z)
				direction = direction.Magnitude > 0.01 and direction.Unit or environment.Vector3.new(0, 0, -1)
				local character = context.player.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				local position = (root and root.Position or frame.Position) + direction * 9
				local localHumanoid = character and character:FindFirstChildOfClass("Humanoid")
				local ground
				if root then ground = root.Position.Y - root.Size.Y / 2 - (localHumanoid and localHumanoid.HipHeight or 2) end
				if not ground then
					local hit = GameEffects.Kill.ground(state, position, {a = character, b = camera})
					ground = hit and hit.Y or position.Y - 3
				end

				local humanoid = model:FindFirstChildOfClass("Humanoid")
				local previewRoot = model:FindFirstChild("HumanoidRootPart")
				previewRoot.Anchored = true
				for _, part in model:GetDescendants() do
					if part:IsA("BasePart") then part.CanCollide, part.CanQuery, part.CanTouch = false, false, false end
				end
				if humanoid then humanoid.DisplayDistanceType = environment.Enum.HumanoidDisplayDistanceType.None end

				local center = environment.Vector3.new(position.X, ground + (humanoid and humanoid.HipHeight or 2) + previewRoot.Size.Y / 2, position.Z)
				model:PivotTo(environment.CFrame.lookAt(center, environment.Vector3.new(frame.Position.X, center.Y, frame.Position.Z)))
				model.Parent = GameEffects.Kill.folder(state)
				if title and context.window then
					pcall(function() context.window:Notify({Title = context.translation.tr(title), Text = context.translation.tr(name), Kind = "info", Duration = 2}) end)
				end

				environment.task.wait(0.45)
				if generation and (state.showGen ~= generation or not state.showing) then pcall(function() model:Destroy() end); return end

				character = context.player.Character
				local killer = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart"))
				GameEffects.Kill.play(state, name, options, model, killer)
				environment.task.wait(2.6 / state.speed)
				pcall(function() model:Destroy() end)
			end)
		end

		function GameEffects.Kill.clearShow(state)
			for _, folder in {state.folder, state.bodies} do
				if not folder then continue end
				for _, child in folder:GetChildren() do pcall(function() child:Destroy() end) end
			end
			pcall(GameEffects.Kill.resetShake, state)
		end

		function GameEffects.Kill.showLabel(state, showing)
			local button, environment = state.showButton, state.context.environment
			if environment.typeof(button) ~= "Instance" then return end

			local start = state.context.translation.tr("Show All Effects")
			local stop = state.context.translation.tr("Stop Showing")
			local text = showing and stop or start
			local objects = button:GetDescendants()
			table.insert(objects, button)
			for _, object in objects do
				if not object:IsA("TextLabel") and not object:IsA("TextButton") then continue end
				if object.Text == start or object.Text == stop then object.Text = text end
			end
		end

		function GameEffects.Kill.previewAll(state)
			local environment = state.context.environment
			state.showGen += 1
			local generation = state.showGen
			if state.showing then
				state.showing = false
				GameEffects.Kill.clearShow(state)
				environment.task.spawn(function()
					for _ = 1, 16 do
						environment.task.wait(0.2)
						if state.showing or state.showGen ~= generation then break end
						GameEffects.Kill.clearShow(state)
					end
				end)
				GameEffects.Kill.showLabel(state, false)
				return
			end

			state.showing = true
			GameEffects.Kill.showLabel(state, true)
			environment.task.spawn(function()
				local function active() return state.alive and state.showing and state.showGen == generation end
				for _, group in {{GameEffects.Kill.knifeEffects, "Knife Kill"}, {GameEffects.Kill.gunEffects, "Gun Kill"}} do
					for _, name in group[1] do
						if not active() then break end
						GameEffects.Kill.preview(state, name, group[1], group[2], generation)
						local started = environment.os.clock()
						while active() and environment.os.clock() - started < 3.2 / state.speed do environment.task.wait(0.05) end
					end
				end
				if state.showGen == generation then
					state.showing = false
					GameEffects.Kill.showLabel(state, false)
				end
			end)
		end

		function GameEffects.Kill.options(names)
			local options = {}
			for _, name in names do
				table.insert(options, {code = name, label = name:gsub("(%l)(%u)", "%1 %2")})
			end
			table.insert(options, {code = "Random", label = "Random"})
			return options
		end


		-- the Show-All button in this UI has no changeable label, so tell the user instead
		GameEffects.Kill.showLabel = function(_, showing)
			note("Kill Effects", showing and "Showing every effect - press the button again to stop" or "Stopped showing effects", "sparkles")
		end

		-- ---------------------------------------------------------------- install + UI (Visuals tab)
		if type(genv.__fvlKillFXStop) == "function" then
			pcall(genv.__fvlKillFXStop)
		end

		local state = GameEffects.Kill.create(context)
		state.showGen = 0
		state.stop = function()
			GameEffects.Kill.stop(state)
		end
		genv.__fvlKillFX, genv.__fvlKillFXStop = state, state.stop
		GameEffects.Kill.observe(state)

		list2.conns[#list2.conns + 1] = { Disconnect = function()
			state.on = false
			pcall(state.stop)
			genv.__fvlKillFX, genv.__fvlKillFXStop = nil, nil
		end }

		local function labelOf(code)
			return (code:gsub("(%l)(%u)", "%1 %2"))
		end

		local function makeValues(list)
			local values, map = {}, {}
			for _, code in ipairs(list) do
				local label = labelOf(code)
				values[#values + 1] = label
				map[label] = code
			end
			values[#values + 1] = "Random"
			map["Random"] = "Random"
			return values, map
		end

		local function asText(v)
			if type(v) == "table" then
				return v[1]
			end
			return v
		end

		local knifeValues, knifeMap = makeValues(GameEffects.Kill.knifeEffects)
		local gunValues, gunMap = makeValues(GameEffects.Kill.gunEffects)

		tbl43.visuals:Section({ Title = "Kill Effects" })

		tbl43.visuals:Toggle({
			Title = "Kill Effects", Flag = "Toggle_KFX_On",
			Desc = "When someone dies to a knife or a gun, the body is taken over and the effect picked below plays on it. Not the same as Death Effects (aura) or Kill Cam.",
			Type = "Toggle", Value = false,
			Callback = function(v)
				state.on = v == true
			end,
		})

		tbl43.visuals:Dropdown({
			Title = "Knife Kill Effect", Flag = "Dropdown_KFX_Knife", Multi = false, Value = "Slash",
			Desc = "Effect for kills made with the knife (thrown or stabbed). Random = a different one every kill.",
			Values = knifeValues,
			Callback = function(v)
				local code = knifeMap[asText(v)]
				if code then
					state.knife = code
				end
			end,
		})

		tbl43.visuals:Dropdown({
			Title = "Gun Kill Effect", Flag = "Dropdown_KFX_Gun", Multi = false, Value = "Headshot",
			Desc = "Effect for kills made with the gun. Random = a different one every kill.",
			Values = gunValues,
			Callback = function(v)
				local code = gunMap[asText(v)]
				if code then
					state.gun = code
				end
			end,
		})

		tbl43.visuals:Toggle({
			Title = "Kill Effect Screen Shake", Flag = "Toggle_KFX_Shake",
			Desc = "Camera shake on the big effects",
			Type = "Toggle", Value = true,
			Callback = function(v)
				state.shake = v == true
				if not state.shake then
					GameEffects.Kill.resetShake(state)
				end
			end,
		})

		tbl43.visuals:Toggle({
			Title = "Kill Effects: Only My Kills", Flag = "Toggle_KFX_Mine",
			Desc = "Only play the effect on players you killed yourself",
			Type = "Toggle", Value = false,
			Callback = function(v)
				state.mine = v == true
			end,
		})

		tbl43.visuals:Toggle({
			Title = "Kill Effect Sounds", Flag = "Toggle_KFX_Sound",
			Desc = "The sounds that come with each effect (separate from the Knife Kill / GunKill Sound replacements)",
			Type = "Toggle", Value = true,
			Callback = function(v)
				state.sound = v == true
			end,
		})

		tbl43.visuals:Slider({
			Title = "Kill Effect Volume", Flag = "Slider_KFX_Volume", Step = 1,
			Value = { Min = 0, Max = 100, Default = 60 },
			Callback = function(v)
				state.volume = tonumber(v) or 60
			end,
		})

		tbl43.visuals:Button({
			Title = "Preview Knife Kill Effect",
			Desc = "Plays the chosen knife effect on a copy of your character in front of you",
			Callback = function()
				GameEffects.Kill.preview(state, state.knife, GameEffects.Kill.knifeEffects, "Knife Kill")
			end,
		})

		tbl43.visuals:Button({
			Title = "Preview Gun Kill Effect",
			Desc = "Plays the chosen gun effect on a copy of your character in front of you",
			Callback = function()
				GameEffects.Kill.preview(state, state.gun, GameEffects.Kill.gunEffects, "Gun Kill")
			end,
		})

		tbl43.visuals:Button({
			Title = "Show All Kill Effects",
			Desc = "Plays every knife effect, then every gun effect, one after another. Press again to stop.",
			Callback = function()
				GameEffects.Kill.previewAll(state)
			end,
		})
	end)

	if not okKFX then
		warn("Kill Effects failed to load: " .. tostring(errKFX))
	end
end

-- ===================== JERK OFF (ported from MM2_readable) =====================
do
	local Players = game:GetService("Players")
	local localPlayer = Players.LocalPlayer

	local JO = { on = false, tool = nil, track = nil, thread = nil, equipped = false, charConn = nil, diedConn = nil }

	-- Same animations / timings the original script uses
	local ID_R6 = "rbxassetid://72042024"
	local ID_R15 = "rbxassetid://698251653"

	local function stopJerk()
		JO.equipped = false

		if JO.thread then
			pcall(task.cancel, JO.thread)
			JO.thread = nil
		end

		if JO.track then
			pcall(function()
				JO.track:Stop()
			end)
			JO.track = nil
		end
	end

	local function startJerk(tool)
		stopJerk()

		local char = localPlayer.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not hum then
			return
		end

		local isR15 = char:FindFirstChild("UpperTorso") ~= nil
		local speed = isR15 and 0.7 or 0.65
		local stopAt = isR15 and 0.7 or 0.65

		JO.equipped = true

		JO.thread = task.spawn(function()
			while JO.equipped and tool.Parent do
				task.wait()

				if not JO.track then
					local anim = Instance.new("Animation")
					anim.AnimationId = isR15 and ID_R15 or ID_R6

					local ok, track = pcall(function()
						return hum:LoadAnimation(anim)
					end)

					if not ok or not track then
						return
					end

					JO.track = track
				end

				-- play only a short slice of the animation, stop, repeat = the stroking motion
				local track = JO.track
				track:Play()
				track:AdjustSpeed(speed)
				track.TimePosition = 0.6
				task.wait(0.1)

				while JO.equipped and JO.track and JO.track.TimePosition < stopAt do
					task.wait(0.1)
				end

				if JO.track then
					pcall(function()
						JO.track:Stop()
					end)
					JO.track = nil
				end
			end
		end)
	end

	local function destroyOldTools()
		local backpack = localPlayer:FindFirstChildOfClass("Backpack")
		local char = localPlayer.Character

		for _, holder in ipairs({ backpack, char }) do
			if holder then
				for _, child in ipairs(holder:GetChildren()) do
					if child:IsA("Tool") and child.Name == "Jerk Off" then
						pcall(function()
							child:Destroy()
						end)
					end
				end
			end
		end
	end

	local function removeTool()
		stopJerk()

		if JO.diedConn then
			pcall(function()
				JO.diedConn:Disconnect()
			end)
			JO.diedConn = nil
		end

		destroyOldTools()
		JO.tool = nil
	end

	local function ensureTool()
		removeTool()

		local char = localPlayer.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local backpack = localPlayer:FindFirstChildOfClass("Backpack")
		if not hum or not backpack then
			return false
		end

		local tool = Instance.new("Tool")
		tool.Name = "Jerk Off"
		tool.ToolTip = "jorking it."
		tool.RequiresHandle = false
		tool.CanBeDropped = false

		tool.Equipped:Connect(function()
			startJerk(tool)
		end)
		tool.Unequipped:Connect(stopJerk)
		JO.diedConn = hum.Died:Connect(stopJerk)

		tool.Parent = backpack
		JO.tool = tool
		return true
	end

	local function setJerk(v)
		JO.on = v and true or false

		if JO.on then
			local ok = ensureTool()
			obj2:Notify({
				Title = "Jerk",
				Content = ok and "Tool added to backpack!" or "No character yet - respawn and toggle again.",
				Duration = 2,
				Icon = ok and "check" or "x",
			})
		else
			removeTool()
			obj2:Notify({ Title = "Jerk", Content = "Removed.", Duration = 2, Icon = "check" })
		end
	end

	-- respawn gives a fresh Backpack, so hand the tool back if the toggle is still on
	JO.charConn = localPlayer.CharacterAdded:Connect(function()
		stopJerk()
		JO.tool = nil

		if JO.on then
			task.wait(1)
			if JO.on then
				ensureTool()
			end
		end
	end)

	list2.conns[#list2.conns + 1] = {
		Disconnect = function()
			JO.on = false
			if JO.charConn then
				pcall(function()
					JO.charConn:Disconnect()
				end)
				JO.charConn = nil
			end
			removeTool()
		end,
	}

	tbl43.troll:Section({ Title = "Jerk Off" })

	tbl43.troll:Toggle({
		Title = "Jerk Off",
		Flag = "Toggle_Troll_Jerk_Off",
		Desc = "Adds a Jerk Off tool to your backpack. Equip it to play the animation, unequip to stop.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			setJerk(v)
		end,
	})
end

-- ===================== BOUNCY MODE (Troll & Fun) =====================
-- Free bounce: you fly through the air like a super ball. There is no fixed direction and no hopping from the
-- ground: you bounce off floors, walls and ceilings in every direction (real reflection off the surface), and
-- every bounce keeps your full speed, so you never slow down. The speed slider sets how fast you fly.
do
	local RS = game:GetService("RunService")
	local GRAVITY = 55 -- lighter than the real gravity so the arcs stay long and floaty
	local RADIUS = 3.2 -- how far from a surface we turn around
	local BN = {
		on = false, speed = 50, conn = nil, vel = nil, safeCF = nil,
		rayParams = nil, rayChar = nil, lastBounce = 0, stand = {},
	}

	local function randomUnit()
		local v = Vector3.new(math.random() * 2 - 1, math.random() * 1.2 - 0.2, math.random() * 2 - 1)

		if v.Magnitude < 0.1 then
			return Vector3.new(0, 1, 0)
		end

		return v.Unit
	end

	-- the same direction, nudged a little in a random way so no two bounces look alike
	local function jitter(dir, amount)
		local v = dir + Vector3.new(math.random() * 2 - 1, math.random() * 2 - 1, math.random() * 2 - 1) * amount

		if v.Magnitude < 0.1 then
			return dir
		end

		return v.Unit
	end

	local function step(dt)
		dt = math.min(dt, 0.1)

		local char = localPlayer.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")

		if not hrp or not hum or hum.Health <= 0 then
			return
		end

		-- new character (respawn): fresh ray filter, fresh start
		if BN.rayChar ~= char then
			BN.rayChar = char
			BN.rayParams = RaycastParams.new()
			BN.rayParams.FilterType = Enum.RaycastFilterType.Exclude
			BN.rayParams.FilterDescendantsInstances = { char }
			BN.rayParams.RespectCanCollide = true
			BN.safeCF = nil
			BN.vel = randomUnit() * BN.speed
		end

		-- limp body: the humanoid stops fighting the movement, and you tumble while you fly
		if not hum.PlatformStand then
			hum.PlatformStand = true
			BN.stand[hum] = true
		end

		BN.vel = BN.vel or randomUnit() * BN.speed
		local pos = hrp.Position

		-- bounced into the void: back to the last safe spot, launched upwards
		if BN.safeCF and pos.Y < workspace.FallenPartsDestroyHeight + 60 then
			hrp.CFrame = BN.safeCF + Vector3.new(0, 6, 0)
			BN.vel = (Vector3.new(0, 1.5, 0) + randomUnit()).Unit * BN.speed
			hrp.AssemblyLinearVelocity = BN.vel
			return
		end

		-- gravity, then the speed slider is the speed we fly at (also while falling)
		local vel = BN.vel + Vector3.new(0, -GRAVITY * dt, 0)
		vel = vel.Unit * BN.speed

		-- look ahead along the flight path: anything in the way is a bounce
		local reach = BN.speed * dt + RADIUS
		local hit = workspace:Raycast(pos, vel.Unit * reach, BN.rayParams)

		if hit and os.clock() - BN.lastBounce > 0.03 then
			BN.lastBounce = os.clock()
			local n = hit.Normal

			-- reflect off the surface
			local r = vel - 2 * vel:Dot(n) * n
			r = jitter(r.Unit, 0.18)

			-- a floor never lets you skim along it: always throw you properly back up
			if n.Y > 0.6 then
				BN.safeCF = CFrame.new(hit.Position + n * RADIUS)
				r = Vector3.new(r.X, math.max(r.Y, 0.55), r.Z).Unit
			end

			-- step off the surface so you cannot get stuck inside it
			local away = hit.Position + n * RADIUS
			hrp.CFrame = CFrame.new(away) * (hrp.CFrame - hrp.CFrame.Position)

			vel = r * BN.speed
			hrp.AssemblyAngularVelocity = (randomUnit() * 12)
		end

		BN.vel = vel
		hrp.AssemblyLinearVelocity = vel
	end

	local function setBounce(v)
		v = v and true or false

		if v == BN.on then
			return
		end

		BN.on = v

		if BN.conn then
			BN.conn:Disconnect()
			BN.conn = nil
		end

		if v then
			BN.vel = nil
			BN.lastBounce = 0
			BN.conn = RS.Heartbeat:Connect(function(dt)
				pcall(step, dt)
			end)
		else
			-- give the body back: standing again, upright, no more speed
			for hum in pairs(BN.stand) do
				pcall(function()
					hum.PlatformStand = false
				end)
			end

			BN.stand = {}

			local char = localPlayer.Character
			local hrp = char and char:FindFirstChild("HumanoidRootPart")

			if hrp then
				pcall(function()
					local look = hrp.CFrame.LookVector
					local flat = Vector3.new(look.X, 0, look.Z)

					if flat.Magnitude < 0.01 then
						flat = Vector3.new(0, 0, -1)
					end

					hrp.AssemblyAngularVelocity = Vector3.zero
					hrp.AssemblyLinearVelocity = Vector3.zero
					hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flat.Unit)
				end)
			end

			BN.vel = nil
		end
	end

	list2.conns[#list2.conns + 1] = {
		Disconnect = function()
			setBounce(false)
		end,
	}

	tbl43.troll:Section({ Title = "Bouncy Mode" })

	tbl43.troll:Slider({
		Title = "Bounce Speed",
		Flag = "Slider_Troll_Bounce_Speed",
		Desc = "How fast you fly. You keep this speed through every bounce.",
		Step = 5,
		Value = { Min = 10, Max = 150, Default = 50 },
		Callback = function(v)
			local n = tonumber(v) or type(v) == "table" and tonumber(v.Value)

			if n then
				BN.speed = n
			end
		end,
	})

	tbl43.troll:Toggle({
		Title = "Bouncy Mode",
		Flag = "Toggle_Troll_Bounce",
		Desc = "Free bounce: you fly and tumble around the whole map like a super ball, bouncing off floors, walls and ceilings in every direction. Works best on its own: Follow Player and Stand In Front Of Sheriff fight it for your position.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			setBounce(v)
		end,
	})
end

-- ===================== EXTRA FEATURES (ported from MM2_readable) =====================
-- Aimlock, Auto Knife Throw, Avoid Murder, AntiCoin, Shutup GunReload,
-- OffDamageWater, FadeDisabler. (Vote Duper already exists here as "Pick Map".)
do
	local Players = game:GetService("Players")
	local RS = game:GetService("RunService")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local lp = Players.LocalPlayer

	local function note(title, content, icon)
		obj2:Notify({ Title = title, Content = content, Duration = 2, Icon = icon or "check" })
	end

	local function onUnload(fn)
		list2.conns[#list2.conns + 1] = { Disconnect = fn }
	end

	local function killConns(t)
		for _, c in ipairs(t) do
			pcall(function()
				c:Disconnect()
			end)
		end
		table.clear(t)
	end

	-- ---------------------------------------------------------------- Aimlock
	local AL = { name = nil, conn = nil, dropdown = nil }

	local function alNames()
		local names = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp then
				table.insert(names, p.Name)
			end
		end
		return names
	end

	local function alStop()
		if AL.conn then
			pcall(function()
				AL.conn:Disconnect()
			end)
			AL.conn = nil
		end
	end

	local function alStart()
		alStop()
		AL.conn = RS.RenderStepped:Connect(function()
			local target = AL.name and Players:FindFirstChild(AL.name)
			local c = target and target.Character
			local hrp = c and c:FindFirstChild("HumanoidRootPart")
			local cam = workspace.CurrentCamera
			if hrp and cam then
				cam.CFrame = CFrame.new(cam.CFrame.Position, hrp.Position)
			end
		end)
	end

	-- ---------------------------------------------------------------- Auto Knife Throw
	-- Every 1.4s: if you are the murderer, throw at the nearest player (same throw as the Throw Knife button,
	-- but silent when nobody is in range / behind a wall so it does not spam notifications).
	local AK = { on = false, thread = nil }

	local function akStop()
		AK.on = false
		if AK.thread then
			pcall(task.cancel, AK.thread)
			AK.thread = nil
		end
	end

	local function akStart()
		akStop()
		AK.on = true

		AK.thread = task.spawn(function()
			while AK.on do
				task.wait(1.4)
				if not AK.on then
					break
				end

				pcall(function()
					if func15() ~= lp then
						return
					end

					local target = func66()
					if not target or not target.Character then
						return
					end

					local c = lp.Character
					local hand = c and (c:FindFirstChild("RightHand") or c:FindFirstChild("HumanoidRootPart"))
					if hand and flag78 and not func65(target.Character, hand) then
						return
					end

					func68()
				end)
			end
		end)
	end

	-- ---------------------------------------------------------------- Avoid Murder (used by Coin Autofarm)
	list2.avoidMurderOn = false

	list2.murdererNearby = function()
		local c = lp.Character
		local hrp = c and c:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return false
		end

		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp and p.Character then
				local oh = p.Character:FindFirstChild("HumanoidRootPart")
				if oh and (oh.Position - hrp.Position).Magnitude <= 10 then
					if list2.isMurderer(p) and not list2.isPlayerDead(p) then
						return true
					end
				end
			end
		end

		return false
	end

	-- Positions of every alive murderer (used by the Coin Autofarm to skip the coins around him)
	list2.avoidCoinRadius = 30

	list2.murdererPositions = function()
		local out = {}

		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp and p.Character then
				local oh = p.Character:FindFirstChild("HumanoidRootPart")
				if oh and list2.isMurderer(p) and not list2.isPlayerDead(p) then
					out[#out + 1] = oh.Position
				end
		end
		end

		return out
	end

	-- ---------------------------------------------------------------- AntiCoin
	-- Every 0.5s: coins become invisible, untouchable and non-solid. Turning it off puts them back.
	local AC = { on = false, thread = nil, saved = {} }

	local function hideCoinPart(part)
		if AC.saved[part] == nil then
			AC.saved[part] = { Touch = part.CanTouch, Collide = part.CanCollide, Trans = part.Transparency }
		end
		part.CanTouch = false
		part.CanCollide = false
		part.Transparency = 1
	end

	local function hideCoinsIn(root)
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("BasePart") then
				hideCoinPart(d)
			end
		end
	end

	local function acTick()
		local mansion = workspace:FindFirstChild("Mansion2")
		local container = mansion and mansion:FindFirstChild("CoinContainer")

		if container then
			hideCoinsIn(container)
			return
		end

		for _, m in ipairs(workspace:GetDescendants()) do
			if m:IsA("Model") and string.find(m.Name:lower(), "coin") then
				hideCoinsIn(m)
			end
		end
	end

	local function acStop()
		AC.on = false
		if AC.thread then
			pcall(task.cancel, AC.thread)
			AC.thread = nil
		end

		for part, s in pairs(AC.saved) do
			if part and part.Parent then
				pcall(function()
					part.CanTouch = s.Touch
					part.CanCollide = s.Collide
					part.Transparency = s.Trans
				end)
			end
		end
		table.clear(AC.saved)
	end

	local function acStart()
		acStop()
		AC.on = true

		AC.thread = task.spawn(function()
			while AC.on do
				pcall(acTick)
				task.wait(0.5)
			end
		end)
	end

	-- ---------------------------------------------------------------- OffDamageWater
	-- Anything under a water / river / ocean object (or with a Splash / HitWater child) stops being touchable
	-- and its Touched handlers are switched off, so water can no longer hurt you.
	local WP = { on = false, saved = {}, cons = {}, conns = {} }

	local function isWater(inst)
		local n = inst.Name:lower()
		if string.find(n, "water") or string.find(n, "river") or string.find(n, "ocean") then
			return true
		end
		return inst:FindFirstChild("Splash") ~= nil or inst:FindFirstChild("HitWater") ~= nil
	end

	local function underWater(part)
		local cur = part
		while cur and cur ~= workspace do
			if isWater(cur) then
				return true
			end
			cur = cur.Parent
		end
		return false
	end

	local function disableWater(part)
		if WP.saved[part] == nil then
			WP.saved[part] = part.CanTouch
		end
		part.CanTouch = false

		if getconnections then
			pcall(function()
				for _, c in ipairs(getconnections(part.Touched)) do
					if c.Disable then
						c:Disable()
						WP.cons[#WP.cons + 1] = c
					end
				end
			end)
		end
	end

	local function wpStop()
		WP.on = false
		killConns(WP.conns)

		for part, was in pairs(WP.saved) do
			if part and part.Parent then
				pcall(function()
					part.CanTouch = was
				end)
			end
		end
		table.clear(WP.saved)

		for _, c in ipairs(WP.cons) do
			pcall(function()
				if c.Enable then
					c:Enable()
				end
			end)
		end
		table.clear(WP.cons)
	end

	local function wpStart()
		wpStop()
		WP.on = true

		WP.conns[#WP.conns + 1] = workspace.DescendantAdded:Connect(function(d)
			if WP.on and d:IsA("BasePart") then
				pcall(function()
					if underWater(d) then
						disableWater(d)
					end
				end)
			end
		end)

		task.spawn(function()
			for _, d in ipairs(workspace:GetDescendants()) do
				if not WP.on then
					return
				end
				if d:IsA("BasePart") then
					pcall(function()
						if underWater(d) then
							disableWater(d)
						end
					end)
				end
			end
		end)
	end

	-- ---------------------------------------------------------------- FadeDisabler
	-- The fade GUIs (CameraFade / Fade / SpawnFade) are made invisible IN PLACE. They are never moved or
	-- deleted: the game's own scripts (FadeModule, RoleSelect, GameplayAnimations) look them up and throw
	-- errors / wait forever if they are gone.
	local FD = { on = false, saved = {}, conns = {} }
	local FADE_NAMES = { CameraFade = true, Fade = true, SpawnFade = true }

	local function fdHide(obj)
		local prop
		if obj:IsA("ScreenGui") then
			prop = "Enabled"
		elseif obj:IsA("GuiObject") then
			prop = "Visible"
		else
			return
		end

		if FD.saved[obj] then
			return
		end

		-- "value" always holds what the game last wanted, so turning this off restores the right state
		local rec = { prop = prop, value = obj[prop] }
		FD.saved[obj] = rec
		obj[prop] = false

		FD.conns[#FD.conns + 1] = obj:GetPropertyChangedSignal(prop):Connect(function()
			if FD.on and obj[prop] ~= false then
				rec.value = obj[prop]
				obj[prop] = false
			end
		end)
	end

	local function fdStop()
		FD.on = false
		killConns(FD.conns)

		for obj, rec in pairs(FD.saved) do
			if obj and obj.Parent then
				pcall(function()
					obj[rec.prop] = rec.value
				end)
			end
		end
		table.clear(FD.saved)
	end

	local function fdStart()
		fdStop()
		FD.on = true

		local pg = lp:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end

		for _, d in ipairs(pg:GetDescendants()) do
			if FADE_NAMES[d.Name] then
				pcall(fdHide, d)
			end
		end

		FD.conns[#FD.conns + 1] = pg.DescendantAdded:Connect(function(d)
			if FD.on and FADE_NAMES[d.Name] then
				pcall(fdHide, d)
			end
		end)
	end

	-- ---------------------------------------------------------------- Shutup GunReload
	local SR = { on = false, conns = {}, vol = {} }

	local function srMute(s)
		if not s:IsA("Sound") or s.Name ~= "Reload" or SR.vol[s] ~= nil then
			return
		end

		SR.vol[s] = s.Volume
		s.Volume = 0
		pcall(function()
			s:Stop()
		end)

		SR.conns[#SR.conns + 1] = s.Played:Connect(function()
			if SR.on then
				s.Volume = 0
				pcall(function()
					s:Stop()
				end)
			end
		end)
	end

	local function srStop()
		SR.on = false
		killConns(SR.conns)

		for s, v in pairs(SR.vol) do
			if s and s.Parent then
				pcall(function()
					s.Volume = v
				end)
			end
		end
		table.clear(SR.vol)
	end

	local function srStart()
		srStop()
		SR.on = true

		for _, d in ipairs(workspace:GetDescendants()) do
			pcall(srMute, d)
		end

		SR.conns[#SR.conns + 1] = workspace.DescendantAdded:Connect(function(d)
			if SR.on then
				pcall(srMute, d)
			end
		end)
	end

	onUnload(function()
		alStop()
		akStop()
		acStop()
		wpStop()
		fdStop()
		srStop()
		list2.avoidMurderOn = false
	end)

	-- ---------------------------------------------------------------- UI
	tbl43.combat:Section({ Title = "Aimlock" })

	AL.dropdown = tbl43.combat:Dropdown({
		Title = "Aimlock Target",
		Desc = "Pick the player your camera locks onto.",
		Multi = false,
		Value = nil,
		Values = alNames(),
		Callback = function(value)
			AL.name = value
			if value then
				note("Aimlock", "Target set to " .. tostring(value))
			end
		end,
	})

	local function alRefresh()
		task.defer(function()
			pcall(function()
				AL.dropdown:Refresh(alNames())
			end)
		end)
	end

	list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(alRefresh)
	list2.conns[#list2.conns + 1] = Players.PlayerRemoving:Connect(alRefresh)

	local alToggle
	alToggle = tbl43.combat:Toggle({
		Title = "Aimlock",
		Flag = "Toggle_Extra_Aimlock",
		Desc = "Your camera stays locked on the player picked in Aimlock Target.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			if v then
				if not AL.name then
					note("Aimlock", "Pick a target first!", "x")
					task.defer(function()
						pcall(list2.setToggle, alToggle, false)
					end)
					return
				end
				alStart()
			else
				alStop()
			end
		end,
	})

	-- the Auto Knife Throw switch now lives in the "Knife" section of the combat tab (next to Auto Dodge Knife)
	list2.autoKnifeThrow = function(v)
		if v then
			akStart()
			note("Auto Knife Throw", "Enabled.")
		else
			akStop()
			note("Auto Knife Throw", "Disabled.", "power-off")
		end
	end

	-- Farm Extras toggles: built later inside the Auto Farm > Settings section
	list2.mkFarmExtras = function()
	tbl43.farm:Toggle({
		Title = "Avoid Murder",
		Flag = "Toggle_Extra_AvoidMurder",
		Desc = "Coin Autofarm never goes for coins near the murderer (see the radius slider below). It does not stop when he is close to you.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			list2.avoidMurderOn = v and true or false
		end,
	})

	tbl43.farm:Slider({
		Title = "Avoid Murder Coin Radius",
		Flag = "Slider_Extra_AvoidMurderRadius",
		Desc = "Coins closer than this (studs) to the murderer are skipped while Avoid Murder is on.",
		Step = 5,
		Value = { Min = 10, Max = 100, Default = 30 },
		Callback = function(v)
			local n = tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or 30
			list2.avoidCoinRadius = math.clamp(n, 10, 100)
		end,
	})

	tbl43.farm:Toggle({
		Title = "AntiCoin",
		Flag = "Toggle_Extra_AntiCoin",
		Desc = "Hides coins and makes them untouchable. Turn off to bring them back.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			if v then
				acStart()
				note("AntiCoin", "Coins removed.")
			else
				acStop()
				note("AntiCoin", "Coins restored.", "power-off")
			end
		end,
	})

	tbl43.farm:Toggle({
		Title = "OffDamageWater",
		Flag = "Toggle_Extra_OffDamageWater",
		Desc = "Water stops hurting you.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			if v then
				wpStart()
				note("OffDamageWater", "Enabled.")
			else
				wpStop()
				note("OffDamageWater", "Disabled.", "power-off")
			end
		end,
	})

	tbl43.farm:Toggle({
		Title = "FadeDisabler",
		Flag = "Toggle_Extra_FadeDisabler",
		Desc = "Hides the black screen fades (they stay in place, just invisible).",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			if v then
				fdStart()
				note("FadeDisabler", "Fades hidden.")
			else
				fdStop()
				note("FadeDisabler", "Fades restored.", "power-off")
			end
		end,
	})

	end

	tbl43.visuals:Section({ Title = "Gun Sounds" })

	tbl43.visuals:Toggle({
		Title = "Shutup GunReload",
		Flag = "Toggle_Extra_ShutupReload",
		Desc = "Mutes the gun reload sound.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			if v then
				srStart()
				note("GunReload Sound", "Muted!")
			else
				srStop()
				note("GunReload Sound", "Unmuted!")
			end
		end,
	})
end

-- ===================== EXTRA FEATURES 2 (ported from MM2_readable) =====================
-- Magic Aura, Gun Beam, Angel Wings, Aura Pack, Shader (RTX).
-- Every feature sits in its own do-block so its locals are released again (Lua allows 200 locals per chunk).
do
	local Players = game:GetService("Players")
	local RS = game:GetService("RunService")
	local TweenService = game:GetService("TweenService")
	local Lighting = game:GetService("Lighting")
	local Debris = game:GetService("Debris")
	local lp = Players.LocalPlayer

	local function note(title, content, icon)
		obj2:Notify({ Title = title, Content = content, Duration = 2, Icon = icon or "check" })
	end

	local function onUnload(fn)
		list2.conns[#list2.conns + 1] = { Disconnect = fn }
	end

	local function newGui(name)
		local g = Instance.new("ScreenGui")
		g.Name = name
		g.ResetOnSpawn = false
		g.IgnoreGuiInset = true
		g.DisplayOrder = 9999
		local ok = pcall(function()
			g.Parent = game:GetService("CoreGui")
		end)
		if not ok or not g.Parent then
			g.Parent = lp:FindFirstChildOfClass("PlayerGui")
		end
		return g
	end

	-- ================================================================ Magic Aura
	-- Six neon balls orbiting your root part.
	do
		local MA = { on = false, parts = {}, conn = nil }
		local COLORS = {
			Color3.fromRGB(170, 90, 255), Color3.fromRGB(255, 90, 130), Color3.fromRGB(90, 255, 130),
			Color3.fromRGB(255, 255, 90), Color3.fromRGB(255, 130, 255), Color3.fromRGB(130, 255, 255),
		}

		local function maClear()
			for _, p in ipairs(MA.parts) do
				pcall(function()
					p:Destroy()
				end)
			end
			table.clear(MA.parts)
		end

		local function maStop()
			MA.on = false
			if MA.conn then
				MA.conn:Disconnect()
				MA.conn = nil
			end
			maClear()
		end

		local function maStart()
			maStop()
			MA.on = true

			MA.conn = RS.Heartbeat:Connect(function()
				local c = lp.Character
				local hrp = c and c:FindFirstChild("HumanoidRootPart")
				if not hrp then
					return
				end

				while #MA.parts < 6 do
					local p = Instance.new("Part")
					p.Name = "AuraSphere"
					p.Anchored = true
					p.CanCollide = false
					p.CanQuery = false
					p.CanTouch = false
					p.CastShadow = false
					p.Material = Enum.Material.Neon
					p.Shape = Enum.PartType.Ball
					p.Size = Vector3.new(0.6, 0.6, 0.6)
					p.Transparency = 0.3
					p.Parent = workspace
					table.insert(MA.parts, p)
				end

				local t = tick()
				for i, p in ipairs(MA.parts) do
					local phase = (i - 1) * (math.pi / 3)
					local x = math.cos(t * 1.5 + phase) * 3
					local z = math.sin(t * 1.5 + phase) * 3
					local y = math.sin(t * 2 + phase)
					p.CFrame = CFrame.new(hrp.Position + Vector3.new(x, y, z))
					p.Color = COLORS[i] or COLORS[1]
				end
			end)
		end

		onUnload(maStop)

		tbl43.visuals:Section({ Title = "Auras" })

		local maToggle = tbl43.visuals:Toggle({
			Title = "Magic Aura",
			Flag = "Toggle_Extra_MagicAura",
			Desc = "Six glowing orbs circle around you (only you see them).",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				if v then
					maStart()
				else
					maStop()
				end
			end,
		})

		list2.auraOff = list2.auraOff or {}
		list2.auraOff[#list2.auraOff + 1] = function()
			if MA.on then
				pcall(list2.setToggle, maToggle, false)
				maStop()
			end
		end
	end

	-- ================================================================ Angel Wings (Auras)
	-- The wings are a local copy that is NOT parented to your character: no collisions, no weight and no
	-- extra joints, so they can't change how you walk. Every frame they are re-fitted onto your torso, so
	-- they follow your height / size automatically (and keep following after a respawn).
	do
		local ASSET = 97658130917593

		-- ---- optional tuning (the defaults are automatic) ----
		local SIZE_MULT      = 1     -- extra multiplier on top of the automatic size (1.2 = 20% bigger)
		local SPAN_ACCESSORY = 0     -- 0 = keep the size the creator made, scaled to your avatar. Or a width in studs.
		local SPAN_MODEL     = 7     -- wing width (studs) on a default avatar, used when the asset has no back attachment
		-- only used when the asset has NO back attachment (it is then placed by its shape):
		local BACK_GAP       = 0.1   -- gap between your back and the wings (studs)
		local RAISE          = 0.15  -- raise (+) / lower (-) the wings, as a fraction of torso height
		local FLIP_BACK      = false -- true = the wings face the wrong way (front/back swapped)
		local FLIP_UP        = false -- true = the wings are upside down

		local ATTACH_NAMES = { "BodyBackAttachment", "WaistBackAttachment" }
		local AW = { on = false, asset = nil, model = nil, info = nil, conn = nil, token = 0 }

		local function comp(v, i)
			if i == 1 then
				return v.X
			elseif i == 2 then
				return v.Y
			end
			return v.Z
		end

		local function awRemove()
			AW.info = nil
			if AW.model then
				pcall(function()
					AW.model:Destroy()
				end)
				AW.model = nil
			end
		end

		-- Turns the downloaded asset into one anchored Model + a description of how to fit it.
		local function awBuild()
			if not AW.asset then
				return nil
			end

			local obj = AW.asset:Clone()

			-- throw away everything that could move / weigh down / script the wings
			for _, d in ipairs(obj:GetDescendants()) do
				if d:IsA("BaseScript") or d:IsA("Humanoid") or d:IsA("Animator") or d:IsA("AnimationController")
					or d:IsA("BodyMover") or d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Constraint") then
					pcall(function()
						d:Destroy()
					end)
				end
			end

			local parts = {}
			if obj:IsA("BasePart") then
				parts[#parts + 1] = obj
			end
			for _, d in ipairs(obj:GetDescendants()) do
				if d:IsA("BasePart") then
					parts[#parts + 1] = d
				end
			end
			if #parts == 0 then
				obj:Destroy()
				return nil
			end

			-- every part goes straight into one wrapper Model (world positions are kept)
			local wrap = Instance.new("Model")
			wrap.Name = "AngelWingsFx"
			for _, p in ipairs(parts) do
				p.Anchored = true
				p.CanCollide = false
				p.CanQuery = false
				p.CanTouch = false
				p.Parent = wrap
			end
			if not obj:IsA("BasePart") then
				obj:Destroy()
			end

			-- measure the wings (ignoring invisible helper parts)
			local vis = {}
			for _, p in ipairs(parts) do
				if p.Transparency < 0.95 then
					vis[#vis + 1] = p
				end
			end
			if #vis == 0 then
				vis = parts
			end

			local main, best = vis[1], -1
			for _, p in ipairs(vis) do
				local v = p.Size.X * p.Size.Y * p.Size.Z
				if v > best then
					best = v
					main = p
				end
			end

			local rot = main.CFrame - main.CFrame.Position
			local inv = rot:Inverse()
			local mn = Vector3.new(math.huge, math.huge, math.huge)
			local mx = Vector3.new(-math.huge, -math.huge, -math.huge)
			local wsum, csum = 0, Vector3.new(0, 0, 0)

			for _, p in ipairs(vis) do
				local h = p.Size / 2
				for sx = -1, 1, 2 do
					for sy = -1, 1, 2 do
						for sz = -1, 1, 2 do
							local c = inv * (p.CFrame * Vector3.new(sx * h.X, sy * h.Y, sz * h.Z))
							mn = Vector3.new(math.min(mn.X, c.X), math.min(mn.Y, c.Y), math.min(mn.Z, c.Z))
							mx = Vector3.new(math.max(mx.X, c.X), math.max(mx.Y, c.Y), math.max(mx.Z, c.Z))
						end
					end
				end
				local w = math.max(p.Size.X * p.Size.Y * p.Size.Z, 1e-4)
				wsum = wsum + w
				csum = csum + (inv * p.Position) * w
			end

			local ext = mx - mn
			local ctr = (mx + mn) / 2
			local cen = csum / wsum

			-- thinnest side = depth (front/back). Of the other two, the left/right-symmetric one = span.
			local depth = 1
			for i = 2, 3 do
				if comp(ext, i) < comp(ext, depth) then
					depth = i
				end
			end
			local ai, bi
			for i = 1, 3 do
				if i ~= depth then
					if not ai then
						ai = i
					else
						bi = i
					end
				end
			end
			local function asym(i)
				return math.abs(comp(cen, i) - comp(ctr, i)) / math.max(comp(ext, i), 1e-3)
			end
			local span, vert
			if math.abs(asym(ai) - asym(bi)) > 0.04 then
				if asym(ai) < asym(bi) then
					span, vert = ai, bi
				else
					span, vert = bi, ai
				end
			elseif comp(ext, ai) >= comp(ext, bi) then
				span, vert = ai, bi
			else
				span, vert = bi, ai
			end

			-- reference frame of the wings: X = right, Y = up, Z = back (same convention as your torso)
			local mode, attName, frame = "fit", nil, nil
			for _, nm in ipairs(ATTACH_NAMES) do
				for _, p in ipairs(parts) do
					local a = p:FindFirstChild(nm)
					if a and a:IsA("Attachment") then
						mode, attName, frame = "attach", nm, p.CFrame * a.CFrame
						break
					end
				end
				if frame then
					break
				end
			end

			if not frame then
				local function axisW(i)
					local v = (i == 1 and Vector3.new(1, 0, 0)) or (i == 2 and Vector3.new(0, 1, 0)) or Vector3.new(0, 0, 1)
					return rot:VectorToWorldSpace(v)
				end
				local up = axisW(vert) * (FLIP_UP and -1 or 1)
				local back = axisW(depth) * (FLIP_BACK and -1 or 1)
				local right = up:Cross(back)
				frame = CFrame.fromMatrix(rot:VectorToWorldSpace(ctr), right, up, back)
			end

			wrap.WorldPivot = frame

			local meshes = {}
			for _, d in ipairs(wrap:GetDescendants()) do
				if d:IsA("SpecialMesh") and d.MeshType == Enum.MeshType.FileMesh then
					meshes[#meshes + 1] = { d, d.Scale, d.Offset }
				end
			end

			local info = {
				mode = mode,
				attName = attName,
				span = comp(ext, span),
				depth = comp(ext, depth),
				scale = 1,
				meshes = meshes,
			}
			return wrap, info
		end

		local function awSetScale(model, info, s)
			if math.abs(s / info.scale - 1) < 0.01 then
				return
			end
			info.scale = s
			pcall(function()
				model:ScaleTo(s)
			end)
			-- make sure file-meshes follow the scale too (no-op if ScaleTo already did it)
			for _, m in ipairs(info.meshes) do
				local sm = m[1]
				if sm.Parent then
					local want = m[2] * s
					if (sm.Scale - want).Magnitude > 1e-3 * math.max(want.Magnitude, 1) then
						sm.Scale = want
						sm.Offset = m[3] * s
					end
				end
			end
		end

		-- runs every frame: fits the wings onto the current torso
		local function awStep()
			local model, info = AW.model, AW.info
			if not (model and info) then
				return
			end

			local char = lp.Character
			local base = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
			local cam = workspace.CurrentCamera
			if not (base and base:IsA("BasePart") and cam) then
				if model.Parent then
					model.Parent = nil
				end
				return
			end
			if model.Parent ~= cam then
				model.Parent = cam
			end

			-- body size: upper + lower torso height (2 studs on a default avatar, R6 and R15)
			local lower = char:FindFirstChild("LowerTorso")
			local torsoH = base.Size.Y + ((lower and lower:IsA("BasePart")) and lower.Size.Y or 0)
			local charScale = math.clamp(torsoH / 2, 0.1, 25)

			local carrier, cAtt
			if info.mode == "attach" then
				for _, nm in ipairs({ "UpperTorso", "LowerTorso", "Torso" }) do
					local p = char:FindFirstChild(nm)
					local a = p and p:FindFirstChild(info.attName)
					if a and a:IsA("Attachment") then
						carrier, cAtt = p, a
						break
					end
				end
			end

			local s, target
			if info.mode == "attach" then
				local fit = (SPAN_ACCESSORY > 0 and info.span > 0.01) and (SPAN_ACCESSORY / info.span) or 1
				s = fit * charScale * SIZE_MULT
				if carrier then
					target = carrier.CFrame * cAtt.CFrame
				else
					target = base.CFrame * CFrame.new(0, 0.35 * base.Size.Y, base.Size.Z / 2)
				end
			else
				local fit = (SPAN_MODEL > 0 and info.span > 0.01) and (SPAN_MODEL / info.span) or 1
				s = fit * charScale * SIZE_MULT
				-- wings sit just behind the back; a little of their depth is allowed to sink in (0.4 of half)
				local zc = base.Size.Z / 2 + s * info.depth * 0.4 + BACK_GAP * charScale
				target = base.CFrame * CFrame.new(0, RAISE * base.Size.Y, zc)
			end

			awSetScale(model, info, math.clamp(s, 0.05, 100))
			model:PivotTo(target)
		end

		-- returns true = ready, false = failed, nil = cancelled while loading
		local function awApply(my)
			awRemove()

			if not AW.asset then
				local ok, objs = pcall(function()
					return game:GetObjects("rbxassetid://" .. ASSET)
				end)
				if AW.token ~= my then
					return nil
				end
				if not ok or type(objs) ~= "table" or not objs[1] then
					return false
				end
				AW.asset = objs[1]
			end

			local ok, model, info = pcall(awBuild)
			if not ok or not model then
				return false
			end

			AW.model = model
			AW.info = info
			return true
		end

		local awToggle

		local function awStop()
			AW.on = false
			AW.token = AW.token + 1
			if AW.conn then
				AW.conn:Disconnect()
				AW.conn = nil
			end
			awRemove()
		end

		local function awStart()
			awStop()
			AW.on = true
			AW.token = AW.token + 1
			local my = AW.token

			task.spawn(function()
				local ok = awApply(my)
				if ok == nil or AW.token ~= my then
					return
				end

				if not ok then
					note("Auras", "Failed to load Angel Wings", "x")
					task.defer(function()
						pcall(list2.setToggle, awToggle, false)
					end)
					return
				end

				AW.conn = RS.Heartbeat:Connect(awStep)
				note("Auras", "Angel Wings enabled!")
			end)
		end

		onUnload(awStop)

		awToggle = tbl43.visuals:Toggle({
			Title = "Angel Wings",
			Flag = "Toggle_Extra_AngelWings",
			Desc = "Puts a pair of angel wings on your back. Fits your height automatically (only you see them).",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				if v then
					awStart()
				else
					awStop()
					note("Auras", "Angel Wings disabled.", "power-off")
				end
			end,
		})

		list2.auraOff = list2.auraOff or {}
		list2.auraOff[#list2.auraOff + 1] = function()
			if AW.on then
				pcall(list2.setToggle, awToggle, false)
				awStop()
			end
		end
	end

	-- ================================================================ Aura Pack (16 auras as toggles + Clear Aura)
	-- These toggles live in the same "Auras" section as Magic Aura and Angel Wings.
	-- Each toggle loads the aura model from its asset id and puts its parts / effects on YOUR character
	-- (client side only: other players don't see it). Any number of them can be on together.
	-- Everything that gets created is tracked, so turning it off, Clear Aura or unloading removes all of it.
	-- The active aura is put back on automatically after you respawn.
	-- The model is used as the creator made it (no recolouring / softening), so nothing disappears by accident.
	do
		local InsertService = game:GetService("InsertService")

		local AURAS = {
			{ "Midnight Blues", "12002206611" },
			{ "Rainbow Effect", "8509695714" },
			{ "Red Shield", "14598330167" },
			{ "Crimson King", "11955208820" },
			{ "Daemon of Cards", "10373359918" },
			{ "Starlight", "134645216613107" },
			{ "Heavenly", "139300897520961" },
			{ "Ribbon", "132069507632161" },
			{ "Sakura", "81755778619404" },
			{ "Wind", "80694081850877" },
			{ "Flow", "119913533725648" },
			{ "Star", "73754563740680" },
			{ "Wings Aura", "90816193741219" },
			{ "404 Aura", "18380225083" },
			{ "Star Aura", "14531523902" },
			{ "Necromancer", "113083314851722" },
		}


		-- parts of the downloaded model that only stand in for a body part (they are not copied themselves)
		local BODY = {}
		for _, n in ipairs({
			"Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart", "Head",
			"Left Arm", "Right Arm", "Left Leg", "Right Leg",
			"LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
			"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot",
		}) do
			BODY[n] = true
		end

		local R6_TO_R15 = {
			["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
			["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg",
		}

		local FX = {
			ParticleEmitter = true, Trail = true, Beam = true, Highlight = true,
			Fire = true, Smoke = true, Sparkles = true,
		}
		local LINKED = { Beam = true, Trail = true } -- effects that point at two attachments

		local AU = { set = {}, cache = {}, charConn = nil, toggles = {}, switching = false, st = {} }
		for _, a in ipairs(AURAS) do
			AU.st[a[1]] = { items = {}, token = 0, want = false, pending = nil }
		end
		-- Auras made of many separate pieces (circles, chains, discs ...): EVERY piece of the model is put on you,
		-- even the see-through ones that only hold decals / gui glows / attachments.
		AU.keepAll = { ["Necromancer"] = true }

		-- Floating auras: the pieces are not welded to your body. They glide after your character (smoothed)
		-- and bob gently, so they trail behind you instead of being stuck to you.
		AU.floaty = { ["Necromancer"] = true }
		AU.float = {}
		AU.floatConn = nil

		AU.floatStep = function(dt)
			local list = AU.float
			local now = os.clock()
			local alpha = 1 - math.exp(-5 * dt)

			for i = #list, 1, -1 do
				local f = list[i]
				local part, root = f.part, f.root

				if not (part and part.Parent and root and root.Parent) then
					table.remove(list, i)
				else
					local goal = (root.CFrame * f.rel) + Vector3.new(0, math.sin(now * 1.6 + f.phase) * 0.25, 0)

					if (part.Position - goal.Position).Magnitude > 30 then
						part.CFrame = goal -- you teleported: do not fly across the map
					else
						part.CFrame = part.CFrame:Lerp(goal, alpha)
					end
				end
			end

			if #list == 0 and AU.floatConn then
				AU.floatConn:Disconnect()
				AU.floatConn = nil
			end
		end

		local cur = nil -- record of the aura that is being built right now (a build never yields)

		local function track(inst)
			cur.items[#cur.items + 1] = inst
			AU.set[inst] = true
			return inst
		end

		local function auWipe(S)
			local list = S.items
			S.items = {}
			for _, inst in ipairs(list) do
				AU.set[inst] = nil
				pcall(function()
					inst:Destroy()
				end)
			end
		end

		local function weld(a, b)
			local w = Instance.new("WeldConstraint")
			w.Part0 = a
			w.Part1 = b
			w.Parent = b
			track(w)
		end

		-- body part of your character that matches a part name of the model (nil if there is none)
		local function charPartFor(char, name)
			local c = char:FindFirstChild(R6_TO_R15[name] or name)
			if not (c and c:IsA("BasePart")) then
				c = char:FindFirstChild(name)
			end
			if c and c:IsA("BasePart") and not AU.set[c] then
				return c
			end
			return nil
		end

		-- accessory style: an attachment on your body with the same name (BodyBackAttachment, HatAttachment ...)
		local function findBodyAtt(char, name)
			for _, p in ipairs(char:GetChildren()) do
				if p:IsA("BasePart") and not AU.set[p] then
					local a = p:FindFirstChild(name)
					if a and a:IsA("Attachment") and not AU.set[a] then
						return a
					end
				end
			end
			return nil
		end

		-- cleans the downloaded copy: no scripts / sounds / lights, loose weightless parts, no joints.
		-- If nothing in the model is switched on or visible, every effect is switched on.
		local function prepare(src)
			local anyOn = false
			for _, d in ipairs(src:GetDescendants()) do
				local cn = d.ClassName
				if d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("Humanoid") or d:IsA("Animator")
					or d:IsA("PointLight") or d:IsA("SpotLight") or d:IsA("SurfaceLight")
					or d:IsA("JointInstance") or d:IsA("WeldConstraint") then
					pcall(function()
						d:Destroy()
					end)
				elseif d:IsA("BasePart") then
					d.Anchored = false
					d.CanCollide = false
					d.CanQuery = false
					d.CanTouch = false
					d.Massless = true
					if not BODY[d.Name] and d.Transparency < 0.95 then
						anyOn = true
					end
				elseif FX[cn] and d.Enabled then
					anyOn = true
				end
			end

			if not anyOn then
				for _, d in ipairs(src:GetDescendants()) do
					if FX[d.ClassName] then
						pcall(function()
							d.Enabled = true
						end)
					end
				end
			end
		end

		local function ownerPart(inst, src)
			local p = inst.Parent
			while p and p ~= src do
				if p:IsA("BasePart") then
					return p
				end
				p = p.Parent
			end
			return nil
		end

		-- puts the (already prepared) model `src` onto the character. returns true, or false + reason
		local function auBuild(src, name)
			local char = lp.Character
			if not char then
				return false, "Character not ready!"
			end

			local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
			local head = char:FindFirstChild("Head")
			if not (torso and torso:IsA("BasePart") and head and head:IsA("BasePart")) then
				return false, "Character parts not found!"
			end

			local shield = (name == "Red Shield")

			local parts = {}
			for _, d in ipairs(src:GetDescendants()) do
				if d:IsA("BasePart") then
					parts[#parts + 1] = d
				end
			end

			-- reference frame of the model: its own torso, otherwise the middle of all its parts
			local function findPart(n)
				local p = src:FindFirstChild(n, true)
				if p and p:IsA("BasePart") then
					return p
				end
				return nil
			end
			local srcTorso = findPart("Torso") or findPart("UpperTorso") or findPart("HumanoidRootPart")
			local srcHead = findPart("Head")
			local refCF
			if srcTorso then
				refCF = srcTorso.CFrame
			elseif #parts > 0 then
				local sum = Vector3.new(0, 0, 0)
				for _, p in ipairs(parts) do
					sum = sum + p.Position
				end
				refCF = CFrame.new(sum / #parts)
			end

			-- parts that are visible, or that carry effects, are moved onto your character
			local moved, snap = {}, {}
			for _, p in ipairs(parts) do
				if not BODY[p.Name] then
					local use = AU.keepAll[name] or p.Transparency < 0.95
					if not use then
						for _, d in ipairs(p:GetDescendants()) do
							if FX[d.ClassName] then
								use = true
								break
							end
						end
					end
					if use then
						moved[#moved + 1] = p
						snap[p] = p.CFrame
					end
				end
			end

			for _, p in ipairs(moved) do
				local cf0 = snap[p]
				local carrier = torso
				local target

				for _, a in ipairs(p:GetChildren()) do
					if a:IsA("Attachment") then
						local ca = findBodyAtt(char, a.Name)
						if ca then
							carrier = ca.Parent
							target = carrier.CFrame * ca.CFrame * a.CFrame:Inverse()
							break
						end
					end
				end

				if not target then
					if p.Name == "Crown Base" then
						carrier = head
						local rel = CFrame.new(0, 1.5, 0)
						if srcHead then
							rel = srcHead.CFrame:Inverse() * cf0
						end
						target = head.CFrame * rel
					else
						target = torso.CFrame * (refCF and (refCF:Inverse() * cf0) or CFrame.new())
						if p.Name == "Aura" then
							target = target * CFrame.new(0, 0.5, 0)
						end
					end
				end

				p.Parent = char
				p.CFrame = target

				if AU.floaty[name] then
					local root = char:FindFirstChild("HumanoidRootPart") or torso

					p.Anchored = true
					AU.float[#AU.float + 1] = {
						part = p,
						root = root,
						rel = root.CFrame:Inverse() * target,
						phase = #AU.float * 0.9,
					}
					track(p)
				else
					weld(carrier, p)
					track(p)
				end
			end

			-- everything that is still inside the model (effects on stand-in parts / loose effects)
			local rest = src:GetDescendants()
			local attMap = {}

			local function targetFor(inst)
				local owner = ownerPart(inst, src)
				if owner then
					return charPartFor(char, owner.Name) or torso
				end
				return torso
			end

			for _, d in ipairs(rest) do
				if d:IsA("Attachment") then
					local c = d:Clone()
					c.Parent = targetFor(d)
					track(c)
					attMap[d] = c
				end
			end

			local linked = {}
			for _, d in ipairs(rest) do
				local cn = d.ClassName
				if FX[cn] and not d.Parent:IsA("Attachment") then
					if LINKED[cn] then
						linked[#linked + 1] = d
					else
						local c = d:Clone()
						c.Parent = targetFor(d)
						track(c)
					end
				end
			end

			for _, b in ipairs(linked) do
				local c = b:Clone()
				local good = true
				for _, prop in ipairs({ "Attachment0", "Attachment1" }) do
					local a = b[prop]
					if a then
						local m = attMap[a]
						if not m and a:IsDescendantOf(char) then
							m = a -- the attachment travelled with a moved part
						end
						if m then
							c[prop] = m
						else
							good = false
						end
					end
				end
				if good and c.Attachment0 and c.Attachment1 then
					c.Parent = targetFor(b)
					track(c)
				else
					c:Destroy()
				end
			end

			-- Red Shield: longer-lived particles that stay glued to the part
			local fxCount, visible = 0, 0
			local function fix(e)
				if FX[e.ClassName] then
					fxCount = fxCount + 1
				end
				if shield and e:IsA("ParticleEmitter") then
					local lt = e.Lifetime
					e.Lifetime = NumberRange.new(lt.Min * 4, lt.Max * 4)
					e.LockedToPart = true
				end
			end
			for _, it in ipairs(cur.items) do
				if it:IsA("BasePart") and (AU.keepAll[name] or it.Transparency < 0.95) then
					visible = visible + 1
				end
				fix(it)
				for _, d in ipairs(it:GetDescendants()) do
					fix(d)
				end
			end

			if #AU.float > 0 and not AU.floatConn then
				AU.floatConn = game:GetService("RunService").RenderStepped:Connect(AU.floatStep)
				list2.conns[#list2.conns + 1] = AU.floatConn
			end

			print(string.format("[F$VL Auras] %s: %d part(s) moved, %d effect(s), %d visible part(s)", name, #moved, fxCount, visible))

			if fxCount == 0 and visible == 0 then
				return false, "Nothing usable found in " .. name
			end
			return true
		end

		local function waitChar(timeout)
			local t0 = os.clock()
			while os.clock() - t0 < timeout do
				local c = lp.Character
				if c and c.Parent and c:FindFirstChild("Head") and (c:FindFirstChild("UpperTorso") or c:FindFirstChild("Torso")) then
					return c
				end
				task.wait(0.2)
			end
			return nil
		end

		-- mode: nil = normal (toggle turned on), "respawn" = silent re-apply after you respawned
		-- done(ok) is called when the load finished
		local function auEquip(id, name, mode, done)
			local S = AU.st[name]
			S.token = S.token + 1
			local my = S.token
			auWipe(S)
			S.want = true
			if mode == nil then
				S.pending = nil
			end

			local function fail(msg)
				if S.token ~= my then
					return
				end
				auWipe(S)
				if mode == nil then
					S.want = false
					S.pending = nil
				end
				note("Auras", msg, "x")
				if done then
					done(false)
				end
			end

			task.spawn(function()
				local raw = AU.cache[id]
				if not raw then
					local objs
					local ok, res = pcall(function()
						return game:GetObjects("rbxassetid://" .. id)
					end)
					if ok and type(res) == "table" and res[1] then
						objs = res
					else
						local ok2, model = pcall(function()
							return InsertService:LoadAsset(tonumber(id))
						end)
						if ok2 and model then
							objs = model:GetChildren()
						end
					end
					if S.token ~= my then
						return
					end
					if objs and #objs > 0 then
						raw = Instance.new("Model")
						for _, o in ipairs(objs) do
							o.Parent = raw
						end
						AU.cache[id] = raw
					end
				end

				if not raw then
					return fail("Failed to load " .. name)
				end

				if not waitChar(10) then
					return fail("Character not ready!")
				end
				if S.token ~= my then
					return
				end

				local src = raw:Clone()
				local ok, built, reason = pcall(function()
					cur = S
					prepare(src)
					return auBuild(src, name)
				end)
				cur = nil
				pcall(function()
					src:Destroy()
				end)

				if S.token ~= my then
					auWipe(S)
					return
				end

				if not ok then
					warn("[F$VL Auras] " .. tostring(built))
					return fail("Failed to apply " .. name)
				end
				if not built then
					return fail(reason or ("Failed to apply " .. name))
				end

				S.pending = { id = id, name = name }
				if mode == nil then
					note("Auras", name .. " enabled!")
				end
				if done then
					done(true)
				end
			end)
		end

		local function auClearOne(S)
			S.token = S.token + 1
			S.want = false
			S.pending = nil
			auWipe(S)
		end

		local function auClearAll()
			for _, a in ipairs(AURAS) do
				auClearOne(AU.st[a[1]])
			end
		end

		-- turns every pack toggle off in the UI (their callbacks are ignored while this runs)
		local function setToggles()
			AU.switching = true
			for _, tg in pairs(AU.toggles) do
				pcall(list2.setToggle, tg, false)
			end
			AU.switching = false
		end

		-- every instance of the auras that are on right now (used by "Tint Auras / VFX")
		list2.auraItems = function()
			local out = {}
			for _, a in ipairs(AURAS) do
				for _, inst in ipairs(AU.st[a[1]].items) do
					out[#out + 1] = inst
				end
			end
			return out
		end

		-- put every active aura back on after a respawn
		AU.charConn = lp.CharacterAdded:Connect(function(char)
			local list = {}
			for _, a in ipairs(AURAS) do
				local p = AU.st[a[1]].pending
				if p then
					list[#list + 1] = p
				end
			end
			if #list == 0 then
				return
			end
			task.spawn(function()
				task.wait(0.8)
				for _, p in ipairs(list) do
					if AU.st[p.name].pending == p and lp.Character == char then
						auEquip(p.id, p.name, "respawn")
					end
				end
			end)
		end)

		onUnload(function()
			auClearAll()
			if AU.charConn then
				AU.charConn:Disconnect()
				AU.charConn = nil
			end
			for _, obj in pairs(AU.cache) do
				pcall(function()
					obj:Destroy()
				end)
			end
			AU.cache = {}
		end)

		-- no new section: these toggles continue the existing "Auras" section (Magic Aura, Angel Wings)
		for _, a in ipairs(AURAS) do
			local nm, id = a[1], a[2]
			AU.toggles[nm] = tbl43.visuals:Toggle({
				Title = nm,
				Flag = "Toggle_Aura_" .. (nm:gsub("%s+", "_")),
				Desc = "Puts the " .. nm .. " aura on you (only you see it). Can be combined with the other auras.",
				Type = "Toggle",
				Value = false,
				Callback = function(v)
					if AU.switching then
						return
					end
					local S = AU.st[nm]
					if v then
						auEquip(id, nm, nil, function(ok)
							if not ok then
								task.defer(function()
									AU.switching = true
									pcall(list2.setToggle, AU.toggles[nm], false)
									AU.switching = false
								end)
							end
						end)
					elseif S.want then
						auClearOne(S)
						note("Auras", nm .. " disabled.", "power-off")
					end
				end,
			})
		end

		tbl43.visuals:Button({
			Title = "Clear Aura",
			Desc = "Turns off every aura in this section (the pack auras, Magic Aura and Angel Wings)",
			Icon = "circle-slash",
			Callback = function()
				auClearAll()
				setToggles()
				for _, fn in ipairs(list2.auraOff or {}) do
					pcall(fn)
				end
				note("Auras", "Aura cleared!")
			end,
		})
	end

	-- ================================================================ Auras: Tint + Constellations + Runes
	-- Ported from the Qwern / Pulse build (all client side, removed again when you unload):
	--   * Tint Auras / VFX  - recolours the aura pack (particles, beams, trails, lights, fire ...) with one colour
	--   * Constellations    - glowing star net: Energy pulses, Follow cursor, Rainbow lines, Star figures
	--   * Runes             - floating runes / glyphs (Rune set)
	-- The toggles start OFF like every other toggle in this script.
	do
		local function appendValues(destination, offset, ...)
			local values = table.pack(...)
			table.move(values, 1, values.n, offset + 1, destination)
		end

		local function num(v, default)
			if type(v) == "table" then
				v = v.Value or v[1]
			end
			return tonumber(v) or default
		end

		local function str(v, default)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			if v == nil then
				return default
			end
			return tostring(v)
		end

		local SKY = (function()
		    return function(argument2)
		        local localPlayer2 = argument2.lp
		        local connectSignal2, isActive =
		            argument2.pconn, argument2.pAlive or function()
		                return true
		            end
		        local runService, lighting, tx =
		            game:GetService("RunService"),
		            game:GetService("Lighting"),
		            {
		                dot = "rbxassetid://16512006463",
		                soft = "rbxassetid://1075864321",
		                spark = "rbxassetid://14590086212",
		                sharp = "rbxassetid://17391818367",
		                bright = "rbxassetid://16515551397",
		                runes = "rbxassetid://11910560348",
		                glyphs = "rbxassetid://10713705343",
		                const1 = "rbxassetid://14101033134",
		                const2 = "rbxassetid://14101036795",
		                beam = "rbxassetid://12781750620",
		                rays = "rbxassetid://4553095322",
		            }
		        local entries = {
		            dead = false,
		            fx = {},
		            t = 0,
		            envClock = 1,
		            R = 160,
		            sq = 0,
		            ky = 1,
		            kb = 1,
		            ctx = {},
		            TX = tx,
		            order = { "stars", "meteors", "comets", "net", "runes", "dust" },
		        }
		        entries.cfg = {
		            general = { bright = 100 },
		            stars = { on = false, density = 60, size = 100, twinkle = 60, tint = "Natural" },
		            meteors = { on = false, rate = 45, length = 100, color = Color3.fromRGB(190, 225, 255) },
		            comets = { on = false, rate = 40, size = 100, color = Color3.fromRGB(120, 210, 255) },
		            net = {
		                on = false,
		                nodes = 80,
