		            dust = { on = false, amount = 50, palette = "Gold" },
		        }
		        entries.palettes = {
		            stars = {
		                Natural = {
		                    Color3.fromRGB(232, 240, 255),
		                    Color3.fromRGB(170, 200, 255),
		                    Color3.fromRGB(255, 226, 190),
		                },
		                Cold = {
		                    Color3.fromRGB(205, 225, 255),
		                    Color3.fromRGB(140, 185, 255),
		                    Color3.fromRGB(190, 240, 255),
		                },
		                Warm = {
		                    Color3.fromRGB(255, 238, 214),
		                    Color3.fromRGB(255, 205, 150),
		                    Color3.fromRGB(255, 180, 140),
