		                Pink = { Color3.fromRGB(255, 170, 220), Color3.fromRGB(255, 120, 190) },
		                Aqua = { Color3.fromRGB(140, 255, 235), Color3.fromRGB(110, 200, 255) },
		            },
		        }
		        local randomGenerator = Random.new()
		        local function callback5(argument, argument2)
		            return argument + (argument2 - argument) * randomGenerator:NextNumber()
		        end
		        local function callback6(argument)
		            local entries2 = {}
		            for unused, item in ipairs(argument) do
		                entries2[#entries2 + 1] =
		                    NumberSequenceKeypoint.new(item[1], math.clamp(item[2], 0, 1000000), item[3] or 0)
