		                argument.speed and (argument.speed[2] or argument.speed[1])
		            particleEmitter.Speed = new(calculatedValue, calculatedValue2 or 0)
		            particleEmitter.LockedToPart = argument.locked == true
		            particleEmitter.Orientation = argument.orient or Enum.ParticleOrientation.FacingCamera
