		                    featureState.star = callback15(
		                        featureState.head,
		                        { tex = tx.spark, life = { 30 }, locked = true, bright = 3 }
		                    )
		                    featureState.dust = callback15(
		                        featureState.head,
		                        { tex = tx.dot, life = { 0.3, 0.8 }, bright = 2.2, speed = { 0.2, 1 }, spread = Vector2.new(
		                            180,
