		            end,
		            apply = function(argument, argument2)
		                local meteors, r = entries.cfg.meteors, argument2.R
		                argument.trail = 0.3 * meteors.length / 100
		                for unused, item in ipairs(argument.pool) do
		                    item.b.Color = callback8({
		                        { 0, meteors.color },
		                        { 0.7, callback10(meteors.color, Color3.new(1, 1, 1), 0.5) },
		                        { 1, Color3.new(1, 1, 1) },
		                    })
		                    item.b2.Color = ColorSequence.new(meteors.color)
		                    item.glow.Color = ColorSequence.new(meteors.color)
		                    item.dust.Color = ColorSequence.new(meteors.color)
		                    item.star.Size = NumberSequence.new(r * 0.03)
		                    item.glow.Size = NumberSequence.new(r * 0.032)
		                    item.dust.Size = callback6({ { 0, r * 0.007 }, { 1, 0 } })
		                    local dust, entries2 = item.dust, {}
		                    appendValues(entries2, 0, { 0, 0.1 }, { 1, 1 })
		                    dust.Transparency = callback7(entries2)
		                    callback18({ item.star, item.glow, item.dust }, true)
		                end
		                if meteors.rate <= 0 then
		                    argument.next = math.huge
		                elseif argument.next == math.huge then
