		                if not value then
		                    return
		                end
		                local r, calculatedValue, radResult, width1 =
		                    argument2.R,
		                    randomGenerator:NextNumber() < 0.8
		                            and callback12(argument2) + callback5(-1, 1) * 1.0471975511965976
		                        or callback5(0, 6.283185307179586),
