		            ctx.cam, ctx.dt, ctx.t, ctx.R = cam, dt, entries.t, entries.R
		            ctx.pos = cam.CFrame.Position
		            ctx.look = cam.CFrame.LookVector
		            cam = localPlayer2.Character
		            local on = cam and (cam:FindFirstChild("HumanoidRootPart"))
		            ctx.me = on and on.Position or ctx.pos
		            for key, item in ipairs(entries.order) do
		                key, on = entries.fx[item], entries.cfg[item].on
		                if on and not key.live and not (key.failAt and entries.t < key.failAt) then
		                    local success, result = pcall(key.build, key, entries.folder, ctx)
		                    if success then
		                        key.live = true
		                        key.dirty = true
		                    else
		                        key.failAt = entries.t + 5
		                        pcall(key.drop, key)
		                        warn("[F$VL] sky fx " .. item .. ": " .. tostring(result))
		                    end
		                elseif on then
		                elseif key.live then
		                    pcall(key.drop, key)
		                    key.live = false
		                end
		                if key.live then
		                    if key.dirty then
		                        key.dirty = false
		                        local success, result = pcall(key.apply, key, ctx)
		                        if not success then
		                            warn("[F$VL] sky fx " .. item .. ": " .. tostring(result))
		                        end
		                    end
		                    local success, result = pcall(key.step, key, ctx)
		                    if not success then
		                        key.failAt = entries.t + 5
		                        pcall(key.drop, key)
		                        key.live = false
		                        warn("[F$VL] sky fx " .. item .. ": " .. tostring(result))
		                    end
		                end
		            end
		        end
		        entries.destroy = function()
		            entries.dead = true
		            pcall(entries.dropAll)
		            if entries.conn then
		                pcall(function()
		                    entries.conn:Disconnect()
		                end)
		            end
		        end
		        entries.conn = connectSignal2(runService.RenderStepped, function(argument)
		            local success, result = pcall(entries.step, argument)
		            if not success then
		                warn("[F$VL] sky fx step: " .. tostring(result))
		            end
		        end)
		        return entries
		    end
		end)()({
			lp = lp,
			pconn = function(signal, fn)
				local conn = signal:Connect(fn)
				list2.conns[#list2.conns + 1] = conn
				return conn
			end,
		})

