		-- ---------------------------------------------------------------- Tint Auras / VFX
		local TINT = { on = false, color = Color3.fromRGB(0, 200, 255), glow = 100, token = 0 }
		local weak = { __mode = "k" }
		local origA = setmetatable({}, weak) -- original Color / FillColor / VertexColor
		local origB = setmetatable({}, weak) -- original LightEmission / Brightness
		local origC = setmetatable({}, weak) -- original second colour (Fire / Highlight)
		local touched = setmetatable({}, weak)
		local applied = setmetatable({}, weak)

		local function recolor(seq, c)
			if typeof(seq) ~= "ColorSequence" then
				return ColorSequence.new(c)
			end
			local out = {}
			for _, kp in ipairs(seq.Keypoints) do
				local v = kp.Value
				local mx, mn = math.max(v.R, v.G, v.B), math.min(v.R, v.G, v.B)
				local k = 0.3 + 0.7 * mx
				local col = Color3.new(c.R * k, c.G * k, c.B * k)
				if mn > 0.72 then
					col = col:Lerp(Color3.new(1, 1, 1), (mn - 0.72) / 0.28 * 0.75)
				end
				out[#out + 1] = ColorSequenceKeypoint.new(kp.Time, col)
			end
			return ColorSequence.new(out)
		end

		-- c = colour to apply (nil = put the original look back)
		local function paint(inst, c, glow)
			local key = c and (c:ToHex() .. ":" .. tostring(glow)) or false
			if applied[inst] == key then
				return
			end
			pcall(function()
				if inst:IsA("ParticleEmitter") or inst:IsA("Beam") or inst:IsA("Trail") then
					if origA[inst] == nil then
						origA[inst] = inst.Color
						origB[inst] = inst.LightEmission
					end
					touched[inst] = true
					if c then
						inst.Color = recolor(origA[inst], c)
						inst.LightEmission = math.clamp(origB[inst] * glow, 0, 1)
					else
						inst.Color = origA[inst]
						inst.LightEmission = origB[inst]
					end
				elseif inst:IsA("PointLight") or inst:IsA("SpotLight") or inst:IsA("SurfaceLight") then
					if origA[inst] == nil then
						origA[inst] = inst.Color
						origB[inst] = inst.Brightness
					end
					touched[inst] = true
					inst.Color = c or origA[inst]
					inst.Brightness = c and origB[inst] * glow or origB[inst]
				elseif inst:IsA("Fire") then
					if origA[inst] == nil then
						origA[inst] = inst.Color
						origC[inst] = inst.SecondaryColor
					end
					touched[inst] = true
					inst.Color = c or origA[inst]
					inst.SecondaryColor = c and c:Lerp(Color3.new(0, 0, 0), 0.35) or origC[inst]
				elseif inst:IsA("Smoke") then
					if origA[inst] == nil then
						origA[inst] = inst.Color
					end
					touched[inst] = true
					inst.Color = c or origA[inst]
				elseif inst:IsA("Sparkles") then
					if origA[inst] == nil then
						origA[inst] = inst.SparkleColor
					end
					touched[inst] = true
					inst.SparkleColor = c or origA[inst]
				elseif inst:IsA("Highlight") then
					if origA[inst] == nil then
						origA[inst] = inst.FillColor
						origC[inst] = inst.OutlineColor
					end
					touched[inst] = true
					inst.FillColor = c or origA[inst]
					inst.OutlineColor = c or origC[inst]
				elseif inst:IsA("BasePart") then
					if origA[inst] == nil then
						origA[inst] = inst.Color
					end
					touched[inst] = true
					inst.Color = c or origA[inst]
				end
			end)
			applied[inst] = key
		end

		local function applyTint()
			if not list2.auraItems then
				return
			end
			local glow = TINT.glow / 100
			for _, it in ipairs(list2.auraItems()) do
				paint(it, TINT.color, glow)
				for _, d in ipairs(it:GetDescendants()) do
					paint(d, TINT.color, glow)
				end
			end
		end

		local function restoreTint()
			for inst in pairs(touched) do
				if inst.Parent then
					paint(inst, nil, 1)
				end
			end
		end

		local function tintStart()
			TINT.token = TINT.token + 1
			local mine = TINT.token
			task.spawn(function()
				-- re-applied twice a second so auras that are turned on / respawned later get tinted too
				while TINT.on and TINT.token == mine do
					pcall(applyTint)
					task.wait(0.5)
				end
			end)
		end

		onUnload(function()
			TINT.on = false
			TINT.token = TINT.token + 1
			pcall(restoreTint)
		end)

