list2.applyEspPreset = function(pr)
	if list2.setBoxLook then
		pcall(list2.setBoxLook, pr.box or "Full", pr.boxFill == true)
	end

	local set = list2.espFlagSet

	set("Toggle_Extra_Box", pr.box and true or false)
	set("Toggle_Extra_Skeleton", pr.skel and true or false)
	set("Toggle_Extra_Flags", pr.flags and true or false)
	set("Toggle_ESP_Outline", pr.outline and true or false)
	set("Toggle_Display_Name_ESP", pr.names and true or false)
	set("Toggle_ESP_Tracers", pr.tracers and true or false)
	set("Toggle_ESP_Arrows", pr.arrows and true or false)
	set("Toggle_ESP_Distance", pr.dist and true or false)
	set("Dropdown_ESP_Style", pr.style or "Classic")

	local fill = tonumber(pr.fill) or 0

	if fill > 0 then
		set("Slider_ESP_FillStrength", math.clamp(fill, 0.1, 1))
	end

	set("Toggle_Full_Body_ESP", fill > 0)
end

