		{ "AWP", "rbxassetid://120989608556423" },
		{ "Revolver", "rbxassetid://115486270266848" },
		{ "Revolver 2", "rbxassetid://120771468205926" },
		{ ".357 Magnum", "rbxassetid://6350479847" },
		{ ".44 Magnum", "rbxassetid://18918494387" },
		{ "Sniper", "rbxassetid://103104730555203" },
		{ "Heavy Sniper", "rbxassetid://5700090398" },
		{ "Glock Silenced", "rbxassetid://112707321486177" },
		{ "XPR50 Silenced", "rbxassetid://130946834720896" },
		{ "M4A1 Silenced", "rbxassetid://5707240744" },
		{ "Pistol", "rbxassetid://6506930532" },
		{ "Realistic", "rbxassetid://115567133047135" },
		{ "Retro", "rbxassetid://3976061026" },
		{ "Laser", "rbxassetid://4400449399" },
		{ "Plasma", "rbxassetid://1905343596" },
		{ "Railgun", "rbxassetid://133865552007016" },
		{ "Fortnite", "rbxassetid://113797851917516" },
		{ "MLG", "rbxassetid://122180189312589" },
		{ "Single Shot", "rbxassetid://9114729252" },
	}

	local KILL_LIST = {
		{ "Respectful", "rbxassetid://127793374596820" },
		{ "enrike", "rbxassetid://111135055793821" },
		{ "Mahito", "rbxassetid://17774376295" },
		{ "CS:GO Headshot", "rbxassetid://133002449941130" },
