		{ "Madness Headshot", "rbxassetid://7849569525" },
		{ "Kill Confirmed", "rbxassetid://127053529664678" },
	}

	local function weaponId(kind)
		if kind == "shot" then
			if W.shot == "Off" then
				return nil
			elseif W.shot == "Custom ID" then
				return assetFromInput(W.customShot)
			end
			return (lookup(SHOT_LIST, W.shot))
		end
		if W.kill == "Off" then
			return nil
		elseif W.kill == "Custom ID" then
			return assetFromInput(W.customKill)
		end
		return (lookup(KILL_LIST, W.kill))
	end

	local function weaponPreview(id)
		if not id or id == "" then
			return
		end
		local snd = Instance.new("Sound")
		snd.Name = "FVLWeaponSound"
		snd.SoundId = id
		snd.Volume = (tonumber(W.vol) or 60) / 100 * 3
		snd.Parent = SoundService
		pcall(function()
			snd:Play()
		end)
		pcall(function()
			snd.Ended:Once(function()
				pcall(function()
					snd:Destroy()
				end)
			end)
		end)
		task.delay(8, function()
			pcall(function()
				snd:Destroy()
			end)
		end)
	end

	local function gunTool()
		local char = lp.Character
		local gun = char and char:FindFirstChild("Gun")
		if gun then
			return gun
		end
		local bp = lp:FindFirstChild("Backpack")
		return bp and bp:FindFirstChild("Gun")
	end

	-- the game's own gun sounds get muted while a replacement is selected
	local function shouldMute(snd)
		local n = string.lower(snd.Name)
		if W.shot ~= "Off" and (n == "gunshot" or n == "reload" or n == "gunkill") then
			return true
		end
		if W.kill ~= "Off" and n == "gunkill" then
			return true
		end
		return false
	end

	local function muteSound(snd)
		if not snd:IsA("Sound") then
			return
		end
		if shouldMute(snd) then
			if not W.muted[snd] then
				W.muted[snd] = { vol = snd.Volume }
			end
			if not W.hooked[snd] then
				W.hooked[snd] = true
				pcall(function()
					track(snd:GetPropertyChangedSignal("Volume"):Connect(function()
						local rec = W.muted[snd]
						if rec and snd.Volume ~= 0 then
							rec.vol = snd.Volume
							snd.Volume = 0
						end
					end))
				end)
			end
			if snd.Volume ~= 0 then
				pcall(function()
					snd.Volume = 0
				end)
			end
		elseif W.muted[snd] then
			local rec = W.muted[snd]
			W.muted[snd] = nil
			pcall(function()
				snd.Volume = rec.vol
			end)
		end
	end

	local function restoreMuted()
		for snd, rec in pairs(W.muted) do
			pcall(function()
				snd.Volume = rec.vol
			end)
		end
		W.muted = {}
	end

	local function weaponScan()
		for snd, rec in pairs(W.muted) do
			if not snd.Parent then
				W.muted[snd] = nil
				W.hooked[snd] = nil
			elseif not shouldMute(snd) then
				W.muted[snd] = nil
				pcall(function()
					snd.Volume = rec.vol
				end)
			end
		end
		local gun = gunTool()
		if not gun then
			return
		end
		if W.watching ~= gun then
			W.watching = gun
			if W.watchConn then
				pcall(function()
					W.watchConn:Disconnect()
				end)
			end
			W.watchConn = gun.DescendantAdded:Connect(function(inst)
				if inst:IsA("Sound") then
					pcall(muteSound, inst)
				end
			end)
		end
		for _, inst in ipairs(gun:GetDescendants()) do
			if inst:IsA("Sound") then
				pcall(muteSound, inst)
			end
		end
	end

	task.spawn(function()
		while PACK.alive do
			task.wait(0.25)
			if W.shot ~= "Off" or W.kill ~= "Off" or next(W.muted) then
				pcall(weaponScan)
			end
		end
	end)

	local function modelOf(inst)
		local p = inst
		while p and not (p:IsA("Model") and p:FindFirstChildOfClass("Humanoid")) do
			p = p.Parent
		end
		return p
	end

	task.spawn(function()
		local cs = RepStorage:WaitForChild("ClientServices", 30)
		local ws = cs and cs:WaitForChild("WeaponService", 30)
		local ev = ws and ws:WaitForChild("GunFired", 30)
		if not ev or not ev:IsA("RemoteEvent") or not PACK.alive then
			return
		end
		track(ev.OnClientEvent:Connect(function(gun, _, _, hit)
			local mine = false
			pcall(function()
				local m = typeof(gun) == "Instance" and modelOf(gun) or nil
				mine = m ~= nil and m == lp.Character
			end)
			if not mine then
				return
			end
			local now = os.clock()
			if W.shot ~= "Off" and now - W.last > 0.15 then
				W.last = now
				weaponPreview(weaponId("shot"))
			end
			if W.kill ~= "Off" and typeof(hit) == "Instance" then
				local victim
				pcall(function()
					local m = modelOf(hit)
					if m and m ~= lp.Character and Players:GetPlayerFromCharacter(m) then
						victim = m
					end
				end)
				if victim then
					task.delay(0.06, function()
						weaponPreview(weaponId("kill"))
					end)
				end
			end
			pcall(weaponScan)
		end))
	end)

