	-- =================================================================== ROUND SOUNDS
	do
	local G = {
		cfg = { roll = "Game", reveal = "Game", win = "Game", vol = 100, winId = "" },
		orig = {},
		capTok = {},
		won = false,
		wonAt = -math.huge,
		endSound = nil,
		endAt = 0,
		endPending = false,
		own = nil,
	}

	-- who wins the round for which role (so Victory Music only replaces the track when YOU won)
	local WIN = {
		Innocent = { MurdererDied = true, MurdererLeft = true, Time = true, InnocentsEscaped = true },
		Hero = { MurdererLeft = true, Time = true, MurdererDied = true },
		Sheriff = { SheriffWin = true, MurdererDied = true, MurdererLeft = true },
		Murderer = { MurdererWin = true },
		Assassin = { PlayerWon = true },
		Zombie = { ZombiesWin = true },
		Survivor = { SurvivorsWin = true, Time = true },
		Freezer = { FreezersWin = true },
		Runner = { Time = true, RunnersWin = true },
		Team1 = { Team1Victory = true },
		Team2 = { Team2Victory = true },
		Vampire = { VampireWin = true },
		Hunter = { Time = true, InnocentWin = true },
		Villager = { Time = true, InnocentWin = true },
	}

	local KIND = { ["179235828"] = "roll", ["179287602"] = "reveal" }

	local END_IDS = {
		["13934589675"] = true,
		["139379638020186"] = true,
		["320397765"] = true,
		["320403652"] = true,
		["1836013831"] = true,
		["1838605064"] = true,
		["1841274964"] = true,
	}

	-- { name, soundId, optional max seconds }
	local LIB = {
		roll = {
			{ "Bright Click", "rbxassetid://15675059323" },
			{ "Fast Click", "rbxasset://sounds/clickfast.wav" },
			{ "Switch", "rbxasset://sounds/SWITCH3.wav" },
			{ "Snap", "rbxasset://sounds/snap.wav" },
			{ "Soft Click", "rbxassetid://16480568148" },
			{ "Heavy Click", "rbxassetid://16480567946" },
			{ "8-Bit Blip", "rbxassetid://16480580213" },
			{ "8-Bit Beep", "rbxassetid://16480578737" },
			{ "Wheel Tick", "rbxassetid://9120658649" },
			{ "Ping", "rbxasset://sounds/electronicpingshort.wav" },
			{ "Bubble", "rbxassetid://9112872239" },
		},
		reveal = {
			{ "Sparkle Ding", "rbxassetid://9126073001" },
			{ "Magic Chime", "rbxassetid://9116394545" },
			{ "Magic Glow", "rbxassetid://9116395089" },
			{ "Choir", "rbxassetid://9114792002", 3.5 },
			{ "Desk Bell", "rbxassetid://9125485591", 2.5 },
			{ "Big Bell", "rbxassetid://1034263055", 3 },
			{ "Stinger", "rbxassetid://15675043410" },
			{ "Notify", "rbxassetid://17208361335" },
			{ "Sword Draw", "rbxassetid://9119742466" },
			{ "Riser", "rbxassetid://9125805579" },
			{ "8-Bit Riser", "rbxassetid://16480578169" },
			{ "Cymbal", "rbxassetid://9113966034", 3 },
			{ "Party Horn", "rbxassetid://9117240379" },
		},
	}

	local function findLib(kind, name)
		for _, item in ipairs(LIB[kind] or {}) do
			if item[1] == name then
				return item
			end
		end
		return nil
	end

	local function idDigits(id)
		return tostring(id):match("(%d+)%s*$")
	end

	local function capSound(snd, seconds)
		G.capTok[snd] = (G.capTok[snd] or 0) + 1
		local token = G.capTok[snd]
		task.delay(seconds, function()
			if G.capTok[snd] ~= token or not snd.Parent or not snd.IsPlaying then
				return
			end
			local vol = snd.Volume
			pcall(function()
				TweenService:Create(snd, TweenInfo.new(0.6), { Volume = 0 }):Play()
			end)
			task.wait(0.65)
			if G.capTok[snd] ~= token or not snd.Parent then
				return
			end
			pcall(function()
				snd:Stop()
			end)
			snd.Volume = vol
		end)
	end

	local function applySound(snd)
		local rec = G.orig[snd]
		if not rec then
			return
		end
		local choice = G.cfg[rec.kind]
		if choice == "Game" or choice == nil then
			if snd.SoundId ~= rec.id then
				snd.SoundId = rec.id
			end
			snd.Volume = rec.vol
			snd:SetAttribute("FVLOrigSound", nil)
			snd:SetAttribute("FVLOrigVol", nil)
			return
		end
		snd:SetAttribute("FVLOrigSound", rec.id)
		snd:SetAttribute("FVLOrigVol", rec.vol)
		if choice == "Off" then
			snd.Volume = 0
			return
		end
		local item = findLib(rec.kind, choice)
		if item then
			if snd.SoundId ~= item[2] then
				snd.SoundId = item[2]
			end
			snd.Volume = rec.vol * G.cfg.vol / 100
		end
	end

	local function trackSound(snd)
		if not snd:IsA("Sound") then
			return
		end
		if G.orig[snd] then
			applySound(snd)
			return
		end
		local id = snd:GetAttribute("FVLOrigSound") or snd.SoundId
		local kind = KIND[idDigits(id) or ""]
		if not kind then
			return
		end
		G.orig[snd] = { id = id, kind = kind, vol = tonumber(snd:GetAttribute("FVLOrigVol")) or snd.Volume }
		track(snd.Played:Connect(function()
			local rec = G.orig[snd]
			local item = rec and findLib(rec.kind, G.cfg[rec.kind])
			if item and item[3] then
				capSound(snd, item[3])
			end
		end))
		applySound(snd)
	end

	local function refreshSounds()
		for snd in pairs(G.orig) do
			if snd.Parent then
				pcall(applySound, snd)
			else
				G.orig[snd] = nil
			end
		end
	end

	local function winAsset()
		if G.cfg.win == "Custom ID" then
			return assetFromInput(G.cfg.winId)
		end
		return nil
	end

	local END_LIFE, END_VOL = 10, 0.4

	local function playOwn(id, preview)
		if G.own then
			pcall(function()
				G.own:Destroy()
			end)
		end
		local snd = Instance.new("Sound")
		snd.Name = "FVLEndMusic"
		snd.SoundId = id
		snd.Volume = END_VOL * G.cfg.vol / 100
		snd.Looped = false
		snd.PlayOnRemove = false
		if not preview then
			snd.SoundGroup = SoundService:FindFirstChild("Music")
		end
		snd.Parent = SoundService
		G.own = snd
		snd.Ended:Once(function()
			pcall(function()
				snd:Destroy()
			end)
		end)
		snd:Play()
		task.delay(END_LIFE, function()
			pcall(function()
				snd:Destroy()
			end)
		end)
	end

	local function playEnd(endSnd)
		if not G.won then
			return
		end
		local mode = G.cfg.win
		if mode == "Game" or mode == nil then
			return
		end
		local custom = winAsset()
		if mode == "Custom ID" and not custom then
			return
		end
		pcall(function()
			endSnd.Volume = 0
			endSnd:Stop()
		end)
		task.defer(function()
			pcall(function()
				endSnd:Stop()
			end)
		end)
		if custom then
			playOwn(custom, false)
		end
	end

	local function previewRound(kind)
		local choice = G.cfg[kind]
		if choice == "Off" then
			return
		end
		local item = findLib(kind, choice)
		local id = item and item[2] or (kind == "roll" and "rbxassetid://179235828" or "rbxassetid://179287602")
		local snd = Instance.new("Sound")
		snd.SoundId = id
		snd.Volume = 0.5 * G.cfg.vol / 100
		snd.Parent = SoundService
		snd:Play()
		task.delay(item and item[3] or 6, function()
			pcall(function()
				TweenService:Create(snd, TweenInfo.new(0.5), { Volume = 0 }):Play()
			end)
			task.wait(0.55)
			pcall(function()
				snd:Destroy()
			end)
		end)
	end

	task.spawn(function()
		local gui = lp:WaitForChild("PlayerGui", 30)
		if not gui or not PACK.alive then
			return
		end
		for _, inst in ipairs(gui:GetDescendants()) do
			if inst:IsA("Sound") then
				pcall(trackSound, inst)
			end
		end
		track(gui.DescendantAdded:Connect(function(inst)
			if inst:IsA("Sound") then
				task.defer(function()
					pcall(trackSound, inst)
				end)
			end
		end))
		-- the end-of-round track is parented straight into PlayerGui
		track(gui.ChildAdded:Connect(function(snd)
			if not snd:IsA("Sound") then
				return
			end
			local recent = os.clock() - G.wonAt < 2 and snd.SoundGroup ~= nil and snd.SoundGroup.Name == "Music"
			if not recent and not END_IDS[idDigits(snd.SoundId) or ""] then
				return
			end
			G.endSound, G.endAt = snd, os.clock()
			if os.clock() - G.wonAt < 3 then
				G.endPending = false
				pcall(playEnd, snd)
			else
				G.endPending = true
			end
		end))
		local rem = RepStorage:WaitForChild("Remotes", 30)
		rem = rem and rem:WaitForChild("Gameplay", 30)
		local vs = rem and rem:WaitForChild("VictoryScreen", 30)
		if not vs or not PACK.alive then
			return
		end
		track(vs.OnClientEvent:Connect(function(_, role, reason)
			local entry = WIN[tostring(role)]
			G.won = entry ~= nil and entry[tostring(reason)] == true
			G.wonAt = os.clock()
			local endSnd = G.endSound
			if G.endPending and endSnd and endSnd.Parent and os.clock() - G.endAt < 1.5 then
				G.endPending = false
				pcall(playEnd, endSnd)
			end
		end))
	end)

	local function roundNames(kind, extra)
		local out = { "Game", "Off" }
		for _, item in ipairs(LIB[kind] or {}) do
			out[#out + 1] = item[1]
		end
		for _, item in ipairs(extra or {}) do
			out[#out + 1] = item
		end
		return out
	end

