		end,
	})

	tbl43.visuals:Input({
		Title = "Custom Victory Sound ID",
		Flag = "Input_RSound_VictoryId",
		Desc = "Used when Victory Music is set to Custom ID.",
		Placeholder = "e.g. 9178397781",
		Default = "",
		Callback = function(v)
			G.cfg.winId = tostring(v or "")
		end,
	})

	tbl43.visuals:Slider({
		Title = "Round Sounds Volume",
		Flag = "Slider_RSound_Volume",
		Min = 0,
		Max = 200,
		Value = 100,
		Step = 1,
		Suffix = "%",
		Callback = function(v)
			G.cfg.vol = tonumber(v) or 100
			refreshSounds()
		end,
	})

	tbl43.visuals:Button({
		Title = "Preview Role Sounds",
		Icon = "speaker",
		Callback = function()
			task.spawn(function()
				for _ = 1, 6 do
					previewRound("roll")
					task.wait(0.11)
				end
				previewRound("reveal")
			end)
		end,
	})

	tbl43.visuals:Button({
		Title = "Preview Victory Music",
		Icon = "speaker",
		Callback = function()
			local mode = G.cfg.win
			if mode == "Off" then
				return
			end
			playOwn(winAsset() or "rbxassetid://13934589675", true)
		end,
	})


	obj3:OnDestroy(function()
		G.cfg.roll, G.cfg.reveal = "Game", "Game"
		pcall(refreshSounds)
		if G.own then
			pcall(function()
				G.own:Destroy()
			end)
		end
	end)
	end

	-- =================================================================== SOUNDCLOUD
	do
	local SC = {
		cid = nil,
		results = {},
		sel = nil,
		cur = nil,
		snd = nil,
		gen = 0,
		vol = 60,
		loop = false,
		auto = true,
		query = "",
		busy = false,
		dir = "FVLV2/sc",
	}

	local function httpRequest(opts)
		local fn = (syn and syn.request) or http_request or request or (http and http.request)
		if type(fn) ~= "function" then
			return nil
		end
		local ok, res = pcall(fn, opts)
		if ok and type(res) == "table" then
			return res
		end
		return nil
	end

	local function bodyOf(res)
		return res and (res.Body or res.body)
	end

	local function statusOf(res)
		return res and (res.StatusCode or res.status)
	end

	local function getClientId(force)
		if SC.cid and not force then
			return SC.cid
		end
		local home = httpRequest({ Url = "https://soundcloud.com", Method = "GET" })
		local html = bodyOf(home)
		if type(html) ~= "string" then
			return nil
		end
		local urls = {}
		for u in html:gmatch('src="(https://a%-v2%.sndcdn%.com/assets/[^"]+%.js)"') do
			urls[#urls + 1] = u
		end
		for i = #urls, 1, -1 do
			local js = bodyOf(httpRequest({ Url = urls[i], Method = "GET" }))
			if type(js) == "string" then
				local id = js:match('client_id:"(%w+)"') or js:match('client_id=(%w+)')
				if id and #id >= 20 then
					SC.cid = id
					return id
				end
			end
		end
		return nil
	end

	-- GET <api-v2 path> and decode the JSON; refreshes the client id once if SoundCloud rejects it
	local function scApi(path, params, retried)
		local cid = getClientId(retried)
		if not cid then
			return nil, "client"
		end
		local sep = string.find(path, "?", 1, true) and "&" or "?"
		local url = "https://api-v2.soundcloud.com" .. path .. sep .. (params and (params .. "&") or "") .. "client_id=" .. cid
		local res = httpRequest({ Url = url, Method = "GET" })
		local code = statusOf(res)
		if (code == 401 or code == 403) and not retried then
			SC.cid = nil
			return scApi(path, params, true)
		end
		if code ~= 200 then
			return nil, "http"
		end
		local ok, data = pcall(HttpSvc.JSONDecode, HttpSvc, bodyOf(res) or "")
		if ok and type(data) == "table" then
			return data
		end
		return nil, "json"
	end

	local function normTrack(t)
		if type(t) ~= "table" or not t.id or type(t.title) ~= "string" then
			return nil
		end
		local trans = type(t.media) == "table" and t.media.transcodings or nil
		return {
			id = t.id,
			title = t.title,
			artist = type(t.user) == "table" and t.user.username or "SoundCloud",
			dur = (tonumber(t.duration) or 0) / 1000,
			trans = trans,
			auth = t.track_authorization,
		}
	end

	local function fmtTime(sec)
		sec = math.max(0, math.floor(sec or 0))
		return string.format("%d:%02d", sec // 60, sec % 60)
	end

	local function ensureDir()
		pcall(function()
			if not isfolder("FVLV2") then
				makefolder("FVLV2")
			end
			if not isfolder(SC.dir) then
				makefolder(SC.dir)
			end
		end)
	end

	local function stripCtl(s)
		return (tostring(s or ""):gsub("%c", " "))
	end

	-- downloads the mp3 for a track and returns a getcustomasset url
	local function trackAsset(tr)
		if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then
			return nil, "executor"
		end
		ensureDir()
		local path = SC.dir .. "/" .. tostring(tr.id) .. ".mp3"
		if type(isfile) == "function" and isfile(path) then
			local ok, asset = pcall(getcustomasset, path)
			if ok and type(asset) == "string" and asset ~= "" then
				return asset
			end
		end
		local trans = tr.trans
		if type(trans) ~= "table" then
			return nil, "unavailable"
		end
		local pick
		for _, t in ipairs(trans) do
			local f = type(t.format) == "table" and t.format or {}
			if f.protocol == "progressive" and tostring(f.mime_type):find("mpeg") then
				pick = t
				break
			end
		end
		if not pick then
			for _, t in ipairs(trans) do
				local f = type(t.format) == "table" and t.format or {}
				if f.protocol == "hls" and tostring(f.mime_type):find("mpeg") then
					pick = t
					break
				end
			end
		end
		if not pick or type(pick.url) ~= "string" then
			return nil, "unavailable"
		end
		local cid = getClientId()
		if not cid then
			return nil, "client"
		end
		local link = pick.url .. "?client_id=" .. cid
		if tr.auth then
			link = link .. "&track_authorization=" .. tostring(tr.auth)
		end
		local meta = httpRequest({ Url = link, Method = "GET" })
		local ok, info = pcall(HttpSvc.JSONDecode, HttpSvc, bodyOf(meta) or "")
		if not ok or type(info) ~= "table" or type(info.url) ~= "string" then
			return nil, "unavailable"
		end
		local data
		if pick.format.protocol == "progressive" then
			data = bodyOf(httpRequest({ Url = info.url, Method = "GET" }))
		else
			local playlist = bodyOf(httpRequest({ Url = info.url, Method = "GET" }))
			if type(playlist) ~= "string" then
				return nil, "download"
			end
			local parts, n = {}, 0
			for line in playlist:gmatch("[^\r\n]+") do
				if line:sub(1, 1) ~= "#" and line:match("^https?://") then
					n += 1
					if n > 150 then
						break
					end
					local seg = bodyOf(httpRequest({ Url = line, Method = "GET" }))
					if type(seg) ~= "string" then
						return nil, "download"
					end
					parts[#parts + 1] = seg
				end
			end
			data = table.concat(parts)
		end
		if type(data) ~= "string" or #data < 1024 then
			return nil, "download"
		end
		if not pcall(writefile, path, data) then
			return nil, "download"
		end
		local ok2, asset = pcall(getcustomasset, path)
		if ok2 and type(asset) == "string" and asset ~= "" then
			return asset
		end
		return nil, "download"
	end

	local statusLabel

	local function setStatus(text)
		pcall(function()
			statusLabel:Set(text)
		end)
	end

	local resultsDropdown

	local function resultNames()
		local out = {}
		for i, tr in ipairs(SC.results) do
			out[i] = string.format("%d. %s - %s (%s)", i, stripCtl(tr.title):sub(1, 48), stripCtl(tr.artist):sub(1, 24), fmtTime(tr.dur))
		end
		return out
	end

	local function setResults(list)
		SC.results = list
		SC.sel = list[1] and 1 or nil
		local names = resultNames()
		if resultsDropdown then
			resultsDropdown:Refresh(names, false)
			if names[1] then
				resultsDropdown:Set(names[1], true)
			end
		end
	end

	local stopSC

	local playIndex
	local function playNext(step)
		if #SC.results == 0 then
			return
		end
		local idx = (SC.cur and SC.cur.index or SC.sel or 0) + step
		if idx > #SC.results then
			idx = 1
		elseif idx < 1 then
			idx = #SC.results
		end
		playIndex(idx)
	end

	playIndex = function(idx)
		local tr = SC.results[idx]
		if not tr then
			note("SoundCloud", "Search for a track first.")
			return
		end
		SC.gen += 1
		local gen = SC.gen
		if SC.snd then
			pcall(function()
				SC.snd:Destroy()
			end)
			SC.snd = nil
		end
		SC.sel = idx
		setStatus("Loading: " .. stripCtl(tr.title))
		task.spawn(function()
			local asset, err = trackAsset(tr)
			if gen ~= SC.gen or not PACK.alive then
				return
			end
			if not asset then
				local msg = ({
					executor = "Your executor has no writefile/getcustomasset.",
					unavailable = "Track unavailable.",
					download = "Download failed.",
					client = "Could not reach SoundCloud.",
				})[err] or "Could not play the track."
				setStatus("SoundCloud: " .. msg)
				note("SoundCloud", msg)
				return
			end
			local snd = Instance.new("Sound")
			snd.Name = "FVLSoundCloud"
			snd.SoundId = asset
			snd.Volume = SC.vol / 100
			snd.Looped = SC.loop
			snd.Parent = SoundService
			SC.snd = snd
			SC.cur = { index = idx, track = tr }
			snd.Ended:Connect(function()
				if gen ~= SC.gen or not PACK.alive then
					return
				end
				if SC.loop then
					return
				end
				if SC.auto then
					playNext(1)
				else
					setStatus("SoundCloud: finished")
				end
			end)
			snd:Play()
			setStatus("Playing: " .. stripCtl(tr.title) .. " - " .. stripCtl(tr.artist))
		end)
	end

	stopSC = function()
		SC.gen += 1
		if SC.snd then
			pcall(function()
				SC.snd:Destroy()
			end)
			SC.snd = nil
		end
		SC.cur = nil
		setStatus("SoundCloud: stopped")
	end

	local function runSearch(query)
		query = tostring(query or ""):gsub("^%s+", ""):gsub("%s+$", "")
		if query == "" then
			note("SoundCloud", "Type something in the search box first.")
			return
		end
		if SC.busy then
			return
		end
		SC.busy = true
		setStatus("Searching...")
		task.spawn(function()
			local list = {}
			local failed
			if query:find("soundcloud%.com/") then
				local data, err = scApi("/resolve", "url=" .. HttpSvc:UrlEncode(query))
				if data and data.kind == "track" then
					list[1] = normTrack(data)
				elseif data and data.kind == "playlist" and type(data.tracks) == "table" then
					local missing = {}
					for _, t in ipairs(data.tracks) do
						local nt = normTrack(t)
						if nt then
							list[#list + 1] = nt
						elseif type(t) == "table" and t.id and #missing < 30 then
							missing[#missing + 1] = tostring(t.id)
						end
					end
					if #missing > 0 then
						local more = scApi("/tracks", "ids=" .. table.concat(missing, ","))
						if type(more) == "table" then
							for _, t in ipairs(more) do
								local nt = normTrack(t)
								if nt then
									list[#list + 1] = nt
								end
							end
						end
					end
				else
					failed = err or "unsupported link"
				end
			else
				local data, err = scApi("/search/tracks", "q=" .. HttpSvc:UrlEncode(query) .. "&limit=25")
				if data and type(data.collection) == "table" then
					for _, t in ipairs(data.collection) do
						local nt = normTrack(t)
						if nt then
							list[#list + 1] = nt
						end
					end
				else
					failed = err or "no data"
				end
			end
			SC.busy = false
			if not PACK.alive then
				return
			end
			if #list == 0 then
				setStatus("SoundCloud: no results" .. (failed and (" (" .. tostring(failed) .. ")") or ""))
				note("SoundCloud", "No results.")
				return
			end
			setResults(list)
			setStatus("SoundCloud: " .. #list .. " result(s) - pick one and press Play")
		end)
	end

	tbl43.visuals:Section({ Title = "SoundCloud" })

	statusLabel = tbl43.visuals:Label({ Text = "SoundCloud: nothing playing" })

	tbl43.visuals:Input({
		Title = "Search / SoundCloud Link",
		Flag = "Input_SC_Query",
		Desc = "Type a song name or paste a SoundCloud track/playlist link, then press Search.",
		Placeholder = "Search SoundCloud or paste a link",
		Default = "",
		Callback = function(v)
			SC.query = tostring(v or "")
		end,
	})

	tbl43.visuals:Button({
		Title = "Search",
		Icon = "search",
		Callback = function()
			runSearch(SC.query)
		end,
	})

	resultsDropdown = tbl43.visuals:Dropdown({
		Title = "Results",
		Flag = "Dropdown_SC_Results",
		Desc = "Pick a track, then press Play Selected.",
		Multi = false,
		Value = "(search first)",
		Values = { "(search first)" },
		Callback = function(v)
			local n = tonumber(tostring(v or ""):match("^(%d+)%."))
			if n and SC.results[n] then
				SC.sel = n
			end
		end,
	})

	tbl43.visuals:Button({
		Title = "Play Selected",
		Icon = "play",
		Callback = function()
			playIndex(SC.sel or 1)
		end,
	})

	tbl43.visuals:Button({
		Title = "Pause / Resume",
		Icon = "pause",
		Callback = function()
			local snd = SC.snd
			if not snd then
				return
			end
			if snd.IsPaused then
				snd:Resume()
			else
				snd:Pause()
			end
		end,
	})

	tbl43.visuals:Button({
		Title = "Next Track",
		Icon = "skip-forward",
		Callback = function()
			playNext(1)
		end,
	})

	tbl43.visuals:Button({
		Title = "Previous Track",
		Icon = "skip-back",
		Callback = function()
			playNext(-1)
		end,
	})

	tbl43.visuals:Button({
		Title = "Stop",
		Icon = "square",
		Callback = function()
			stopSC()
		end,
	})

	tbl43.visuals:Slider({
		Title = "SoundCloud Volume",
		Flag = "Slider_SC_Volume",
		Min = 0,
		Max = 100,
		Value = 60,
		Step = 1,
		Suffix = "%",
		Callback = function(v)
			SC.vol = tonumber(v) or 60
			if SC.snd then
				SC.snd.Volume = SC.vol / 100
			end
		end,
	})

	tbl43.visuals:Toggle({
		Title = "Repeat Track",
		Flag = "Toggle_SC_Loop",
		Desc = "Loops the current song.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			SC.loop = v == true
			if SC.snd then
				SC.snd.Looped = SC.loop
			end
		end,
	})

	tbl43.visuals:Toggle({
		Title = "Autoplay Next",
		Flag = "Toggle_SC_Auto",
		Desc = "Plays the next result when a song ends.",
		Type = "Toggle",
		Value = true,
		Callback = function(v)
			SC.auto = v == true
		end,
	})


	obj3:OnDestroy(function()
		SC.gen += 1
		if SC.snd then
			pcall(function()
				SC.snd:Destroy()
			end)
		end
		pcall(function()
			if type(listfiles) == "function" and type(delfile) == "function" and isfolder(SC.dir) then
				for _, f in ipairs(listfiles(SC.dir)) do
					pcall(delfile, f)
				end
			end
		end)
	end)
	end

	obj3:OnDestroy(function()
		PACK.alive = false
		for _, c in ipairs(PACK.conns) do
			pcall(function()
				c:Disconnect()
			end)
		end
	end)
end

-- ===================== FARM PACK: Webhook extras / Crates / Anti Coin Leak / Role Actions + Prestige =====================
-- (ported from the other hub. Webhook, box opening and prestige already existed here in part, so this adds what was
--  missing: Disconnect Alert + report-now, a dynamic Crates module, the Anti Coin Leak guard and the Role Actions farm.)
do
	local Players = game:GetService("Players")
	local RepStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")
	local GuiService = game:GetService("GuiService")
	local lp = Players.LocalPlayer

	local FP = { alive = true, conns = {} }

	local function track(conn)
		FP.conns[#FP.conns + 1] = conn
		return conn
	end

	local function note(title, text)
		pcall(function()
			list2.notifyNow({ Title = title, Content = text, Duration = 4 })
		end)
	end

	local function comma(n)
		local ok, res = pcall(list2.comma, n)
		return ok and res or tostring(n)
	end

	-- =================================================================== FARM WEBHOOK EXTRAS
	do
		local WX = { kick = true, kickAt = 0 }

		local function sendReport(title, body, color)
			list2.whForce = true
			local ok, res, code = pcall(list2.whFarmEmbed, title, body, color, true)
			list2.whForce = false
			return ok and res == true, ok and code or res
		end

		local function onDisconnect(reason)
			if not WX.kick or not FP.alive then
				return
			end
			if os.clock() - WX.kickAt < 60 then
				return
			end
			WX.kickAt = os.clock()
			local text = tostring(reason or "Connection lost"):sub(1, 300)
			task.spawn(function()
				pcall(sendReport, utf8.char(10060) .. " Disconnected", "**Reason** " .. text, 15158332)
			end)
		end

		track(GuiService.ErrorMessageChanged:Connect(function(msg)
			if type(msg) == "string" and msg ~= "" then
				onDisconnect(msg)
			end
		end))

		-- the "You were kicked / disconnected" prompt that Roblox puts into CoreGui
		task.spawn(function()
			local overlay
			pcall(function()
				local cg = game:GetService("CoreGui")
				local pg = cg:WaitForChild("RobloxPromptGui", 20)
				overlay = pg and pg:WaitForChild("promptOverlay", 20)
			end)
			if not overlay or not FP.alive then
				return
			end
			track(overlay.ChildAdded:Connect(function(child)
				if child.Name ~= "ErrorPrompt" then
					return
				end
				task.wait(0.2)
				local reason = "disconnected"
				pcall(function()
					local msg = child:FindFirstChild("MessageArea", true)
					msg = msg and msg:FindFirstChild("ErrorFrame", true)
					local label = msg and msg:FindFirstChild("ErrorMessage", true)
					if label and label.Text ~= "" then
						reason = label.Text
					end
				end)
				onDisconnect(reason)
			end))
		end)

		tbl43.farm:Section({ Title = "Webhook Extras" })

		tbl43.farm:Toggle({
			Title = "Disconnect Alert",
			Flag = "Toggle_Webhook_Disconnect",
			Desc = "Posts to your Discord webhook when you get kicked or disconnected. Needs the Webhook URL above.",
			Type = "Toggle",
			Value = true,
			Callback = function(v)
				WX.kick = v == true
			end,
		})

		tbl43.farm:Button({
			Title = "Send Farm Report Now",
			Desc = "Posts the current farm stats (balance, rate, farmed this session) to the webhook right away.",
			Callback = function()
				task.spawn(function()
					local ok, info = sendReport(utf8.char(128202) .. " Auto Farm Report", "Manual report.", 16753920)
					note(ok and "Report Sent" or "Report Failed", ok and "Posted to your webhook." or ("Could not post: " .. tostring(info)))
				end)
			end,
		})
	end

	-- =================================================================== CRATES
	do
		local C = { on = false, opened = 0, state = "Off", busy = false, id = "Halloween2026Box", pay = "Auto", delay = 1, anim = false, lastName = nil, lastRarity = nil }

		local CURRENCY_NAME = { Candies2026 = "Candies", HalloweenKey2026 = "Halloween Key", Coins = "Coins", Key = "Key", Gems = "Gems" }
		local PAY_ORDER = { "HalloweenKey2026", "Key", "Candies2026", "Coins" }
		local RARE = { Legendary = true, Godly = true, Ancient = true, Unique = true, Vintage = true, Chroma = true }

		local sync, profile
		local function modules()
			if not sync then
				pcall(function()
					sync = require(RepStorage.Database.Sync)
				end)
			end
			if not profile then
				pcall(function()
					profile = require(RepStorage.Modules.ProfileData)
				end)
			end
			return sync, profile
		end

		-- every mystery box that can be bought without Robux
		local function boxList()
			local s = modules()
			local out = {}
			if not s then
				return out
			end
			for id, item in pairs(s.NewShop or {}) do
				if type(item) == "table" and item.Type == "MysteryBox" and type(item.Price) == "table" and item.Price.Robux == nil and next(item.Price) ~= nil then
					local meta = s.MysteryBox and s.MysteryBox[id]
					out[#out + 1] = {
						id = id,
						name = tostring(meta and (meta.ItemName or meta.Name) or id),
						price = item.Price,
						order = tonumber(item.LayoutOrder) or 999,
					}
				end
			end
			if #out == 0 then
				for id, item in pairs(s.Shop and s.Shop.Weapons or {}) do
					local meta = s.MysteryBox and s.MysteryBox[id]
					if meta and type(item) == "table" and type(item.Price) == "table" and item.Price.Robux == nil then
						out[#out + 1] = { id = id, name = tostring(meta.ItemName or meta.Name or id), price = item.Price, order = 999 }
					end
				end
			end
			table.sort(out, function(a, b)
				if a.order ~= b.order then
					return a.order < b.order
				end
				return a.name < b.name
			end)
			return out
		end

		local function boxById(id)
			for _, b in ipairs(boxList()) do
				if b.id == id then
					return b
				end
			end
			return nil
		end

		local function owned(name)
			local _, p = modules()
			if not p then
				return 0
			end
			local v
			pcall(function()
				v = p[name]
			end)
			if type(v) ~= "number" then
				pcall(function()
					v = p.Materials.Owned[name]
				end)
			end
			if type(v) ~= "number" then
				pcall(function()
					v = p.Weapons.Owned[name]
				end)
			end
			return tonumber(v) or 0
		end

		-- which currency pays for this box right now: returns currency, price (or nil, price, wantedCurrency)
		local function payWith(box)
			if not box then
				return nil
			end
			if C.pay ~= "Auto" then
				local price = box.price[C.pay]
				if price and owned(C.pay) >= price then
					return C.pay, price
				end
				return nil, price, C.pay
			end
			local first
			for _, cur in ipairs(PAY_ORDER) do
				local price = box.price[cur]
				if price then
					first = first or cur
					if owned(cur) >= price then
						return cur, price
					end
				end
			end
			return nil, nil, first
		end

		local function itemInfo(itemId)
			local s = modules()
			local w = s and s.Weapons and s.Weapons[itemId]
			return tostring(w and (w.ItemName or w.Name) or itemId), w and w.Rarity or nil
		end

		local function openOnce()
			local box = boxById(C.id)
			if not box then
				C.state = "Off"
				return false
			end
			local cur, price = payWith(box)
			if not cur then
				C.state = "Not enough"
				return false
			end
			C.state = "Opening"
			local shop = RepStorage:FindFirstChild("Remotes") and RepStorage.Remotes:FindFirstChild("Shop")
			local remote = shop and shop:FindFirstChild("OpenCrate")
			if not remote then
				C.state = "Off"
				return false
			end
			local ok, result = pcall(function()
				return remote:InvokeServer(box.id, "MysteryBox", cur)
			end)
			if not ok or not result then
				C.state = "Not enough"
				return false
			end
			C.opened += 1
			local name, rarity = itemInfo(result)
			C.lastName, C.lastRarity = name, rarity
			if C.anim then
				pcall(function()
					local controller = shop:FindFirstChild("BoxController")
					if controller then
						controller:Fire({ { MysteryBoxId = box.id, RewardedItemId = result } })
					end
				end)
			end
			if rarity and RARE[tostring(rarity)] then
				note(tostring(rarity) .. " drop", name)
			end
			return true
		end

		task.spawn(function()
			while FP.alive do
				if C.on and not C.busy then
					C.busy = true
					local ok, result = pcall(openOnce)
					C.busy = false
					if ok and result then
						task.wait(math.clamp(tonumber(C.delay) or 1, 0.5, 10))
					else
						task.wait(2.5)
					end
				else
					if not C.on and not C.busy then
						C.state = "Off"
					end
					task.wait(0.3)
				end
			end
		end)

		local function boxNames()
			local names, byName = {}, {}
			for _, b in ipairs(boxList()) do
				local label = b.name
				if byName[label] then
					label = label .. " (" .. b.id .. ")"
				end
				byName[label] = b.id
				names[#names + 1] = label
			end
			if #names == 0 then
				names[1] = "Halloween Box '26"
				byName["Halloween Box '26"] = "Halloween2026Box"
			end
			return names, byName
		end

		local names, byName = boxNames()
		local boxDropdown, statusLabel
		C.id = byName[names[1]] or C.id

		tbl43.farm:Section({ Title = "Crates" })

		statusLabel = tbl43.farm:Label({ Text = "Crates: idle" })

		boxDropdown = tbl43.farm:Dropdown({
			Title = "Box",
			Flag = "Dropdown_Crates_Box",
			Desc = "Which box to open. Press Refresh Boxes if the list is empty or a new box appeared.",
			Multi = false,
			Value = names[1],
			Values = names,
			Callback = function(v)
				local id = byName[tostring(v)]
				if id then
					C.id = id
				end
			end,
		})

		tbl43.farm:Button({
			Title = "Refresh Boxes",
			Icon = "refresh-cw",
			Callback = function()
				names, byName = boxNames()
				pcall(function()
					boxDropdown:Refresh(names, false)
					boxDropdown:Set(names[1], false)
				end)
				note("Crates", #names .. " box(es) found.")
			end,
		})

		tbl43.farm:Dropdown({
			Title = "Crate Pay With",
			Flag = "Dropdown_Crates_Pay",
			Desc = "Auto tries Halloween Key, Key, Candies, then Coins, whichever you can afford.",
			Multi = false,
			Value = "Auto",
			Values = { "Auto", "Candies2026", "HalloweenKey2026", "Coins", "Key", "Gems" },
			Callback = function(v)
				C.pay = tostring(v or "Auto")
			end,
		})

		tbl43.farm:Slider({
			Title = "Crate Open Delay",
			Flag = "Slider_Crates_Delay",
			Min = 0.5,
			Max = 5,
			Value = 1,
			Step = 0.1,
			Suffix = " s",
			Callback = function(v)
				C.delay = tonumber(v) or 1
			end,
		})

		tbl43.farm:Toggle({
			Title = "Crate Show Animation",
			Flag = "Toggle_Crates_Anim",
			Desc = "Plays the game's box opening animation for each box.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				C.anim = v == true
			end,
		})

		tbl43.farm:Toggle({
			Title = "Crate Auto Open",
			Flag = "Toggle_Crates_Auto",
			Desc = "Keeps opening the selected box while you can afford it.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				C.on = v == true
			end,
		})

		tbl43.farm:Button({
			Title = "Open Crate Once",
			Icon = "package-open",
			Callback = function()
				if C.busy then
					return
				end
				task.spawn(function()
					C.busy = true
					pcall(openOnce)
					C.busy = false
				end)
			end,
		})

		task.spawn(function()
			while FP.alive do
				task.wait(0.5)
				pcall(function()
					local box = boxById(C.id)
					local cur, _, want = payWith(box)
					cur = cur or want
					local balance = cur and (comma(math.floor(owned(cur))) .. " " .. (CURRENCY_NAME[cur] or cur)) or "-"
					local last = C.lastName and (C.lastName .. (C.lastRarity and (" [" .. tostring(C.lastRarity) .. "]") or "")) or "-"
					statusLabel:Set(string.format("Opened: %d   Status: %s   Balance: %s   Last: %s", C.opened, C.state, balance, last))
				end)
			end
		end)

		obj3:OnDestroy(function()
			C.on = false
		end)
	end

	-- =================================================================== ANTI COIN LEAK
	do
		local AC = { on = false, n = 0, leaks = 0, strict = false }
		local workspaceSvc = game:GetService("Workspace")
		local coinTouch = setmetatable({}, { __mode = "k" })
		local selfTouch = setmetatable({}, { __mode = "k" })

		local function disableCoin(part)
			if not part:IsA("BasePart") then
				return
			end
			if coinTouch[part] == nil then
				coinTouch[part] = part.CanTouch
			end
			if part.CanTouch then
				part.CanTouch = false
				AC.n += 1
			end
		end

		local function sweepCoins()
			for _, child in ipairs(workspaceSvc:GetChildren()) do
				local container = child:FindFirstChild("CoinContainer")
				if container then
					for _, coin in ipairs(container:GetChildren()) do
						pcall(disableCoin, coin)
					end
				end
			end
		end

		-- strict mode: even your own body stops touching things
		local function lockSelf()
			local char = lp.Character
			if not char then
				return
			end
			for _, part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") then
					if selfTouch[part] == nil then
						selfTouch[part] = part.CanTouch
					end
					if part.CanTouch then
						pcall(function()
							part.CanTouch = false
						end)
					end
				end
			end
		end

		local function restore()
			for part, can in pairs(coinTouch) do
				if part.Parent then
					pcall(function()
						part.CanTouch = can
					end)
				end
				coinTouch[part] = nil
			end
			for part, can in pairs(selfTouch) do
				if part.Parent then
					pcall(function()
						part.CanTouch = can
					end)
				end
				selfTouch[part] = nil
			end
			AC.strict = false
		end

		track(workspaceSvc.DescendantAdded:Connect(function(inst)
			if not AC.on then
				return
			end
			local parent = inst.Parent
			if parent and parent.Name == "CoinContainer" then
				pcall(disableCoin, inst)
			end
		end))

		track(lp.CharacterAdded:Connect(function()
			if not AC.on or not AC.strict then
				return
			end
			task.wait(0.5)
			pcall(lockSelf)
		end))

		-- a coin still got collected: switch to strict mode
		task.spawn(function()
			local remote
			while FP.alive and not remote do
				local rem = RepStorage:FindFirstChild("Remotes")
				local gp = rem and rem:FindFirstChild("Gameplay")
				remote = gp and gp:FindFirstChild("CoinCollected")
				if not remote then
					task.wait(1)
				end
			end
			if not remote then
				return
			end
			track(remote.OnClientEvent:Connect(function()
				if not AC.on then
					return
				end
				AC.leaks += 1
				if not AC.strict then
					AC.strict = true
					pcall(lockSelf)
					note("Anti Coin Leak", "A coin leaked through - strict mode is on.")
				end
			end))
		end)

		task.spawn(function()
			while FP.alive do
				task.wait(0.5)
				if AC.on then
					pcall(sweepCoins)
					if AC.strict then
						pcall(lockSelf)
					end
				end
			end
		end)

		tbl43.farm:Section({ Title = "Anti Coin Leak" })

		tbl43.farm:Toggle({
			Title = "Anti Coin Leak",
			Flag = "Toggle_AntiCoinLeak",
			Desc = "Makes the round coins untouchable so you never pick one up by accident. If one still gets collected, strict mode also disables touching on your own character.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				AC.on = v == true
				if AC.on then
					pcall(sweepCoins)
				else
					restore()
				end
			end,
		})

		obj3:OnDestroy(function()
			AC.on = false
			restore()
		end)
	end

	-- =================================================================== ROLE ACTIONS + PRESTIGE
	do
		local RF = {
			on = { inno = false, sheriff = false, murder = false, exp = false },
			state = "Off",
			role = nil,
			drops = {},
			hooked = false,
			holding = false,
			acted = false,
			wins = 0,
			kills = 0,
			seen = {},
			flung = setmetatable({}, { __mode = "k" }),
			flingWait = 0,
			lastShot = 0,
			target = nil,
		}

		-- who wins the round for which role (to count your wins)
		local WIN = {
			Innocent = { MurdererDied = true, MurdererLeft = true, Time = true, InnocentsEscaped = true },
			Hero = { MurdererLeft = true, Time = true, MurdererDied = true },
			Sheriff = { SheriffWin = true, MurdererDied = true, MurdererLeft = true },
			Murderer = { MurdererWin = true },
		}

		local KPARTS = { "HumanoidRootPart", "UpperTorso", "Torso", "LowerTorso", "Head" }

		local function hrp()
			local c = lp.Character
			return c and c:FindFirstChild("HumanoidRootPart")
		end

		local function hum()
			local c = lp.Character
			return c and c:FindFirstChildOfClass("Humanoid")
		end

		local function isAlive()
			local h = hum()
			return h ~= nil and h.Health > 0
		end

		local function mine()
			local data = list2.liveData
			if type(data) ~= "table" then
				return nil, {}
			end
			local rec = data[lp.Name]
			if type(rec) ~= "table" or not rec.Role or rec.Dead == true or rec.Killed == true then
				return nil, data
			end
			return tostring(rec.Role), data
		end

		local function lobbyCF()
			local lobby = workspace:FindFirstChild("RegularLobby") or workspace:FindFirstChild("Lobby")
			if not lobby then
				return nil
			end
			local spawns = lobby:FindFirstChild("Spawns")
			local part = (spawns and spawns:FindFirstChildWhichIsA("BasePart")) or lobby:FindFirstChildWhichIsA("SpawnLocation", true)
			return part and part.CFrame + Vector3.new(0, 4, 0) or nil
		end

		local function inLobby()
			local root, cf = hrp(), lobbyCF()
			return root ~= nil and cf ~= nil and (root.Position - cf.Position).Magnitude < 300
		end

		local function toLobby()
			if inLobby() then
				return true
			end
			local root, cf = hrp(), lobbyCF()
			if not (root and cf) then
				return false
			end
			pcall(function()
				root.AssemblyLinearVelocity = Vector3.zero
				root.AssemblyAngularVelocity = Vector3.zero
				root.CFrame = cf
			end)
			return true
		end

		-- first living player whose role name contains `pattern`
		local function who(data, pattern)
			for name, rec in pairs(data) do
				if type(rec) == "table" and rec.Role and rec.Dead ~= true and rec.Killed ~= true and tostring(rec.Role):lower():find(pattern) then
					local plr = Players:FindFirstChild(name)
					local char = plr and plr ~= lp and plr.Character
					local h = char and char:FindFirstChildOfClass("Humanoid")
					if h and h.Health > 0 then
						return plr, char
					end
				end
			end
			return nil, nil
		end

		local function findGun()
			local c = lp.Character
			local g = c and c:FindFirstChild("Gun")
			if g then
				return g, true
			end
			local bp = lp:FindFirstChildOfClass("Backpack")
			return bp and bp:FindFirstChild("Gun"), false
		end

		local function shootMurderer(data)
			local plr = who(data, "murder")
			if not plr then
				return false
			end
			local gun, inHand = findGun()
			if not gun then
				return false
			end
			if not inHand then
				local h = hum()
				if h then
					pcall(function()
						h:EquipTool(gun)
					end)
				end
				return true
			end
			local remote = gun:FindFirstChild("Shoot")
			if not (remote and remote:IsA("RemoteEvent") and list2.saShoot) then
				return false
			end
			if os.clock() - RF.lastShot < 1 then
				return true
			end
			RF.lastShot = os.clock()
			RF.target = plr.Name
			pcall(list2.saShoot, remote, lp.Character, plr, { wallbang = list2.wallbang })
			return true
		end

		local function getKnife()
			local c = lp.Character
			local k = c and c:FindFirstChild("Knife")
			if k then
				return k
			end
			local bp = lp:FindFirstChildOfClass("Backpack")
			local tool = bp and bp:FindFirstChild("Knife")
			local h = hum()
			if tool and tool:IsA("Tool") and h then
				pcall(function()
					h:EquipTool(tool)
				end)
			end
			return c and c:FindFirstChild("Knife")
		end

		local function stabAll(data)
			local knife = getKnife()
			if not (knife and firetouchinterest) then
				return 0
			end
			local handle = knife:FindFirstChild("Handle") or knife:FindFirstChildWhichIsA("BasePart")
			if not handle then
				return 0
			end
			local count = 0
			for _, plr in ipairs(Players:GetPlayers()) do
				local rec = plr ~= lp and data[plr.Name]
				if type(rec) == "table" and rec.Dead ~= true and rec.Killed ~= true then
					local char = plr.Character
					local h = char and char:FindFirstChildOfClass("Humanoid")
					if h and h.Health > 0 then
						count += 1
						for _, partName in ipairs(KPARTS) do
							local part = char:FindFirstChild(partName)
							if part then
								pcall(function()
									firetouchinterest(handle, part, 0)
									firetouchinterest(handle, part, 1)
									firetouchinterest(part, handle, 0)
									firetouchinterest(part, handle, 1)
								end)
							end
						end
					end
				end
			end
			if count > 0 then
				pcall(function()
					knife:Activate()
				end)
			end
			return count
		end

		local function hookDrops()
			if RF.hooked then
				return
			end
			RF.hooked = true
			track(workspace.DescendantAdded:Connect(function(inst)
				if inst.Name == "GunDrop" and inst:IsA("BasePart") then
					table.insert(RF.drops, inst)
				end
			end))
			for _, inst in ipairs(workspace:GetDescendants()) do
				if inst.Name == "GunDrop" and inst:IsA("BasePart") then
					table.insert(RF.drops, inst)
				end
			end
		end

		local function currentDrop()
			for i = #RF.drops, 1, -1 do
				local d = RF.drops[i]
				if d.Parent and d:IsDescendantOf(workspace) then
					return d
				end
				table.remove(RF.drops, i)
			end
			return nil
		end

		local function touchWith(part)
			local char = lp.Character
			if not (char and part and firetouchinterest) then
				return
			end
			for _, inst in ipairs(char:GetChildren()) do
				if inst:IsA("BasePart") then
					pcall(function()
						firetouchinterest(inst, part, 0)
						firetouchinterest(inst, part, 1)
					end)
				end
			end
		end

		local function grabGun()
			local drop = currentDrop()
			if not drop then
				return false
			end
			local t0 = os.clock()
			while os.clock() - t0 < 0.6 and drop.Parent and not findGun() and isAlive() do
				touchWith(drop)
				RunService.Heartbeat:Wait()
			end
			if findGun() then
				return true
			end
			if not drop.Parent then
				return false
			end
			local root = hrp()
			if not root then
				return false
			end
			t0 = os.clock()
			while os.clock() - t0 < 1.2 and drop.Parent and not findGun() and isAlive() do
				pcall(function()
					root.AssemblyLinearVelocity = Vector3.zero
					root.CFrame = CFrame.new(drop.Position + Vector3.new(0, 2.5, 0))
				end)
				touchWith(drop)
				RunService.Heartbeat:Wait()
			end
			local got = findGun() ~= nil
			toLobby()
			return got
		end

		local function flingPlayer(plr)
			if flag33 then
				return false
			end
			pcall(func27, plr)
			task.wait(0.15)
			local t0 = os.clock()
			while flag33 and os.clock() - t0 < 12 and FP.alive do
				task.wait(0.1)
			end
			return true
		end

		local function hold(v)
			v = v and true or false
			if v then
				RF.acted = true
			end
			RF.holding = v
		end

		-- count kills for the stats: somebody we had seen alive is now dead
		local function countKills(data)
			for name, rec in pairs(data) do
				if name ~= lp.Name and type(rec) == "table" then
					if rec.Dead == true or rec.Killed == true then
						if RF.seen[name] then
							RF.seen[name] = nil
							if RF.state == "Killing" then
								RF.kills += 1
							elseif RF.state == "Shooting" and RF.target == name then
								RF.kills += 1
							end
						end
					else
						RF.seen[name] = true
					end
				end
			end
		end

		local function expInnocent(data)
			if findGun() then
				toLobby()
				RF.state = "Shooting"
				shootMurderer(data)
				return
			end
			local sheriff = who(data, "sheriff") or who(data, "hero")
			if sheriff and os.clock() >= RF.flingWait and (RF.flung[sheriff] or 0) < 4 then
				RF.flung[sheriff] = (RF.flung[sheriff] or 0) + 1
				RF.state = "Flinging"
				local ok = flingPlayer(sheriff)
				RF.flingWait = os.clock() + (ok and 2.5 or 0.5)
				toLobby()
				return
			end
			if currentDrop() then
				RF.state = "Picking Gun"
				grabGun()
				return
			end
			toLobby()
			RF.state = "Surviving"
		end

		local function step()
			local s = RF.on
			if not (s.inno or s.sheriff or s.murder or s.exp) then
				RF.state, RF.role = "Off", nil
				hold(false)
				return
			end
			hookDrops()
			local role, data = mine()
			RF.role = role
			if not role or not isAlive() then
				RF.state = "Waiting"
				hold(false)
				if not role then
					table.clear(RF.seen)
				end
				return
			end
			countKills(data)
			local low = role:lower()
			if low:find("murder") then
				if s.murder or s.exp then
					hold(true)
					RF.state = "Killing"
					stabAll(data)
					return
				end
			elseif low == "sheriff" then
				if s.sheriff or s.exp then
					hold(true)
					toLobby()
					RF.state = "Shooting"
					shootMurderer(data)
					return
				end
			elseif low == "hero" then
				if s.exp then
					hold(true)
					toLobby()
					RF.state = "Shooting"
					shootMurderer(data)
					return
				elseif s.inno then
					hold(true)
					toLobby()
					RF.state = "Surviving"
					return
				end
			elseif s.exp then
				hold(true)
				expInnocent(data)
				return
			elseif s.inno then
				hold(true)
				toLobby()
				RF.state = "Surviving"
				return
			end
			hold(false)
			RF.state = "Waiting"
		end

		task.spawn(function()
			while FP.alive do
				task.wait(0.1)
				local ok, err = pcall(step)
				if not ok then
					task.wait(1)
				end
			end
			hold(false)
		end)

		task.spawn(function()
			local rem = RepStorage:WaitForChild("Remotes", 30)
			rem = rem and rem:WaitForChild("Gameplay", 30)
			local vs = rem and rem:WaitForChild("VictoryScreen", 30)
			if not vs or not FP.alive then
				return
			end
			track(vs.OnClientEvent:Connect(function(_, role, reason)
				local entry = WIN[tostring(role)]
				if RF.acted and entry and entry[tostring(reason)] == true then
					RF.wins += 1
				end
				RF.acted = false
			end))
		end)

		-- ---- prestige (its own module: level / prestige readout + manual and automatic prestige)
		local PR = { on = false, last = 0, done = 0 }
		local ROMAN = { [0] = "0", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X" }

		local function levelAndPrestige()
			if PR.pd == nil then
				PR.pd = false
				pcall(function()
					local mods = RepStorage:WaitForChild("Modules", 5)
					PR.lm = require(mods:WaitForChild("LevelModule", 5))
					PR.pd = require(mods:WaitForChild("ProfileData", 5))
				end)
			end
			if not PR.pd or not PR.lm then
				return nil, nil
			end
			local ok, level = pcall(PR.lm.GetLevel, PR.pd.NewXP)
			return ok and tonumber(level) or nil, tonumber(PR.pd.Prestige) or 0
		end

		local function firePrestige()
			local rem = RepStorage:FindFirstChild("Remotes")
			local inv = rem and rem:FindFirstChild("Inventory")
			local ev = inv and inv:FindFirstChild("Prestige")
			if ev and ev:IsA("RemoteEvent") then
				PR.last = os.clock()
				ev:FireServer()
				PR.done += 1
				return true
			end
			return false
		end

		task.spawn(function()
			while FP.alive do
				task.wait(2)
				pcall(function()
					local level, pres = levelAndPrestige()
					if not level then
						return
					end
					PR.level, PR.pres = level, pres
					if PR.on and level >= 100 and pres < 10 and os.clock() - PR.last > 15 then
						firePrestige()
					end
				end)
			end
		end)

		tbl43.farm:Section({ Title = "Role Actions" })

		local roleLabel = tbl43.farm:Label({ Text = "Role: -   Status: Off" })

		tbl43.farm:Toggle({
			Title = "Innocent Win Farm",
			Flag = "Toggle_RoleFarm_Innocent",
			Desc = "As innocent (or hero) you wait safely in the lobby until the round ends.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				RF.on.inno = v == true
			end,
		})

		tbl43.farm:Toggle({
			Title = "Sheriff Win Farm",
			Flag = "Toggle_RoleFarm_Sheriff",
			Desc = "As sheriff you shoot the murderer from the lobby.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				RF.on.sheriff = v == true
			end,
		})

		tbl43.farm:Toggle({
			Title = "Murderer Kill Farm",
			Flag = "Toggle_RoleFarm_Murderer",
			Desc = "As murderer you stab every living player with your knife.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				RF.on.murder = v == true
			end,
		})

		tbl43.farm:Toggle({
			Title = "EXP Farm",
			Flag = "Toggle_RoleFarm_EXP",
			Desc = "Plays every role for you. As innocent it flings the sheriff, grabs the dropped gun and shoots the murderer. Don't run it together with the Coin Autofarm.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				RF.on.exp = v == true
			end,
		})

		tbl43.farm:Section({ Title = "Prestige" })

		local presLabel = tbl43.farm:Label({ Text = "Level: -   Prestige: -" })

		tbl43.farm:Toggle({
			Title = "Role Auto Prestige",
			Flag = "Toggle_RoleFarm_AutoPrestige",
			Desc = "Prestiges as soon as you reach level 100 (up to prestige X).",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				PR.on = v == true
			end,
		})

		tbl43.farm:Button({
			Title = "Prestige Now",
			Icon = "crown",
			Callback = function()
				local level, pres = levelAndPrestige()
				if not level then
					note("Prestige", "Could not read your level.")
				elseif level < 100 then
					note("Prestige", "You need level 100 (you are level " .. level .. ").")
				elseif pres >= 10 then
					note("Prestige", "You are already at the highest prestige.")
				elseif firePrestige() then
					note("Prestige", "Prestige requested.")
				else
					note("Prestige", "The prestige remote was not found.")
				end
			end,
		})

		task.spawn(function()
			while FP.alive do
				task.wait(0.5)
				pcall(function()
					roleLabel:Set(string.format("Role: %s   Status: %s   Wins: %d   Kills: %d", RF.role or "-", RF.state, RF.wins, RF.kills))
					if PR.level then
						presLabel:Set(string.format("Level: %d   Prestige: %s   Prestiged this session: %d", PR.level, ROMAN[PR.pres or 0] or tostring(PR.pres), PR.done))
					end
				end)
			end
		end)

		obj3:OnDestroy(function()
			RF.on.inno, RF.on.sheriff, RF.on.murder, RF.on.exp = false, false, false, false
			PR.on = false
			hold(false)
		end)
	end

	obj3:OnDestroy(function()
		FP.alive = false
		for _, c in ipairs(FP.conns) do
			pcall(function()
				c:Disconnect()
			end)
		end
	end)
end

-- ===== Lobby / Map warp =====
do
	local returnCFrame = nil -- where we were in the map before warping to the lobby

	local function notify(title, content, ok)
		pcall(function()
			obj2:Notify({ Title = title, Content = content, Duration = 1.5, Icon = ok and "check" or "x" })
		end)
	end

	local function getRoot()
		local char = localPlayer.Character
		return char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
	end

	-- turn Part / Model / Folder into a CFrame we can stand on
	local function cframeOf(inst)
		if not inst then
			return nil
		end

		if inst:IsA("BasePart") then
			return inst.CFrame * CFrame.new(0, inst.Size.Y / 2 + 4, 0)
		end

		if inst:IsA("Model") then
			local ok, pivot = pcall(function()
				return inst:GetPivot()
			end)
			if ok then
				return pivot * CFrame.new(0, 4, 0)
			end
		end

		for _, d in ipairs(inst:GetDescendants()) do
			if d:IsA("BasePart") then
				return d.CFrame * CFrame.new(0, d.Size.Y / 2 + 4, 0)
			end
		end
	end

	-- lobby target: workspace.Lobby.Spawns (pick one of the spawn parts)
	local function lobbyCFrame()
		local lobbyFolder = Workspace:FindFirstChild("Lobby")
		local spawns = lobbyFolder and lobbyFolder:FindFirstChild("Spawns")
		if not spawns then
			return nil
		end

		if spawns:IsA("BasePart") then
			return cframeOf(spawns)
		end

		local parts = {}
		for _, d in ipairs(spawns:GetDescendants()) do
			if d:IsA("BasePart") then
				parts[#parts + 1] = d
			end
		end

		if #parts > 0 then
			return cframeOf(parts[math.random(1, #parts)])
		end

		return cframeOf(spawns)
	end

	-- the map of the current round = the model in workspace that has CoinContainer / Spawns
	local function findMap()
		for _, child in ipairs(Workspace:GetChildren()) do
			if child:IsA("Model") and child.Name ~= "RegularLobby" and child.Name ~= "Lobby"
				and (child:FindFirstChild("CoinContainer") or child:FindFirstChild("CoinAreas") or child:FindFirstChild("Spawns")) then
				return child
			end
		end
	end

	local function mapCFrame()
		local map = findMap()
		if not map then
			return nil
		end

		local spawns = map:FindFirstChild("Spawns")
		if spawns then
			local parts = {}
			for _, p in ipairs(spawns:GetChildren()) do
				if p:IsA("BasePart") then
					parts[#parts + 1] = p
				end
			end
			if #parts > 0 then
				return cframeOf(parts[math.random(1, #parts)])
			end
		end

		return cframeOf(map)
	end

	local function warp(cf)
		local root = getRoot()
		if not root or not cf then
			return false
		end

		local hum = localPlayer.Character and localPlayer.Character:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.PlatformStand = false
			hum:ChangeState(Enum.HumanoidStateType.GettingUp)
		end

		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
		root.CFrame = cf
		return true
	end

	local function warpLobby()
		local root = getRoot()
		if not root then
			notify("Error!", "Character not loaded!", false)
			return
		end

		local cf = lobbyCFrame()
		if not cf then
			notify("Error!", "Lobby not found!", false)
			return
		end

		-- remember the map position only if we are actually in a round map
		if findMap() and not list2.inLobbyNow() then
			returnCFrame = root.CFrame
		end

		if warp(cf) then
			notify("Teleported!", "Teleported to Lobby", true)
		end
	end

	local function warpMap()
		if not findMap() then
			notify("Error!", "No map loaded - wait for a round to start!", false)
			return
		end

		local cf = returnCFrame or mapCFrame()
		if not cf then
			notify("Error!", "Couldn't find a spot on the map!", false)
			return
		end

		if warp(cf) then
			notify("Teleported!", "Teleported back to the Map", true)
		end
	end

	-- shared with the floating (on-screen) buttons
	list2.warpLobby = warpLobby
	list2.warpMap = warpMap

	tbl43.fling:Section({ Title = "Teleport" })

	tbl43.fling:Button({
		Title = "Teleport to Lobby",
		Desc = "Warp to the lobby",
		Icon = "lucide:home",
		Callback = warpLobby,
	})

	tbl43.fling:Button({
		Title = "Teleport back to Map",
		Desc = "Go back to the map you were playing on (your last spot, or a map spawn)",
		Icon = "lucide:map",
		Callback = warpMap,
	})

	list2.el.tpMurd = tbl43.fling:Button({
		Title = "Teleport to Murderer",
		Desc = "Instantly go to whoever has the knife",
		Icon = "lucide:crosshair",
		Callback = function()
