	-- one embed in the Star Hub style: who you are, balances, rate, what this farm session brought in, runtime
	list2.whFarmEmbed = function(title, body, color, wait)
		if not list2.whReady() then
			return false, "no webhook set"
		end

		local E = utf8.char
		local candy = list2.farmMode == "Candy"
		local coins = list2.readCoins()
		local gems, candies

		pcall(function()
			local owned = list2.readOwned()

			if owned then
				gems = tonumber(owned.Gems)
				candies = tonumber(owned.Candies2026)
			end
		end)

		local _, perHour = list2.farmGetRates()
		local base = list2.whFarmCollected0 or 0

		if list2.farmStats.collected < base then
			base = 0 -- "Reset Stats" was pressed
		end

		local farmed = list2.farmStats.collected - base
		local seconds = list2.whFarmT0 and math.max(0, os.clock() - list2.whFarmT0) or 0
		local runtime

		if seconds >= 3600 then
			runtime = string.format("%dh %dm", math.floor(seconds / 3600), math.floor(seconds % 3600 / 60))
		elseif seconds >= 60 then
			runtime = string.format("%dm %ds", math.floor(seconds / 60), math.floor(seconds % 60))
		else
			runtime = string.format("%ds", math.floor(seconds))
		end

		local gained = coins and list2.whFarmCoins0 and coins > list2.whFarmCoins0 and coins - list2.whFarmCoins0 or nil
		local lvl = list2.readLevel()
		local fld = list2.fld
		local fields = {
			fld(E(128100) .. " Player", "`" .. tostring(game:GetService("Players").LocalPlayer.Name) .. "`"),
			fld(E(11088) .. " Level", "`" .. (lvl and list2.comma(lvl) or "?") .. "`"),
			fld(E(129689) .. " Coins", coins and "**" .. list2.comma(coins) .. "**" or "`?`"),
			fld(E(128142) .. " Gems", "`" .. list2.comma(gems or 0) .. "`"),
			fld(E(128200) .. (candy and " Candies / hour" or " Coins / hour"), "`" .. list2.comma(perHour) .. "`"),
			fld(E(9203) .. " Runtime", "`" .. runtime .. "`"),
		}

		if candy and candies then
			table.insert(fields, 5, fld(E(127852) .. " Candies", "`" .. list2.comma(candies) .. "`"))
		end

		fields = list2.pad3(fields)
		fields[#fields + 1] = fld(
			E(127806) .. " Farmed this session",
			"`" .. list2.comma(farmed) .. "`" .. (gained and "  ( `+" .. list2.comma(gained) .. "` to balance )" or ""),
			false
		)

		return list2.whPost({ title = title, body = body, color = color, fields = fields, wait = wait })
	end

