	-- watcher: farm switched on / off, bag filled up, checkpoint due
	do
		local loopToken = {}
		list2.whFarmLoop = loopToken

		task.spawn(function()
			local E = utf8.char
			local wasOn = list2.farmActive and true or false
			local wasFull = false
			local lastCheckpoint = os.clock()

			local function baseline()
				list2.whFarmT0 = os.clock()
				list2.whFarmCollected0 = list2.farmStats.collected
				list2.whFarmCoins0 = list2.readCoins()
				lastCheckpoint = os.clock()
			end

			if wasOn then
				pcall(baseline)
			end

			while list2.whFarmLoop == loopToken and list2.current() do
				task.wait(1)

				pcall(function()
					local on = list2.farmActive and true or false
					local what = list2.farmMode == "Candy" and "candy" or "coin"

					if on ~= wasOn then
						wasOn = on

						if on then
							baseline()
							list2.whFarmEmbed(E(128994) .. " Farm started", "The " .. what .. " farm is now running.", 3066993)
						else
							list2.whFarmEmbed(E(128308) .. " Farm stopped", "The " .. what .. " farm was switched off.", 15158332)
						end
					end

					if not on then
						wasFull = false
						return
					end

					local full = list2.bagIsFull() and true or false

					if full and not wasFull and list2.whBagFull then
						list2.whFarmEmbed(E(128176) .. " Bag full", "Bag filled up -- cashing in.", 16766720)
					end

					wasFull = full

					if list2.whPeriodic then
						local minutes = math.max(1, tonumber(list2.whInterval) or 10)

						if os.clock() - lastCheckpoint >= minutes * 60 then
							lastCheckpoint = os.clock()
							list2.whFarmEmbed(E(9201) .. " Farm checkpoint", string.format("Still farming -- %d min checkpoint.", minutes), 16758338)
						end
					end
				end)
			end
		end)
	end

