	-- ===================== HALLOWEEN QUEST TRACKER (on-screen quest panel) =====================
	-- Reads the quest list the game already shows in your Halloween event menu and mirrors it in a
	-- small draggable panel: progress bar, 3 goals, rewards and your candy count. Display only.
	-- Drag the panel to move it, drag the little corner handle to resize it.
	do
		local okQT, errQT = pcall(function()
			local TweenService = game:GetService("TweenService")
			local UIS = game:GetService("UserInputService")
			local RepStorage = game:GetService("ReplicatedStorage")
			local PLAYER = game:GetService("Players").LocalPlayer
			local SAVE_FILE = "fvl_quest_panel.txt"
			local CANDY_ICON = "rbxassetid://127192865191352"
			local PUMPKIN_B64 = ""

			local ORANGE = Color3.fromRGB(255, 126, 32)
			local GREY = Color3.fromRGB(168, 149, 179)
			local GREEN = Color3.fromRGB(120, 230, 120)
			local CREAM = Color3.fromRGB(255, 232, 205)
			local WHITE = Color3.fromRGB(246, 238, 250)

			local Q = { on = false, alive = true, list = nil, lastRefresh = 0 }
			local sizeSlider -- set when the UI is built below

			local function pumpkinAsset()
				if type(isfile) == "function" and type(writefile) == "function"
					and type(base64decode) == "function" and type(getcustomasset) == "function" then
					local ok, res = pcall(function()
						local name = "fvl_pill_pumpkin_v1.png"
						if not isfile(name) then
							writefile(name, base64decode(PUMPKIN_B64))
						end
						return getcustomasset(name)
					end)
					if ok and res then
						return res
					end
				end
				return ""
			end

			----------------------------------------------------------------
			-- panel
			----------------------------------------------------------------
			local gui = Instance.new("ScreenGui")
			gui.Name = "FVLQuestTracker"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 90
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			gui.Enabled = false
			gui.Parent = hui

			local fontBold = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold)
			local fontSoft = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Medium)

			local holder = Instance.new("Frame")
			holder.Name = "Holder"
			holder.AnchorPoint = Vector2.new(0.5, 0)
			holder.Position = UDim2.new(0.5, 0, 0, 70)
