			----------------------------------------------------------------
			-- position save / load, size, reset
			----------------------------------------------------------------
			local function savePosition()
				local p = holder.Position
				pcall(function()
					writefile(SAVE_FILE, table.concat({ p.X.Scale, p.X.Offset, p.Y.Scale, p.Y.Offset }, ","))
				end)
			end

			pcall(function()
				if type(isfile) == "function" and isfile(SAVE_FILE) then
					local a, b, c, d = readfile(SAVE_FILE):match("([%-%d%.]+),([%-%d%.]+),([%-%d%.]+),([%-%d%.]+)")
					if a then
						holder.Position = UDim2.new(tonumber(a), tonumber(b), tonumber(c), tonumber(d))
					end
				end
			end)

			local function setSize(pct)
				scale.Scale = math.clamp((tonumber(pct) or 100) / 100, 0.4, 1.8)
			end

			local function resetPosition()
				holder.Position = UDim2.new(0.5, 0, 0, 70)
				pcall(function()
					if type(delfile) == "function" and type(isfile) == "function" and isfile(SAVE_FILE) then
						delfile(SAVE_FILE)
					end
				end)
			end

			----------------------------------------------------------------
			-- drag (move) + corner handle (resize)
			----------------------------------------------------------------
			local function isPointer(input)
				return input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
			end

			local resizing, resizeStartX, resizeStartScale, resizeStartPos = false, 0, 1, nil
			local dragging, dragStart, dragStartPos = false, nil, nil

			local panelConns = {}
			local function track(c)
				panelConns[#panelConns + 1] = c
				return c
			end

			track(handle.InputBegan:Connect(function(input)
				if isPointer(input) then
					resizing = true
					resizeStartX = input.Position.X
					resizeStartScale = scale.Scale
					resizeStartPos = holder.Position
				end
			end))

			track(holder.InputBegan:Connect(function(input)
				if isPointer(input) then
					dragging = true
					dragStart = input.Position
					dragStartPos = holder.Position
				end
			end))

			track(UIS.InputChanged:Connect(function(input)
				if resizing and (input.UserInputType == Enum.UserInputType.MouseMovement
					or input.UserInputType == Enum.UserInputType.Touch) then
					dragging = false
					local s = math.clamp(resizeStartScale + (input.Position.X - resizeStartX) / 340, 0.5, 1.6)
					scale.Scale = s
					holder.Position = UDim2.new(
						resizeStartPos.X.Scale, resizeStartPos.X.Offset + (s - resizeStartScale) * 340 / 2,
						resizeStartPos.Y.Scale, resizeStartPos.Y.Offset
					)
				elseif dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
					or input.UserInputType == Enum.UserInputType.Touch) then
					local delta = input.Position - dragStart
					holder.Position = UDim2.new(
						dragStartPos.X.Scale, dragStartPos.X.Offset + delta.X,
						dragStartPos.Y.Scale, dragStartPos.Y.Offset + delta.Y
					)
				end
			end))

			track(UIS.InputEnded:Connect(function(input)
				if not isPointer(input) then
					return
				end
				if resizing then
					resizing = false
					savePosition()
					if sizeSlider then
						pcall(function()
							sizeSlider:Set(math.floor(scale.Scale * 100 + 0.5), true)
						end)
					end
				elseif dragging then
					dragging = false
					savePosition()
				end
			end))

			----------------------------------------------------------------
			-- reading the game's own quest list
			----------------------------------------------------------------
			local function dig(root, ...)
				for _, name in ipairs({ ... }) do
					root = root and root:FindFirstChild(name)
				end
				return root
			end

			local function textOf(root, ...)
				local o = dig(root, ...)
				return o and o:IsA("TextLabel") and o.Text or ""
			end

			local function findList()
				if Q.list and Q.list.Parent then
					return Q.list
				end
				Q.list = dig(PLAYER:FindFirstChild("PlayerGui"), "CrossPlatform", "Halloween2026", "MainEvent", "Main", "Quests", "Container", "ScrollingFrame")
				return Q.list
			end

			local function refresh()
				if os.clock() - Q.lastRefresh < 0.5 then
					return
				end
				Q.lastRefresh = os.clock()

				pcall(function()
					local owned = require(RepStorage.Modules.ProfileData).Materials.Owned
					candyText.Text = tostring(math.floor(tonumber(owned.Candies2026) or 0))
				end)

				local list = findList()
				local used = 0

				if list then
					for _, child in ipairs(list:GetChildren()) do
						local main = child.Name == "QuestFrame" and used < #rows and child:FindFirstChild("Main")
						if main then
							used += 1
							local r = rows[used]
							r.row.Visible = true

							local progress = tonumber(textOf(main, "Progress", "Progress", "Current", "AmountLabel")) or 0
							local goals = {}
							for i = 1, 3 do
								goals[i] = tonumber(textOf(main, "Challenges", "Challenge" .. i, "TextLabel")) or 0
							end

							local maxGoal = math.max(goals[3], 1)
							local done = goals[3] > 0 and progress >= goals[3]
							local rewards = textOf(main, "Rewards", "Container", "Description", "TextLabel")

							local timer = textOf(main, "Title", "Container", "RefreshLabel")
							timer = timer:gsub("^Refreshes in%s*", "")
							timer = timer:gsub(",%s*", "   ")

							r.title.Text = string.upper(textOf(main, "Title", "Container", "TitleLabel"))
							r.title.TextColor3 = done and GREEN or WHITE
							r.refresh.Text = "resets in   " .. timer
							r.desc.Text = rewards

							if string.find(string.lower(rewards), "candies", 1, true) then
								r.icon.Image = CANDY_ICON
								r.icon.Size = UDim2.fromOffset(24, 24)
							else
								r.icon.Image = pumpkin.Image
								r.icon.Size = UDim2.fromOffset(25, 23)
							end

							r.amount.Text = done and "DONE" or string.format("%d / %d", progress, goals[3])
							r.amount.TextColor3 = done and GREEN or ORANGE
							r.rim.Color = done and GREEN or ORANGE
							r.rim.Transparency = done and 0.5 or 0.82

							local frac = math.clamp(progress / maxGoal, 0, 1)
							TweenService:Create(r.fill, TweenInfo.new(0.4), { Size = UDim2.fromScale(frac, 1) }):Play()
							r.fill.BackgroundColor3 = done and GREEN or ORANGE
							r.runner.Visible = true
							r.runner.Position = UDim2.new(math.clamp(frac, 0.03, 0.97), 0, 0, 48.5)

							for i = 1, 3 do
								local reached = goals[i] > 0 and progress >= goals[i]
								local at = math.clamp(goals[i] / maxGoal, 0.14, 0.9)

								r.ticks[i].Visible = true
								r.ticks[i].Position = UDim2.fromScale(math.clamp(goals[i] / maxGoal, 0, 1), 0.5)
								r.ticks[i].BackgroundColor3 = reached and GREEN or CREAM
								r.goalText[i].Position = UDim2.new(at, 0, 0, 30)
								r.goalText[i].Text = tostring(goals[i])
								r.goalText[i].TextColor3 = reached and GREEN or GREY

								local rf = dig(main, "Rewards", "Container", "Reward" .. i, "ItemFrame")
								local icon = dig(rf, "Container", "Icon")
								local amt = textOf(rf, "Container", "Amount")
								local itemName = textOf(rf, "ItemName", "TextLabel")

								r.rewardIcon[i].Image = icon and icon:IsA("ImageLabel") and icon.Image or ""
								r.rewardIcon[i].Position = UDim2.new(at, -22, 0, 58)
								r.rewardText[i].Position = UDim2.new(at, -3, 0, 58)
								r.rewardText[i].Text = amt ~= "" and amt or itemName
								r.rewardText[i].TextColor3 = reached and GREEN or CREAM
							end
						end
					end
				end

				for i = used + 1, #rows do
					rows[i].row.Visible = false
				end

				if used == 0 then
					local r = rows[1]
					r.row.Visible = true
					r.title.Text = "NO EVENT QUESTS RIGHT NOW"
					r.title.TextColor3 = WHITE
					r.refresh.Text = ""
					r.desc.Text = "The Halloween quest list is empty"
					r.amount.Text = ""
					r.icon.Image = ""
					r.runner.Visible = false
					r.fill.Size = UDim2.fromScale(0, 1)
					for i = 1, 3 do
						r.goalText[i].Text = ""
						r.rewardText[i].Text = ""
						r.rewardIcon[i].Image = ""
						r.ticks[i].Visible = false
					end
				end
			end

			local function setEnabled(v)
				Q.on = v and true or false
				gui.Enabled = Q.on
				if Q.on then
					Q.lastRefresh = 0
					pcall(refresh)
				end
			end

			task.spawn(function()
				while Q.alive do
					task.wait(0.25)
					if Q.on then
						pcall(refresh)
					end
				end
			end)

			-- unload / re-execute: stop the loop and remove the panel
			list2.conns[#list2.conns + 1] = {
				Disconnect = function()
					Q.alive = false
					Q.on = false
					for _, c in ipairs(panelConns) do
						pcall(function()
							c:Disconnect()
						end)
					end
					pcall(function()
						gui:Destroy()
					end)
				end,
			}

