			make("TextLabel", {
				Position = UDim2.fromOffset(42, 1),
				Size = UDim2.new(1, -76, 0, 18),
				BackgroundTransparency = 1,
				Font = Enum.Font.GothamBold,
				TextSize = 13,
				TextColor3 = COL.text,
				TextXAlignment = Enum.TextXAlignment.Left,
