			}, header)

			make("TextLabel", {
				Position = UDim2.fromOffset(42, 20),
				Size = UDim2.new(1, -76, 0, 14),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				TextSize = 10,
				TextColor3 = COL.dim,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
