			local function statBlock(xScale, xOffset, label)
				local block = make("Frame", {
					Position = UDim2.new(xScale, xOffset, 0, 0),
					Size = UDim2.new(0.5, -4, 1, 0),
					BackgroundTransparency = 1,
				}, stats)

				make("TextLabel", {
					Size = UDim2.new(1, 0, 0, 12),
					BackgroundTransparency = 1,
					Font = Enum.Font.GothamMedium,
					TextSize = 9,
					TextColor3 = COL.dim,
					TextXAlignment = Enum.TextXAlignment.Left,
					Text = label,
				}, block)

				return make("TextLabel", {
					Position = UDim2.fromOffset(0, 14),
					Size = UDim2.new(1, 0, 0, 20),
					BackgroundTransparency = 1,
					Font = Enum.Font.Code,
					TextSize = 15,
					TextColor3 = COL.text,
					TextXAlignment = Enum.TextXAlignment.Left,
					Text = "--",
				}, block)
			end

			tag.distVal = statBlock(0, 0, "DISTANCE")
			tag.fromVal = statBlock(0.5, 4, "FROM MURDERER")

			-- threat meter
			local threat = make("Frame", {
				LayoutOrder = 4,
				Size = UDim2.new(1, 0, 0, 30),
				BackgroundTransparency = 1,
			}, panel)

			make("TextLabel", {
				Size = UDim2.new(0.5, 0, 0, 14),
				BackgroundTransparency = 1,
				Font = Enum.Font.GothamMedium,
				TextSize = 9,
				TextColor3 = COL.dim,
				TextXAlignment = Enum.TextXAlignment.Left,
				Text = "THREAT LEVEL",
			}, threat)

			tag.tierName = make("TextLabel", {
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, 0, 0, 0),
				Size = UDim2.new(0.6, 0, 0, 14),
				BackgroundTransparency = 1,
				Font = Enum.Font.GothamBold,
				TextSize = 12,
				TextColor3 = COL.dim,
				TextXAlignment = Enum.TextXAlignment.Right,
				Text = "NO DATA",
			}, threat)

			local meter = make("Frame", {
				Position = UDim2.fromOffset(0, 20),
				Size = UDim2.new(1, 0, 0, 6),
				BackgroundTransparency = 1,
			}, threat)

			make("UIListLayout", {
				FillDirection = Enum.FillDirection.Horizontal,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 3),
			}, meter)

			tag.segs = {}

			for i = 1, 5 do
				local seg = make("Frame", {
					LayoutOrder = i,
					Size = UDim2.new(0.2, -3, 1, 0),
					BackgroundColor3 = COL.off,
					BorderSizePixel = 0,
				}, meter)

				corner(seg, 3)
				tag.segs[i] = seg
			end

			-- action buttons
			local actions = make("Frame", {
				LayoutOrder = 5,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
			}, panel)

			make("UIListLayout", {
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 6),
			}, actions)

			tag.tpBtn = makeButton(actions, 1, "TELEPORT TO", COL.violet)
			tag.giveBtn = makeButton(actions, 2, "GIVE GUN", COL.amber)

			tag.hint = make("TextLabel", {
				LayoutOrder = 3,
				Size = UDim2.new(1, 0, 0, 12),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				TextSize = 9,
				TextColor3 = COL.dim,
				Text = "",
			}, actions)

			tag.tpBtn.btn.Activated:Connect(function()
				teleportTo(player)
			end)

			tag.giveBtn.btn.Activated:Connect(function()
				if not hasGun() then
					notify("No Gun", "You are not holding the gun.", "x")
					return
				end

				if tag.confirmUntil and os.clock() < tag.confirmUntil then
					tag.confirmUntil = nil
					task.spawn(giveGun, player)
				else
					-- it kills our own character, so ask for a second tap
					tag.confirmUntil = os.clock() + 3
				end
			end)

			-- ---------- chip (always visible, tap to open) ----------
			local chip = make("TextButton", {
				Name = "Chip",
				LayoutOrder = 2,
				Size = UDim2.fromOffset(K.chipW, 26),
				BackgroundColor3 = COL.bg,
				BackgroundTransparency = 0.12,
				AutoButtonColor = false,
				Text = "",
			}, root)

			corner(chip, 13)
			tag.chipStroke, tag.chipGrad = glowStroke(chip, 1.2)

			tag.diamond = make("Frame", {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromOffset(13, 13),
				Size = UDim2.fromOffset(7, 7),
				Rotation = 45,
				BackgroundColor3 = COL.violet,
				BorderSizePixel = 0,
			}, chip)

			make("TextLabel", {
				Position = UDim2.fromOffset(26, 0),
				Size = UDim2.new(1, -78, 1, 0),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				TextSize = 12,
				TextColor3 = COL.text,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Text = player.DisplayName,
			}, chip)

			tag.chipDist = make("TextLabel", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -10, 0.5, 0),
				Size = UDim2.fromOffset(46, 20),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				TextSize = 11,
				TextColor3 = COL.dim,
				TextXAlignment = Enum.TextXAlignment.Right,
				Text = "--",
			}, chip)

			chip.Activated:Connect(function()
				setOpen(tag, not tag.open)
			end)

			return tag
		end

		setOpen = function(tag, state)
			if tag.open == state then
				return
			end

			tag.open = state
			tag.confirmUntil = nil

			if state then
				for _, other in pairs(ui.tags) do
					if other ~= tag and other.open then
						setOpen(other, false)
					end
				end

				tag.panel.Visible = true
				tag.pscale.Scale = 0.86
				tw(tag.pscale, 0.18, { Scale = 1 })
			else
				tw(tag.pscale, 0.12, { Scale = 0.9 })

				task.delay(0.12, function()
					if not tag.open and tag.panel.Parent then
						tag.panel.Visible = false
					end
				end)
			end
		end

		local function removeTag(player)
			local tag = ui.tags[player]

			if tag then
				ui.tags[player] = nil

				pcall(function()
					tag.root:Destroy()
				end)
			end
		end

		local function clearTags()
			for player in pairs(ui.tags) do
				removeTag(player)
			end
		end

		-- whitelisted = ticked in the dropdown, or a Roblox friend while "Whitelist Roblox Friends" is on
		local function isWhitelisted(player)
			if player == localPlayer then
				return false
			end

			if wb.has(wb.white, player) then
				return true
			end

			return wb.friends and wb.friendCache[player.UserId] == true
		end

		local function syncTags()
			if not ui.enabled or not ui.gui then
				return
			end

			for _, player in ipairs(Players:GetPlayers()) do
				if isWhitelisted(player) then
					if not ui.tags[player] then
						ui.tags[player] = buildTag(player)
					end
				elseif ui.tags[player] then
					removeTag(player)
				end
			end

			for player in pairs(ui.tags) do
				if not player.Parent then
					removeTag(player)
				end
			end
		end

		ui.sync = syncTags

		-- text, colours, danger level and button states (10 times a second)
		local function refreshTag(tag, info)
			local player = tag.player
			local char = player.Character
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			local myChar = localPlayer.Character
			local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")

			local dead = hum == nil or hum.Health <= 0
			local myDist = (myHrp and hrp) and (myHrp.Position - hrp.Position).Magnitude or nil
			local distText = myDist and string.format("%d st", math.floor(myDist + 0.5)) or "--"

			local tier, fromText

			if dead then
				tier, fromText = TIERS.dead, "--"
			elseif info.murderer == player then
				tier, fromText = TIERS.murd, "ARMED"
			elseif info.mHrp and hrp then
				local d = (info.mHrp.Position - hrp.Position).Magnitude

				tier, fromText = tierFor(d), string.format("%d st", math.floor(d + 0.5))
			elseif info.mDown then
				tier, fromText = TIERS.clear, "DOWN"
			else
				tier, fromText = TIERS.none, "--"
			end

			tag.chipDist.Text = distText
			tag.diamond.BackgroundColor3 = tier.color

			if not tag.open then
				return
			end

			tag.distVal.Text = distText
			tag.fromVal.Text = fromText
			tag.fromVal.TextColor3 = tier.color
			tag.tierName.Text = tier.name
			tag.tierName.TextColor3 = tier.color
			tag.avatarStroke.Color = tier.color

			for i, seg in ipairs(tag.segs) do
				seg.BackgroundColor3 = i <= tier.level and tier.color or COL.off
			end

			local confirming = tag.confirmUntil ~= nil and os.clock() < tag.confirmUntil

			setBtn(tag.tpBtn, "TELEPORT TO", COL.violet, hrp ~= nil)

			if info.gun and not dead then
				setBtn(tag.giveBtn, confirming and "TAP AGAIN: RESET SELF" or "GIVE GUN", confirming and COL.red or COL.amber, true)
				tag.hint.Text = confirming and "you die, the gun drops at their feet" or "stands in front of them, then you reset"
			else
				setBtn(tag.giveBtn, info.gun and "TARGET DOWN" or "NO GUN", COL.dim, false)
				tag.hint.Text = info.gun and "that player is not alive" or "you are not holding the gun"
			end
		end

		-- follows the head on screen (every frame)
		local function positionTag(tag, cam, vp, now)
			local char = tag.player.Character
			local head = char and (char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart"))

			if not head then
				tag.root.Visible = false
				return
			end

			local screen, onScreen = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 2.2, 0))

			if not onScreen or screen.Z <= 0 then
				tag.root.Visible = false
				return
			end

			-- far away = a bit smaller, an open panel is always full size
			local dist = (cam.CFrame.Position - head.Position).Magnitude

			tag.scale.Scale = tag.open and 1 or math.clamp(1.1 - dist / 220, 0.65, 1)
			tag.root.Visible = true

			local size = tag.root.AbsoluteSize
			local x = math.clamp(screen.X, size.X / 2 + 6, math.max(size.X / 2 + 6, vp.X - size.X / 2 - 6))
			local y = math.clamp(screen.Y, size.Y + 6, math.max(size.Y + 6, vp.Y - 6))

			tag.root.Position = UDim2.fromOffset(x, y)

			-- slow rotating glow + pulsing diamond
			tag.chipGrad.Rotation = (now * 45) % 360
			tag.diamond.BackgroundTransparency = 0.1 + 0.3 * (0.5 + 0.5 * math.sin(now * 3))

			if tag.open then
				tag.panelGrad.Rotation = (now * 40) % 360
			end
		end

		local function step()
			if not ui.enabled or not ui.gui then
				return
			end

			local now = os.clock()

			if now - ui.lastSync > 0.4 then
				ui.lastSync = now
				syncTags()
			end

			if next(ui.tags) == nil then
				return
			end

			local cam = workspace.CurrentCamera

			if not cam then
				return
			end

			if now - ui.lastText > 0.1 then
				ui.lastText = now

				local murderer = func15()
				local mChar = murderer and murderer.Character
				local mHrp = mChar and mChar:FindFirstChild("HumanoidRootPart")
				local mHum = mChar and mChar:FindFirstChildOfClass("Humanoid")
				local mAlive = mHrp ~= nil and (mHum == nil or mHum.Health > 0)

				local info = {
					murderer = murderer,
					mHrp = mAlive and mHrp or nil,
					mDown = mHrp ~= nil and not mAlive,
					gun = hasGun(),
				}

				for _, tag in pairs(ui.tags) do
					refreshTag(tag, info)
				end
			end

			local vp = cam.ViewportSize

			for _, tag in pairs(ui.tags) do
				positionTag(tag, cam, vp, now)
			end
		end

		pcall(function()
			for _, container in ipairs({ (gethui and gethui()) or CoreGui, CoreGui }) do
				local old = container:FindFirstChild("FVLWhitelistTags")

				if old then
					old:Destroy()
				end
			end
		end)

		ui.gui = make("ScreenGui", {
			Name = "FVLWhitelistTags",
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			DisplayOrder = 9000,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		}, (gethui and gethui()) or CoreGui)

		ui.conn = RunService.RenderStepped:Connect(function()
			pcall(step)
		end)

		list2.conns[#list2.conns + 1] = ui.conn

		obj3:OnDestroy(function()
			ui.enabled = false

			if ui.conn then
				pcall(function()
					ui.conn:Disconnect()
				end)
			end

			pcall(function()
				ui.gui:Destroy()
			end)
		end)

		----------------------------------------------------------------
		-- Menu
		----------------------------------------------------------------
		tbl43.combat:Section({ Title = "Whitelist" })

		tbl43.combat:Toggle({
			Title = "Whitelist Roblox Friends",
			Flag = "Toggle_WB_Friends",
			Desc = "Every Roblox friend of yours that is in the server is treated as whitelisted.",
			Type = "Toggle",
			Value = false,
			Callback = function(on)
				wb.friends = on

				if on then
					for _, player in ipairs(Players:GetPlayers()) do
						wb.queryFriend(player)
					end
				end
			end,
		})

		tbl43.combat:Toggle({
			Title = "Whitelist Tag UI",
			Flag = "Toggle_WB_Tags",
			Desc = "Shows a small tag over every whitelisted player. Tap it to see the distance, the distance from the murderer (with a danger level), teleport to them, or give them the gun.",
			Type = "Toggle",
			Value = true,
			Callback = function(on)
				ui.enabled = on == true

				if ui.gui then
					ui.gui.Enabled = ui.enabled
				end

				if not ui.enabled then
					clearTags()
				end
			end,
		})

		whiteDrop = tbl43.combat:Dropdown({
			Title = "Whitelist",
			Flag = "Dropdown_WB_White",
			Desc = "Tick the players Auto Shoot, Silent Aim, Triggerbot and Kill Aura must never attack. Nothing ticked = nobody is protected. Ticked players get a tag with a UI above their head.",
			Multi = true,
			Placeholder = "Nobody",
			Values = options(nil),
			Callback = function(list)
				wb.white = toSet(list)

				-- show / hide the tags right away
				task.defer(syncTags)
			end,
		})

		local function refreshPlayers()
			pcall(function()
				whiteDrop:Refresh(options(whiteDrop))
			end)
		end

		list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(function(player)
			if wb.friends then
				wb.queryFriend(player)
			end

			task.delay(0.1, refreshPlayers)
		end)

		list2.conns[#list2.conns + 1] = Players.PlayerRemoving:Connect(function()
			task.delay(0.2, refreshPlayers)
		end)
	end

	-- ===== Kill Aura (murderer) =====
	-- While you hold the knife, everyone alive within the distance below is stabbed automatically, over and over.
	-- (The same stab messages the "Kill All" button sends, but only for players close to you and without any key.)
	do
		local RunService_ = game:GetService("RunService")
		local ka = { on = false, distance = 15, conn = nil, last = 0, visibleOnly = true }

		-- Visible Only (from Star Hub): a player behind a wall is skipped. A ray from you to their torso that hits
		-- anything (ignoring both characters) means they are hidden.
		local kaRay = RaycastParams.new()
		kaRay.FilterType = Enum.RaycastFilterType.Exclude
		kaRay.IgnoreWater = true

		ka.visible = function(myChar, otherChar, myRoot, otherRoot)
			local target = otherChar:FindFirstChild("UpperTorso") or otherChar:FindFirstChild("Torso") or otherRoot

			kaRay.FilterDescendantsInstances = { myChar, otherChar }

			return workspace:Raycast(myRoot.Position, target.Position - myRoot.Position, kaRay) == nil
		end

		tbl43.combat:Section({ Title = "Kill" })

		tbl43.combat:Toggle({
			Title = "Kill Aura",
			Flag = "Toggle_Kill_Aura",
			Desc = "Murderer / Zombie: while you hold the knife, everyone within the distance below is stabbed automatically (zombies skip other zombies). Whitelisted players are skipped.",
			Type = "Toggle",
			Value = false,
			Callback = function(on)
				ka.on = on

				if ka.conn then
					ka.conn:Disconnect()
					ka.conn = nil
				end

				if not on then
					return
				end

				ka.conn = RunService_.Heartbeat:Connect(function()
					if os.clock() - ka.last < 0.12 then
						return
					end

					ka.last = os.clock()

					pcall(function()
						local character = localPlayer.Character
						local hrp = character and character:FindFirstChild("HumanoidRootPart")
						local knife = character and character:FindFirstChild("Knife")
						local events = knife and knife:FindFirstChild("Events")
						local stab = events and events:FindFirstChild("KnifeStabbed")
						local touched = events and events:FindFirstChild("HandleTouched")

						if not (hrp and stab and touched) then
							return
						end

						local ordered = Players:GetPlayers()

						for _, player in ipairs(ordered) do
							local otherCharacter = player ~= localPlayer and player.Character
							local otherHrp = otherCharacter and otherCharacter:FindFirstChild("HumanoidRootPart")
							local otherHumanoid = otherCharacter and otherCharacter:FindFirstChildOfClass("Humanoid")

							if otherHrp and otherHumanoid and otherHumanoid.Health > 0
								and not (list2.isRole(localPlayer, "Zombie") and list2.isRole(player, "Zombie"))
								and not list2.wb.isWhite(player)
								and (otherHrp.Position - hrp.Position).Magnitude <= ka.distance
								and (not ka.visibleOnly or ka.visible(character, otherCharacter, hrp, otherHrp)) then
								pcall(function()
									stab:FireServer()
								end)

								pcall(function()
									touched:FireServer(otherHrp)
								end)
							end
						end
					end)
				end)
				list2.conns[#list2.conns + 1] = ka.conn
			end,
		})

		tbl43.combat:Slider({
			Title = "Kill Aura Distance",
			Flag = "Slider_Kill_Aura_Distance",
			Desc = "How close (studs) a player has to be to get stabbed.",
			Step = 1,
			Value = { Min = 5, Max = 60, Default = 15 },
			Callback = function(value)
				local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

				if n then
					ka.distance = n
				end
			end,
		})

		tbl43.combat:Toggle({
			Title = "Kill Aura: Visible Only",
			Flag = "Toggle_Kill_Aura_Visible",
			Desc = "Only stabs players you can actually see - nobody behind a wall or a closed door. Turn off to stab through walls.",
			Type = "Toggle",
			Value = true,
			Callback = function(on)
				ka.visibleOnly = on and true or false
			end,
		})
	end


	killTargetDropdown = tbl43.combat:Dropdown({
		Title = "Target",
		Desc = "Pick who to stab, then use the button below.",
		Multi = false,
		Value = nil,
		Values = func121(),
		Callback = function(value)
			selectedKillTarget = value
		end,
	})

	list2.knifeEls[#list2.knifeEls + 1] = killTargetDropdown

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Button({
		Title = "Kill Target",
		Desc = "Instantly stabs the player picked above.",
		Callback = function()
			func76(selectedKillTarget)
		end,
	})

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Button({
		Title = "Kill All",
		Desc = "Instantly stabs every player in the server.",
		Callback = function()
			func77()
		end,
	})

	do
		local RunService_ = game:GetService("RunService")
		local autoKill = { on = false, conn = nil, perFrame = 50 } -- fixed, always full speed

		list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Toggle({
			Title = "Auto Kill All",
			Flag = "Toggle_Auto_Kill_All",
			Desc = "Murderer: keeps stabbing every player in the server, nonstop, at full speed. Off by default.",
			Type = "Toggle",
			Value = false,
			Callback = function(on)
				autoKill.on = on

				if autoKill.conn then
					autoKill.conn:Disconnect()
					autoKill.conn = nil
				end

				if not on then
					return
				end

				-- every frame: one target list, then `perFrame` stabs on all of them
				autoKill.conn = RunService_.Heartbeat:Connect(function()
					if not autoKill.on or not list2.killAllBurst then
						return
					end

					pcall(list2.killAllBurst, autoKill.perFrame)
				end)

				list2.conns[#list2.conns + 1] = autoKill.conn
			end,
		})
	end

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Button({
		Title = "Kill Nearest",
		Desc = "Murderer: stabs the closest living player.",
		Icon = "sword",
		Callback = function()
			if list2.killNearest then
				list2.killNearest()
			end
		end,
	})

	tbl43.combat:Section({ Title = "Knife Hitbox" })
	local n4 = 0

	UserInputService.InputBegan:Connect(function()
		n4 = os.clock()
	end)

	local function func196()
		return os.clock() - n4 < 1
	end

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Toggle({
		Title = "Enable Knife Hitbox",
		Flag = "Toggle_Change_Knife_Hitbox",
		Desc = "Turns the bigger Knife Hitbox on or off. The slider below sets the size.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			num17.on = on and true or false

			if num17.on then
				num17.start()
			else
				num17.stop()
			end
		end,
	})

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Slider({
		Title = "Change Knife Hitbox  (OP!)",
		Flag = "Slider_Change_Knife_Hitbox",
		Desc = "Change the size of your Knife! (1 is default hitbox)",
		Step = 1,
		Value = { Min = 1, Max = 200, Default = 1 },
		Callback = function(value)
			local num32 = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if num32 then
				num17.setMult(num32)
			end
		end,
	})

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Toggle({
		Title = "Show Hitbox",
		Flag = "Toggle_Show_Hitbox",
		Desc = "Draws the reach as a sphere.",
		Type = "Toggle",
		Value = false,
		Callback = function(show)
			if not func196() then
				return
			end
			num17.show = show

			if show then
				num17.showBall()
			else
				num17.hideBall()
			end
		end,
	})

	list2.knifeEls[#list2.knifeEls + 1] = tbl43.combat:Toggle({
		Title = "Silent Throw",
		Flag = "Toggle_Silent_Throw",
		Desc = "Right click throws the knife at the nearest player. Murderer only.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			flag83.on = on

			if on then
				flag83.start()
			else
				flag83.stop()
			end
		end,
	})
end
--[[ ===== Anti-Aim (ported from Pulse / Qwern) =====
	Two modes:
	  * Side Profile   - finds nearest threat, spoofs velocity + MoveDirection sideways
	                     and rotates HRP CFrame to present a narrow profile (Pulse "Prediction").
	  * Velocity Desync - random / spin / jitter / sky / underground velocity spoof
	                     (Pulse non-Prediction desync).
	Spoof is applied on RunService.Stepped (before physics) and restored on Heartbeat
	(after physics), so local movement / camera is unaffected but the server and other
	clients receive the fake velocity / orientation.
]]
do
	local RS = game:GetService("RunService")
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer

	local AA = {
		on = false,
		mode = "Side Profile", -- "Side Profile" | "Velocity Desync"
		dir = "Random",        -- Velocity Desync only: Random | Spin | Jitter | Sky | Underground
		power = 5,             -- 1..10
		smart = true,          -- Smart Pause (hold-off while a tool is equipped)
		vel = true,            -- Spoof Velocity
		md = true,             -- Spoof Move Direction
		side = true,           -- Side Profile CFrame rotation
		sideDir = 1,
		sideFlipAt = 0,
		spinA = 0,
		jitterDir = nil,
		jitterUntil = 0,
		jitterFlip = 1,
		mdDir = nil,
		mdUntil = 0,
		threat = nil,
		threatAt = 0,
		toolAt = 0,
		realVel = nil,
		realMD = nil,
		realCF = nil,
		hrp = nil,
		hum = nil,
	}

	local function getChar()
		local c = lp.Character
		if not c then return nil, nil end
		local hrp = c:FindFirstChild("HumanoidRootPart")
		local hum = c:FindFirstChildOfClass("Humanoid")
		if not hrp or not hum or hum.Health <= 0 then return nil, nil end
		return hrp, hum
	end

	local BAD_STATES = {
		[Enum.HumanoidStateType.Dead] = true,
		[Enum.HumanoidStateType.Seated] = true,
		[Enum.HumanoidStateType.Swimming] = true,
		[Enum.HumanoidStateType.Climbing] = true,
		[Enum.HumanoidStateType.Physics] = true,
		[Enum.HumanoidStateType.Ragdoll] = true,
		[Enum.HumanoidStateType.PlatformStanding] = true,
		[Enum.HumanoidStateType.FallingDown] = true,
		[Enum.HumanoidStateType.GettingUp] = true,
	}

	local function isBusy()
		-- Smart Pause: hold off while a tool is equipped (gun / knife) so Silent Aim /
		-- Aimbot / Triggerbot still work, and for 0.35s after equip (Pulse behaviour).
		if not AA.smart then return false end
		if os.clock() - AA.toolAt < 0.35 then return true end
		local c = lp.Character
		if c then
			for _, t in ipairs(c:GetChildren()) do
				if t:IsA("Tool") then return true end
			end
		end
		return false
	end

	local function clampVec(v)
		return Vector3.new(
			math.clamp(v.X, -32767, 32767),
			math.clamp(v.Y, -32767, 32767),
			math.clamp(v.Z, -32767, 32767)
		)
	end

	local function randOffset(mag)
		local d = AA.dir
		if d == "Underground" then
			return Vector3.new((math.random() * 2 - 1) * mag * 0.15, -mag, (math.random() * 2 - 1) * mag * 0.15)
		elseif d == "Sky" then
			return Vector3.new((math.random() * 2 - 1) * mag * 0.15, mag, (math.random() * 2 - 1) * mag * 0.15)
		elseif d == "Spin" then
			AA.spinA = (AA.spinA + 0.9 + math.random() * 0.6) % (math.pi * 2)
			return Vector3.new(math.cos(AA.spinA) * mag, (math.random() * 2 - 1) * mag * 0.35, math.sin(AA.spinA) * mag)
		elseif d == "Jitter" then
			local now = os.clock()
			if (not AA.jitterDir) or now >= AA.jitterUntil then
				local v = Vector3.new(math.random() * 2 - 1, (math.random() * 2 - 1) * 0.4, math.random() * 2 - 1)
				AA.jitterDir = v.Magnitude > 0.1 and v.Unit or Vector3.xAxis
				AA.jitterUntil = now + 0.25 + math.random() * 0.25
			end
			AA.jitterFlip = -AA.jitterFlip
			return AA.jitterDir * (mag * 1.6 * AA.jitterFlip)
		end
		-- Random
		return Vector3.new(
			(math.random() < 0.5 and -1 or 1) * mag,
			(math.random() * 2 - 1) * mag,
			(math.random() < 0.5 and -1 or 1) * mag
		)
	end

	local function findThreat(pos)
		-- nearest alive player (in MM2 the actual threat is the murderer / sheriff,
		-- but role detection is executor-specific; nearest player is a safe port).
		local best, bestD = nil, nil
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp then
				local c = p.Character
				if c then
					local hrp = c:FindFirstChild("HumanoidRootPart")
					local hum = c:FindFirstChildOfClass("Humanoid")
					if hrp and hum and hum.Health > 0 then
						local d = (hrp.Position - pos).Magnitude
						if (not bestD) or d < bestD then
							best, bestD = hrp, d
						end
					end
				end
			end
		end
		return best
	end

	-- APPLY spoof before physics simulation
	local applyConn = RS.Stepped:Connect(function()
		if not AA.on then return end
		local hrp, hum = getChar()
		if not hrp then return end
		AA.hrp, AA.hum = hrp, hum
		if isBusy() then return end
		local ok, state = pcall(function() return hum:GetState() end)
		if ok and BAD_STATES[state] then return end

		local mag = 32767 * math.clamp(AA.power, 1, 10) / 10

		if AA.mode == "Velocity Desync" then
			if AA.vel then
				AA.realVel = hrp.AssemblyLinearVelocity
				hrp.AssemblyLinearVelocity = clampVec(randOffset(mag))
				pcall(function()
					if sethiddenproperty then
						sethiddenproperty(hrp, "NetworkIsSleeping", false)
					end
				end)
			end
			if AA.md then
				local now = os.clock()
				if (not AA.mdDir) or now >= AA.mdUntil then
					local a = math.random() * math.pi * 2
					AA.mdDir = Vector3.new(math.cos(a), 0, math.sin(a))
					AA.mdUntil = now + 0.15 + math.random() * 0.3
				end
				AA.realMD = hum.MoveDirection
				pcall(function() hum:Move(AA.mdDir, false) end)
			end
		else
			-- Side Profile (Pulse Prediction mode)
			local now = os.clock()
			if now >= AA.threatAt then
				AA.threatAt = now + 0.25
				AA.threat = findThreat(hrp.Position)
			end
			local threat = AA.threat
			if not (threat and threat.Parent) then return end

			local toMe = hrp.Position - threat.Position
			toMe = Vector3.new(toMe.X, 0, toMe.Z)
			if toMe.Magnitude < 0.5 then return end
			toMe = toMe.Unit

			local perp = Vector3.new(-toMe.Z, 0, toMe.X) -- perpendicular to threat line
			local vel = hrp.AssemblyLinearVelocity
			local flatVel = Vector3.new(vel.X, 0, vel.Z)
			local dot = flatVel:Dot(perp)

			if math.abs(dot) > 3 then
				AA.sideDir = dot > 0 and -1 or 1
			elseif AA.side then
				if now >= AA.sideFlipAt then
					AA.sideDir = -AA.sideDir
					AA.sideFlipAt = now + 0.6 + math.random() * 1.2
				end
			else
				AA.sideDir = math.random() < 0.5 and -1 or 1
			end

			local sideVec = perp * AA.sideDir
			local maxV = math.max(10 + math.clamp(AA.power, 1, 10) * 9, flatVel.Magnitude)

			if AA.vel then
				AA.realVel = vel
				hrp.AssemblyLinearVelocity = Vector3.new(sideVec.X * maxV, vel.Y, sideVec.Z * maxV)
			end
			if AA.md then
				AA.realMD = hum.MoveDirection
				pcall(function() hum:Move(sideVec, false) end)
			end
			if AA.side then
				AA.realCF = hrp.CFrame
				-- face perpendicular to the threat (narrower hitbox profile)
				hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + sideVec)
			end
		end
	end)

	-- RESTORE after physics so local movement / view is unaffected (Pulse restore logic)
	local restoreConn = RS.Heartbeat:Connect(function()
		local hrp = AA.hrp
		local hum = AA.hum
		if hrp and hrp.Parent then
			if AA.realVel then
				hrp.AssemblyLinearVelocity = AA.realVel
			end
			if AA.realCF then
				local cur = hrp.CFrame
				if (cur.Position - AA.realCF.Position).Magnitude < 0.01 then
					hrp.CFrame = AA.realCF
				end
			end
		end
		if hum and hum.Parent and AA.realMD then
			pcall(function() hum:Move(AA.realMD, false) end)
		end
		AA.realVel, AA.realMD, AA.realCF = nil, nil, nil
	end)

	-- track tool equip for Smart Pause
	local function hookTool(c)
		if not c then return end
		c.ChildAdded:Connect(function(t)
			if t:IsA("Tool") then AA.toolAt = os.clock() end
		end)
	end
	hookTool(lp.Character)
	lp.CharacterAdded:Connect(hookTool)

	-- register connections for cleanup on unload (matches F$VL pattern)
	pcall(function()
		if list2 and list2.conns then
			list2.conns[#list2.conns + 1] = applyConn
			list2.conns[#list2.conns + 1] = restoreConn
		end
	end)

	-- ===== UI (Combat tab) =====
	pcall(function() tbl43.combat:Section({ Title = "Anti-Aim" }) end)

	tbl43.combat:Toggle({
		Title = "Anti Aim",
		Flag = "Toggle_AntiAim",
		Desc = "Spoofs velocity / rotation so other aimbots miss you. Ported from Pulse.",
		Type = "Toggle",
		Value = false,
		Callback = function(v) AA.on = v end,
	})

	tbl43.combat:Dropdown({
		Title = "AA Mode",
		Flag = "Dropdown_AntiAim_Mode",
		Desc = "Side Profile = hide from nearest threat. Velocity Desync = random velocity spoof.",
		Multi = false,
		Value = "Side Profile",
		Values = { "Side Profile", "Velocity Desync" },
		Callback = function(v) if v then AA.mode = v end end,
	})

	tbl43.combat:Dropdown({
		Title = "Direction",
		Flag = "Dropdown_AntiAim_Dir",
		Desc = "Spoof direction (Velocity Desync mode only).",
		Multi = false,
		Value = "Random",
		Values = { "Random", "Spin", "Jitter", "Sky", "Underground" },
		Callback = function(v) if v then AA.dir = v end end,
	})

	tbl43.combat:Slider({
		Title = "Spoof Strength",
		Flag = "Slider_AntiAim_Power",
		Desc = "Strength of the velocity spoof (1-10).",
		Step = 1, Min = 1, Max = 10, Value = 5,
		Callback = function(v) AA.power = v end,
	})

	tbl43.combat:Toggle({
		Title = "Smart Pause",
		Flag = "Toggle_AntiAim_Smart",
		Desc = "Pause anti-aim while holding a tool (gun/knife) so Silent Aim / Aimbot work.",
		Type = "Toggle",
		Value = true,
		Callback = function(v) AA.smart = v end,
	})

	tbl43.combat:Toggle({
		Title = "Spoof Velocity",
		Flag = "Toggle_AntiAim_Vel",
		Desc = "Spoof AssemblyLinearVelocity (the main desync).",
		Type = "Toggle",
		Value = true,
		Callback = function(v) AA.vel = v end,
	})

	tbl43.combat:Toggle({
		Title = "Spoof Move Direction",
		Flag = "Toggle_AntiAim_MD",
		Desc = "Spoof Humanoid MoveDirection.",
		Type = "Toggle",
		Value = true,
		Callback = function(v) AA.md = v end,
	})

	tbl43.combat:Toggle({
		Title = "Side Profile",
		Flag = "Toggle_AntiAim_Side",
		Desc = "Rotate your character sideways to the nearest threat (narrower hitbox).",
		Type = "Toggle",
		Value = true,
		Callback = function(v) AA.side = v end,
	})
end


func118("Kill All", Color3.fromHex("#7F1D1D"), 0.25)
func118("Kill Nearest", Color3.fromHex("#7F1D1D"), 0.25)
func120(ICON.mono)
