                }
                pulseWeather.number = function(numberValue, argument2, argument3, argument4)
                    numberValue = tonumber(numberValue)
                    numberValue = if numberValue == nil
                        then argument2
                        else if numberValue ~= numberValue
                            then argument2
                            else if numberValue == math.huge
                                then argument2
                                else if numberValue == -math.huge then argument2 else numberValue
                    return math.clamp(numberValue, argument3, argument4)
                end
                pulseWeather.validate = function()
                    if pulseWeather.recipes[pulseWeather.kind] == nil then
                        pulseWeather.kind = "Snow"
