                    if pulseWeather.qualities[pulseWeather.quality] == nil then
                        pulseWeather.quality = "Balanced"
                    end
                    for key, item in pairs(pulseWeather.limits) do
                        pulseWeather[key] = pulseWeather.number(pulseWeather[key], item[1], item[2], item[3])
                    end
                    for unused, item in ipairs(pulseWeather.colourFields) do
                        if typeof(pulseWeather[item]) ~= "Color3" then
                            pulseWeather[item] = pulseWeather.defaults[item]
                        end
                    end
                end
                pulseWeather.mapRoots = function()
                    local now = os.clock()
                    if pulseWeather.rootsAt then
                        if now - pulseWeather.rootsAt < 5 then
                            if pulseWeather.roots then
                                return pulseWeather.roots
                            end
                        end
                    end
                    local roots = {}
                    for unused, instance in ipairs(workspace:GetChildren()) do
                        if instance.ClassName == "Model" then
                            if instance:FindFirstChild("CoinContainer") then
                                roots[#roots + 1] = instance
                            elseif string.find(instance.Name, "Lobby", 1, true) then
                                roots[#roots + 1] = instance
                            end
                        end
                    end
                    pulseWeather.roots = roots
                    pulseWeather.rootsAt = now
                    return roots
                end
                local b, entries3 = setmetatable, { __mode = "k" }
                pulseWeather.invisible = b({}, entries3)
                pulseWeather.splashes = {}
                pulseWeather.filter = function(argument2)
                    local filterDescendantsInstances = { argument2 }
                    for unused, localPlayer2 in ipairs(game:GetService("Players"):GetPlayers()) do
                        if localPlayer2.Character then
                            filterDescendantsInstances[#filterDescendantsInstances + 1] = localPlayer2.Character
                        end
                    end
                    for key in pairs(pulseWeather.invisible) do
                        if key.Parent then
                            filterDescendantsInstances[#filterDescendantsInstances + 1] = key
                        end
                    end
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Exclude
