                    gradeFx.Saturation = (calculatedValue.saturation or 0) * gradeLevel
                    gradeFx.Contrast = (calculatedValue.contrast or 0) * gradeLevel
                    gradeFx.Brightness = (calculatedValue.brightness or 0) * gradeLevel
                end
                pulseWeather.bolt = function(entries4, argument2, argument)
                    local entries2 = {}
                    for key, worldPosition in ipairs(entries4) do
                        local attachment = Instance.new("Attachment")
                        attachment.Parent = pulseWeather.boltPart
                        attachment.WorldPosition = worldPosition
                        entries2[key] = attachment
                    end
                    entries4 = {}
                    for index = 1, #entries2 - 1, 1 do
                        local calculatedValue, callback5, entries3 =
                            0.55 + 0.45 * index / #entries2,
                            ipairs,
                            { { 1, Color3.fromRGB(232, 240, 255) }, { 4.5, Color3.fromRGB(150, 178, 255) } }
                        for beam, item in callback5(entries3) do
                            beam = Instance.new("Beam")
                            beam.Attachment0, beam.Attachment1 = entries2[index], entries2[index + 1]
                            beam.Color = ColorSequence.new(item[2])
                            beam.Width0, beam.Width1 =
                                argument2 * item[1] * calculatedValue,
                                argument2 * item[1] * (0.55 + 0.45 * (index + 1) / #entries2)
                            beam.LightEmission = 1
                            beam.LightInfluence = 0
                            beam.FaceCamera = true
                            beam.Segments = 1
                            beam.Transparency = NumberSequence.new(1)
                            beam.Parent = pulseWeather.boltPart
                            local calculatedValue2, entries5 = #entries4 + 1, { beam = beam }
                            entries5.weight, entries4[calculatedValue2] = item[1] == 1 and 1 or argument, entries5
                        end
                    end
                    return entries4
                end
                pulseWeather.strike = function(volume)
                    local storm, calculatedValue, beams = pulseWeather.storm, pulseWeather.stormPower / 100, math.random()
                    local text, calculatedValue2
                    if beams < 0.12 then
                        text, calculatedValue2 = "close", 110 + math.random() * 90
                    else
                        if beams < 0.55 then
                            text, calculatedValue2 = "mid", 260 + math.random() * 260
                        else
                            text, calculatedValue2 = "far", 560 + math.random() * 420
                        end
                    end
                    beams = pulseWeather.camera.CFrame.LookVector
                    local atan2Result = math.atan2(beams.Z, beams.X)
                    atan2Result = math.random() < 0.6 and atan2Result + (math.random() - 0.5) * 1.6
                        or math.random() * 3.141592653589793 * 2
                    beams = volume
                        + Vector3.new(
                            math.cos(atan2Result) * calculatedValue2,
                            -6,
                            math.sin(atan2Result) * calculatedValue2
                        )
                    volume = beams
                        + Vector3.new(
                            (math.random() - 0.5) * calculatedValue2 * 0.15,
                            130 + calculatedValue2 * 0.55,
                            (math.random() - 0.5) * calculatedValue2 * 0.15
                        )
                    local magnitude = (volume - beams).Magnitude
                    local calculatedValue3 = magnitude * 0.045
                    local function callback5(argument, argument2, argument3, argument4)
                        local entries2 = { argument }
                        for index = 1, argument3 - 1, 1 do
                            local calculatedValue4 = index / argument3
                            entries2[#entries2 + 1] = argument:Lerp(argument2, calculatedValue4)
                                + Vector3.new(
                                    (math.random() - 0.5) * 2 * argument4 * (1 - calculatedValue4 * 0.3),
                                    (math.random() - 0.5) * argument4 * 0.4,
                                    (math.random() - 0.5) * 2 * argument4 * (1 - calculatedValue4 * 0.3)
                                )
                        end
                        entries2[#entries2 + 1] = argument2
                        return entries2
                    end
                    local value, clampedValue =
                        callback5(volume, beams, 16, calculatedValue3), math.clamp(calculatedValue2 * 0.0065, 0.7, 4.5)
                    beams = pulseWeather.bolt(value, clampedValue, 0.32)
                    for index = 1, 2, 1 do
                        volume = value[math.random(4, 11)]
                        index = volume
                            + Vector3.new(
                                (math.random() - 0.5) * magnitude * 0.35,
                                -magnitude * (0.12 + math.random() * 0.14),
                                (math.random() - 0.5) * magnitude * 0.35
                            )
                        for unused, item in
                            ipairs(
                                pulseWeather.bolt(
                                    callback5(volume, index, 6, calculatedValue3 * 0.6),
                                    clampedValue * 0.55,
                                    0.28
                                )
                            )
                        do
                            beams[#beams + 1] = item
                        end
                    end
                    clampedValue = text == "close" and 0.26 or text == "mid" and 0.16 or 0.09
                    storm.active = { t0 = os.clock(), beams = beams }
                    storm.flashPower = clampedValue * (0.35 + calculatedValue) * (pulseWeather.cameraCovered and 0.45 or 1)
                    calculatedValue, volume =
                        text == "far" and entries.thunderFar or entries.thunderClose,
                        text == "close" and 1 or text == "mid" and 0.8 or 0.6
                    storm.thunder[#storm.thunder + 1] = {
                        at = os.clock() + 0.3 + calculatedValue2 / 430,
                        id = calculatedValue[math.random(1, #calculatedValue)],
                        volume = volume,
                        crack = text == "close",
                    }
                end
                pulseWeather.playOnce = function(equalizerSoundEffect, argument2, argument)
                    if pulseWeather.sound then
                        if not pulseWeather.folder then
                            return
                        end
                    else
                        return
                    end
                    local sound = Instance.new("Sound")
                    sound.SoundId = equalizerSoundEffect
                    sound.Volume = argument2 * pulseWeather.soundVolume / 100
                    if argument then
                        equalizerSoundEffect = Instance.new("EqualizerSoundEffect")
                        equalizerSoundEffect.HighGain = -16
                        equalizerSoundEffect.MidGain = -3
                        equalizerSoundEffect.Parent = sound
                    end
                    sound.Parent = pulseWeather.folder
                    pcall(function()
                        sound:Play()
                    end)
                    task.delay(16, function()
                        pcall(function()
                            sound:Destroy()
                        end)
                    end)
                end
                pulseWeather.stormStep = function(argument2, entry)
                    local storm = pulseWeather.storm
                    if not storm then
                        return
                    end
                    if pulseWeather.thunder then
                        if pulseWeather.stormPower > 0 then
                            if not storm.active then
                                if argument2 >= storm.nextAt then
                                    pulseWeather.strike(entry)
                                    storm.nextAt = argument2
                                        + (14 + math.random() * 30) * (1.9 - 1.6 * pulseWeather.stormPower / 100)
                                end
                            end
                        end
                    end
                    local calculatedValue, active = 0, storm.active
                    if active then
                        entry = argument2 - active.t0
                        if entry < 0.05 then
                            calculatedValue = 1
                        else
                            if entry < 0.1 then
                                calculatedValue = 0.25
                            else
                                if entry < 0.19 then
                                    calculatedValue = 0.9
                                else
                                    if entry < 0.55 then
                                        calculatedValue = 0.55 * (1 - (entry - 0.19) / 0.36)
                                    else
                                        for unused, item in ipairs(pulseWeather.boltPart:GetChildren()) do
                                            item:Destroy()
                                        end
                                        storm.active = nil
                                    end
                                end
                            end
                        end
                        if storm.active then
                            for unused, item in ipairs(active.beams) do
                                item.beam.Transparency =
                                    NumberSequence.new(1 - math.clamp(calculatedValue * item.weight * 1.6, 0, 1) * 0.96)
                            end
                        end
                    else
                    end
                    if pulseWeather.flash then
                        pulseWeather.flash.Brightness = calculatedValue * storm.flashPower
                        pulseWeather.flash.TintColor = Color3.new(1 - calculatedValue * 0.08, 1 - calculatedValue * 0.03, 1)
                    end
                    for index = #storm.thunder, 1, -1 do
                        entry = storm.thunder[index]
                        if argument2 >= entry.at then
                            pulseWeather.playOnce(entry.id, entry.volume, pulseWeather.cameraCovered)
                            if entry.crack then
                                pulseWeather.playOnce(
                                    entries.crack[math.random(1, #entries.crack)],
                                    0.5,
                                    pulseWeather.cameraCovered
                                )
                            end
                            table.remove(storm.thunder, index)
                        end
                    end
                end
                pulseWeather.wetStore = function()
                    local pulseWetStore = getgenv().__pulseWetStore
                    if type(pulseWetStore) ~= "table" then
                        pulseWetStore = {}
                        getgenv().__pulseWetStore = pulseWetStore
                    else
                    end
                    return pulseWetStore
                end
                pulseWeather.wetRestore = function()
                    local wetStoreResult = pulseWeather.wetStore()
                    for key, item in pairs(wetStoreResult) do
                        if key.Parent then
                            pcall(function()
                                key.Color = item[1]
                                key.Reflectance = item[2]
                            end)
                        end
                        wetStoreResult[key] = nil
                    end
                    pulseWeather.wetSkip = {}
                end
                pulseWeather.wetFloor = function(argument2)
                    if argument2.Transparency >= 0.5 then
                        return false
                    end
                    local size, transform = argument2.Size, argument2.CFrame
                    local y, upVector, maximumValue = size.Y, transform.UpVector, math.max(size.X, size.Z)
                    if size.X < y then
                        y, upVector, maximumValue = size.X, transform.RightVector, math.max(size.Y, size.Z)
                    else
                    end
                    if size.Z < y then
                        y, upVector, maximumValue = size.Z, transform.LookVector, math.max(size.X, size.Y)
                    else
                    end
                    return math.abs(upVector.Y) > 0.9 and y <= 6 and y < maximumValue * 0.7 and maximumValue >= 3
                end
                pulseWeather.wetPaint = function(argument2, argument3, argument)
                    local calculatedValue = pulseWeather.wetness / 100 * argument
                    argument2.Color = argument3[1]:Lerp(Color3.new(0, 0, 0), 0.3 * calculatedValue)
                    argument2.Reflectance = math.min(argument3[2] + 0.26 * calculatedValue, 0.4)
                end
                pulseWeather.wetScan = function(argument2)
                    local filterDescendantsInstances = pulseWeather.mapRoots()
                    if #filterDescendantsInstances == 0 then
                        return
                    end
                    local wetStoreResult = pulseWeather.wetStore()
                    pulseWeather.wetSkip = pulseWeather.wetSkip or {}
                    local overlapParams = OverlapParams.new()
                    overlapParams.FilterType = Enum.RaycastFilterType.Include
                    overlapParams.FilterDescendantsInstances = filterDescendantsInstances
                    overlapParams.MaxParts = 1800
                    filterDescendantsInstances = {}
                    for unused, instance in ipairs((workspace:GetPartBoundsInRadius(argument2, 64, overlapParams))) do
                        filterDescendantsInstances[instance] = true
                        if not wetStoreResult[instance] then
                            if not pulseWeather.wetSkip[instance] then
                                if instance:IsA("BasePart") then
                                    if instance:IsA("MeshPart") then
                                        pulseWeather.wetSkip[instance] = true
                                    elseif pulseWeather.wetFloor(instance) then
                                        wetStoreResult[instance] = { instance.Color, instance.Reflectance }
                                        pulseWeather.wetPaint(instance, wetStoreResult[instance], pulseWeather.wetLevel)
                                    else
                                        pulseWeather.wetSkip[instance] = true
                                    end
                                else
                                    pulseWeather.wetSkip[instance] = true
                                end
                            end
                        end
                    end
                    overlapParams = 0
                    for key in pairs(pulseWeather.wetSkip) do
                        overlapParams += 1
                        if not key.Parent then
                            pulseWeather.wetSkip[key] = nil
                        end
                    end
                    if overlapParams > 6000 then
                        pulseWeather.wetSkip = {}
                    end
                    for key, item in pairs(wetStoreResult) do
                        if key.Parent then
                            if not filterDescendantsInstances[key] then
                                if (key.Position - argument2).Magnitude > 100 then
                                    pcall(function()
                                        key.Color = item[1]
                                        key.Reflectance = item[2]
                                    end)
                                    wetStoreResult[key] = nil
                                end
                            end
                        else
                            wetStoreResult[key] = nil
                        end
                    end
                end
                pulseWeather.wetStep = function(argument2, argument3)
                    local calculatedValue = pulseWeather.on
                        and pulseWeather.wet
                        and pulseWeather.recipes[pulseWeather.kind].wet
                        and pulseWeather.wetness > 0
                    local calculatedValue2 = calculatedValue and 0.35 + 0.65 * pulseWeather.amount / 100 or 0
                    pulseWeather.wetLevel = (pulseWeather.wetLevel or 0)
                        + (calculatedValue2 - (pulseWeather.wetLevel or 0)) * (1 - math.exp(-argument2 / 7))
                    pulseWeather.wetClock = (pulseWeather.wetClock or 0) + argument2
                    if not calculatedValue then
                        if pulseWeather.wetLevel < 0.03 then
                            if next(pulseWeather.wetStore()) ~= nil then
                                pulseWeather.wetLevel = 0
                                pulseWeather.wetPainted = 0
                                pcall(pulseWeather.wetRestore)
                            end
                            return
                        end
                    end
                    if pulseWeather.wetClock < 1.3 then
                        return
                    end
                    pulseWeather.wetClock = 0
                    pcall(pulseWeather.wetScan, argument3)
                    if
                        math.abs(pulseWeather.wetLevel - (pulseWeather.wetPainted or 0)) > 0.04
                        or pulseWeather.wetnessPainted ~= pulseWeather.wetness
                    then
                        pulseWeather.wetPainted, pulseWeather.wetnessPainted = pulseWeather.wetLevel, pulseWeather.wetness
                        for key, item in pairs(pulseWeather.wetStore()) do
                            if key.Parent then
                                pcall(pulseWeather.wetPaint, key, item, pulseWeather.wetLevel)
                            end
                        end
                    end
                end
                pulseWeather.groundY = function(argument2)
                    local now = os.clock()
                    if pulseWeather.groundAt then
                        if now - pulseWeather.groundAt < 0.5 then
                            if pulseWeather.groundValue then
                                return pulseWeather.groundValue
                            end
                        end
                    end
                    pulseWeather.groundAt = now
                    now = pulseWeather.cast(argument2 + Vector3.new(0, 4, 0), Vector3.new(0, -60, 0))
                    pulseWeather.groundValue = now and now.Position.Y or argument2.Y - 3
                    return pulseWeather.groundValue
                end
                pulseWeather.settingsChanged = function()
                    if pulseWeather.uiSyncing then
                        return
                    end
                    pulseWeather.validate()
                    pulseWeather.dirty = true
                    pulseWeather.probeElapsed = 1
                    if pulseWeather.renderedKind then
                        if pulseWeather.renderedKind ~= pulseWeather.kind then
                            pulseWeather.clear()
                        end
                    end
                    if not pulseWeather.on then
                        pulseWeather.stop()
                    end
                end
                pulseWeather.setEnabled = function(argument2)
                    if pulseWeather.uiSyncing then
                        return
                    end
                    pulseWeather.on = argument2 == true
                    pulseWeather.settingsChanged()
                end
                pulseWeather.step = function(numberResult)
                    if pulseWeather.dead then
                        return
                    end
                    if not (pAlive()) then
                        pulseWeather.destroy()
                        return
                    end
                    if not pulseWeather.on then
                        if pulseWeather.folder then
                            pulseWeather.stop()
                        end
                        return
                    end
                    local camera = workspace.CurrentCamera
                    if camera == nil then
                        if pulseWeather.folder then
                            pulseWeather.stop()
                        end
                        return
                    end
                    numberResult = pulseWeather.number(numberResult, 0.016666666666666666, 0, 0.1)
                    pulseWeather.frameElapsed = pulseWeather.frameElapsed + numberResult
                    if pulseWeather.frameElapsed < 0.03333333333333333 then
                        return
                    end
                    local frameElapsed = pulseWeather.frameElapsed
                    pulseWeather.frameElapsed = 0
                    pulseWeather.phase = pulseWeather.phase + frameElapsed
                    pulseWeather.validate()
                    pulseWeather.envClock = (pulseWeather.envClock or 0) + frameElapsed
                    if pulseWeather.envClock > 1 then
                        pulseWeather.envClock = 0
                        local envDark = pulseWeather.envDark
                        pulseWeather.envStep()
                        if math.abs(envDark - pulseWeather.envDark) > 0.08 then
                            pulseWeather.dirty = true
                        end
                    end
                    local entry = pulseWeather.qualities[pulseWeather.quality]
                    if pulseWeather.failureAt then
                        if os.clock() < pulseWeather.failureAt then
                            return
                        end
                    end
                    if
                        pulseWeather.camera ~= camera
                        or not pulseWeather.folder
                        or pulseWeather.folder.Parent ~= camera
                        or pulseWeather.builtKind ~= pulseWeather.kind
                        or pulseWeather.builtQuality ~= pulseWeather.quality
                        or pulseWeather.builtSound ~= pulseWeather.sound
                    then
                        local success, result = pcall(pulseWeather.build, camera)
                        if not success then
                            pulseWeather.stop()
                            pulseWeather.failureAt = os.clock() + 3
                            warn("[F$VL] weather build failed: " .. tostring(result))
                            return
                        end
                    end
                    local transform, result = camera.CFrame, localPlayer.Character
                    local focus, result2 = transform.Position, result and (result:FindFirstChild("HumanoidRootPart"))
                    focus = if result2
                        then if (result2.Position - focus).Magnitude < 70 then result2.Position else focus
                        else focus
                    result2 = Vector3.new(transform.LookVector.X, 0, transform.LookVector.Z)
                    focus = if result2.Magnitude > 0.05 then focus + result2.Unit * 4 else focus
                    pulseWeather.focus = focus
                    if
                        pulseWeather.character ~= result
                        or pulseWeather.lastPosition and (focus - pulseWeather.lastPosition).Magnitude > 48
                    then
                        pulseWeather.clear()
                        pulseWeather.visibility = 0
                        pulseWeather.probeElapsed = 1
                        pulseWeather.filter(camera)
                    end
                    pulseWeather.character = result
                    pulseWeather.lastPosition = focus
                    if pulseWeather.dirty then
                        result2, result = pcall(pulseWeather.configure)
                        if not result2 then
                            pulseWeather.stop()
                            pulseWeather.failureAt = os.clock() + 3
                            warn("[F$VL] weather setup failed: " .. tostring(result))
                            return
                        end
                    end
                    pulseWeather.renderedKind = pulseWeather.kind
                    result2 = pulseWeather.stretchSquash()
                    if result2 ~= pulseWeather.squash then
                        pulseWeather.applySquash(result2)
                    end
                    camera, result = pulseWeather.gustValue(), math.rad(pulseWeather.windAngle)
                    result2 = Vector3.new(math.cos(result), 0, math.sin(result))
                    local position, minimumValue = Vector3.new(-result2.Z, 0, result2.X), pulseWeather.groundY(focus)
                    for key, item in ipairs(pulseWeather.nodes) do
                        result = item.layer
                        key = result.base == "ground" and minimumValue + result.y or focus.Y + result.y
                        item.part.CFrame = CFrame.new(
                            focus.X + (item.gx or 0) * (item.tile or 0),
                            key,
                            focus.Z + (item.gz or 0) * (item.tile or 0)
                        )
                    end
                    pulseWeather.probeElapsed = pulseWeather.probeElapsed + frameElapsed
                    if pulseWeather.probeElapsed >= entry.probeInterval then
                        pulseWeather.probeElapsed = 0
                        pulseWeather.probe(focus)
                    end
                    result = pulseWeather.amount == 0
                    if result then
                        if not pulseWeather.suspended then
                            pulseWeather.clear()
                        end
                    end
                    pulseWeather.suspended = result
                    minimumValue = result and 0 or 1
                    pulseWeather.visibility = pulseWeather.visibility
                        + (minimumValue - pulseWeather.visibility) * (1 - math.exp(-frameElapsed * 5))
                    if result then
                        pulseWeather.visibility = 0
                    end
                    minimumValue = pulseWeather.wind * 0.3 * camera * (pulseWeather.speed / 100) ^ 2
                    for emitter, item in ipairs(pulseWeather.nodes) do
                        local layer, calculatedValue, calculatedValue2 =
                            item.layer,
                            math.sin(pulseWeather.phase * 0.9 + item.seed) * 0.6 + math.sin(
                                pulseWeather.phase * 2.3 + item.seed * 1.7 + 1.7
                            ) * 0.4,
                            math.cos(pulseWeather.phase * 1.3 + item.seed * 0.7) * 0.5
                        local calculatedValue3, calculatedValue4, calculatedValue5 =
                            layer.noWind and Vector3.zero or result2 * minimumValue * (layer.windK or 1),
                            layer.sway or 0,
                            (layer.lift or 0) - (layer.fall or 0)
                        if layer.still then
                            item.emitter.Acceleration = result2 * (layer.drift or 0.3) * pulseWeather.wind * 0.1
                        else
                            item.emitter.Acceleration = calculatedValue3
                                + position * (calculatedValue4 * calculatedValue)
                                + result2 * (calculatedValue4 * calculatedValue2 * 0.5)
                                + Vector3.new(0, calculatedValue5, 0)
                        end
                        camera, emitter = pulseWeather.cameraCovered and not layer.noShelter
                        emitter, camera = item.emitter, item.blocked or camera
                        emitter.Rate = camera and 0 or item.rate * pulseWeather.visibility
                    end
                    if #pulseWeather.splashes > 0 and not result and not pulseWeather.cameraCovered then
                        pulseWeather.splashBudget = pulseWeather.splashBudget
                            + frameElapsed * entry.splashes * (pulseWeather.amount / 100) * pulseWeather.visibility
                        minimumValue = math.min(math.floor(pulseWeather.splashBudget), 10)
                        pulseWeather.splashBudget = pulseWeather.splashBudget - minimumValue
                        position = transform.LookVector
                        for unused = 1, minimumValue, 1 do
                            pulseWeather.splash(focus, position)
                        end
                    else
                        pulseWeather.splashBudget = 0
                    end
                    pulseWeather.audioStep(frameElapsed)
                    pulseWeather.gradeStep(frameElapsed)
                    pulseWeather.stormStep(os.clock(), focus)
                    pulseWeather.wetStep(frameElapsed, focus)
                end
                pulseWeather.reset = function()
                    pulseWeather.scene = ""
                    pulseWeather.stop()
                    for key, item in pairs(pulseWeather.defaults) do
                        pulseWeather[key] = item
                    end
                    if pulseWeather.syncUI then
                        pulseWeather.syncUI()
                    end
                end
                pcall(pulseWeather.wetRestore)
                connectSignal(game:GetService("RunService").RenderStepped, function(argument2)
                    local success, result = pcall(pulseWeather.step, argument2)
                    if not success then
                        pulseWeather.failureAt = os.clock() + 3
                        pcall(pulseWeather.stop)
                        warn("[F$VL] weather step failed: " .. tostring(result))
                    end
                end)
                callback2(function()
                    pcall(pulseWeather.destroy)
                end)

		-- ---------- weather-only presets ----------
		pulseWeather.scenes = {
			{ name = "Misty Morning", weather = { kind = "Mist", amount = 70, wind = 2 } },
			{ name = "Snow Day", weather = { kind = "Snow", amount = 55, wind = 4 } },
			{ name = "Blizzard", weather = { kind = "Snow", amount = 100, wind = 16, speed = 130 } },
			{ name = "Winter Night", weather = { kind = "Snow", amount = 45, wind = 3 } },
			{ name = "Cherry Blossom", weather = { kind = "Blossom", amount = 62, wind = 5 } },
			{ name = "Autumn", weather = { kind = "Leaves", amount = 58, wind = 7 } },
			{ name = "Golden Pollen", weather = { kind = "Pollen", amount = 62, wind = 2 } },
			{ name = "Firefly Night", weather = { kind = "Fireflies", amount = 65, wind = 1 } },
			{ name = "Bonfire Night", weather = { kind = "Embers", amount = 55, wind = 3 } },
			{ name = "Volcano", weather = { kind = "Ash", amount = 70, wind = 5 } },
		}

		local V = tbl43.visuals
		local controls = {}

		local function pickValue(v)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			return v ~= nil and tostring(v) or nil
		end

		local function numberOf(v)
			return tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or nil
		end

		local function setField(key, value)
			if pulseWeather.uiSyncing then
				return
			end
			pulseWeather[key] = value
			pulseWeather.settingsChanged()
		end

		-- puts every control back in line with the values the weather really has (without firing the callbacks)
		pulseWeather.syncUI = function()
			local was = pulseWeather.uiSyncing
			pulseWeather.uiSyncing = true
			for _, item in ipairs(controls) do
				local value = pulseWeather[item.key]
				if value ~= nil then
					if item.invert then
						value = not value
					end
					pcall(function()
						item.ctl:Set(value, true)
					end)
				end
			end
			pulseWeather.uiSyncing = was
		end

		pulseWeather.applyScene = function(name)
			local picked
			for _, item in ipairs(pulseWeather.scenes) do
				if item.name == name then
					picked = item
					break
				end
			end
			if not picked then
				return
			end
			pulseWeather.stop()
			local keep = {
				quality = true, shelter = true, sound = true, soundVolume = true, wet = true, wetness = true,
				grade = true, matchLight = true, radius = true, scale = true, ripples = true, gusts = true,
			}
			for key, item in pairs(pulseWeather.defaults) do
				if not keep[key] and not string.find(key, "olour", 1, true) then
					pulseWeather[key] = item
				end
			end
			pulseWeather.scene = name
			pulseWeather.on = true
			for key, item in pairs(picked.weather) do
				pulseWeather[key] = item
			end
			pulseWeather.settingsChanged()
			pulseWeather.syncUI()
		end

		pulseWeather.clearScene = function()
			pulseWeather.scene = ""
			pulseWeather.on = false
			pulseWeather.settingsChanged()
			pulseWeather.syncUI()
		end

		local function addToggle(key, title, desc, flag, invert)
			local ctl = V:Toggle({
				Title = title,
				Flag = flag,
				Desc = desc,
				Type = "Toggle",
				Value = false,
				Callback = function(on)
					if pulseWeather.uiSyncing then
						return
					end
					on = on and true or false
					if invert then
						on = not on
					end
					if key == "on" then
						pulseWeather.setEnabled(on)
					else
						setField(key, on)
					end
				end,
			})
			controls[#controls + 1] = { key = key, ctl = ctl, invert = invert }
			return ctl
		end

		local function addSlider(key, title, desc, flag, min, max, step)
			local ctl = V:Slider({
				Title = title,
				Flag = flag,
				Desc = desc,
				Step = step,
				Value = { Min = min, Max = max, Default = pulseWeather.defaults[key] or min },
				Callback = function(v)
					local n = numberOf(v)
					if n then
						setField(key, n)
					end
				end,
			})
			controls[#controls + 1] = { key = key, ctl = ctl }
			return ctl
		end

		local function addDropdown(key, title, desc, flag, values)
			local ctl = V:Dropdown({
				Title = title,
				Flag = flag,
				Desc = desc,
				Multi = false,
				Value = pulseWeather[key],
				Values = values,
				Callback = function(v)
					local picked = pickValue(v)
					if picked and picked ~= "" then
						setField(key, picked)
					end
				end,
			})
			controls[#controls + 1] = { key = key, ctl = ctl }
			return ctl
		end

		local function addColour(key, title, flag)
			local ctl = V:Colorpicker({
				Title = title,
				Flag = flag,
				Default = pulseWeather[key],
				Callback = function(c)
					if typeof(c) == "Color3" then
						setField(key, c)
					end
				end,
			})
			controls[#controls + 1] = { key = key, ctl = ctl }
			return ctl
		end

		-- ---------- Weather ----------
		V:Section({ Title = "Weather" })

		addToggle("on", "Enable Weather", "Particles of the chosen weather fall / drift around your camera.", "Toggle_Weather_On")
		addDropdown("kind", "Weather Type", "Snow, Blossom, Leaves, Fireflies, Mist (fog), Embers, Ash or Pollen.", "Dropdown_Weather_Type", pulseWeather.order)
		addSlider("amount", "Amount", "How much weather there is (0 = none).", "Slider_Weather_Amount", 0, 100, 1)
		addSlider("opacity", "Visibility", "How solid the particles look.", "Slider_Weather_Visibility", 20, 100, 1)
		addSlider("scale", "Particle Size", "Makes every particle smaller or bigger.", "Slider_Weather_Size", 0.5, 1.8, 0.05)

		V:Button({
			Title = "Reset Weather",
			Desc = "Switches the weather off and puts every weather setting back to its default.",
			Callback = function()
				pulseWeather.reset()
			end,
		})

		-- ---------- Presets ----------
		V:Section({ Title = "Weather Presets" })

		local sceneNames = {}
		for _, item in ipairs(pulseWeather.scenes) do
			sceneNames[#sceneNames + 1] = item.name
		end

		V:Dropdown({
			Title = "Weather Preset",
			Desc = "One click weather: picks the type, amount and wind for you and switches the weather on.",
			Placeholder = "Choose a preset",
			Multi = false,
			Values = sceneNames,
			Callback = function(v)
				if pulseWeather.uiSyncing then
					return
				end
				local name = pickValue(v)
				if name and name ~= "" then
					pulseWeather.applyScene(name)
				end
			end,
		})

		V:Button({
			Title = "Clear Preset",
			Desc = "Switches the weather off again.",
			Callback = function()
				pulseWeather.clearScene()
			end,
		})

		-- ---------- Wind ----------
		V:Section({ Title = "Weather Wind" })

		addSlider("wind", "Wind Strength", "How hard the wind pushes the particles.", "Slider_Weather_Wind", 0, 18, 0.5)
		addSlider("windAngle", "Wind Direction", "Compass angle the wind blows towards (degrees).", "Slider_Weather_WindAngle", 0, 360, 1)
		addSlider("speed", "Falling Speed", "How fast the particles move (%).", "Slider_Weather_Speed", 60, 150, 1)
		addToggle("gusts", "Steady Wind (No Gusts)", "Off = the wind swells and fades in gentle gusts. On = the wind stays constant.", "Toggle_Weather_NoGusts", true)

		-- ---------- Detail ----------
		V:Section({ Title = "Weather Detail" })

		addDropdown("quality", "Particle Budget", "Light is the easiest on FPS, Ultra is the thickest.", "Dropdown_Weather_Quality", { "Light", "Balanced", "High", "Ultra" })
		addSlider("radius", "Coverage", "How far around you the weather reaches (studs).", "Slider_Weather_Coverage", 12, 50, 1)
		addToggle("shelter", "Show Weather Indoors", "Off = the weather pauses when you are under a roof. On = it keeps falling indoors too.", "Toggle_Weather_Indoors", true)
		addToggle("grade", "Disable Weather Tint", "Off = a light colour tint matching the weather (cool for snow, warm for embers...). On = no tint.", "Toggle_Weather_NoTint", true)
		addToggle("sound", "Mute Weather Sound", "Off = soft wind / crickets / fire ambience that fits the weather. On = silent.", "Toggle_Weather_Mute", true)
		addSlider("soundVolume", "Weather Volume", "How loud the weather ambience is.", "Slider_Weather_Volume", 0, 100, 1)

		-- ---------- Colours ----------
		V:Section({ Title = "Weather Colors" })

		addColour("snowColour", "Snow Color", "Colorpicker_Weather_Snow")
		addColour("petalColour", "Petal Color", "Colorpicker_Weather_Petal")
		addColour("leafColour", "Leaf Color", "Colorpicker_Weather_Leaf")
		addColour("mistColour", "Fog / Mist Color", "Colorpicker_Weather_Mist")
		addColour("emberColour", "Ember Color", "Colorpicker_Weather_Ember")
		addColour("ashColour", "Ash Color", "Colorpicker_Weather_Ash")
		addColour("fireflyColour", "Firefly Color", "Colorpicker_Weather_Firefly")
		addColour("pollenColour", "Pollen Color", "Colorpicker_Weather_Pollen")
	end)

	if not okWeather then
		warn("[F$VL] Weather tab failed: " .. tostring(errWeather))
	end
end

-- ===== World & Camera =====
-- Features that the other hub has and this script did not: Fullbright, Time Changer, Custom Fog, Custom FOV and
-- Aspect Ratio. Everything is local to your screen and every switch puts back what it changed.
do
	local Lighting_ = game:GetService("Lighting")
	local RunService_ = game:GetService("RunService")

	tbl43.visuals:Section({ Title = "World & Camera" })

	-- ---------- Fullbright ----------
	local fb = { saved = nil, conn = nil }

	tbl43.visuals:Toggle({
		Title = "Fullbright",
		Flag = "Toggle_Fullbright",
		Desc = "Everything is lit evenly: no dark corners, no shadows.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			if fb.conn then
				fb.conn:Disconnect()
				fb.conn = nil
			end

			if on then
				fb.saved = fb.saved or {
					Brightness = Lighting_.Brightness,
					Ambient = Lighting_.Ambient,
					OutdoorAmbient = Lighting_.OutdoorAmbient,
					GlobalShadows = Lighting_.GlobalShadows,
				}

				fb.conn = RunService_.RenderStepped:Connect(function()
					Lighting_.Brightness = 2
					Lighting_.Ambient = Color3.new(1, 1, 1)
					Lighting_.OutdoorAmbient = Color3.new(1, 1, 1)
					Lighting_.GlobalShadows = false
				end)
				list2.conns[#list2.conns + 1] = fb.conn
			elseif fb.saved then
				for property, value in pairs(fb.saved) do
					pcall(function()
						Lighting_[property] = value
					end)
				end

				fb.saved = nil
			end
		end,
	})

	-- ---------- Time Changer ----------
	local tc = { on = false, time = 12, saved = nil, conn = nil }

	tbl43.visuals:Toggle({
		Title = "Time Changer",
		Flag = "Toggle_Time_Changer",
		Desc = "Locks the time of day to the hour chosen below.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			tc.on = on

			if tc.conn then
				tc.conn:Disconnect()
				tc.conn = nil
			end

			if on then
				tc.saved = tc.saved or Lighting_.ClockTime
				tc.conn = RunService_.RenderStepped:Connect(function()
					Lighting_.ClockTime = tc.time
				end)
				list2.conns[#list2.conns + 1] = tc.conn
			elseif tc.saved then
				Lighting_.ClockTime = tc.saved
				tc.saved = nil
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Time Of Day",
		Flag = "Slider_Time_Of_Day",
		Desc = "Hour of the day (0 = midnight, 12 = noon).",
		Step = 0.1,
		Value = { Min = 0, Max = 24, Default = 12 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				tc.time = n
			end
		end,
	})

	-- ---------- Custom Fog ----------
	local fog = { on = false, start = 0, finish = 400, saved = nil, conn = nil }

	tbl43.visuals:Toggle({
		Title = "Custom Fog",
		Flag = "Toggle_Custom_Fog",
		Desc = "Sets how close the fog starts and how far it ends (sliders below).",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			fog.on = on

			if fog.conn then
				fog.conn:Disconnect()
				fog.conn = nil
			end

			if on then
				fog.saved = fog.saved or { FogStart = Lighting_.FogStart, FogEnd = Lighting_.FogEnd }
				fog.conn = RunService_.RenderStepped:Connect(function()
					Lighting_.FogStart = fog.start
					Lighting_.FogEnd = math.max(fog.finish, fog.start + 1)
				end)
				list2.conns[#list2.conns + 1] = fog.conn
			elseif fog.saved then
				for property, value in pairs(fog.saved) do
					pcall(function()
						Lighting_[property] = value
					end)
				end

				fog.saved = nil
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Fog Start",
		Flag = "Slider_Fog_Start",
		Desc = "Distance (studs) where the fog begins.",
		Step = 5,
		Value = { Min = 0, Max = 2000, Default = 0 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				fog.start = n
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Fog End",
		Flag = "Slider_Fog_End",
		Desc = "Distance (studs) where the fog is solid.",
		Step = 10,
		Value = { Min = 20, Max = 5000, Default = 400 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				fog.finish = n
			end
		end,
	})

	-- ---------- Custom FOV ----------
	local fov = { on = false, value = 70, saved = nil, conn = nil }

	tbl43.visuals:Toggle({
		Title = "Custom FOV",
		Flag = "Toggle_Custom_FOV",
		Desc = "Changes how wide the camera sees. Holds the value even if the game tries to change it.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			fov.on = on

			if fov.conn then
				fov.conn:Disconnect()
				fov.conn = nil
			end

			local camera = workspace.CurrentCamera

			if on then
				fov.saved = fov.saved or (camera and camera.FieldOfView)
				fov.conn = RunService_.RenderStepped:Connect(function()
					local cam = workspace.CurrentCamera

					if cam then
						cam.FieldOfView = fov.value
					end
				end)
				list2.conns[#list2.conns + 1] = fov.conn
			elseif fov.saved and camera then
				camera.FieldOfView = fov.saved
				fov.saved = nil
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "FOV",
		Flag = "Slider_Custom_FOV",
		Desc = "Field of view in degrees (the game's normal is 70).",
		Step = 1,
		Value = { Min = 30, Max = 120, Default = 90 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				fov.value = n
			end
		end,
	})

	-- ---------- Unlock Zoom + Max Zoom (from Star Hub) ----------
	local zoom = { on = false, value = 40, saved = nil, conn = nil }

	local function applyZoom()
		local lp = game:GetService("Players").LocalPlayer

		if zoom.conn then
			zoom.conn:Disconnect()
			zoom.conn = nil
		end

		if not lp then
			return
		end

		if zoom.on then
			if zoom.saved == nil then
				zoom.saved = lp.CameraMaxZoomDistance
			end

			lp.CameraMaxZoomDistance = zoom.value

			-- the game / camera scripts may lower the limit again: put ours back
			zoom.conn = lp:GetPropertyChangedSignal("CameraMaxZoomDistance"):Connect(function()
				if zoom.on and math.abs(lp.CameraMaxZoomDistance - zoom.value) > 0.01 then
					lp.CameraMaxZoomDistance = zoom.value
				end
			end)
			list2.conns[#list2.conns + 1] = zoom.conn
		elseif zoom.saved ~= nil then
			pcall(function()
				lp.CameraMaxZoomDistance = zoom.saved
			end)
			zoom.saved = nil
		end
	end

	tbl43.visuals:Toggle({
		Title = "Unlock Zoom",
		Flag = "Toggle_Unlock_Zoom",
		Desc = "Lets you zoom the camera out further than the game normally allows. Holds the limit even if the game tries to lower it.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			zoom.on = on
			applyZoom()
		end,
	})

	tbl43.visuals:Slider({
		Title = "Max Zoom",
		Flag = "Slider_Max_Zoom",
		Desc = "How far you can zoom out, in studs (needs Unlock Zoom on).",
		Step = 5,
		Value = { Min = 15, Max = 400, Default = 40 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				zoom.value = math.clamp(n, 15, 400)

				if zoom.on then
					applyZoom()
				end
			end
		end,
	})

	-- ---------- Aspect Ratio ----------
	local aspect = { on = false, value = 0.8 }

	tbl43.visuals:Toggle({
		Title = "Aspect Ratio",
		Flag = "Toggle_Aspect_Ratio",
		Desc = "Squeezes or stretches the picture vertically (the stretched-resolution look).",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			aspect.on = on

			pcall(function()
				RunService_:UnbindFromRenderStep("FVLAspectRatio")
			end)

			if on then
				-- right after the camera has been positioned for the frame
				RunService_:BindToRenderStep("FVLAspectRatio", Enum.RenderPriority.Camera.Value + 1, function()
					local cam = workspace.CurrentCamera

					if cam then
						cam.CFrame = cam.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, aspect.value, 0, 0, 0, 1)
					end
				end)
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Aspect Ratio Amount",
		Flag = "Slider_Aspect_Ratio",
		Desc = "Below 1 = squeezed (wider look), above 1 = stretched.",
		Step = 0.05,
		Value = { Min = 0.3, Max = 1.5, Default = 0.8 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				aspect.value = n
			end
		end,
	})
end

-- ===== Color Grading + Bloom (from Star Hub): adjustable by you =====
-- A switch plus sliders for Saturation, Contrast, Brightness, Tint and Bloom intensity (the ready-made looks in the
-- Shader sections can't be tuned). Uses its own two effects in Lighting, so it stacks with the other shaders and
-- turning a switch off removes exactly what it added. Local to you.
do
	local Lighting_ = game:GetService("Lighting")

	local CG = {
		on = false,
		saturation = 0.15,
		contrast = 0.1,
		brightness = 0,
		tint = Color3.new(1, 1, 1),
		bloom = false,
		bloomIntensity = 1.2,
		cc = nil,
		bl = nil,
	}

	local function sliderNumber(value)
		return tonumber(value) or type(value) == "table" and tonumber(value.Value) or nil
	end

	local function apply()
		if CG.on then
			if not (CG.cc and CG.cc.Parent) then
				CG.cc = Instance.new("ColorCorrectionEffect")
				CG.cc.Name = "FVLColorGrade"
				CG.cc:SetAttribute("FVLKeep", true) -- FPS Boost must not switch this one off
				CG.cc.Parent = Lighting_
			end

			CG.cc.Saturation = CG.saturation
			CG.cc.Contrast = CG.contrast
			CG.cc.Brightness = CG.brightness
			CG.cc.TintColor = CG.tint
			CG.cc.Enabled = true
		elseif CG.cc then
			pcall(function()
				CG.cc:Destroy()
			end)

			CG.cc = nil
		end

		if CG.bloom then
			if not (CG.bl and CG.bl.Parent) then
				CG.bl = Instance.new("BloomEffect")
				CG.bl.Name = "FVLBloomCustom"
				CG.bl:SetAttribute("FVLKeep", true)
				CG.bl.Parent = Lighting_
			end

			CG.bl.Intensity = CG.bloomIntensity
			CG.bl.Size = 28
			CG.bl.Threshold = 0.9
			CG.bl.Enabled = true
		elseif CG.bl then
			pcall(function()
				CG.bl:Destroy()
			end)

			CG.bl = nil
		end
	end

	tbl43.visuals:Section({ Title = "Color Grading" })

	tbl43.visuals:Toggle({
		Title = "Color Grading",
		Flag = "Toggle_ColorGrade",
		Desc = "Adjust the colours of the whole screen with the sliders below. Only you see it.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			CG.on = on and true or false
			pcall(apply)
		end,
	})

	tbl43.visuals:Slider({
		Title = "Saturation",
		Flag = "Slider_ColorGrade_Saturation",
		Desc = "Below 0 drains the colour, above 0 makes it richer.",
		Step = 0.05,
		Value = { Min = -1, Max = 1, Default = 0.15 },
		Callback = function(value)
			local n = sliderNumber(value)

			if n then
				CG.saturation = n
				pcall(apply)
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Contrast",
		Flag = "Slider_ColorGrade_Contrast",
		Desc = "Difference between the darkest and the brightest parts.",
		Step = 0.05,
		Value = { Min = -0.5, Max = 1, Default = 0.1 },
		Callback = function(value)
			local n = sliderNumber(value)

			if n then
				CG.contrast = n
				pcall(apply)
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Brightness",
		Flag = "Slider_ColorGrade_Brightness",
		Desc = "Makes the whole picture lighter or darker.",
		Step = 0.05,
		Value = { Min = -0.5, Max = 0.5, Default = 0 },
		Callback = function(value)
			local n = sliderNumber(value)

			if n then
				CG.brightness = n
				pcall(apply)
			end
		end,
	})

	tbl43.visuals:Colorpicker({
		Title = "Tint",
		Flag = "Colorpicker_ColorGrade_Tint",
		Default = Color3.new(1, 1, 1),
		Callback = function(color)
			if typeof(color) == "Color3" then
				CG.tint = color
				pcall(apply)
			end
		end,
	})

	tbl43.visuals:Section({ Title = "Bloom" })

	tbl43.visuals:Toggle({
		Title = "Bloom",
		Flag = "Toggle_Bloom_Custom",
		Desc = "A soft glow around bright things. Only you see it.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			CG.bloom = on and true or false
			pcall(apply)
		end,
	})

	tbl43.visuals:Slider({
		Title = "Bloom Intensity",
		Flag = "Slider_Bloom_Custom_Intensity",
		Desc = "How strong the glow is.",
		Step = 0.1,
		Value = { Min = 0.2, Max = 3, Default = 1.2 },
		Callback = function(value)
			local n = sliderNumber(value)

			if n then
				CG.bloomIntensity = n
				pcall(apply)
			end
		end,
	})

	obj3:OnDestroy(function()
		CG.on = false
		CG.bloom = false
		pcall(apply)
	end)
end

