-- ===== FPS Boost + FPS Cap + Lite Mode (from Star Hub) =====
-- FPS Boost: a lighter, separate cousin of Performance Mode. It switches off particles, trails, beams, post effects,
-- decals and mesh textures in the workspace, drops shadows / fog / water effects and the quality level. Everything it
-- touches is remembered and put back when you switch it off. (It also hides effects YOU add, e.g. Gun Beam.)
-- FPS Cap: limits the frame rate (needs an executor with setfpscap). 0 = leave the game's own cap.
-- Lite Mode (phones): makes the ESP lighter - no avatar / Neon / Pulse looks, no skeleton, the ESP and chams update
-- less often. On by default on touch devices.
do
	local Lighting_ = game:GetService("Lighting")
	local RunService_ = game:GetService("RunService")
	local UserInputService_ = game:GetService("UserInputService")

	local FB = {
		on = false,
		token = 0,
		stash = setmetatable({}, { __mode = "k" }),
		watchWorkspace = nil,
		watchLighting = nil,
		quality = nil,
	}

	list2.fpsBoost = FB

	local function remember(inst, prop)
		local saved = FB.stash[inst]

		if not saved then
			saved = {}
			FB.stash[inst] = saved
		end

		if saved[prop] == nil then
			local ok, value = pcall(function()
				return inst[prop]
			end)

			if ok then
				saved[prop] = value
			end
		end
	end

	local function strip(inst)
		if inst:GetAttribute("FVLKeep") then
			return
		end

		if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam") or inst:IsA("Smoke") or inst:IsA("Fire") or inst:IsA("Sparkles") then
			remember(inst, "Enabled")
			inst.Enabled = false
		elseif inst:IsA("PostEffect") then
			remember(inst, "Enabled")
			inst.Enabled = false
		elseif inst:IsA("Decal") or inst:IsA("Texture") then
			remember(inst, "Transparency")
			inst.Transparency = 1
		elseif inst:IsA("MeshPart") and inst.TextureID ~= "" then
			remember(inst, "TextureID")
			inst.TextureID = ""
		end
	end

	local function dropWatchers()
		if FB.watchWorkspace then
			FB.watchWorkspace:Disconnect()
			FB.watchWorkspace = nil
		end

		if FB.watchLighting then
			FB.watchLighting:Disconnect()
			FB.watchLighting = nil
		end
	end

	local function startBoost()
		FB.token += 1

		local mine = FB.token

		pcall(function()
			remember(Lighting_, "GlobalShadows")
			Lighting_.GlobalShadows = false
		end)

		pcall(function()
			remember(Lighting_, "FogEnd")
			Lighting_.FogEnd = 1e9
		end)

		pcall(function()
			local terrain = workspace.Terrain

			if terrain then
				for _, prop in ipairs({ "WaterWaveSize", "WaterWaveSpeed", "WaterReflectance", "WaterTransparency" }) do
					remember(terrain, prop)
					terrain[prop] = 0
				end
			end
		end)

		pcall(function()
			local rendering = settings().Rendering

			if FB.quality == nil then
				FB.quality = rendering.QualityLevel
			end

			rendering.QualityLevel = Enum.QualityLevel.Level01
		end)

		-- things that appear later (new map, effects) are handled as they show up
		dropWatchers()

		local function onAdded(inst)
			if FB.on then
				task.defer(function()
					pcall(strip, inst)
				end)
			end
		end

		FB.watchWorkspace = workspace.DescendantAdded:Connect(onAdded)
		FB.watchLighting = Lighting_.DescendantAdded:Connect(onAdded)

		-- what is already there: swept in chunks so the game does not hitch
		task.spawn(function()
			for _, inst in ipairs(Lighting_:GetDescendants()) do
				pcall(strip, inst)
			end

			local count = 0

			for _, inst in ipairs(workspace:GetDescendants()) do
				if not FB.on or FB.token ~= mine then
					return
				end

				pcall(strip, inst)
				count += 1

				if count % 600 == 0 then
					RunService_.Heartbeat:Wait()
				end
			end
		end)
	end

	local function stopBoost()
		FB.token += 1
		dropWatchers()

		for inst, saved in pairs(FB.stash) do
			for prop, value in pairs(saved) do
				pcall(function()
					inst[prop] = value
				end)
			end
		end

		table.clear(FB.stash)

		pcall(function()
			settings().Rendering.QualityLevel = FB.quality or Enum.QualityLevel.Automatic
		end)

		FB.quality = nil
	end

	-- FPS cap
	local defaultCap = 60
	local capChanged = false

	pcall(function()
		local cap = getfpscap and getfpscap()

		if type(cap) == "number" and cap >= 0 and cap <= 240 then
			defaultCap = cap
		end
	end)

	local function setCap(value)
		local cap = tonumber(value) or 0

		if cap <= 0 and not capChanged then
			return
		end

		pcall(function()
			if not setfpscap then
				return
			end

			if cap > 0 then
				setfpscap(cap)
			else
				setfpscap(defaultCap)
			end
		end)

		capChanged = cap > 0
	end

	tbl43.visuals:Section({ Title = "FPS & Lite Mode" })

	tbl43.visuals:Toggle({
		Title = "FPS Boost",
		Flag = "Toggle_Perf_FpsBoost",
		Desc = "Lighter than Performance Mode: switches off particles, trails, beams, post effects, decals and mesh textures, plus shadows, fog and water effects. Fully reversible.",
		Type = "Toggle",
		Value = false,
		Callback = function(on)
			on = on and true or false

			if on == FB.on then
				return
			end

			FB.on = on

			if on then
				startBoost()
			else
				stopBoost()
			end
		end,
	})

	tbl43.visuals:Slider({
		Title = "FPS Cap",
		Flag = "Slider_Perf_FpsCap",
		Desc = "Limits the frame rate (needs an executor with setfpscap). 0 = the game's own cap.",
		Step = 10,
		Value = { Min = 0, Max = 360, Default = 0 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				setCap(n)
			end
		end,
	})

	list2.liteMode = UserInputService_.TouchEnabled

	tbl43.visuals:Toggle({
		Title = "Lite Mode (phones)",
		Flag = "Toggle_Perf_LiteMode",
		Desc = "Makes the ESP lighter on phones: no avatar / Neon / Pulse looks, no skeleton, and the ESP and chams update less often.",
		Type = "Toggle",
		Value = UserInputService_.TouchEnabled,
		Callback = function(on)
			list2.liteMode = on and true or false

			pcall(function()
				if list2.espPulseSync then
					list2.espPulseSync()
				end
			end)

			pcall(function()
				if list2.espRecolourSoon then
					list2.espRecolourSoon()
				end
			end)
		end,
	})

	obj3:OnDestroy(function()
		if FB.on then
			FB.on = false
			stopBoost()
		end

		if capChanged then
			capChanged = false

			pcall(function()
				if setfpscap then
					setfpscap(defaultCap)
				end
			end)
		end
	end)
end

