-- ===== Anti-Void =====
-- Remembers the last spot you stood on (on the ground) and puts you back there when you fall into the void.
-- "Void" = you are well below that spot, falling, and there is NO ground under you any more (a drop onto a lower
-- floor is left alone), or you are about to reach the map's FallenPartsDestroyHeight (which would kill you).
-- It stays out of the way of anything that moves you under the map on purpose: Fling (all modes), Noclip, Fly,
-- Invisible and Coin Autofarm; after a fling / respawn / teleport it waits a moment and learns a fresh safe spot.
do
	-- script re-run: drop the old loop first
	if _G.FVLAntiVoidCleanup then
		pcall(_G.FVLAntiVoidCleanup)
	end

	local RunService_ = game:GetService("RunService")
	local AV = { on = false, drop = 80, conn = nil, char = nil, safe = nil, lastPos = nil, grace = 0, cooldown = 0, lastNotify = 0 }

	local function forget()
		AV.safe, AV.lastPos = nil, nil
	end

	local function avStep()
		local character = localPlayer.Character
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local now = os.clock()

		if not (hum and root) or hum.Health <= 0 then
			forget()

			return
		end

		-- new character (respawn): start over
		if AV.char ~= character then
			AV.char = character
			forget()
			AV.grace = now + 1
		end

		-- something that moves us on purpose is running: do nothing and learn a new safe spot afterwards
		if flag33 or flag41 or flag42 or list2.farmActive or (list2.invis and list2.invis.on) then
			forget()
			AV.grace = now + 1.5

			return
		end

		local pos = root.Position

		-- a teleport (round start, map change, other features): the old safe spot is no longer meaningful
		if AV.lastPos and (pos - AV.lastPos).Magnitude > 60 then
			AV.safe = nil
			AV.grace = now + 0.5
		end

		AV.lastPos = pos

		if now < AV.grace then
			return
		end

		local vel = root.AssemblyLinearVelocity

		-- standing on something: this is a safe spot
		if hum.FloorMaterial ~= Enum.Material.Air and vel.Y > -50 then
			AV.safe = root.CFrame

			return
		end

		if not AV.safe or now < AV.cooldown then
			return
		end

		local inVoid = false

		if pos.Y < Workspace.FallenPartsDestroyHeight + 40 then
			inVoid = true
		elseif pos.Y < AV.safe.Position.Y - AV.drop and vel.Y < -15 then
			-- far below the safe spot and still falling: is there any ground under us at all?
			local rp = RaycastParams.new()

			rp.FilterType = Enum.RaycastFilterType.Exclude
			rp.FilterDescendantsInstances = { character }

			pcall(function()
				rp.RespectCanCollide = true
			end)

			local ok, hit = pcall(function()
				return Workspace:Raycast(pos, Vector3.new(0, -2000, 0), rp)
			end)

			inVoid = ok and hit == nil
		end

		if not inVoid then
			return
		end

		AV.cooldown = now + 1

		pcall(function()
			root.AssemblyLinearVelocity = Vector3.zero
			root.AssemblyAngularVelocity = Vector3.zero
			root.CFrame = AV.safe + Vector3.new(0, 3, 0)
		end)

		if now - AV.lastNotify > 3 then
			AV.lastNotify = now
			obj2:Notify({ Title = "Anti-Void", Content = "You fell into the void - sent back to your last safe spot.", Duration = 2, Icon = "shield" })
		end
	end

	local function setAntiVoid(on)
		AV.on = on and true or false

		if AV.conn then
			AV.conn:Disconnect()
			AV.conn = nil
		end

		forget()

		if AV.on then
			AV.grace = os.clock() + 1
			AV.conn = RunService_.Heartbeat:Connect(function()
				pcall(avStep)
			end)
		end
	end

	list2.el.antivoid = tbl43.player:Toggle({
		Title = "Anti-Void",
		Flag = "Toggle_Anti_Void",
		Desc = "If you fall off the map, you are put back on the last place you stood on. Pauses itself during Fling, Noclip, Fly, Invisible and Coin Autofarm.",
		Type = "Toggle",
		Value = true,
		Callback = function(value)
			setAntiVoid(value)
		end,
	})

	tbl43.player:Slider({
		Title = "Anti-Void Drop Distance",
		Flag = "Slider_Anti_Void_Drop",
		Step = 10,
		Desc = "How far (studs) below your last safe spot you must be falling, with nothing under you, before Anti-Void brings you back.",
		Value = { Min = 30, Max = 300, Default = 80 },
		Callback = function(value)
			AV.drop = math.clamp(tonumber(value) or 80, 30, 300)
		end,
	})

	_G.FVLAntiVoidCleanup = function()
		setAntiVoid(false)
	end
end

