		{ "Wicked \"Dancing Through Life\"", { idle = 92849173543269, walk = 73718308412641, run = 135515454877967, jump = 78508480717326, fall = 78147885297412, climb = 129447497744818, swim = 110657013921774, swimidle = 129183123083281 } },
		{ "Unboxed", { idle = 98281136301627, walk = 90478085024465, run = 134824450619865, jump = 121454505477205, fall = 94788218468396, climb = 121145883950231, swim = 105962919001086, swimidle = 129126268464847 } },
	}

	-- swim animations for the packs that were already here
	local PACK_SWIM = {
		["Stylish"] = { 616143378, 616144772 },
		["Zombie"] = { 616165109, 616166655 },
		["Robot"] = { 616092998, 616094091 },
		["Toy"] = { 782844582, 782845186 },
		["Cartoony"] = { 742639220, 742639812 },
		["Superhero"] = { 616119360, 616120861 },
		["Mage"] = { 707876443, 707894699 },
		["Levitation"] = { 616011509, 616012453 },
		["Vampire"] = { 1083464683, 1083467779 },
		["Elder"] = { 845401742, 845403127 },
		["Werewolf"] = { 1083222527, 1083225406 },
		["Knight"] = { 657560551, 657557095 },
		["Astronaut"] = { 891639666, 891663592 },
		["Bubbly"] = { 910028158, 910030921 },
		["Pirate"] = { 750784579, 750785176 },
		["Ninja"] = { 656119721, 656121397 },
	}

	-- { idle, walk, run, jump, fall, climb }
	local PACKS = {
		{ "Ninja", 656117400, 656121766, 656118852, 656117878, 656115606, 656114359 },
		{ "Zombie", 616158929, 616168032, 616163682, 616161997, 616157476, 616156119 },
		{ "Robot", 616088211, 616095330, 616091570, 616090535, 616087089, 616086039 },
		{ "Cartoony", 742637544, 742640026, 742638842, 742637942, 742637151, 742636889 },
		{ "Toy", 782841498, 782843345, 782842708, 782847020, 782846423, 782843869 },
		{ "Levitation", 616006778, 616013216, 616010382, 616008936, 616005863, 616003713 },
		{ "Superhero", 616111295, 616122287, 616117076, 616115533, 616108001, 616104706 },
		{ "Vampire", 1083445855, 1083473930, 1083462077, 1083455352, 1083443587, 1083439238 },
		{ "Stylish", 616136790, 616146177, 616140816, 616139451, 616134815, 616133594 },
		{ "Bubbly", 910004836, 910034870, 910025107, 910016857, 910001910, 909997997 },
		{ "Mage", 707742142, 707897309, 707861613, 707853694, 707829716, 707826056 },
		{ "Knight", 657595757, 657552124, 657564596, 658409194, 657600338, 658360781 },
		{ "Pirate", 750781874, 750785693, 750783738, 750782230, 750780242, 750779899 },
		{ "Elder", 845397899, 845403856, 845386501, 845398858, 845396048, 845392038 },
		{ "Werewolf", 1083195517, 1083178339, 1083216690, 1083218792, 1083189019, 1083182000 },
		{ "Astronaut", 891621366, 891667138, 891636393, 891627522, 891617961, 891609353 },
	}

	local emoteNames, packNames = {}, {}
	local emoteIds, packData = {}, {}

	-- Rig support. Catalog emotes are made for R15 bodies and do NOT work on R6.
	-- Emotes whose name already says R6 are R6-only. The classic Roblox emotes have an R6 version too,
	-- so they work on both: [R15+R6]. Everything else is [R15].
	local R6_IDS = {
		["Wave"] = 128777973,
		["Point"] = 128853357,
		["Cheer"] = 129423030,
		["Laugh"] = 129423131,
		["Dance 1"] = 182435998,
		["Dance 2"] = 182436842,
		["Dance 3"] = 182436935,
	}

	-- emoteIds[displayName] = { r15 = id or nil, r6 = id or nil }
	local function addEmote(rawName, id)
		local stripped = rawName:gsub("%s*[%[%(]%s*R6%s*[%]%)]", "")
		local isR6Only = stripped ~= rawName
		local base = stripped:gsub("^%s+", ""):gsub("%s+$", "")
		local info
		local tag

		if isR6Only then
			info = { r6 = id }
			tag = "R6"
		elseif R6_IDS[base] then
			info = { r15 = id, r6 = R6_IDS[base] }
			tag = "R15+R6"
		else
			info = { r15 = id }
			tag = "R15"
		end

		local display = base .. " [" .. tag .. "]"

		if not emoteIds[display] then
			emoteNames[#emoteNames + 1] = display
			emoteIds[display] = info
		end
	end

	for _, entry in ipairs(EMOTES) do
		addEmote(entry[1], entry[2])
	end

	for _, entry in ipairs(PACKS) do
		packNames[#packNames + 1] = entry[1]
		packData[entry[1]] = { idle = entry[2], walk = entry[3], run = entry[4], jump = entry[5], fall = entry[6], climb = entry[7] }
	end

	for _, entry in ipairs(MORE_EMOTES) do
		addEmote(entry[1], entry[2])
	end

	for _, entry in ipairs(MORE_PACKS) do
		if not packData[entry[1]] then
			packNames[#packNames + 1] = entry[1]
			packData[entry[1]] = entry[2]
		end
	end

	for name, ids in pairs(PACK_SWIM) do
		if packData[name] then
			packData[name].swim = ids[1]
			packData[name].swimidle = ids[2]
		end
	end

	table.sort(emoteNames, function(x, y)
		return x:lower() < y:lower()
	end)

	local state = {
		emote = emoteNames[1],
		loop = false,
		speed = 1,
		stopOnMove = false, -- off = the emote keeps playing while you walk / jump
		wanted = nil, -- the emote that should keep playing (also after you die and respawn)
		emoteRespawnConn = nil,
		respawnToken = 0,
		track = nil,
		conns = {},
		pack = packNames[1],
		activePack = nil, -- the pack that is applied (and re-applied after you respawn)
		original = {}, -- the animation ids the character had before any pack: [Animation object] = id
		respawnConn = nil,
	}

	local function warn(text)
		obj2:Notify({ Title = "Emotes", Content = text, Duration = 3, Icon = "x" })
	end

	local function getHumanoid()
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
		return character, humanoid, animator
	end

	-- ---------- emotes ----------
	local function clearTrack()
		for i = #state.conns, 1, -1 do
			pcall(function()
				state.conns[i]:Disconnect()
			end)

			state.conns[i] = nil
		end

		if state.track then
			local track = state.track
			state.track = nil

			pcall(function()
				track:Stop(0.2)
			end)
		end
	end

	-- a real stop (button / walking with "Stop Emote When Moving"): forget the emote so it is not replayed
	local function stopEmote()
		state.wanted = nil
		state.respawnToken = state.respawnToken + 1
		clearTrack()
	end

	local playEmote

	-- after you die and respawn, play the same emote again
	local function ensureRespawnReplay()
		if state.emoteRespawnConn then
			return
		end

		state.emoteRespawnConn = localPlayer.CharacterAdded:Connect(function(character)
			local name = state.wanted

			if not name then
				return
			end

			state.respawnToken = state.respawnToken + 1
			local token = state.respawnToken

			clearTrack()

			task.spawn(function()
				local humanoid = character:WaitForChild("Humanoid", 10)

				if not humanoid then
					return
				end

				character:WaitForChild("HumanoidRootPart", 10)
				humanoid:WaitForChild("Animator", 5)
				task.wait(1) -- let the game's animation script start first

				if token ~= state.respawnToken or state.wanted ~= name or localPlayer.Character ~= character then
					return
				end

				playEmote(name)
			end)
		end)

		list2.conns[#list2.conns + 1] = state.emoteRespawnConn
	end

	function playEmote(name)
		local character, humanoid, animator = getHumanoid()
		local info = emoteIds[name]

		if not humanoid or not info then
			warn("No character to play the emote on.")
			return
		end

		-- pick the animation that matches the body type
		local isR15 = humanoid.RigType == Enum.HumanoidRigType.R15
		local id = isR15 and info.r15 or info.r6

		if not id then
			if isR15 then
				warn("This emote is R6 only - you are R15.")
			else
				warn("This emote is R15 only - you are R6.")
			end
			return
		end

		clearTrack()
		state.wanted = name
		ensureRespawnReplay()

		local animation = Instance.new("Animation")
		animation.AnimationId = "rbxassetid://" .. id

		-- R6 characters sometimes have no Animator, so fall back to the Humanoid
		local loader = animator or humanoid

		local ok, track = pcall(function()
			return loader:LoadAnimation(animation)
		end)

		if not ok or not track then
			warn("Could not load that emote.")
			return
		end

		track.Looped = state.loop
		-- Action4 is the highest priority, so the walk / run / jump animations cannot override the emote
		track.Priority = Enum.AnimationPriority.Action4
		track:Play(0.2, 1, state.speed)
		state.track = track

		-- if the emote ends by itself while you are alive (not looped), forget it.
		-- If it ended because you died, keep it so it plays again after the respawn.
		state.conns[#state.conns + 1] = track.Stopped:Connect(function()
			if state.track == track then
				state.track = nil

				if humanoid.Health > 0 and character.Parent then
					state.wanted = nil
				end
			end
		end)

		-- only when "Stop Emote When Moving" is on: walking or jumping ends the emote
		if state.stopOnMove then
			state.conns[#state.conns + 1] = humanoid:GetPropertyChangedSignal("MoveDirection"):Connect(function()
				if state.stopOnMove and humanoid.MoveDirection.Magnitude > 0.1 then
					stopEmote()
				end
			end)

			state.conns[#state.conns + 1] = humanoid.Jumping:Connect(function()
				if state.stopOnMove then
					stopEmote()
				end
			end)
		end
	end

	-- ---------- animation packs ----------
	local function animateParts(character)
		local animate = character and character:FindFirstChild("Animate")

		if not animate then
			return nil
		end

		local function find(folder, name)
			local group = animate:FindFirstChild(folder)
			return group and group:FindFirstChild(name)
		end

		return animate, {
			idle = { find("idle", "Animation1"), find("idle", "Animation2") },
			walk = { find("walk", "WalkAnim") },
			run = { find("run", "RunAnim") },
			jump = { find("jump", "JumpAnim") },
			fall = { find("fall", "FallAnim") },
			climb = { find("climb", "ClimbAnim") },
			swim = { find("swim", "Swim") },
			swimidle = { find("swimidle", "SwimIdle") },
		}
	end

	-- make the game's animation script pick the new animations up straight away
	local function restartAnimate(character, animate)
		local _, humanoid, animator = getHumanoid()

		animate.Disabled = true

		if animator then
			for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
				pcall(function()
					track:Stop()
				end)
			end
		end

		animate.Disabled = false
	end

	local function applyPack(name)
		local pack = packData[name]
		local character, humanoid = getHumanoid()

		if not pack or not character or not humanoid then
			warn("No character to change.")
			return
		end

		if humanoid.RigType ~= Enum.HumanoidRigType.R15 then
			warn("Animation packs need an R15 character.")
			return
		end

		local animate, parts = animateParts(character)

		if not animate then
			warn("This character has no animation script to change.")
			return
		end

		for kind, objects in pairs(parts) do
			for _, object in ipairs(objects) do
				if object and pack[kind] then
					if state.original[object] == nil then
						state.original[object] = object.AnimationId
					end

					object.AnimationId = "rbxassetid://" .. pack[kind]
				end
			end
		end

		restartAnimate(character, animate)
		state.activePack = name

		-- keep the pack after you respawn
		if not state.respawnConn then
			state.respawnConn = localPlayer.CharacterAdded:Connect(function()
				task.wait(1.5)

				if state.activePack then
					applyPack(state.activePack)
				end
			end)
			list2.conns[#list2.conns + 1] = state.respawnConn
		end
	end

	local function resetPack()
		state.activePack = nil
		local character = localPlayer.Character
		local animate = character and character:FindFirstChild("Animate")

		for object, id in pairs(state.original) do
			if object and object.Parent then
				object.AnimationId = id
			end
		end

		table.clear(state.original)

		if animate then
			restartAnimate(character, animate)
		end
	end

	-- the Animation Bundles code (further down) uses this so a bundle and a pack do not fight
	list2.resetAnimPack = resetPack

	-- ---------- the controls ----------
	tbl43.player:Section({ Title = "Emotes & Animations" })

	local emoteDrop

	tbl43.player:Input({
		Title = "Search Emote",
		Flag = "Input_Emote_Search",
		Desc = "Type part of a name to filter the emote list. You can also search r6 or r15.",
		Placeholder = "e.g. twice, blackpink, r6",
		Callback = function(text)
			local q = tostring(text or ""):lower()
			local list = {}

			for _, n in ipairs(emoteNames) do
				if q == "" or n:lower():find(q, 1, true) then
					list[#list + 1] = n
				end
			end

			if #list == 0 then
				warn("No emotes match that.")
				return
			end

			if emoteDrop then
				emoteDrop:Refresh(list)
			end
		end,
	})

	emoteDrop = tbl43.player:Dropdown({
		Title = "Emote",
		Flag = "Dropdown_Emote",
		Desc = "Pick an emote, then press Play Emote.  [R15] = R15 only, [R6] = R6 only, [R15+R6] = works on both.",
		Multi = false,
		Value = emoteNames[1],
		Values = emoteNames,
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			if emoteIds[chosen] then
				state.emote = chosen
			end
		end,
	})

	tbl43.player:Button({
		Title = "Play Emote",
		Desc = "Plays the emote picked above. It keeps playing while you walk (see Stop Emote When Moving).",
		Callback = function()
			playEmote(state.emote)
		end,
	})

	tbl43.player:Button({
		Title = "Stop Emote",
		Desc = "Stops the emote that is playing.",
		Callback = function()
			stopEmote()
		end,
	})

	tbl43.player:Toggle({
		Title = "Loop Emote",
		Flag = "Toggle_Loop_Emote",
		Desc = "The emote repeats until you press Stop Emote. Works on the emote that is already playing too.",
		Type = "Toggle",
		Value = false,
		Callback = function(value)
			state.loop = value and true or false

			if state.track then
				pcall(function()
					state.track.Looped = state.loop
				end)
			end
		end,
	})

	tbl43.player:Toggle({
		Title = "Stop Emote When Moving",
		Flag = "Toggle_Emote_Stop_On_Move",
		Desc = "Off = the emote keeps playing while you walk or jump. On = walking or jumping stops it. Applies to the next emote you play.",
		Type = "Toggle",
		Value = false,
		Callback = function(value)
			state.stopOnMove = value and true or false
		end,
	})

	tbl43.player:Slider({
		Title = "Emote Speed",
		Flag = "Slider_Emote_Speed",
		Desc = "How fast the emote plays (1 = normal).",
		Step = 0.05,
		Value = { Min = 0.25, Max = 3, Default = 1 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				state.speed = n

				if state.track then
					pcall(function()
						state.track:AdjustSpeed(n)
					end)
				end
			end
		end,
	})

	tbl43.player:Dropdown({
		Title = "Animation Pack",
		Flag = "Dropdown_Animation_Pack",
		Desc = "How you idle, walk, run, jump, fall and climb. Pick one, then turn on the Animation Pack switch below. Changing it while the switch is on applies it straight away.",
		Multi = false,
		Value = packNames[1],
		Values = packNames,
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			if packData[chosen] then
				state.pack = chosen

				if state.packOn then
					applyPack(chosen)
				end
			end
		end,
	})

	tbl43.player:Toggle({
		Title = "Animation Pack",
		Flag = "Toggle_Animation_Pack",
		Desc = "On = uses the pack picked above (stays on after you respawn). Off = gives you your normal animations back.",
		Type = "Toggle",
		Value = false,
		Callback = function(value)
			state.packOn = value and true or false

			if state.packOn then
				applyPack(state.pack)

				-- no character yet (for example right after the config loads): keep trying for a few seconds
				if state.activePack ~= state.pack then
					task.spawn(function()
						for _ = 1, 10 do
							task.wait(1)

							if not state.packOn then
								return
							end

							applyPack(state.pack)

							if state.activePack == state.pack then
								return
							end
						end
					end)
				end
			else
				resetPack()
			end
		end,
	})

	-- ---------- emote by ID ----------
	-- Paste the ID (or the catalog link) of any emote and play it. The emote's real animation is found with the
	-- game's own emote system, then it plays like the emotes in the list, so Loop Emote, Emote Speed and
	-- Stop Emote When Moving all apply to it. Emotes in the list above were already here, so they were not added again.
	local byId = { text = "", cache = {} }

	local function emoteIdFromText(text)
		text = tostring(text or "")
		return tonumber(text:match("catalog/(%d+)") or text:match("(%d%d%d+)"))
	end

	-- the animation id an emote asset plays: the game's PlayEmote function is swapped for a spy for a moment
	local function animationIdOfEmote(assetId)
		local character, humanoid = getHumanoid()
		local animate = character and character:FindFirstChild("Animate")

		if not (humanoid and animate) then
			return nil
		end

		local found
		local oldEmote = animate:FindFirstChild("PlayEmote")
		local spy = Instance.new("BindableFunction")

		spy.OnInvoke = function(animation)
			if typeof(animation) == "Instance" and animation:IsA("Animation") then
				found = animation.AnimationId:match("%d+")
			end

			return false
		end

		if oldEmote then
			oldEmote.Name = "PlayEmote_FVLHold"
		end

		spy.Name = "PlayEmote"
		spy.Parent = animate

		pcall(function()
			humanoid:PlayEmoteAndGetAnimTrackById(assetId)
		end)

		pcall(function()
			spy:Destroy()
		end)

		if oldEmote and oldEmote.Parent then
			oldEmote.Name = "PlayEmote"
		end

		return found
	end

	local function playEmoteById(text)
		local assetId = emoteIdFromText(text)

		if not assetId then
			warn("Type an emote ID or paste its catalog link first.")
			return
		end

		local _, humanoid = getHumanoid()

		if not humanoid then
			warn("No character to play the emote on.")
			return
		end

		if humanoid.RigType ~= Enum.HumanoidRigType.R15 then
			warn("Emotes from the catalog need an R15 character.")
			return
		end

		task.spawn(function()
			local animationId = byId.cache[assetId]

			if not animationId then
				animationId = animationIdOfEmote(assetId)

				if not animationId then
					warn("Could not read that emote. Check the ID.")
					return
				end

				byId.cache[assetId] = animationId
			end

			local name = "ID " .. assetId .. " [R15]"

			if not emoteIds[name] then
				emoteIds[name] = { r15 = tonumber(animationId) }
			end

			playEmote(name)
		end)
	end

	tbl43.player:Section({ Title = "Emote by ID" })

	tbl43.player:Input({
		Title = "Emote ID",
		Flag = "Input_Emote_ById",
		Desc = "Paste the ID or the catalog link of any emote (roblox.com/catalog/ID), then press Play Emote ID.",
		Placeholder = "e.g. 3576968026",
		Default = "",
		Callback = function(value)
			byId.text = tostring(value or "")
		end,
	})

	tbl43.player:Button({
		Title = "Play Emote ID",
		Desc = "Plays the emote with the ID above. Loop Emote, Emote Speed and Stop Emote When Moving apply to it too.",
		Callback = function()
			playEmoteById(byId.text)
		end,
	})
end

-- ===== Animation Bundles (ported from the "Free anims" tab of the other script) =====
-- Load any Roblox animation bundle by its ID or catalog link: how you idle, walk, run, jump, fall, climb and swim
-- becomes the bundle's. The Animation Speed slider speeds those animations up or slows them down, and the combo
-- controls let you take the idle from one bundle and the run from another.
-- Bundles are R15 animations, so they need an R15 character.
-- NOT added again because this script already has them: the emote list, Play / Stop Emote, Loop, Emote Speed,
-- Stop Emote When Moving (the other script's "Hold") and the built-in Animation Pack.
do
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local AvatarEditorService = game:GetService("AvatarEditorService")
	local lp = Players.LocalPlayer

	local SLOTS = { "Idle", "Walk", "Run", "Jump", "Fall", "Climb", "Swim" }

	-- which folders of the game's Animate script belong to each slot
	local SLOT_FOLDERS = {
		Idle = { "idle" },
		Walk = { "walk" },
		Run = { "run" },
		Jump = { "jump" },
		Fall = { "fall" },
		Climb = { "climb" },
		Swim = { "swim", "swimidle" },
	}

	-- asset type of a bundle item -> slot (the asset type is also the property name on a HumanoidDescription)
	local ASSET_SLOT = {
		IdleAnimation = "Idle",
		WalkAnimation = "Walk",
		RunAnimation = "Run",
		JumpAnimation = "Jump",
		FallAnimation = "Fall",
		ClimbAnimation = "Climb",
		SwimAnimation = "Swim",
	}

	-- used only when a bundle item does not say what kind of animation it is: guess from its name
	local NAME_GUESS = {
		{ "climb", "ClimbAnimation" },
		{ "swim", "SwimAnimation" },
		{ "idle", "IdleAnimation" },
		{ "walk", "WalkAnimation" },
		{ "run", "RunAnimation" },
		{ "jump", "JumpAnimation" },
		{ "fall", "FallAnimation" },
	}

	local state = {
		text = "",
		loaded = nil, -- { id, name, anims = { Idle = { Animation1 = "rbxassetid://..." }, ... } }
		active = nil, -- the set of animations that is applied (and re-applied after you respawn)
		activeIds = {}, -- [animation id number] = true, used by the speed slider
		speed = 1,
		autoLoad = true,
		combo = {}, -- [slot] = { from = bundle name, anims = { ... } }
		comboSlot = "Idle",
		original = {}, -- [Animation object] = the id it had before
		baseSpeed = setmetatable({}, { __mode = "k" }), -- [track] = speed the game's animation script gave it
		lastSpeed = setmetatable({}, { __mode = "k" }), -- [track] = speed we set it to
		respawnConn = nil,
		speedConn = nil,
		busy = false,
		activeIsCombo = false, -- the applied set is the combo (not a single bundle)
	}

	local cache = {}
	local ensureHooks

	local function notify(text, bad)
		obj2:Notify({
			Title = "Animation Bundles",
			Content = text,
			Duration = 4,
			Icon = bad and "x" or "check",
		})
	end

	local function numberOf(id)
		return tonumber(tostring(id or ""):match("%d+"))
	end

	local function bundleIdFromText(text)
		text = tostring(text or "")
		return tonumber(text:match("bundles/(%d+)") or text:match("(%d%d%d+)"))
	end

	-- ---------- reading a bundle ----------
	local function assetTypeOf(item)
		local assetType = item.AssetType and tostring(item.AssetType)

		if assetType then
			-- "Enum.AssetType.IdleAnimation" -> "IdleAnimation"
			assetType = assetType:match("([%w_]+)$")

			if assetType and ASSET_SLOT[assetType] then
				return assetType
			end
		end

		local name = tostring(item.Name or ""):lower()

		for _, guess in ipairs(NAME_GUESS) do
			if name:find(guess[1], 1, true) then
				return guess[2]
			end
		end

		return nil
	end

	-- builds a throw-away R15 rig wearing the bundle's animations and reads the animation ids from its Animate script
	local function readWithRig(items)
		local description = Instance.new("HumanoidDescription")
		local used = {}

		for _, item in ipairs(items) do
			local assetType = assetTypeOf(item)

			if assetType and item.Id then
				local ok = pcall(function()
					description[assetType] = tonumber(item.Id)
				end)

				if ok then
					used[assetType] = true
				end
			end
		end

		if not next(used) then
			description:Destroy()
			return nil
		end

		local ok, rig = pcall(function()
			return Players:CreateHumanoidModelFromDescription(description, Enum.HumanoidRigType.R15)
		end)

		description:Destroy()

		if not ok or not rig then
			return nil
		end

		local anims = {}

		pcall(function()
			local animate = rig:FindFirstChild("Animate")

			if not animate then
				return
			end

			for assetType in pairs(used) do
				local slot = ASSET_SLOT[assetType]
				local found = {}

				for _, folderName in ipairs(SLOT_FOLDERS[slot]) do
					local folder = animate:FindFirstChild(folderName)

					if folder then
						for _, child in ipairs(folder:GetChildren()) do
							if child:IsA("Animation") and child.AnimationId ~= "" then
								found[child.Name] = child.AnimationId
							end
						end
					end
				end

				if next(found) then
					anims[slot] = found
				end
			end
		end)

		pcall(function()
			rig:Destroy()
		end)

		if next(anims) then
			return anims
		end

		return nil
	end

	-- fallback for executors that can load the animation assets directly
	local function readWithObjects(items)
		if type(game.GetObjects) ~= "function" then
			return nil
		end

		local anims = {}

		for _, item in ipairs(items) do
			local assetType = assetTypeOf(item)

			if assetType and item.Id then
				local ok, objects = pcall(function()
					return game:GetObjects("rbxassetid://" .. item.Id)
				end)

				if ok and objects then
					local found = {}

					for _, object in ipairs(objects) do
						for _, child in ipairs(object:GetDescendants()) do
							if child:IsA("Animation") and child.AnimationId ~= "" then
								found[child.Name] = child.AnimationId
							end
						end
					end

					if next(found) then
						anims[ASSET_SLOT[assetType]] = found
					end
				end

				task.wait()
			end
		end

		if next(anims) then
			return anims
		end

		return nil
	end

	local function fetchBundle(id)
		if cache[id] then
			return cache[id]
		end

		local ok, details = pcall(function()
			return AvatarEditorService:GetItemDetails(id, Enum.AvatarItemType.Bundle)
		end)

		if not ok or type(details) ~= "table" or type(details.BundledItems) ~= "table" then
			return nil, "Could not find that bundle. Check the ID."
		end

		local anims = readWithRig(details.BundledItems) or readWithObjects(details.BundledItems)

		if not anims then
			return nil, "That bundle has no animations that can be read."
		end

		local entry = { id = id, name = tostring(details.Name or id), anims = anims }
		cache[id] = entry

		return entry
	end

	-- ---------- applying animations ----------
	local function getCharacter()
		local character = lp.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local animate = character and character:FindFirstChild("Animate")

		return character, humanoid, animate
	end

	-- make the game's animation script pick the new animations up straight away
	local function restartAnimate(animate, humanoid)
		local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")

		animate.Disabled = true

		if animator then
			for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
				pcall(function()
					track:Stop()
				end)
			end
		end

		animate.Disabled = false
	end

	local function rebuildActiveIds()
		table.clear(state.activeIds)

		if state.active then
			for _, group in pairs(state.active) do
				for _, id in pairs(group) do
					local n = numberOf(id)

					if n then
						state.activeIds[n] = true
					end
				end
			end
		end
	end

	local function restoreOriginals()
		for object, id in pairs(state.original) do
			if object and object.Parent then
				object.AnimationId = id
			end
		end

		table.clear(state.original)
	end

	-- set = { Idle = { Animation1 = "rbxassetid://..." }, Walk = { ... }, ... }
	local function applySet(set, quiet)
		local character, humanoid, animate = getCharacter()

		if not (character and humanoid) then
			if not quiet then
				notify("No character to change.", true)
			end

			return false
		end

		if humanoid.RigType ~= Enum.HumanoidRigType.R15 then
			if not quiet then
				notify("Animation bundles need an R15 character.", true)
			end

			return false
		end

		if not animate then
			if not quiet then
				notify("This character has no animation script to change.", true)
			end

			return false
		end

		-- the built-in Animation Pack and a bundle would fight over the same animations
		if list2.resetAnimPack then
			pcall(list2.resetAnimPack)
		end

		-- slots the new set does not have go back to normal
		restoreOriginals()

		for slot, group in pairs(set) do
			for _, folderName in ipairs(SLOT_FOLDERS[slot] or {}) do
				local folder = animate:FindFirstChild(folderName)

				if folder then
					for _, child in ipairs(folder:GetChildren()) do
						if child:IsA("Animation") and group[child.Name] then
							if state.original[child] == nil then
								state.original[child] = child.AnimationId
							end

							child.AnimationId = group[child.Name]
						end
					end
				end
			end
		end

		restartAnimate(animate, humanoid)

		state.active = set
		rebuildActiveIds()
		ensureHooks()

		return true
	end

	local function resetAll()
		state.active = nil
		state.activeIsCombo = false
		rebuildActiveIds()

		local _, humanoid, animate = getCharacter()

		restoreOriginals()

		if animate and humanoid then
			restartAnimate(animate, humanoid)
		end

		-- hand the tracks back to the game at their normal speed
		for track, base in pairs(state.baseSpeed) do
			pcall(function()
				if track.IsPlaying then
					track:AdjustSpeed(base)
				end
			end)
		end

		table.clear(state.baseSpeed)
		table.clear(state.lastSpeed)
	end

	-- ---------- animation speed ----------
	local function speedStep()
		if not state.active then
			return
		end

		local character = lp.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")

		if not animator then
			return
		end

		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			local id = track.Animation and numberOf(track.Animation.AnimationId)

			if id and state.activeIds[id] then
				local last = state.lastSpeed[track]

				-- first time we see this track, or the game's animation script just changed its speed
				if last == nil or math.abs(track.Speed - last) > 0.001 then
					state.baseSpeed[track] = track.Speed

					local target = track.Speed * state.speed
					state.lastSpeed[track] = target

					if state.speed ~= 1 then
						pcall(function()
							track:AdjustSpeed(target)
						end)
					end
				end
			end
		end
	end

	local function setSpeed(n)
		state.speed = n

		for track, base in pairs(state.baseSpeed) do
			pcall(function()
				if track.IsPlaying then
					local target = base * n

					track:AdjustSpeed(target)
					state.lastSpeed[track] = target
				end
			end)
		end
	end

	-- keep the bundle after you respawn, and keep the speed applied
	function ensureHooks()
		if not state.respawnConn then
			state.respawnConn = lp.CharacterAdded:Connect(function(character)
				table.clear(state.original)
				table.clear(state.baseSpeed)
				table.clear(state.lastSpeed)

				local set = state.active

				if not set then
					return
				end

				if not state.autoLoad then
					state.active = nil
					state.activeIsCombo = false
					rebuildActiveIds()
					return
				end

				task.spawn(function()
					local humanoid = character:WaitForChild("Humanoid", 10)

					if not humanoid then
						return
					end

					character:WaitForChild("Animate", 10)
					task.wait(1.5) -- let the game's animation script start first

					if lp.Character == character and state.active == set then
						applySet(set, true)
					end
				end)
			end)

			list2.conns[#list2.conns + 1] = state.respawnConn
		end

		if not state.speedConn then
			state.speedConn = RunService.Heartbeat:Connect(speedStep)
			list2.conns[#list2.conns + 1] = state.speedConn
		end
	end

	-- when the script is closed, give the normal animations back
	list2.resetBundles = function()
		pcall(resetAll)
	end

	-- ---------- loading a bundle ----------
	local function loadBundle()
		if state.busy then
			notify("Still loading, wait a moment.", true)
			return
		end

		local id = bundleIdFromText(state.text)

		if not id then
			notify("Type a bundle ID or paste its catalog link first.", true)
			return
		end

		state.busy = true

		task.spawn(function()
			local ok, entry, err = pcall(fetchBundle, id)

			state.busy = false

			if not ok then
				notify("Could not load that bundle.", true)
				return
			end

			if not entry then
				notify(err or "Could not load that bundle.", true)
				return
			end

			state.loaded = entry

			if applySet(entry.anims) then
				state.activeIsCombo = false
				notify("Applied: " .. entry.name)
			end
		end)
	end

	-- ---------- combo ----------
	local function comboSet()
		local set = {}

		for slot, entry in pairs(state.combo) do
			set[slot] = entry.anims
		end

		if next(set) then
			return set
		end

		return nil
	end

	local function comboSummary()
		local parts = {}

		for _, slot in ipairs(SLOTS) do
			local entry = state.combo[slot]

			if entry then
				parts[#parts + 1] = slot .. ": " .. entry.from
			end
		end

		if #parts == 0 then
			return "The combo is empty."
		end

		return table.concat(parts, "  |  ")
	end

	-- ---------- the controls ----------
	tbl43.player:Section({ Title = "Animation Bundles" })

	tbl43.player:Input({
		Title = "Bundle ID or Link",
		Flag = "Input_Bundle_Id",
		Desc = "Paste the ID or the catalog link of an animation bundle (roblox.com/bundles/ID), then press Load Bundle.",
		Placeholder = "e.g. 3000 or roblox.com/bundles/3000",
		Default = "",
		Callback = function(value)
			state.text = tostring(value or "")
		end,
	})

	tbl43.player:Button({
		Title = "Load Bundle",
		Desc = "Looks the bundle up and gives your character its idle, walk, run, jump, fall, climb and swim animations. Needs R15.",
		Callback = function()
			loadBundle()
		end,
	})

	tbl43.player:Slider({
		Title = "Animation Speed",
		Flag = "Slider_Bundle_Speed",
		Desc = "How fast the bundle animations play (1 = normal).",
		Step = 0.05,
		Value = { Min = 0.25, Max = 3, Default = 1 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				setSpeed(n)
			end
		end,
	})

	tbl43.player:Toggle({
		Title = "Auto-load on Respawn",
		Flag = "Toggle_Bundle_AutoLoad",
		Desc = "On = the bundle or combo comes back by itself after you die and respawn.",
		Type = "Toggle",
		Value = true,
		Callback = function(value)
			state.autoLoad = value and true or false
		end,
	})

	tbl43.player:Button({
		Title = "Reset to Default Animations",
		Desc = "Removes the bundle or combo and gives you the game's normal animations back.",
		Callback = function()
			resetAll()
			notify("Back to the normal animations.")
		end,
	})

	tbl43.player:Section({ Title = "Animation Combo" })

	tbl43.player:Dropdown({
		Title = "Combo Slot",
		Flag = "Dropdown_Bundle_Slot",
		Desc = "Which animation to take from the bundle you loaded last.",
		Multi = false,
		Value = SLOTS[1],
		Values = SLOTS,
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			if SLOT_FOLDERS[chosen] then
				state.comboSlot = chosen
			end
		end,
	})

	tbl43.player:Button({
		Title = "Set Slot From Loaded Bundle",
		Desc = "Puts the chosen slot of the bundle you loaded last into the combo. Load another bundle and repeat for the next slot.",
		Callback = function()
			local loaded = state.loaded

			if not loaded then
				notify("Load a bundle first.", true)
				return
			end

			local anims = loaded.anims[state.comboSlot]

			if not anims then
				notify(loaded.name .. " has no " .. state.comboSlot .. " animation.", true)
				return
			end

			state.combo[state.comboSlot] = { from = loaded.name, anims = anims }
			notify(comboSummary())
		end,
	})

	tbl43.player:Button({
		Title = "Apply Combo",
		Desc = "Uses the combo you built: each slot plays the animation of the bundle you picked for it.",
		Callback = function()
			local set = comboSet()

			if not set then
				notify("The combo is empty. Use Set Slot From Loaded Bundle first.", true)
				return
			end

			if applySet(set) then
				state.activeIsCombo = true
				notify("Combo applied. " .. comboSummary())
			end
		end,
	})

	tbl43.player:Button({
		Title = "Show Combo",
		Desc = "Shows which bundle each slot of the combo comes from.",
		Callback = function()
			notify(comboSummary())
		end,
	})

	tbl43.player:Button({
		Title = "Clear Combo",
		Desc = "Empties the combo. If the combo is the one playing, you get your normal animations back.",
		Callback = function()
			local wasPlaying = state.active ~= nil and state.activeIsCombo

			state.combo = {}

			if wasPlaying then
				resetAll()
			end

			notify("Combo cleared.")
		end,
	})
end

-- ===== Avatar Skin (ported from the "Skins" sub-tab of the other script) =====
-- Wear another player's avatar as a skin: pick a player from the list (or a preset).
-- ONLY YOU CAN SEE IT: other players keep seeing your normal avatar, so the game never sees a change.
-- Two ways to wear it (the "Skin Method" dropdown):
--   Morph   = your REAL character gets the new look on your screen. Because your real body IS the skin, every other
--             feature (Aura, Trails, Runes, Client Ghost, colours, death effects ...) works on it exactly as before.
--   Overlay = your real character is hidden and a copy of the avatar follows you, copying your animations. Used when
--             Morph is blocked. Effects on your real body stay on it, and the copy mirrors the real body's
--             transparency / material / reflectance, so ghost and neon style features still show on the skin.
--   Auto    = Morph first, Overlay if Morph does not work.
-- It comes back by itself after you respawn and needs an R15 character.
-- NOT ported: showing the skin to other users of the other script (that needs its own server) and its Favorites list.
do
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local lp = Players.LocalPlayer

	local PRESETS = {
		{ name = "Iysglimt", id = 163620952 },
		{ name = "runeaid", id = 8990346215 },
		{ name = "7788s", id = 89003145 },
		{ name = "coldness", id = 1219722 },
		{ name = "reaizsym", id = 1195061435 },
		{ name = "aurqzv", id = 887330563 },
	}

	local PRESET_NAMES = {}

	for _, preset in ipairs(PRESETS) do
		PRESET_NAMES[#PRESET_NAMES + 1] = preset.name
	end

	-- the parts of the normal R15 avatar: only these (and hats / the face) are hidden, never parts other features add
	local BODY_PARTS = {
		Head = true,
		UpperTorso = true,
		LowerTorso = true,
		LeftUpperArm = true,
		LeftLowerArm = true,
		LeftHand = true,
		RightUpperArm = true,
		RightLowerArm = true,
		RightHand = true,
		LeftUpperLeg = true,
		LeftLowerLeg = true,
		LeftFoot = true,
		RightUpperLeg = true,
		RightLowerLeg = true,
		RightFoot = true,
	}

	-- description property -> the NumberValue under your Humanoid that holds your current size
	local SCALE_VALUES = {
		HeightScale = "BodyHeightScale",
		WidthScale = "BodyWidthScale",
		DepthScale = "BodyDepthScale",
		HeadScale = "HeadScale",
		BodyTypeScale = "BodyTypeScale",
		ProportionScale = "BodyProportionScale",
	}

	local STEP_NAME = "FVLAvatarSkinStep"

	-- what the copy takes over when another feature changes it on your real body
	local MIRROR_PROPS = { "Material", "Reflectance" }

	local state = {
		target = nil, -- name of the player picked in the list
		preset = PRESET_NAMES[1],
		keepSize = true,
		method = "Auto", -- Auto / Morph / Overlay
		morphed = false, -- your real character is wearing the skin
		morphDesc = nil, -- the avatar that is put on again after you respawn
		originalDesc = nil, -- your own avatar, to give back when the skin is removed
		mirror = {}, -- { { real, copy, rs, cs } } overlay only
		model = nil, -- the copy that is shown in place of your character
		cloneRoot = nil,
		cloneHum = nil,
		cloneParts = {},
		cloneHead = {}, -- the copy's head and hats (hidden while you are in first person)
		cloneRest = nil,
		realRest = nil,
		label = nil,
		character = nil, -- your character the copy is following
		alive = false,
		pairs = {}, -- { { clone = joint, real = joint } }
		hideParts = {}, -- [part of your real avatar] = true
		decals = {}, -- [face decal of your real avatar] = transparency it had
		charConns = {},
		respawnConn = nil,
		removingConn = nil,
		bound = false,
		busy = false,
		token = 0,
	}

	local function notify(text, bad)
		obj2:Notify({
			Title = "Avatar Skin",
			Content = text,
			Duration = 4,
			Icon = bad and "x" or "check",
		})
	end

	-- ---------- hiding your real avatar (on your screen only) ----------
	local function hideAdd(inst, character)
		if inst:IsA("BasePart") then
			local parent = inst.Parent

			if parent == character then
				if BODY_PARTS[inst.Name] then
					state.hideParts[inst] = true
				end
			elseif parent and parent:IsA("Accessory") and parent.Parent == character then
				state.hideParts[inst] = true
			end
		elseif inst:IsA("Decal") and inst.Name:lower() == "face" and inst.Parent and inst.Parent.Parent == character then
			if state.decals[inst] == nil then
				state.decals[inst] = inst.Transparency
			end

			inst.Transparency = 1
		end
	end

	local function showBody()
		for part in pairs(state.hideParts) do
			pcall(function()
				part.LocalTransparencyModifier = 0
			end)
		end

		for decal, transparency in pairs(state.decals) do
			pcall(function()
				decal.Transparency = transparency
			end)
		end

		table.clear(state.hideParts)
		table.clear(state.decals)
	end

	local function dropCharConns()
		for _, conn in ipairs(state.charConns) do
			pcall(function()
				conn:Disconnect()
			end)
		end

		table.clear(state.charConns)
	end

	-- ---------- standing on the ground ----------
	-- how far the soles are below the root part when the pose is neutral (read from the rig's joints)
	local function restHeight(model)
		local root = model:FindFirstChild("HumanoidRootPart")
		local foot = model:FindFirstChild("LeftFoot")

		if not (root and foot) then
			return nil
		end

		local byChild = {}

		for _, inst in ipairs(model:GetDescendants()) do
			if inst:IsA("Motor6D") then
				if inst.Part0 and inst.Part1 then
					byChild[inst.Part1] = { parent = inst.Part0, c0 = inst.C0, c1 = inst.C1 }
				end
			elseif inst:IsA("AnimationConstraint") then
				local a0, a1 = inst.Attachment0, inst.Attachment1

				if a0 and a1 and a0.Parent and a1.Parent then
					byChild[a1.Parent] = { parent = a0.Parent, c0 = a0.CFrame, c1 = a1.CFrame }
				end
			end
		end

		local chain = {}
		local part = foot
		local guard = 0

		while part and part ~= root and guard < 20 do
			local joint = byChild[part]

			if not joint then
				return nil
			end

			table.insert(chain, 1, joint)
			part = joint.parent
			guard = guard + 1
		end

		if part ~= root then
			return nil
		end

		local cf = CFrame.new()

		for _, joint in ipairs(chain) do
			cf = cf * joint.c0 * joint.c1:Inverse()
		end

		return foot.Size.Y / 2 - cf.Position.Y
	end

	-- ---------- the copy ----------
	local function fetchDescription(userId)
		local ok, description = pcall(function()
			return Players:GetHumanoidDescriptionFromUserId(userId)
		end)

		if not ok or not description then
			return nil, "Could not load that avatar"
		end

		local name = tostring(userId)
		local player = Players:GetPlayerByUserId(userId)

		if player then
			name = player.Name
		else
			pcall(function()
				name = Players:GetNameFromUserIdAsync(userId)
			end)
		end

		return description, name
	end

	-- give the avatar the size your own character has, so everything on your real body lines up with it
	local function matchMySize(description, humanoid)
		for property, valueName in pairs(SCALE_VALUES) do
			local value = humanoid:FindFirstChild(valueName)

			if value and value:IsA("NumberValue") then
				pcall(function()
					description[property] = value.Value
				end)
			end
		end
	end

	-- the copy must never push you around: the Humanoid keeps turning collisions back on, so it is forced off
	local function ghost(part)
		part.CanCollide = false
		part.CanTouch = false
		part.CanQuery = false
		part.Massless = true

		part:GetPropertyChangedSignal("CanCollide"):Connect(function()
			if part.CanCollide then
				part.CanCollide = false
			end
		end)
	end

	local function buildModel(description)
		local ok, model = pcall(function()
			return Players:CreateHumanoidModelFromDescription(description, Enum.HumanoidRigType.R15)
		end)

		if not ok or typeof(model) ~= "Instance" then
			return nil, "Could not build that avatar"
		end

		local parts = {}

		for _, inst in ipairs(model:GetDescendants()) do
			if inst:IsA("BaseScript") then
				inst:Destroy()
			elseif inst:IsA("BasePart") then
				ghost(inst)
				parts[#parts + 1] = inst
			elseif inst:IsA("BallSocketConstraint") then
				inst.Enabled = false
			end
		end

		model.DescendantAdded:Connect(function(inst)
			if inst:IsA("BasePart") then
				ghost(inst)
				parts[#parts + 1] = inst
			end
		end)

		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local root = model:FindFirstChild("HumanoidRootPart")

		if not (humanoid and root) then
			model:Destroy()
			return nil, "Could not build that avatar"
		end

		pcall(function()
			humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			humanoid.EvaluateStateMachine = false
			humanoid.BreakJointsOnDeath = false
		end)

		root.Anchored = true
		root.Transparency = 1
		model.Name = "FVLAvatarSkin"

		return { model = model, humanoid = humanoid, root = root, parts = parts }
	end

	-- ---------- following your character ----------
	local function step()
		local model = state.model
		local character = state.character

		if not (state.alive and model and model.Parent and character and character.Parent) then
			return
		end

		local root = character:FindFirstChild("HumanoidRootPart")
		local humanoid = character:FindFirstChildOfClass("Humanoid")

		if not (root and humanoid) then
			return
		end

		-- stand the copy on the same ground as you, whatever its height
		local offset

		if state.cloneRest and state.realRest then
			offset = state.cloneRest - state.realRest
		else
			offset = (state.cloneHum.HipHeight + state.cloneRoot.Size.Y / 2) - (humanoid.HipHeight + root.Size.Y / 2)
		end

		state.cloneRoot.CFrame = root.CFrame * CFrame.new(0, offset, 0)

		-- copy your pose
		for _, joint in ipairs(state.pairs) do
			joint.clone.Transform = joint.real.Transform
		end

		-- the copy shows what other features do to your real body (ghost, neon ...)
		for _, entry in ipairs(state.mirror) do
			local real, copy = entry.real, entry.copy

			if real.Parent and copy.Parent then
				if copy.Transparency ~= real.Transparency then
					copy.Transparency = real.Transparency
				end

				for _, prop in ipairs(MIRROR_PROPS) do
					local current = real[prop]
					local want = current ~= entry.rs[prop] and current or entry.cs[prop]

					if copy[prop] ~= want then
						copy[prop] = want
					end
				end
			end
		end

		-- the copy never collides with you
		for _, part in ipairs(state.cloneParts) do
			if part.CanCollide then
				part.CanCollide = false
			end
		end

		-- keep your real avatar hidden (the game's camera script keeps changing this)
		for part in pairs(state.hideParts) do
			if part.Parent then
				part.LocalTransparencyModifier = 1
			end
		end

		-- in first person the copy's head would block your view
		local camera = workspace.CurrentCamera
		local firstPerson = camera ~= nil and (camera.CFrame.Position - camera.Focus.Position).Magnitude < 1

		for _, part in ipairs(state.cloneHead) do
			part.LocalTransparencyModifier = firstPerson and 1 or 0
		end
	end

	local function bindStep()
		if not state.bound then
			state.bound = true

			RunService:BindToRenderStep(STEP_NAME, Enum.RenderPriority.Camera.Value + 2, function()
				if not pcall(step) then
					-- a joint was removed: it is looked up again on the next respawn
					state.pairs = {}
				end
			end)
		end
	end

	local function unbindStep()
		if state.bound then
			state.bound = false

			pcall(function()
				RunService:UnbindFromRenderStep(STEP_NAME)
			end)
		end
	end

	-- hook the copy up to your (new) character
	local function attach(character)
		local model = state.model

		if not model then
			return false
		end

		local humanoid = character:WaitForChild("Humanoid", 10)
		local root = character:WaitForChild("HumanoidRootPart", 10)

		if not (humanoid and root) then
			return false, "No character"
		end

		if humanoid.RigType ~= Enum.HumanoidRigType.R15 then
			return false, "Avatar Skin needs an R15 character."
		end

		character:WaitForChild("LowerTorso", 5)
		task.wait(0.3) -- let the character finish loading

		if lp.Character ~= character or state.model ~= model then
			return false
		end

		dropCharConns()
		showBody()

		-- joints are matched by name (Root, Waist, Neck, LeftShoulder ...), then your pose is copied onto the copy
		local realJoints = {}

		for _, inst in ipairs(character:GetDescendants()) do
			if inst:IsA("Motor6D") or inst:IsA("AnimationConstraint") then
				realJoints[inst.Name] = inst
			end
		end

		state.pairs = {}

		for _, joint in ipairs(model:GetDescendants()) do
			if joint:IsA("Motor6D") or joint:IsA("AnimationConstraint") then
				local real = realJoints[joint.Name]

				if real then
					local ok = pcall(function()
						joint.Transform = real.Transform
					end)

					if ok then
						state.pairs[#state.pairs + 1] = { clone = joint, real = real }
					end
				end
			end
		end

		state.realRest = restHeight(character)

		state.mirror = {}

		for name in pairs(BODY_PARTS) do
			local real = character:FindFirstChild(name)
			local copy = model:FindFirstChild(name)

			if real and copy and real:IsA("BasePart") and copy:IsA("BasePart") then
				local entry = { real = real, copy = copy, rs = {}, cs = {} }

				for _, prop in ipairs(MIRROR_PROPS) do
					entry.rs[prop] = real[prop]
					entry.cs[prop] = copy[prop]
				end

				state.mirror[#state.mirror + 1] = entry
			end
		end

		for _, inst in ipairs(character:GetDescendants()) do
			hideAdd(inst, character)
		end

		state.charConns[#state.charConns + 1] = character.DescendantAdded:Connect(function(inst)
			hideAdd(inst, character)
		end)

		state.charConns[#state.charConns + 1] = humanoid.Died:Connect(function()
			-- dead: show your real body (it falls apart) and take the copy away until you respawn
			state.alive = false
			showBody()
			model.Parent = nil
		end)

		state.character = character
		state.alive = true
		model.Parent = workspace.CurrentCamera or workspace
		bindStep()

		return true
	end

	local function stop()
		state.token = state.token + 1
		state.alive = false

		unbindStep()
		dropCharConns()
		showBody()

		if state.respawnConn then
			state.respawnConn:Disconnect()
			state.respawnConn = nil
		end

		if state.removingConn then
			state.removingConn:Disconnect()
			state.removingConn = nil
		end

		local model = state.model

		state.model = nil
		state.cloneRoot = nil
		state.cloneHum = nil
		state.character = nil
		state.label = nil
		state.cloneParts = {}
		state.cloneHead = {}
		state.cloneRest = nil
		state.realRest = nil
		state.pairs = {}
		state.mirror = {}

		if model then
			pcall(function()
				model:Destroy()
			end)
		end
	end

	-- ---------- morph: the avatar goes on your real character ----------
	-- the change is only on your screen; the game and other players still have your normal avatar
	local function applyMorph(humanoid, description)
		local finished, ok, err = false, false, nil

		task.spawn(function()
			ok, err = pcall(function()
				humanoid:ApplyDescription(description)
			end)

			finished = true
		end)

		local waited = 0

		while not finished and waited < 20 do
			task.wait(0.1)
			waited = waited + 0.1
		end

		if not finished then
			return false, "timed out"
		end

		return ok, err
	end

	-- remember your own avatar before the first change, to give it back later
	local function captureOriginal(humanoid)
		if state.morphed and state.originalDesc then
			return
		end

		local ok, description = pcall(function()
			return humanoid:GetAppliedDescription()
		end)

		if not ok or not description then
			ok, description = pcall(function()
				return Players:GetHumanoidDescriptionFromUserId(lp.UserId)
			end)
		end

		if ok and description then
			state.originalDesc = description
		end
	end

	local function restoreOriginal()
		local original = state.originalDesc

		state.morphDesc = nil
		state.morphed = false

		local character = lp.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")

		if humanoid and original then
			applyMorph(humanoid, original)
		end
	end

	local function startRespawnHooks()
		if state.respawnConn then
			return
		end

		state.respawnConn = lp.CharacterAdded:Connect(function(character)
			state.alive = false
			dropCharConns()
			state.pairs = {}
			table.clear(state.hideParts)
			table.clear(state.decals)

			local token = state.token

			task.spawn(function()
				if state.token ~= token then
					return
				end

				if state.model then
					attach(character)
				elseif state.morphDesc then
					local humanoid = character:WaitForChild("Humanoid", 10)

					if not humanoid then
						return
					end

					task.wait(2) -- let the game give you your normal avatar first

					if lp.Character == character and state.morphDesc and state.token == token then
						applyMorph(humanoid, state.morphDesc)
					end
				end
			end)
		end)

		state.removingConn = lp.CharacterRemoving:Connect(function()
			state.alive = false

			if state.model then
				state.model.Parent = nil
			end
		end)
	end

	-- wear the saved avatar of a user ID
	local function wear(userId)
		if not userId then
			notify("Pick a player first.", true)
			return
		end

		if state.busy then
			notify("Still loading, wait a moment.", true)
			return
		end

		local character = lp.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")

		if not humanoid then
			notify("No character to put the skin on.", true)
			return
		end

		if humanoid.RigType ~= Enum.HumanoidRigType.R15 then
			notify("Avatar Skin needs an R15 character.", true)
			return
		end

		state.busy = true

		task.spawn(function()
			local description, name = fetchDescription(userId)

			if not description then
				state.busy = false
				notify(name or "Could not load that avatar", true)
				return
			end

			if state.keepSize then
				matchMySize(description, humanoid)
			end

			local method = state.method
			local morphError

			-- 1) Morph: the avatar goes on your real character, so every feature works on it
			if method ~= "Overlay" then
				captureOriginal(humanoid)

				local ok, err = applyMorph(humanoid, description)

				if ok then
					stop() -- takes an overlay copy away if there was one
					state.morphDesc = description
					state.morphed = true
					state.label = name
					startRespawnHooks()
					state.busy = false
					notify("Skin on (Morph): " .. tostring(name))
					return
				end

				morphError = tostring(err)

				if method == "Morph" then
					state.busy = false
					notify("Morph did not work here (" .. morphError .. "). Try the Overlay method.", true)
					return
				end
			end

			-- 2) Overlay: a copy of the avatar follows you
			if state.morphed then
				restoreOriginal()
			end

			local built, err = buildModel(description)

			state.busy = false

			if not built then
				notify(err or "Could not build that avatar", true)
				return
			end

			-- swap the old skin (if any) for the new one
			stop()

			state.model = built.model
			state.cloneHum = built.humanoid
			state.cloneRoot = built.root
			state.cloneParts = built.parts
			state.cloneRest = restHeight(built.model)
			state.label = name

			for _, part in ipairs(built.parts) do
				if part.Name == "Head" or (part.Parent and part.Parent:IsA("Accessory")) then
					state.cloneHead[#state.cloneHead + 1] = part
				end
			end

			startRespawnHooks()

			local ok, attachErr = attach(lp.Character or character)

			if ok then
				if morphError then
					notify("Morph is blocked here, so the overlay copy is on: " .. tostring(name))
				else
					notify("Skin on (Overlay): " .. tostring(name))
				end
			else
				stop()
				notify(attachErr or "Could not put the skin on.", true)
			end
		end)
	end

	-- when the script is closed, give you your own look back
	list2.resetAvatarSkin = function()
		pcall(stop)

		if state.morphed then
			task.spawn(function()
				pcall(restoreOriginal)
			end)
		end
	end

	-- ---------- the controls ----------
	local function playerNames()
		local names = {}

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= lp then
				names[#names + 1] = player.Name
			end
		end

		return names
	end

	tbl43.player:Section({ Title = "Avatar Skin" })

	tbl43.player:Paragraph({
		Title = "Only you can see this",
		Desc = "Other players keep seeing your normal avatar. On your screen you look like the avatar you pick, and the other features (Aura, Trails, Client Ghost ...) work on it. Needs R15.",
	})

	local playerDropdown = tbl43.player:Dropdown({
		Title = "Player",
		Desc = "Pick the player whose avatar you want to wear. The list updates when players join or leave.",
		Multi = false,
		Value = nil,
		Values = playerNames(),
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			if Players:FindFirstChild(chosen) then
				state.target = chosen
			end
		end,
	})

	local function refreshPlayers()
		pcall(function()
			playerDropdown:Refresh(playerNames())
		end)
	end

	list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(refreshPlayers)
	list2.conns[#list2.conns + 1] = Players.PlayerRemoving:Connect(refreshPlayers)

	tbl43.player:Button({
		Title = "Wear Skin",
		Desc = "Puts the avatar of the picked player on you. It comes back after you respawn.",
		Callback = function()
			local player = state.target and Players:FindFirstChild(state.target)

			if not player then
				notify("Pick a player first (they may have left).", true)
				return
			end

			wear(player.UserId)
		end,
	})

	tbl43.player:Button({
		Title = "Refresh Players",
		Desc = "Reloads the player list.",
		Callback = function()
			refreshPlayers()
			notify("Player list updated.")
		end,
	})

	tbl43.player:Button({
		Title = "Remove Skin",
		Desc = "Takes the skin off and shows your real avatar again.",
		Callback = function()
			if state.morphed then
				stop()

				task.spawn(function()
					restoreOriginal()
					notify("Skin removed.")
				end)
			elseif state.model then
				stop()
				notify("Skin removed.")
			else
				notify("No skin is on.", true)
			end
		end,
	})

	tbl43.player:Toggle({
		Title = "Keep My Body Size",
		Flag = "Toggle_Avatar_Skin_KeepSize",
		Desc = "On = the skin gets your body size, so Aura, Trails and other effects on your real body line up with it. Off = it keeps its own size. Applies the next time you wear a skin.",
		Type = "Toggle",
		Value = true,
		Callback = function(value)
			state.keepSize = value and true or false
		end,
	})

	tbl43.player:Dropdown({
		Title = "Skin Method",
		Flag = "Dropdown_Avatar_Skin_Method",
		Desc = "Morph = your real character gets the new look on your screen, so every feature works on it. Overlay = a copy follows you (use it if Morph is blocked). Auto = Morph first, then Overlay. Applies the next time you wear a skin.",
		Multi = false,
		Value = "Auto",
		Values = { "Auto", "Morph", "Overlay" },
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			if chosen == "Auto" or chosen == "Morph" or chosen == "Overlay" then
				state.method = chosen
			end
		end,
	})

	tbl43.player:Dropdown({
		Title = "Preset Skin",
		Flag = "Dropdown_Avatar_Skin_Preset",
		Desc = "Ready-made avatars to wear.",
		Multi = false,
		Value = PRESET_NAMES[1],
		Values = PRESET_NAMES,
		Callback = function(value)
			local chosen = tostring(type(value) == "table" and (value[1] or value.Value) or value)

			for _, preset in ipairs(PRESETS) do
				if preset.name == chosen then
					state.preset = chosen
				end
			end
		end,
	})

	tbl43.player:Button({
		Title = "Wear Preset",
		Desc = "Wears the preset chosen above.",
		Callback = function()
			for _, preset in ipairs(PRESETS) do
				if preset.name == state.preset then
					wear(preset.id)
					return
				end
			end
		end,
	})
end

-- ===== Extra features: Fake Lag, Robloxegor Speed, Fake Knife, Spam Emotes =====
-- Ported from snpware. (Bang / Get Sucked / Get Banged were left out on purpose.)
do
	local Lighting_ = game:GetService("Lighting")
	local conns = {} -- everything we connect, so the menu can clean up when it closes

	local function track(conn)
		conns[#conns + 1] = conn
		return conn
	end

	local function num(v, fallback)
		return tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or fallback
	end

	local function getChar()
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local root = character and character:FindFirstChild("HumanoidRootPart")
		return character, humanoid, root
	end

	local function notify(title, text)
		pcall(function()
			obj2:Notify({ Title = title, Content = text, Duration = 3, Icon = "x" })
		end)
	end

	----------------------------------------------------------------------
	-- Fake Lag
	----------------------------------------------------------------------
	local FL = { on = false, interval = 0.07, anchor = 0.4, tp = false, tpDist = 10, token = 0 }

	local function releaseRoot()
		local _, _, root = getChar()
		if root then
			root.Anchored = false
		end
	end

	local function startFakeLag()
		FL.token = FL.token + 1
		local token = FL.token

		task.spawn(function()
			while FL.on and FL.token == token do
				local _, humanoid, root = getChar()

				if root and humanoid and humanoid.Health > 0 then
					root.Anchored = true
					task.wait(FL.anchor)

					if root.Parent then
						root.Anchored = false
					end

					if FL.tp and humanoid.Parent and humanoid.MoveDirection.Magnitude > 0 and root.Parent then
						local dist = math.random(1, math.max(1, math.floor(FL.tpDist * 100))) / 100
						root.CFrame = root.CFrame + humanoid.MoveDirection.Unit * dist
					end
				end

				task.wait(FL.interval)
			end

			releaseRoot()
		end)
	end

	tbl43.troll:Section({ Title = "Fake Lag" })

	tbl43.troll:Toggle({
		Title = "Fake Lag",
		Flag = "Toggle_Fake_Lag",
		Desc = "Freezes your character in short bursts so you look laggy to other players.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			FL.on = v and true or false

			if FL.on then
				startFakeLag()
			else
				FL.token = FL.token + 1
				releaseRoot()
			end
		end,
	})

	tbl43.troll:Slider({
		Title = "Fake Lag Interval",
		Flag = "Slider_Fake_Lag_Interval",
		Desc = "Time between freezes (1 = 0.01 s, 100 = 1 s).",
		Step = 1,
		Value = { Min = 1, Max = 100, Default = 7 },
		Callback = function(v)
			FL.interval = math.clamp(num(v, 7), 1, 100) / 100
		end,
	})

	tbl43.troll:Slider({
		Title = "Fake Lag Freeze Time",
		Flag = "Slider_Fake_Lag_Freeze",
		Desc = "How long each freeze lasts (30 = 0.3 s, 200 = 2 s).",
		Step = 1,
		Value = { Min = 30, Max = 200, Default = 40 },
		Callback = function(v)
			FL.anchor = math.clamp(num(v, 40), 30, 200) / 100
		end,
	})

	tbl43.troll:Toggle({
		Title = "Fake Lag [Wifi]",
		Flag = "Toggle_Fake_Lag_Wifi",
		Desc = "After each freeze you jump forward a little, like a bad connection catching up.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			FL.tp = v and true or false
		end,
	})

	tbl43.troll:Slider({
		Title = "Wifi Jump Distance",
		Flag = "Slider_Fake_Lag_Wifi_Distance",
		Desc = "Biggest jump forward, in studs.",
		Step = 1,
		Value = { Min = 5, Max = 50, Default = 10 },
		Callback = function(v)
			FL.tpDist = math.clamp(num(v, 10), 5, 50)
		end,
	})

	----------------------------------------------------------------------
	-- Robloxegor Speed
	----------------------------------------------------------------------
	local EG = { on = false, run = nil, speed = nil, track = nil, oldSpeed = 16 }
	local EGOR_ANIM = "rbxassetid://913376220"

	local function stopEgor()
		if EG.run then
			EG.run:Disconnect()
			EG.run = nil
		end

		if EG.speed then
			EG.speed:Disconnect()
			EG.speed = nil
		end

		if EG.track then
			pcall(function()
				EG.track:Stop()
			end)
			EG.track = nil
		end

		local _, humanoid = getChar()

		if humanoid then
			humanoid.WalkSpeed = EG.oldSpeed

			for _, t in ipairs(humanoid:GetPlayingAnimationTracks()) do
				if t.Animation and t.Animation.AnimationId == EGOR_ANIM then
					t:Stop()
				end
			end
		end
	end

	local function startEgor()
		stopEgor()

		local _, humanoid = getChar()

		if not humanoid then
			return
		end

		EG.oldSpeed = humanoid.WalkSpeed > 3 and humanoid.WalkSpeed or 16
		humanoid.WalkSpeed = 3

		EG.speed = humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
			if EG.on and humanoid.WalkSpeed ~= 3 then
				humanoid.WalkSpeed = 3
			end
		end)

		local animation = Instance.new("Animation")
		animation.AnimationId = EGOR_ANIM

		local loader = humanoid:FindFirstChildOfClass("Animator") or humanoid
		local ok, egorTrack = pcall(function()
			return loader:LoadAnimation(animation)
		end)

		if not ok or not egorTrack then
			notify("Robloxegor", "Could not load the animation.")
			return
		end

		egorTrack.Priority = Enum.AnimationPriority.Movement
		egorTrack.Looped = true
		egorTrack:AdjustSpeed(6)
		EG.track = egorTrack

		EG.run = RunService.RenderStepped:Connect(function()
			if not humanoid.Parent then
				if EG.run then
					EG.run:Disconnect()
					EG.run = nil
				end
				return
			end

			if humanoid.MoveDirection.Magnitude == 0 then
				if egorTrack.IsPlaying then
					egorTrack:Stop()
				end
			elseif not egorTrack.IsPlaying then
				egorTrack:Play()
				egorTrack:AdjustSpeed(6)
			end
		end)
	end

	tbl43.troll:Toggle({
		Title = "Robloxegor Speed",
		Flag = "Toggle_Robloxegor",
		Desc = "Slow walk speed with a very fast running animation, so you look like you are sliding.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			EG.on = v and true or false

			if EG.on then
				startEgor()
			else
				stopEgor()
			end
		end,
	})

	track(localPlayer.CharacterAdded:Connect(function()
		if EG.run then
			EG.run:Disconnect()
			EG.run = nil
		end

		if EG.speed then
			EG.speed:Disconnect()
			EG.speed = nil
		end

		EG.track = nil

		if EG.on then
			task.wait(0.4)

			if EG.on then
				startEgor()
			end
		end
	end))

	----------------------------------------------------------------------
	-- Fake Knife
	----------------------------------------------------------------------
	local FK = { on = false, tool = nil, conns = {}, canAttack = true, attacking = false, fling = false, flinging = false, charConn = nil }
	local KNIFE_ANIMS = { "rbxassetid://2467567750", "rbxassetid://1957890538" }

	local function cleanKnife()
		FK.flinging = false
		FK.attacking = false

		if FK.tool then
			pcall(function()
				FK.tool:Destroy()
			end)
			FK.tool = nil
		end

		for _, c in ipairs(FK.conns) do
			pcall(function()
				c:Disconnect()
			end)
		end

		FK.conns = {}
	end

	-- optional: while the fake knife is held, touching players flings them (off by default)
	local function startKnifeFling(tool)
		local n = 0.1

		while FK.tool and FK.tool == tool do
			RunService.Heartbeat:Wait()

			if FK.flinging and FK.fling then
				local _, _, root = getChar()

				if root then
					local velocity = root.Velocity
					root.Velocity = velocity * 1000000 + Vector3.new(0, 1000000, 0)
					RunService.RenderStepped:Wait()
					root.Velocity = velocity
					RunService.Stepped:Wait()
					root.Velocity = velocity + Vector3.new(0, n, 0)
					n = -n
				end
			end
		end
	end

	local function createKnife()
		if FK.tool then
			cleanKnife()
		end

		local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()
		local root = character:WaitForChild("HumanoidRootPart", 5)

		if not root then
			return
		end

		local tool = Instance.new("Tool")
		tool.Name = "Fake Knife"
		tool.CanBeDropped = false
		tool.RequiresHandle = true
		tool.TextureId = "rbxassetid://138663675657207"
		tool.Grip = CFrame.new(0, -1, -0.1, 1, 0, 0, 0, 1, 0, 0, 0, 1)

		local handle = Instance.new("Part")
		handle.Name = "Handle"
		handle.Size = Vector3.new(0.4, 3, 0.7)
		handle.Color = Color3.new(0.639216, 0.635294, 0.647059)
		handle.CanCollide = false
		handle.Parent = tool

		local mesh = Instance.new("SpecialMesh")
		mesh.Name = "Mesh"
		mesh.MeshId = "http://www.roblox.com/asset/?id=121944778"
		mesh.TextureId = "http://www.roblox.com/asset/?id=121944805"
		mesh.MeshType = Enum.MeshType.FileMesh
		mesh.Parent = handle

		local sound = Instance.new("Sound")
		sound.SoundId = "rbxassetid://142247768"
		sound.Volume = 0.8
		sound.Parent = root

		FK.tool = tool
		FK.canAttack = true

		FK.conns[#FK.conns + 1] = tool.Equipped:Connect(function()
			FK.flinging = true
		end)

		FK.conns[#FK.conns + 1] = tool.Unequipped:Connect(function()
			FK.flinging = false
			FK.attacking = false
		end)

		FK.conns[#FK.conns + 1] = tool.Activated:Connect(function()
			if not FK.canAttack then
				return
			end

			FK.canAttack = false
			FK.attacking = true

			local _, humanoid = getChar()

			if humanoid then
				local animation = Instance.new("Animation")
				animation.AnimationId = KNIFE_ANIMS[math.random(1, #KNIFE_ANIMS)]

				local loader = humanoid:FindFirstChildOfClass("Animator") or humanoid
				local ok, slash = pcall(function()
					return loader:LoadAnimation(animation)
				end)

				if ok and slash then
					slash.Priority = Enum.AnimationPriority.Action
					slash:Play()
				end
			end

			task.wait(0.5)
			FK.attacking = false
			task.wait(0.25)
			FK.canAttack = true
		end)

		local function onHandTouched(hit)
			if FK.tool and FK.tool.Parent == character and FK.attacking then
				local parent = hit.Parent

				if parent and parent ~= character and parent:FindFirstChildOfClass("Humanoid") and not sound.IsPlaying then
					sound:Play()
				end
			end
		end

		local hand = character:FindFirstChild("RightHand", true) or character:FindFirstChild("Right Arm", true)

		if hand then
			FK.conns[#FK.conns + 1] = hand.Touched:Connect(onHandTouched)
		end

		local backpack = localPlayer:FindFirstChildOfClass("Backpack")

		if backpack then
			tool.Parent = backpack
		end

		task.spawn(startKnifeFling, tool)
	end

	tbl43.troll:Section({ Title = "Fake Knife" })

	tbl43.troll:Toggle({
		Title = "Fake Knife",
		Flag = "Toggle_Fake_Knife",
		Desc = "Gives you a knife tool that only you can see work: slash animation and stab sound, no damage.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			FK.on = v and true or false

			if FK.charConn then
				FK.charConn:Disconnect()
				FK.charConn = nil
			end

			if FK.on then
				task.spawn(createKnife)

				FK.charConn = localPlayer.CharacterAdded:Connect(function()
					cleanKnife()
					task.wait(0.5)

					if FK.on then
						createKnife()
					end
				end)
			else
				cleanKnife()
			end
		end,
	})

	tbl43.troll:Toggle({
		Title = "Fake Knife Fling",
		Flag = "Toggle_Fake_Knife_Fling",
		Desc = "Holding the fake knife also makes you fling players you touch (this is what the snpware knife did). Off by default.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			FK.fling = v and true or false
		end,
	})

	----------------------------------------------------------------------
	-- Spam Emotes
	----------------------------------------------------------------------
	local SP = { on = false, speed = 1, token = 0 }
	local EMOTE_SPAM_LIST = { "sit", "ninja", "dab", "zen", "floss", "headless", "zombie", "wave", "cheer", "laugh" }

	local function fireEmote(name)
		local remotes = ReplicatedStorage:FindFirstChild("Remotes")
		local misc = remotes and remotes:FindFirstChild("Misc")
		local ev = misc and misc:FindFirstChild("PlayEmote")

		if not ev then
			return false
		end

		if ev:IsA("BindableEvent") then
			ev:Fire(name)
		elseif ev:IsA("RemoteEvent") then
			ev:FireServer(name)
		else
			return false
		end

		return true
	end

	tbl43.player:Section({ Title = "Spam Emotes" })

	tbl43.player:Toggle({
		Title = "Spam Emotes",
		Flag = "Toggle_Spam_Emotes",
		Desc = "Plays the game's own emotes (sit, ninja, dab, zen, floss, headless, zombie, wave, cheer, laugh) over and over in random order.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			SP.on = v and true or false
			SP.token = SP.token + 1
			local token = SP.token

			if not SP.on then
				return
			end

			task.spawn(function()
				while SP.on and SP.token == token do
					if not fireEmote(EMOTE_SPAM_LIST[math.random(1, #EMOTE_SPAM_LIST)]) then
						notify("Spam Emotes", "This game has no emote event here.")
						SP.on = false
						return
					end

					task.wait(1 / math.clamp(SP.speed, 1, 10))
				end
			end)
		end,
	})

	tbl43.player:Slider({
		Title = "Emote Spam Speed",
		Flag = "Slider_Emote_Spam_Speed",
		Desc = "Emotes per second.",
		Step = 1,
		Value = { Min = 1, Max = 10, Default = 1 },
		Callback = function(v)
			SP.speed = math.clamp(num(v, 1), 1, 10)
		end,
	})

	obj3:OnDestroy(function()
		FL.on = false
		FL.token = FL.token + 1
		releaseRoot()

		EG.on = false
		stopEgor()

		FK.on = false
		cleanKnife()

		if FK.charConn then
			FK.charConn:Disconnect()
			FK.charConn = nil
		end

		SP.on = false
		SP.token = SP.token + 1

		for _, c in ipairs(conns) do
			pcall(function()
				c:Disconnect()
			end)
		end
	end)
end

-- ===== Mini Me (Troll & Fun) =====
-- A tiny copy of a character (yours, or any player picked in the list) that floats next to you. It follows you
-- smoothly, bobs up and down a little, and you can choose the animation and the pose it plays. It only exists on
-- your own screen.
-- R6 / R15 is automatic and fast: the rig of every animation / pose you pick is read straight from its keyframe
-- data (instant), with a hidden R6 + R15 test dummy running at the same time as a backup, and the result is
-- remembered. The little one is then rebuilt as that rig (from the avatar of the copied player). If the animation
-- and the pose need different rigs, the pose wins and the animation is skipped.
-- Animation + pose together is automatic too: the animation moves the joints it really moves and the pose holds
-- every other joint, so you see both at once with nothing to adjust.
do
	local okMM, errMM = pcall(function()
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local lp = Players.LocalPlayer

		-- label -> animation id
		local ANIM_LIST = {
			{ "None", nil },
			{ "Wave (R15)", 507770239 },
			{ "Point (R15)", 507770453 },
			{ "Cheer (R15)", 507770677 },
			{ "Laugh (R15)", 507770818 },
			{ "Dance 1 (R15)", 507771019 },
			{ "Dance 2 (R15)", 507776043 },
			{ "Dance 3 (R15)", 507777268 },
			{ "Shrug (R15)", 3576968026 },
			{ "Wave (R6)", 128777973 },
			{ "Point (R6)", 128853357 },
			{ "Cheer (R6)", 129423030 },
			{ "Laugh (R6)", 129423131 },
			{ "Dance (R6)", 182435998 },
		}
		local POSE_LIST = {
			{ "None", nil },
			{ "123289713198454", 123289713198454 },
			{ "Pumpkin King", 105381637724646 },
		}

		local function labels(list)
			local t = {}
			for _, e in ipairs(list) do
				t[#t + 1] = e[1]
			end
			return t
		end

		local function lookup(list, label)
			for _, e in ipairs(list) do
				if e[1] == label then
					return e[2]
				end
			end
			return nil
		end

		local MM = {
			on = false,
			who = "Me",
			size = 0.35,
			side = "Right",
			dist = 3,
			height = 2.5,
			bob = 0.4,
			smooth = 2.2, -- follow speed: low = slow, lazy float
			dir = nil,
			pos = nil,
			vel = nil,
			animName = "None",
			poseName = "None",
			customAnim = "",
			customPose = "",
			model = nil,
			root = nil,
			animator = nil,
			rig = nil, -- rig of the little one right now ("R6" / "R15")
			activeAnim = nil, -- id of the animation that was started with the Play button
			loop = true, -- Loop Animation toggle
			animTrack = nil,
			tracks = {},
			mix = nil, -- animation + pose mixer (hidden rigs that feed the little one)
			playToken = 0,
			cf = nil,
			token = 0,
			animToken = 0,
			building = false,
			nextTry = 0,
			conn = nil,
			charConn = nil,
		}

		local function note(content, icon)
			pcall(function()
				obj2:Notify({ Title = "Mini Me", Content = content, Duration = 3, Icon = icon or "check" })
			end)
		end

		local function pickName(v)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			return v and tostring(v) or nil
		end

		local function toNumber(v)
			return tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or nil
		end

		local function digits(text)
			return string.match(tostring(text or ""), "%d+")
		end

		local function animId()
			local custom = digits(MM.customAnim)
			if custom and #custom >= 5 then
				return custom
			end
			local id = lookup(ANIM_LIST, MM.animName)
			return id and tostring(id) or nil
		end

		local function poseId()
			local custom = digits(MM.customPose)
			if custom and #custom >= 5 then
				return custom
			end
			local id = lookup(POSE_LIST, MM.poseName)
			return id and tostring(id) or nil
		end

		-- ------------------------------------------------------- rig detection
		local KFSProvider = game:GetService("KeyframeSequenceProvider")
		local dummies = {} -- [rig] = hidden test dummy
		local creating = {}
		local rigCache = {} -- [id] = "R6" / "R15" / false (checked, rig unknown)
		local descCache = {} -- [userId] = HumanoidDescription
		local resolvedIds = {} -- [id] = real animation url
		local probeBusy = false

		local R6_PARTS = {
			Torso = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
		}
		local R15_PARTS = {
			UpperTorso = true, LowerTorso = true,
			LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
			RightUpperArm = true, RightLowerArm = true, RightHand = true,
			LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
			RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
		}

		-- Some IDs are not the animation itself (catalog emotes, models ...). Like your own script does, ask
		-- GetObjects first: if the asset holds an Animation, its real AnimationId is the one that has to be played.
		local function resolveUrl(id)
			local cached = resolvedIds[id]
			if cached then
				return cached
			end

			local url = "rbxassetid://" .. id
			local ok, objs = pcall(function()
				return game:GetObjects("rbxassetid://" .. id)
			end)
			if ok and type(objs) == "table" then
				local got = false
				for _, obj in ipairs(objs) do
					if not got then
						local found = obj
						if not obj:IsA("Animation") then
							found = obj:FindFirstChildWhichIsA("Animation", true)
						end
						if found and found.AnimationId ~= "" then
							url = found.AnimationId
							got = true
						end
					end
				end
				for _, obj in ipairs(objs) do
					pcall(function()
						obj:Destroy()
					end)
				end
			end

			resolvedIds[id] = url
			return url
		end

		local function createDummy(rig)
			local ok, model = pcall(function()
				return Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"), Enum.HumanoidRigType[rig])
			end)
			if not ok or not model then
				return nil
			end

			local root = model:FindFirstChild("HumanoidRootPart")
			local hum = model:FindFirstChildOfClass("Humanoid")
			if not root or not hum then
				pcall(function()
					model:Destroy()
				end)
				return nil
			end

			for _, inst in ipairs(model:GetDescendants()) do
				if inst:IsA("LuaSourceContainer") then
					pcall(function()
						inst:Destroy()
					end)
				elseif inst:IsA("BasePart") then
					inst.Transparency = 1
					inst.CanCollide = false
					inst.CanTouch = false
					inst.CanQuery = false
					inst.Massless = true
					inst.Anchored = (inst == root)
				elseif inst:IsA("Decal") then
					inst.Transparency = 1
				end
			end

			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			model.Name = "FVL_MiniMe_Probe"
			model.PrimaryPart = root
			root.CFrame = CFrame.new(0, 4000, 0)
			model.Parent = workspace.CurrentCamera or workspace
			return model
		end

		local function getDummy(rig)
			local existing = dummies[rig]
			if existing and existing.Parent then
				return existing
			end

			while creating[rig] do
				task.wait()
			end
			existing = dummies[rig]
			if existing and existing.Parent then
				return existing
			end

			creating[rig] = true
			local model = createDummy(rig)
			creating[rig] = nil
			dummies[rig] = model
			return model
		end

		-- the hidden test dummies are built in the background so the first check does not have to wait for them
		local function warmDummies()
			task.spawn(function()
				getDummy("R6")
				getDummy("R15")
			end)
		end

		local function destroyDummies()
			for rig, model in pairs(dummies) do
				pcall(function()
					model:Destroy()
				end)
				dummies[rig] = nil
			end
		end

		-- forget the "unknown" results so a refresh checks them again
		local function clearUnknown()
			for id, r in pairs(rigCache) do
				if r == false then
					rigCache[id] = nil
				end
			end
		end

		-- fast path: read the part names inside the animation itself (R6: Torso / Left Arm, R15: UpperTorso ...)
		local function viaSequence(id, state)
			local ok, seq = pcall(function()
				return KFSProvider:GetKeyframeSequenceAsync(state.url)
			end)
			if not ok or not seq then
				return nil
			end

			local s6, s15 = 0, 0
			for _, d in ipairs(seq:GetDescendants()) do
				if d:IsA("Pose") then
					if R6_PARTS[d.Name] then
						s6 = s6 + 1
					elseif R15_PARTS[d.Name] then
						s15 = s15 + 1
					end
				end
			end
			pcall(function()
				seq:Destroy()
			end)

			if s6 > s15 then
				return "R6"
			elseif s15 > s6 then
				return "R15"
			end
			return nil
		end

		-- backup path: play it on a hidden R6 dummy and a hidden R15 dummy and see which one really moves
		local function viaDummies(id, state)
			local rigs = { R6 = getDummy("R6"), R15 = getDummy("R15") }
			if state.done or not rigs.R6 or not rigs.R15 then
				return nil
			end

			while probeBusy and not state.done do
				task.wait()
			end
			if state.done then
				return nil
			end

			probeBusy = true
			local result
			pcall(function()
				local tracks = {}
				for rig, dummy in pairs(rigs) do
					local hum = dummy:FindFirstChildOfClass("Humanoid")
					local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
					local anim = Instance.new("Animation")
					anim.AnimationId = state.url
					local okLoad, track = pcall(function()
						return animator:LoadAnimation(anim)
					end)
					if okLoad and track then
						track.Priority = Enum.AnimationPriority.Action4
						track.Looped = true
						track:Play(0)
						tracks[rig] = track
					end
				end

				local loaded = false
				local t0 = os.clock()
				while not loaded and not state.done and os.clock() - t0 < 1.5 do
					RunService.Heartbeat:Wait()
					for _, track in pairs(tracks) do
						if track.Length > 0 then
							loaded = true
						end
					end
				end

				if loaded and not state.done then
					for _, track in pairs(tracks) do
						pcall(function()
							track.TimePosition = track.Length * 0.5
						end)
					end
					RunService.Heartbeat:Wait()
					RunService.Heartbeat:Wait()

					-- count the joints that really moved on each dummy (the root joint is ignored)
					local score = { R6 = 0, R15 = 0 }
					for rig, dummy in pairs(rigs) do
						for _, m in ipairs(dummy:GetDescendants()) do
							if m:IsA("Motor6D") and m.Name ~= "RootJoint" then
								local tr = m.Transform
								local rx, ry, rz = tr:ToOrientation()
								if math.abs(rx) + math.abs(ry) + math.abs(rz) > 0.02 or tr.Position.Magnitude > 0.02 then
									score[rig] = score[rig] + 1
								end
							end
						end
					end

					if score.R6 > score.R15 then
						result = "R6"
					elseif score.R15 > score.R6 then
						result = "R15"
					end
				end

				for _, track in pairs(tracks) do
					pcall(function()
						track:Stop(0)
						track:Destroy()
					end)
				end
			end)
			probeBusy = false
			return result
		end

		-- which rig does this animation need?  returns "R6", "R15" or nil (unknown). Both methods run at the same
		-- time and the first answer wins; the result is remembered, so the same ID is instant next time.
		local function probe(id)
			local cached = rigCache[id]
			if cached ~= nil then
				return cached or nil
			end

			local state = { done = false, url = resolveUrl(id) }
			local result
			local finished = 0
			local function run(fn)
				task.spawn(function()
					local ok, r = pcall(fn, id, state)
					finished = finished + 1
					if ok and r and not state.done then
						result = r
						state.done = true
					end
				end)
			end
			run(viaSequence)
			run(viaDummies)

			local t0 = os.clock()
			while not state.done and finished < 2 and os.clock() - t0 < 2.5 do
				RunService.Heartbeat:Wait()
			end
			state.done = true

			rigCache[id] = result or false
			return result
		end

		-- rig of an already checked id (nil = not checked yet / unknown)
		local function cachedRig(id)
			local r = id and rigCache[id]
			return r or nil
		end

		-- the rig the little one has to be: the pose decides first, then the animation that was started
		local function wantRig()
			return cachedRig(poseId()) or cachedRig(MM.activeAnim)
		end

		-- checks the pose and the started animation at the same time
		local function detectAll()
			local ids = {}
			local pid = poseId()
			if pid then
				ids[#ids + 1] = pid
			end
			if MM.activeAnim and MM.activeAnim ~= pid then
				ids[#ids + 1] = MM.activeAnim
			end

			local pending = #ids
			for _, id in ipairs(ids) do
				task.spawn(function()
					pcall(probe, id)
					pending = pending - 1
				end)
			end
			while pending > 0 do
				RunService.Heartbeat:Wait()
			end
		end

		-- ------------------------------------------------------- the little one
		local function stopTracks()
			MM.playToken = MM.playToken + 1
			for _, tr in ipairs(MM.tracks) do
				pcall(function()
					tr:Stop(0.1)
					tr:Destroy()
				end)
			end
			table.clear(MM.tracks)
			MM.animTrack = nil
			if MM.mix then
				for _, m in ipairs(MM.mix.models) do
					pcall(function()
						m:Destroy()
					end)
				end
				MM.mix = nil
			end
		end

		local function destroyModel()
			stopTracks()
			if MM.model then
				pcall(function()
					MM.model:Destroy()
				end)
			end
			MM.model, MM.root, MM.animator, MM.rig = nil, nil, nil, nil
		end

		local function playOne(id, priority, label, loop)
			if not id or not MM.animator then
				return
			end
			local anim = Instance.new("Animation")
			anim.AnimationId = resolvedIds[id] or ("rbxassetid://" .. id)
			local ok, track = pcall(function()
				return MM.animator:LoadAnimation(anim)
			end)
			if not ok or not track then
				return
			end
			track.Priority = priority
			track.Looped = (loop ~= false)
			MM.tracks[#MM.tracks + 1] = track
			track:Play(0.2)
			task.delay(2.5, function()
				if track.Parent and track.Length == 0 and MM.on then
					note(label .. " " .. id .. " could not be loaded (not usable in this game).", "x")
				end
			end)
			return track
		end

		-- true when a joint is moved away from its rest position
		local function deviates(tr)
			local rx, ry, rz = tr:ToOrientation()
			return math.abs(rx) + math.abs(ry) + math.abs(rz) > 0.02 or tr.Position.Magnitude > 0.02
		end

		-- Animation + pose together, automatically. Each one plays on its own hidden rig, and every frame the
		-- little one takes each joint from the animation if the animation really moves that joint, otherwise
		-- from the pose. So the animation keeps moving what it moves, and the pose holds all the rest.
		-- returns false when the mixer could not start (then both are just played on the little one directly)
		local function startMix(aid, pid, mine)
			local model = MM.model
			local rigName = MM.rig
			local base = rigName and dummies[rigName]
			if rigName and not (base and base.Parent) then
				base = getDummy(rigName)
			end
			if mine ~= MM.playToken or MM.model ~= model then
				return true
			end
			if not base then
				return false
			end

			local mix = { models = {}, joints = {}, animated = {}, ready = false }

			local function abort(result)
				for _, m in ipairs(mix.models) do
					pcall(function()
						m:Destroy()
					end)
				end
				if MM.mix == mix then
					MM.mix = nil
				end
				return result
			end

			local function makeRig()
				local c = base:Clone()
				c.Name = "FVL_MiniMe_Mix"
				c.Parent = workspace.CurrentCamera or workspace
				mix.models[#mix.models + 1] = c
				return c
			end

			local function loadOn(rig, id)
				local hum = rig:FindFirstChildOfClass("Humanoid")
				if not hum then
					return nil
				end
				local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
				local anim = Instance.new("Animation")
				anim.AnimationId = resolvedIds[id] or ("rbxassetid://" .. id)
				local ok, track = pcall(function()
					return animator:LoadAnimation(anim)
				end)
				if not ok or not track then
					return nil
				end
				track.Priority = Enum.AnimationPriority.Action4
				track.Looped = true
				track:Play(0)
				return track
			end

			local function jointMap(m)
				local t = {}
				for _, d in ipairs(m:GetDescendants()) do
					if d:IsA("Motor6D") then
						t[d.Name] = d
					end
				end
				return t
			end

			local rigA, rigP = makeRig(), makeRig()
			MM.mix = mix

			local trA, trP = loadOn(rigA, aid), loadOn(rigP, pid)
			if not trA or not trP then
				return abort(false)
			end

			-- wait until both have loaded
			local t0 = os.clock()
			while (trA.Length == 0 or trP.Length == 0) and os.clock() - t0 < 1.5 do
				RunService.Heartbeat:Wait()
				if mine ~= MM.playToken then
					return abort(true)
				end
			end
			if trA.Length == 0 or trP.Length == 0 then
				return abort(false)
			end

			local jm, ja, jp = jointMap(model), jointMap(rigA), jointMap(rigP)
			for name, m in pairs(jm) do
				if ja[name] and jp[name] then
					mix.joints[#mix.joints + 1] = { name = name, m = m, a = ja[name], p = jp[name] }
				end
			end
			if #mix.joints == 0 then
				return abort(false)
			end

			-- look through the whole animation once so we know up front which joints it moves
			for i = 0, 7 do
				pcall(function()
					trA.TimePosition = trA.Length * i / 8
				end)
				RunService.Heartbeat:Wait()
				if mine ~= MM.playToken then
					return abort(true)
				end
				for _, j in ipairs(mix.joints) do
					if not mix.animated[j.name] and deviates(j.a.Transform) then
						mix.animated[j.name] = true
					end
				end
			end
			pcall(function()
				trA.TimePosition = 0
			end)
			if not trA.IsPlaying then
				pcall(function()
					trA:Play(0)
				end)
			end
			pcall(function()
				trA.Looped = MM.loop
			end)

			mix.trA = trA
			mix.ready = true
			return true
		end

		-- start the animation and the pose on the little copy (only the ones that fit its rig)
		local function playTracks()
			stopTracks()
			local mine = MM.playToken
			if not MM.model or not MM.animator then
				return
			end

			local rig = MM.rig
			local aid, pid = MM.activeAnim, poseId()

			local rigAn, rigPo = cachedRig(aid), cachedRig(pid)
			if aid and rig and rigAn and rigAn ~= rig then
				note("Animation " .. aid .. " is " .. rigAn .. " but the pose needs " .. rig .. ", so the animation was skipped.", "x")
				aid = nil
			end
			if pid and rig and rigPo and rigPo ~= rig then
				note("Pose " .. pid .. " is " .. rigPo .. " but the mini is " .. rig .. ", so the pose was skipped.", "x")
				pid = nil
			end

			if aid and pid then
				-- both: mix them automatically
				if not startMix(aid, pid, mine) then
					MM.animTrack = playOne(aid, Enum.AnimationPriority.Action4, "Animation", MM.loop)
					playOne(pid, Enum.AnimationPriority.Action, "Pose", true)
				end
			elseif aid then
				MM.animTrack = playOne(aid, Enum.AnimationPriority.Action, "Animation", MM.loop)
			elseif pid then
				playOne(pid, Enum.AnimationPriority.Action, "Pose", true)
			end
		end

		-- the copy: the character cloned (same rig), or rebuilt from the player's avatar as the rig that is wanted
		local function makeSource(want)
			local char, plr
			if MM.who ~= "Me" then
				plr = Players:FindFirstChild(MM.who)
				char = plr and plr.Character
			end
			if not char then
				plr = lp
				char = lp.Character
			end

			local hum = char and char:FindFirstChildOfClass("Humanoid")
			local alive = char and hum and hum.Health > 0 and char:FindFirstChild("HumanoidRootPart") ~= nil
			local nativeRig = alive and hum.RigType.Name or nil

			local function cloneChar()
				local was = char.Archivable
				char.Archivable = true
				local ok, c = pcall(function()
					return char:Clone()
				end)
				char.Archivable = was
				return ok and c or nil
			end

			-- true when a description has nothing on it at all (then it is not the real look of the player)
			local function descEmpty(d)
				local okE, empty = pcall(function()
					return #d:GetAccessories(true) == 0 and d.Shirt == 0 and d.Pants == 0 and d.GraphicTShirt == 0
						and d.Head == 0 and d.Torso == 0 and d.Face == 0
				end)
				return okE and empty
			end

			-- rebuilds the player as the wanted rig. It uses what the player is wearing in THIS game right now
			-- (so the little one looks the same as before), and only falls back to their website avatar.
			local function fromAvatar(rigName)
				if not plr then
					return nil
				end
				local ok, model = pcall(function()
					local desc
					if hum then
						local okD, applied = pcall(function()
							return hum:GetAppliedDescription()
						end)
						if okD and applied and not descEmpty(applied) then
							desc = applied
						end
					end
					if not desc then
						desc = descCache[plr.UserId]
						if not desc then
							desc = Players:GetHumanoidDescriptionFromUserId(plr.UserId)
							descCache[plr.UserId] = desc
						end
					end
					return Players:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType[rigName])
				end)
				return ok and model or nil
			end

			local m
			if nativeRig and (not want or want == nativeRig) then
				m = cloneChar()
				if m then
					return m
				end
			end

			if want then
				m = fromAvatar(want)
				if m then
					return m
				end
			end

			if nativeRig then
				m = cloneChar()
				if m then
					return m
				end
			end

			return fromAvatar("R15")
		end

		local function prepare(m)
			for _, d in ipairs(m:GetDescendants()) do
				if d:IsA("LuaSourceContainer") or d:IsA("Tool") or d:IsA("Sound") or d:IsA("ForceField")
					or d:IsA("BillboardGui") or d:IsA("Highlight") or d:IsA("SelectionBox")
					or d:IsA("Beam") or d:IsA("Trail") then
					pcall(function()
						d:Destroy()
					end)
				end
			end

			local hum = m:FindFirstChildOfClass("Humanoid")
			local root = m:FindFirstChild("HumanoidRootPart")
			if not hum or not root then
				return nil
			end

			for _, d in ipairs(m:GetDescendants()) do
				if d:IsA("BasePart") then
					d.CanCollide = false
					d.CanTouch = false
					d.CanQuery = false
					d.Massless = true
					d.Anchored = (d == root)
				end
			end

			-- a clone keeps the pose the player was in (running, jumping ...): put every joint back to rest
			for _, d in ipairs(m:GetDescendants()) do
				if d:IsA("Motor6D") then
					d.Transform = CFrame.new()
				end
			end

			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			hum.BreakJointsOnDeath = false
			hum.RequiresNeck = false
			pcall(function()
				hum.NameDisplayDistance = 0
				hum.HealthDisplayDistance = 0
			end)

			m.Name = "FVL_MiniMe"
			m.PrimaryPart = root
			pcall(function()
				m:ScaleTo(MM.size)
			end)
			return m, hum, root
		end

		-- which way you face, flattened (nil when you look straight up / down)
		local function flatLook(hrp)
			local look = hrp.CFrame.LookVector
			local flat = Vector3.new(look.X, 0, look.Z)
			if flat.Magnitude < 0.01 then
				return nil
			end
			return flat.Unit
		end

		-- the slow up / down drift, added on top of the follow movement
		local function bobOffset()
			local t = os.clock()
			return math.sin(t * 2.1) * MM.bob + math.sin(t * 3.7 + 1.3) * MM.bob * 0.25
		end

		-- where the little one wants to hover: next to you, using a slowly turning copy of your facing
		local function followGoal(basePos, dir)
			local right = dir:Cross(Vector3.new(0, 1, 0))
			local up = Vector3.new(0, 1, 0)
			local off
			if MM.side == "Left" then
				off = -right * MM.dist + up * MM.height
			elseif MM.side == "Behind" then
				off = -dir * MM.dist + up * MM.height
			elseif MM.side == "Front" then
				off = dir * MM.dist + up * MM.height
			elseif MM.side == "Above Head" then
				off = up * (MM.height + 1.5)
			else
				off = right * MM.dist + up * MM.height
			end
			return basePos + off
		end

		local function updateCF()
			local p = MM.pos + Vector3.new(0, bobOffset(), 0)
			MM.cf = CFrame.lookAt(p, p + MM.dir)
		end

		local function initFollow(hrp)
			MM.dir = flatLook(hrp) or Vector3.new(0, 0, -1)
			MM.pos = followGoal(hrp.Position, MM.dir)
			MM.vel = Vector3.new(0, 0, 0)
			updateCF()
		end

		-- floaty follow: a soft spring pulls the little one toward its spot, so it trails behind when you run,
		-- drifts to a stop when you stop, and is never stuck to your body. The turning is slow as well.
		local function followStep(hrp, dt)
			dt = math.min(dt, 0.1)

			local want = flatLook(hrp)
			if want then
				local k = 1 - math.exp(-math.max(0.6, MM.smooth * 0.6) * dt)
				local mixed = MM.dir:Lerp(want, k)
				if mixed.Magnitude > 0.05 then
					MM.dir = mixed.Unit
				else
					MM.dir = want
				end
			end

			local goal = followGoal(hrp.Position, MM.dir)
			local pos, vel = MM.pos, MM.vel
			if (goal - pos).Magnitude > 80 then
				pos, vel = goal, Vector3.new(0, 0, 0)
			end

			local w = MM.smooth
			local zeta = 0.8
			local steps = math.max(1, math.ceil(dt / 0.016))
			local h = dt / steps
			for _ = 1, steps do
				local acc = (goal - pos) * (w * w) - vel * (2 * zeta * w)
				vel = vel + acc * h
				pos = pos + vel * h
			end

			MM.pos, MM.vel = pos, vel
			updateCF()
		end

		local function build()
			if MM.building then
				return
			end
			MM.building = true
			local token = MM.token

			local ok, err = pcall(function()
				-- find out which rig the chosen animation / pose needs (cached after the first time)
				detectAll()
				if not MM.on or MM.token ~= token then
					return
				end

				local want = wantRig()
				local src = makeSource(want)
				if not src then
					return
				end

				-- toggled off / rebuilt while we were waiting
				if not MM.on or MM.token ~= token then
					src:Destroy()
					return
				end

				local m, hum, root = prepare(src)
				if not m then
					src:Destroy()
					return
				end

				local char = lp.Character
				local hrp = char and char:FindFirstChild("HumanoidRootPart")
				if hrp then
					if not MM.pos then
						initFollow(hrp)
					end
					root.CFrame = MM.cf
				end

				m.Parent = workspace.CurrentCamera or workspace
				MM.model, MM.root = m, root
				MM.rig = hum.RigType.Name
				MM.animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
				playTracks()
			end)

			MM.building = false
			if not ok then
				warn("[FVL] Mini Me build failed: " .. tostring(err))
			end
		end

		local function rebuild()
			MM.token = MM.token + 1
			destroyModel()
			MM.nextTry = 0
		end

		-- the animation / pose choice changed: re-check the rig, rebuild the little one if the rig has to change
		local function onAnimChanged()
			if not MM.on then
				return
			end
			MM.animToken = MM.animToken + 1
			local mine = MM.animToken
			stopTracks()

			task.spawn(function()
				detectAll()
				if not MM.on or MM.animToken ~= mine then
					return
				end

				local want = wantRig()
				if MM.model and want and MM.rig and want ~= MM.rig then
					rebuild()
				else
					playTracks()
				end
			end)
		end

		-- an animation was picked in the dropdown / typed in: it does not play yet, only the Play button starts it.
		-- Its rig is checked in the background so the Play button answers instantly.
		local function onAnimSelected()
			local id = animId()
			if id then
				task.spawn(function()
					pcall(probe, id)
				end)
			elseif MM.activeAnim then
				-- None picked: stop the animation that is playing
				MM.activeAnim = nil
				onAnimChanged()
			end
		end

		-- the Play Animation button
		local function playAnimation()
			if not MM.on then
				note("Turn Mini Me on first.", "x")
				return
			end
			local id = animId()
			if not id then
				note("Pick an animation first.", "x")
				return
			end
			MM.activeAnim = id
			onAnimChanged()
		end

		-- the Loop Animation toggle (also works while the animation is playing)
		local function applyLoop()
			if MM.animTrack then
				pcall(function()
					MM.animTrack.Looped = MM.loop
				end)
			end
			if MM.mix and MM.mix.trA then
				pcall(function()
					MM.mix.trA.Looped = MM.loop
				end)
			end
		end

		local function step(dt)
			if not MM.on then
				return
			end

			local m = MM.model
			if not m or not m.Parent or not MM.root or not MM.root.Parent then
				if m then
					destroyModel()
				end
				if not MM.building and os.clock() >= MM.nextTry then
					MM.nextTry = os.clock() + 1.5
					task.spawn(build)
				end
				return
			end

			local char = lp.Character
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return
			end

			if not MM.pos then
				initFollow(hrp)
			end
			followStep(hrp, dt)
			MM.root.CFrame = MM.cf

			-- animation + pose mixer: joints the animation moves come from it, all the others from the pose
			local mix = MM.mix
			if mix and mix.ready then
				-- once a non-looping animation has finished, everything goes back to the pose
				local animLive = mix.trA ~= nil and mix.trA.IsPlaying
				for _, j in ipairs(mix.joints) do
					local fromAnim = j.a.Transform
					if animLive and not mix.animated[j.name] and deviates(fromAnim) then
						mix.animated[j.name] = true
					end
					j.m.Transform = (animLive and mix.animated[j.name]) and fromAnim or j.p.Transform
				end
			end
		end

		local function setOn(on)
			MM.on = on
			MM.token = MM.token + 1
			destroyModel()
			MM.pos, MM.vel, MM.dir, MM.cf = nil, nil, nil, nil
			MM.activeAnim = nil

			if MM.conn then
				MM.conn:Disconnect()
				MM.conn = nil
			end
			if MM.charConn then
				MM.charConn:Disconnect()
				MM.charConn = nil
			end

			if not on then
				return
			end

			MM.nextTry = 0
			MM.conn = RunService.RenderStepped:Connect(step)
			MM.charConn = lp.CharacterAdded:Connect(function()
				if MM.on and MM.who == "Me" then
					task.delay(2, function()
						if MM.on and MM.who == "Me" then
							rebuild()
						end
					end)
				end
			end)
		end

		list2.conns[#list2.conns + 1] = { Disconnect = function()
			setOn(false)
			destroyDummies()
		end }

		task.delay(1, warmDummies)

		local function plist()
			local t = { "Me" }
			for _, p in ipairs(Players:GetPlayers()) do
				if p ~= lp then
					t[#t + 1] = p.Name
				end
			end
			return t
		end

		-- ---------------------------------------------------------------- UI
		tbl43.troll:Section({ Title = "Mini Me" })

		tbl43.troll:Toggle({
			Title = "Mini Me",
			Flag = "Toggle_Troll_MiniMe",
			Desc = "A tiny copy of a character floats next to you, follows you smoothly and bobs up and down a little. Only you can see it. R6 / R15 follows the animation and pose you pick.",
			Type = "Toggle",
			Value = false,
			Callback = function(v)
				setOn(v and true or false)
			end,
		})

		local charDrop = tbl43.troll:Dropdown({
			Title = "Mini Character",
			Flag = "Dropdown_Troll_MiniMe_Char",
			Desc = "Me = your own character, or pick any player to shrink their character instead",
			Multi = false,
			Value = "Me",
			Values = plist(),
			Callback = function(v)
				MM.who = pickName(v) or "Me"
				if MM.on then
					rebuild()
				end
			end,
		})

		tbl43.troll:Dropdown({
			Title = "Mini Animation",
			Flag = "Dropdown_Troll_MiniMe_Anim",
			Desc = "Pick an animation, then press Play Animation. Pick None to stop it. R6 / R15 is detected automatically.",
			Multi = false,
			Value = "None",
			Values = labels(ANIM_LIST),
			Callback = function(v)
				MM.animName = pickName(v) or "None"
				onAnimSelected()
			end,
		})

		tbl43.troll:Input({
			Title = "Custom Animation ID",
			Flag = "Input_Troll_MiniMe_Anim",
			Desc = "Optional: paste any animation ID. It replaces the choice above while it is filled in.",
			Placeholder = "paste an animation ID",
			Callback = function(value)
				MM.customAnim = digits(value) or ""
				onAnimSelected()
			end,
		})

		tbl43.troll:Button({
			Title = "Play Animation",
			Desc = "Plays the animation you picked on the little one (press again to restart it)",
			Callback = function()
				playAnimation()
			end,
		})

		tbl43.troll:Toggle({
			Title = "Loop Animation",
			Flag = "Toggle_Troll_MiniMe_Loop",
			Desc = "On = the animation keeps repeating. Off = it plays once and stops.",
			Type = "Toggle",
			Value = true,
			Callback = function(v)
				MM.loop = v and true or false
				applyLoop()
			end,
		})

		tbl43.troll:Dropdown({
			Title = "Mini Pose",
			Flag = "Dropdown_Troll_MiniMe_Pose",
			Desc = "Pose the little one holds. It works together with the animation automatically: the animation moves what it moves, the pose holds the rest.",
			Multi = false,
			Value = "None",
			Values = labels(POSE_LIST),
			Callback = function(v)
				MM.poseName = pickName(v) or "None"
				onAnimChanged()
			end,
		})

		tbl43.troll:Input({
			Title = "Custom Pose ID",
			Flag = "Input_Troll_MiniMe_Pose",
			Desc = "Optional: paste any pose ID. It replaces the choice above while it is filled in.",
			Placeholder = "paste a pose ID",
			Callback = function(value)
				MM.customPose = digits(value) or ""
				onAnimChanged()
			end,
		})

		tbl43.troll:Dropdown({
			Title = "Float Side",
			Flag = "Dropdown_Troll_MiniMe_Side",
			Desc = "Where the little one floats around you",
			Multi = false,
			Value = "Right",
			Values = { "Right", "Left", "Behind", "Front", "Above Head" },
			Callback = function(v)
				MM.side = pickName(v) or "Right"
			end,
		})

		tbl43.troll:Slider({
			Title = "Mini Size",
			Flag = "Slider_Troll_MiniMe_Size",
			Desc = "1 = normal size",
			Step = 0.05,
			Value = { Min = 0.1, Max = 1, Default = 0.35 },
			Callback = function(v)
				local n = toNumber(v)
				if n then
					MM.size = n
					if MM.model then
						pcall(function()
							MM.model:ScaleTo(n)
						end)
					end
				end
			end,
		})

		tbl43.troll:Slider({
			Title = "Mini Distance",
			Flag = "Slider_Troll_MiniMe_Dist",
			Desc = "Studs away from you",
			Step = 0.1,
			Value = { Min = 1, Max = 10, Default = 3 },
			Callback = function(v)
				MM.dist = toNumber(v) or MM.dist
			end,
		})

		tbl43.troll:Slider({
			Title = "Mini Height",
			Flag = "Slider_Troll_MiniMe_Height",
			Desc = "Studs above your center",
			Step = 0.1,
			Value = { Min = 0, Max = 8, Default = 2.5 },
			Callback = function(v)
				MM.height = toNumber(v) or MM.height
			end,
		})

		tbl43.troll:Slider({
			Title = "Float Bob",
			Flag = "Slider_Troll_MiniMe_Bob",
			Desc = "How much it drifts up and down (0 = stays level)",
			Step = 0.05,
			Value = { Min = 0, Max = 1.5, Default = 0.4 },
			Callback = function(v)
				MM.bob = toNumber(v) or MM.bob
			end,
		})

		tbl43.troll:Slider({
			Title = "Follow Smoothness",
			Flag = "Slider_Troll_MiniMe_Follow",
			Desc = "Low = slow, lazy, floaty (trails behind you). High = stays closer to you.",
			Step = 0.1,
			Value = { Min = 0.5, Max = 10, Default = 2.2 },
			Callback = function(v)
				MM.smooth = toNumber(v) or MM.smooth
			end,
		})

		tbl43.troll:Button({
			Title = "Refresh Mini Me",
			Desc = "Copies the character again (use it after changing your outfit or skin)",
			Callback = function()
				clearUnknown()
				if MM.on then
					rebuild()
				else
					note("Turn Mini Me on first.", "x")
				end
			end,
		})

		local function refreshList()
			pcall(function()
				charDrop:Refresh(plist())
			end)
		end

		list2.conns[#list2.conns + 1] = Players.PlayerAdded:Connect(refreshList)
		list2.conns[#list2.conns + 1] = Players.PlayerRemoving:Connect(refreshList)
	end)

	if not okMM then
		warn("[FVL] Mini Me failed to load: " .. tostring(errMM))
	end
end

-- ===== Map Picker [EXPERIMENTAL] =====
-- The "Maps" tab of the main UI lists the maps up for vote as cards (picture + name). Tap a card and the
-- script keeps putting you on that map's vote detector until the round starts: warp on once, reset, wait for the
-- new character, warp on again, and so on. Every time you stand on the detector it counts as another vote. It
-- stops by itself when the game starts, and tapping the same card again stops it too. The cards refresh by
-- themselves when the maps up for vote change. The server decides the winning map, so a result is never guaranteed.
do
	local RunService_ = game:GetService("RunService")
	local Players_ = game:GetService("Players")
	local pick = { token = 0, running = false, holder = nil, sig = nil, interval = 0.2, name = nil, conns = {}, cells = {}, items = {} }
	local VOTE_WORDS = { "vote", "voting" }

	local function matches(text)
		text = string.lower(text)

		for _, word in ipairs(VOTE_WORDS) do
			if string.find(text, word, 1, true) then
				return true
			end
		end

		return false
	end

	local function centerOf(item)
		if item:IsA("BasePart") then
			return item.Position + Vector3.new(0, item.Size.Y / 2 + 3, 0)
		end

		if item:IsA("Model") then
			local cf, size = item:GetBoundingBox()
			return cf.Position + Vector3.new(0, size.Y / 2 + 3, 0)
		end

		for _, d in ipairs(item:GetDescendants()) do
			if d:IsA("BasePart") then
				return d.Position + Vector3.new(0, d.Size.Y / 2 + 3, 0)
			end
		end
	end

	-- a bare number is an asset id; anything else is used as it is
	local function normalizeImage(value)
		if type(value) == "number" then
			return "rbxassetid://" .. tostring(math.floor(value))
		end

		if type(value) == "string" and value ~= "" then
			if string.match(value, "^%d+$") then
				return "rbxassetid://" .. value
			end

			return value
		end
	end

	-- The main UI loads pictures from "rbxassetid://<id>" only. Roblox objects often hold the same picture as
	-- "http://www.roblox.com/asset/?id=<id>" or "rbxthumb://...&id=<id>..." or a bare number - those would come
	-- out blank, so every picture is turned into "rbxassetid://<id>" first.
	local function toAssetUri(value)
		if type(value) ~= "string" then
			return value
		end

		local id = string.match(value, "rbxassetid://(%d+)")
			or string.match(value, "[?&]id=(%d+)")
			or string.match(value, "^(%d+)$")

		if id then
			return "rbxassetid://" .. id
		end

		return value
	end

	local IMAGE_WORDS = { "image", "icon", "thumb", "texture", "picture" }

	local function hasImageWord(text)
		text = string.lower(text)

		for _, word in ipairs(IMAGE_WORDS) do
			if string.find(text, word, 1, true) then
				return true
			end
		end

		return false
	end

	-- the picture held by one object, whatever kind of object it is
	local function imageOf(d)
		if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and d.Image ~= "" then
			return d.Image
		end

		if (d:IsA("Decal") or d:IsA("Texture")) and d.Texture ~= "" then
			return d.Texture
		end

		if d:IsA("MeshPart") and d.TextureID ~= "" then
			return d.TextureID
		end

		if d:IsA("SurfaceAppearance") and d.ColorMap ~= "" then
			return d.ColorMap
		end

		if (d:IsA("StringValue") or d:IsA("IntValue") or d:IsA("NumberValue")) and hasImageWord(d.Name) then
			return normalizeImage(d.Value)
		end

		for name, value in pairs(d:GetAttributes()) do
			if hasImageWord(name) and (type(value) == "string" or type(value) == "number") then
				return normalizeImage(value)
			end
		end
	end

	local function firstImageIn(item)
		local image = imageOf(item)

		if image then
			return image
		end

		for _, d in ipairs(item:GetDescendants()) do
			image = imageOf(d)

			if image then
				return image
			end
		end
	end

	-- a SurfaceGui / BillboardGui that sits in PlayerGui but is attached ("Adornee") to this object
	local function attachedGuiImage(root)
		local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")

		if not playerGui then
			return nil
		end

		for _, gui in ipairs(playerGui:GetDescendants()) do
			if (gui:IsA("SurfaceGui") or gui:IsA("BillboardGui")) and gui.Adornee
				and (gui.Adornee == root or gui.Adornee:IsDescendantOf(root)) then
				local image = firstImageIn(gui)

				if image then
					return image
				end
			end
		end
	end

	-- what is inside an object (for the "picture not found" note on a card)
	local function describe(root)
		if not root then
			return "nothing found"
		end

		local parts = {}

		for _, d in ipairs(root:GetDescendants()) do
			if #parts >= 8 then
				break
			end

			if d:IsA("SurfaceGui") or d:IsA("BillboardGui") or d:IsA("ImageLabel") or d:IsA("ImageButton")
				or d:IsA("Decal") or d:IsA("Texture") or d:IsA("MeshPart") or d:IsA("SurfaceAppearance")
				or d:IsA("ValueBase") or d:IsA("TextLabel") then
				parts[#parts + 1] = d.ClassName .. ":" .. d.Name
			end
		end

		return root.ClassName .. ":" .. root.Name .. " > " .. (#parts > 0 and table.concat(parts, ", ") or "no picture-like objects")
	end

	local function firstLabelIn(item)
		for _, d in ipairs(item:GetDescendants()) do
			if d:IsA("TextLabel") and #d.Text >= 2 and #d.Text <= 30
				and not string.match(d.Text, "^[%d%s%p]+$") and not matches(d.Text) then
				return d.Text
			end
		end
	end

	-- Where to stand on a detector: on top of it, or inside it when it is a tall invisible zone
	local function detectorPos(detector)
		local part = detector

		if not detector:IsA("BasePart") then
			part = detector:FindFirstChildWhichIsA("BasePart", true)
		end

		if not part then
			return nil
		end

		if part.Size.Y > 6 then
			return part.Position
		end

		return part.Position + Vector3.new(0, part.Size.Y / 2 + 3, 0)
	end

	-- The three maps up for vote (new MM2 lobby layout), for N = 1 / 2 / 3:
	--   name:    workspace.Lobby.VotePads.VotePadN.VoteInfoGui.Container.MapName
	--   picture: workspace.Lobby.VotePads.VotePadN.MapInfoGui.MapIcon
	--   spot we stand on to vote: workspace.Lobby.VotePads.VotePadN.Pad

	-- the text of one label, with formatting tags removed; empty / placeholder texts do not count
	local function readLabel(nameText)
		if nameText and nameText:IsA("TextLabel") then
			local text = nameText.ContentText ~= "" and nameText.ContentText or nameText.Text
			text = (string.gsub(text, "<[^>]+>", ""))

			if text ~= "" and text ~= "MapName" and text ~= "Label" and text ~= "TextLabel" then
				return text
			end
		end
	end

	-- ===== vote counts =====
	-- A number as the vote pad shows it: "5", "x5", "5 votes", "Votes: 5". Anything else is not a vote count.
	local function strictNumber(text)
		if type(text) ~= "string" then
			return nil
		end

		text = (string.gsub(text, "<[^>]+>", ""))
		text = string.match(text, "^%s*(.-)%s*$")

		local n = string.match(text, "^(%d+)$")
			or string.match(text, "^[xX]%s*(%d+)$")
			or string.match(text, "^(%d+)%s*[Vv][Oo][Tt][Ee][Ss]?$")
			or string.match(text, "^[Vv][Oo][Tt][Ee][Ss]?%s*:?%s*(%d+)$")

		return n and tonumber(n)
	end

	local function labelText(label)
		return label.ContentText ~= "" and label.ContentText or label.Text
	end

	local VOTE_NAME_WORDS = { "vote", "count", "amount", "score", "total" }

	local function looksLikeCounter(name)
		name = string.lower(name)

		if name == "mapname" then
			return false
		end

		for _, word in ipairs(VOTE_NAME_WORDS) do
			if string.find(name, word, 1, true) then
				return true
			end
		end

		return false
	end

	-- The number of votes on one vote pad (workspace.Lobby.VotePads.VotePadN), or nil when it cannot be found:
	--   1. a label / value named like a counter (Votes, VoteCount, Count ...) inside VoteInfoGui, then the pad
	--   2. an attribute named like a counter
	--   3. any lone number shown in VoteInfoGui
	local function readVotes(votePad)
		if not votePad then
			return nil
		end

		local infoGui = votePad:FindFirstChild("VoteInfoGui")
		local roots = {}

		if infoGui then
			roots[#roots + 1] = infoGui
		end

		roots[#roots + 1] = votePad

		for _, root in ipairs(roots) do
			for _, d in ipairs(root:GetDescendants()) do
				if looksLikeCounter(d.Name) then
					if d:IsA("TextLabel") or d:IsA("TextButton") then
						local n = strictNumber(labelText(d))

						if n then
							return n
						end
					elseif d:IsA("IntValue") or d:IsA("NumberValue") then
						return math.floor(d.Value)
					end
				end
			end
		end

		for _, root in ipairs({ votePad, infoGui }) do
			if root then
				for name, value in pairs(root:GetAttributes()) do
					if looksLikeCounter(name) and type(value) == "number" then
						return math.floor(value)
					end
				end
			end
		end

		if infoGui then
			for _, d in ipairs(infoGui:GetDescendants()) do
				if d:IsA("TextLabel") and string.lower(d.Name) ~= "mapname" then
					local n = strictNumber(labelText(d))

					if n then
						return n
					end
				end
			end
		end

		return nil
	end

	local function votePadAt(i)
		local lobby = workspace:FindFirstChild("Lobby")
		local padsFolder = lobby and lobby:FindFirstChild("VotePads")

		return padsFolder and padsFolder:FindFirstChild("VotePad" .. i)
	end

	local function scanFixed()
		local lobby = workspace:FindFirstChild("Lobby")
		local padsFolder = lobby and lobby:FindFirstChild("VotePads")

		if not padsFolder then
			return nil
		end

		local found = {}

		for i = 1, 3 do
			local votePad = padsFolder:FindFirstChild("VotePad" .. i)

			if votePad then
				local pad = votePad:FindFirstChild("Pad")
				local pos = (pad and detectorPos(pad)) or centerOf(votePad)

				if pos then
					local infoGui = votePad:FindFirstChild("VoteInfoGui")
					local container = infoGui and infoGui:FindFirstChild("Container")
					local mapGui = votePad:FindFirstChild("MapInfoGui")
					local icon = mapGui and mapGui:FindFirstChild("MapIcon")

					local label = readLabel(container and container:FindFirstChild("MapName"))
						or readLabel(votePad:FindFirstChild("MapName", true))
						or ("Map " .. i)

					local image = icon and firstImageIn(icon)
					image = toAssetUri(image)

					local note

					if not image then
						note = "Picture not found. MapIcon: " .. describe(icon)
					end

					found[#found + 1] = { name = label, image = image, pos = pos, note = note, padIndex = i }
				end
			end
		end

		return #found > 0 and found or nil
	end

	local statusPara -- the Paragraph at the top of the Maps tab (created at the bottom of this block)

	local function setStatus(text)
		if statusPara then
			pcall(function()
				statusPara:SetDesc(text)
			end)
		end
	end

	local refreshCells
	local updateVotes

	local function stopPicking(reason)
		pick.token = pick.token + 1
		pick.running = false
		pick.name = nil

		for i = #pick.conns, 1, -1 do
			pcall(function()
				pick.conns[i]:Disconnect()
			end)

			pick.conns[i] = nil
		end

		setStatus(reason or "Stopped.")

		if refreshCells then
			refreshCells()
		end
	end

	local function placeOn(pos)
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")

		if hrp then
			hrp.AssemblyLinearVelocity = Vector3.zero
			hrp.CFrame = CFrame.new(pos)
		end
	end

	-- Is a round's map in the world? Same signal the rest of the script uses (findMap / roundRunning).
	-- This does NOT depend on the Inventory GUI, so it still works when you are dead / spectating / just reset.
	local function mapLoaded()
		for _, child in ipairs(workspace:GetChildren()) do
			if child:IsA("Model") and child.Name ~= "RegularLobby" and child.Name ~= "Lobby"
				and (child:FindFirstChild("CoinContainer") or child:FindFirstChild("CoinAreas") or child:FindFirstChild("Spawns")) then
				return true
			end
		end

		return false
	end

	-- Has the round started (or is it starting)? Then we must stop.
	-- Several independent signals: if one of them fails (GUI missing, timer attribute not set), another still catches it.
	local function gameStarting()
		if not list2.inLobbyNow() then
			return true
		end

		if mapLoaded() then
			return true
		end

		local timerPart = workspace:FindFirstChild("RoundTimerPart")

		if timerPart and (tonumber(timerPart:GetAttribute("Time")) or 0) > 0 then
			return true
		end

		return false
	end

	local function startPicking(cand)
		-- Guard clause: voting only makes sense in the lobby vote phase. Once the map is loaded / the round runs,
		-- refuse here (the only entry point), instead of relying on the loop to notice later.
		if gameStarting() then
			stopPicking("A round is running. Wait for the lobby to vote.")
			obj2:Notify({ Title = "Map Picker", Content = "A round is running. Wait for the lobby to vote.", Duration = 4, Icon = "x" })
			return
		end

		pick.token = pick.token + 1
		local token = pick.token
		pick.running = true
		pick.name = cand.id -- which map (its number), not its name
		setStatus("Voting for the highlighted map. Tap it again to stop.")

		if refreshCells then
			refreshCells()
		end

		local function finish(reason)
			stopPicking(reason)
			obj2:Notify({ Title = "Map Picker", Content = reason, Duration = 4, Icon = "check" })
		end

		-- React the moment the game starts, not only when the loop looks: the map being put into the world
		-- (its coin container appears) or the round timer starting to count.
		pick.conns[#pick.conns + 1] = workspace.DescendantAdded:Connect(function(item)
			if pick.token == token and (item.Name == "CoinContainer" or item.Name == "CoinAreas") then
				finish("The map is loading. Stopped.")
			end
		end)

		local timerPart = workspace:FindFirstChild("RoundTimerPart")

		if timerPart then
			pick.conns[#pick.conns + 1] = timerPart:GetAttributeChangedSignal("Time"):Connect(function()
				if pick.token == token and (tonumber(timerPart:GetAttribute("Time")) or 0) > 0 then
					finish("The round started. Stopped.")
				end
			end)
		end

		local baselineSpawn -- where our new characters normally appear in the lobby
		local Heartbeat = RunService_.Heartbeat

		-- the character is "ready" the moment it has a living humanoid and a root part
		local function readyChar(char)
			if not char or not char.Parent then
				return nil
			end

			local humanoid = char:FindFirstChildOfClass("Humanoid")
			local root = char:FindFirstChild("HumanoidRootPart")

			if humanoid and root and humanoid.Health > 0 then
				return root
			end
		end

		-- Kill the character as fast as possible. Health = 0 alone is a server-owned value and is often
		-- ignored from the client; breaking the neck / removing the head is physics the client owns, so the
		-- server sees the humanoid die on the very next replication instead of us waiting and retrying.
		local function fastKill(char, humanoid)
			pcall(function()
				local head = char:FindFirstChild("Head")
				local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")

				for _, d in ipairs(char:GetDescendants()) do
					if d:IsA("Motor6D") and d.Name == "Neck" then
						d:Destroy()
					end
				end

				if head then
					head:Destroy()
				end

				if torso then
					torso:BreakJoints()
				end
			end)

			pcall(function()
				humanoid:ChangeState(Enum.HumanoidStateType.Dead)
				humanoid.Health = 0
				char:BreakJoints()
			end)
		end

		task.spawn(function()
			while pick.token == token do
				if gameStarting() then
					finish("The game is starting. Stopped.")
					return
				end

				-- 1. warp onto the detector the instant the character exists. For the first moments we keep
				-- snapping back (the server may still be placing the fresh character on its spawn), then we just stand.
				placeOn(cand.pos)

				local t0 = os.clock()
				local settleUntil = t0 + math.min(0.15, pick.interval)
				local stayUntil = t0 + pick.interval

				while pick.token == token and os.clock() < stayUntil do
					Heartbeat:Wait()

					if os.clock() < settleUntil then
						local r = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

						if r and (r.Position - cand.pos).Magnitude > 4 then
							placeOn(cand.pos)
						end
					end
				end

				if pick.token ~= token then
					return
				end

				if gameStarting() then
					finish("The game is starting. Stopped.")
					return
				end

				-- if the game has moved us far away from the detector, the round is starting: stop
				local hrp = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

				if hrp and (hrp.Position - cand.pos).Magnitude > 60 then
					finish("The game moved you. Stopped.")
					return
				end

				-- 2. reset right away and keep hitting it EVERY FRAME until the old character is really gone
				-- (a fresh character can ignore a single Health = 0)
				local old = localPlayer.Character
				local waitUntil = os.clock() + 12
				local newRoot

				while pick.token == token and os.clock() < waitUntil do
					local now = localPlayer.Character

					-- 3. the new character is here: go straight back to the detector (no extra waiting)
					if now ~= old then
						newRoot = readyChar(now)

						if newRoot then
							break
						end
					else
						local humanoid = old and old.Parent and old:FindFirstChildOfClass("Humanoid")

						if humanoid and humanoid.Health > 0 then
							fastKill(old, humanoid)
						end
					end

					Heartbeat:Wait()
				end

				if pick.token ~= token then
					return
				end

				if newRoot then
					local spawnPos = newRoot.Position

					if not baselineSpawn then
						baselineSpawn = spawnPos
					elseif (spawnPos - baselineSpawn).Magnitude > 150 then
						finish("The game moved you. Stopped.")
						return
					end
				end
			end
		end)
	end

	local ACCENT = Color3.fromRGB(34, 197, 94) -- same green as the script's other windows
	local DARK = Color3.fromRGB(10, 10, 13)
	local MUTED = Color3.fromRGB(150, 150, 160)

	local function styleBox(box, radius, strokeTransparency, strokeColor)
		box.BackgroundColor3 = DARK
		box.BackgroundTransparency = 0.25
		box.BorderSizePixel = 0
		Instance.new("UICorner", box).CornerRadius = UDim.new(0, radius)

		local stroke = Instance.new("UIStroke")
		stroke.Thickness = 1
		stroke.Color = strokeColor or ACCENT
		stroke.Transparency = strokeTransparency
		stroke.Parent = box
		return stroke
	end

	refreshCells = function()
		for id, cell in pairs(pick.cells) do
			if cell.box.Parent then
				local active = pick.running and pick.name == id
				cell.stroke.Transparency = active and 0 or 0.55
				cell.stroke.Thickness = active and 2 or 1
				cell.box.BackgroundTransparency = active and 0.05 or 0.25
				if active then
					cell.hint.Text = "Voting... tap to stop"
				elseif pick.locked then
					cell.hint.Text = "Round running - wait for lobby"
				else
					cell.hint.Text = "Tap to vote for this map"
				end
				cell.hint.TextColor3 = active and ACCENT or MUTED
			end
		end
	end

	local votesWarned = false

	-- Re-reads the vote count of every card. One map clearly ahead gets the crown; maps tied for the most votes get the tie icon.
	-- It only changes the text / crown of the cards that are already drawn, it never rebuilds them.
	updateVotes = function()
		local best = 0
		local counts = {}
		local unreadable = false
		local anyPad

		for id, cell in pairs(pick.cells) do
			if cell.box.Parent then
				local votePad = votePadAt(cell.padIndex)
				anyPad = anyPad or votePad

				local n = votePad and readVotes(votePad)
				counts[id] = n

				if n then
					if n > best then
						best = n
					end
				else
					unreadable = true
				end
			end
		end

		-- how many maps share the top vote count (a tie when it is more than one)
		local leaders = 0
		for id, cell in pairs(pick.cells) do
			if cell.box.Parent then
				local n = counts[id]
				if n ~= nil and best > 0 and n == best then
					leaders = leaders + 1
				end
			end
		end
		local isTie = leaders > 1

		for id, cell in pairs(pick.cells) do
			if cell.box.Parent then
				local n = counts[id]
				local isLeader = n ~= nil and best > 0 and n == best
				cell.votes.Text = n and tostring(n) or "-"
				-- one map clearly ahead -> crown; maps tied for the top -> the tie icon instead
				cell.crown.Visible = isLeader and not isTie
				cell.tie.Visible = isLeader and isTie
			end
		end

		if unreadable and not votesWarned and not pick.running then
			votesWarned = true
			setStatus("Could not read the vote counts. VoteInfoGui: "
				.. describe(anyPad and anyPad:FindFirstChild("VoteInfoGui")))
		end
	end

	local function clearItems()
		for _, item in ipairs(pick.items) do
			pcall(function()
				item:Destroy()
			end)
		end

		pick.items = {}
		pick.cells = {}
	end

	-- The frame that holds the cards. It lives inside the Paragraph's container, the same way the Skins and
	-- Crosshair grids are put into the main UI (func119 reaches that container).
	local function getHolder()
		if pick.holder and pick.holder.Parent then
			return pick.holder
		end

		local container = statusPara and func119(statusPara)

		if not container then
			return nil
		end

		local holder = Instance.new("Frame")
		holder.Name = "FVLMapCards"
		holder.LayoutOrder = 0
		holder.BackgroundTransparency = 1
		holder.Size = UDim2.new(1, 0, 0, 0)
		holder.Parent = container

		local layout = Instance.new("UIListLayout")
		layout.FillDirection = Enum.FillDirection.Vertical
		layout.Padding = UDim.new(0, 6)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = holder

		local function fit()
			holder.Size = UDim2.new(1, 0, 0, layout.AbsoluteContentSize.Y)
		end

		layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
		fit()

		pick.holder = holder
		return holder
	end

	local function signatureOf(found)
		local parts = {}

		for i, cand in ipairs(found) do
			parts[i] = tostring(cand.name) .. "|" .. tostring(cand.image) .. "|" .. tostring(cand.pos)
		end

		return table.concat(parts, ";")
	end

	local function makeLabel(parent, props)
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Font = props.font or Enum.Font.Gotham
		label.TextSize = props.size or 12
		label.TextColor3 = props.color or Color3.fromRGB(255, 255, 255)
		label.TextXAlignment = props.xAlign or Enum.TextXAlignment.Left
		label.TextYAlignment = props.yAlign or Enum.TextYAlignment.Center
		label.TextWrapped = props.wrapped or false
		label.TextTruncate = props.truncate or Enum.TextTruncate.None
		label.Position = props.position
		label.Size = props.size2
		label.Text = props.text or ""
		label.Parent = parent
		return label
	end

	-- Draws one card (picture + name) per map up for vote, straight into the main UI.
	-- Does nothing when the maps are the same as the last time, unless force is true.
	local function renderCards(force)
		local holder = getHolder()

		if not holder then
			return
		end

		local found = scanFixed() or {}
		local sig = signatureOf(found)

		if not force and sig == pick.sig then
			return
		end

		pick.sig = sig
		clearItems()

		if #found == 0 then
			local empty = makeLabel(holder, {
				position = UDim2.new(0, 0, 0, 0),
				size2 = UDim2.new(1, 0, 0, 44),
				text = "No maps up for vote right now. Go to the lobby, or tap Refresh Maps.",
				color = MUTED,
				wrapped = true,
			})

			pick.items[#pick.items + 1] = empty
			return
		end

		for i, cand in ipairs(found) do
			cand.id = i

			local cell = Instance.new("TextButton")
			cell.Name = "Map" .. i
			cell.LayoutOrder = i
			cell.Size = UDim2.new(1, 0, 0, 84)
			cell.Text = ""
			cell.AutoButtonColor = false
			cell.Parent = holder
			local stroke = styleBox(cell, 8, 0.55)

			-- the picture of the map
			local picture = Instance.new("ImageLabel")
			picture.Name = "Picture"
			picture.Position = UDim2.new(0, 6, 0, 6)
			picture.Size = UDim2.new(0, 112, 1, -12)
			picture.BackgroundColor3 = Color3.fromRGB(24, 24, 30)
			picture.BorderSizePixel = 0
			picture.ScaleType = Enum.ScaleType.Crop
			picture.Image = cand.image or ""
			picture.Parent = cell
			Instance.new("UICorner", picture).CornerRadius = UDim.new(0, 6)

			if not cand.image then
				makeLabel(picture, {
					position = UDim2.new(0, 0, 0, 0),
					size2 = UDim2.new(1, 0, 1, 0),
					text = "Wait for next round",
					size = 12,
					color = MUTED,
					xAlign = Enum.TextXAlignment.Center,
					wrapped = true,
				})
			end

			-- the name of the map (leaves room on the right for the crown and the vote count)
			makeLabel(cell, {
				position = UDim2.new(0, 128, 0, 10),
				size2 = UDim2.new(1, -208, 0, 40),
				text = cand.name,
				font = Enum.Font.GothamBold,
				size = 14,
				yAlign = Enum.TextYAlignment.Top,
				wrapped = true,
				truncate = Enum.TextTruncate.AtEnd,
			})

			local hint = makeLabel(cell, {
				position = UDim2.new(0, 128, 1, -26),
				size2 = UDim2.new(1, -208, 0, 18),
				text = "Tap to vote for this map",
				size = 11,
				color = MUTED,
			})

			-- the crown (only shown on the map with the most votes)
			local crown = Instance.new("ImageLabel")
			crown.Name = "Crown"
			crown.AnchorPoint = Vector2.new(0.5, 0)
			crown.Position = UDim2.new(1, -40, 0, 8)
			crown.Size = UDim2.fromOffset(28, 28)
			crown.BackgroundTransparency = 1
			crown.Image = "rbxassetid://6495659621"
			crown.ScaleType = Enum.ScaleType.Fit
			crown.Visible = false
			crown.Parent = cell

			-- the tie icon (shown instead of the crown on maps that are tied for the most votes)
			local tie = Instance.new("ImageLabel")
			tie.Name = "TieIcon"
			tie.AnchorPoint = Vector2.new(0.5, 0)
			tie.Position = UDim2.new(1, -40, 0, 8)
			tie.Size = UDim2.fromOffset(28, 28)
			tie.BackgroundTransparency = 1
			tie.Image = "rbxassetid://107372061126060"
			tie.ScaleType = Enum.ScaleType.Fit
			tie.Visible = false
			tie.Parent = cell

			-- the vote count
			local votes = makeLabel(cell, {
				position = UDim2.new(1, -40, 0, 38),
				size2 = UDim2.fromOffset(64, 22),
				text = "-",
				font = Enum.Font.GothamBold,
				size = 18,
				color = ACCENT,
				xAlign = Enum.TextXAlignment.Center,
			})
			votes.Name = "Votes"
			votes.AnchorPoint = Vector2.new(0.5, 0)

			local votesCaption = makeLabel(cell, {
				position = UDim2.new(1, -40, 0, 60),
				size2 = UDim2.fromOffset(64, 14),
				text = "votes",
				size = 10,
				color = MUTED,
				xAlign = Enum.TextXAlignment.Center,
			})
			votesCaption.AnchorPoint = Vector2.new(0.5, 0)

			pick.cells[i] = { box = cell, stroke = stroke, hint = hint, crown = crown, tie = tie, votes = votes, padIndex = cand.padIndex }
			pick.items[#pick.items + 1] = cell

			cell.Activated:Connect(function()
				if pick.running and pick.name == cand.id then
					stopPicking("Stopped.") -- tapping the chosen map again turns it off
				else
					startPicking(cand)
				end
			end)
		end

		refreshCells()
		updateVotes()
	end

	-- ===== the Maps tab =====
	tbl43.maps:Section({ Title = "Map Picker" })

	statusPara = tbl43.maps:Paragraph({
		Title = "Maps up for vote [EXPERIMENTAL]",
		Desc = "Tap a map card. You stand on its detector, reset, stand on it again... every time adds another vote for that map, until the game starts. Tap the card again to stop. Each card shows its vote count, and the map with the most votes gets a crown.",
	})

	tbl43.maps:Button({
		Title = "Refresh Maps",
		Icon = "lucide:refresh-cw",
		Desc = "Reads the maps up for vote again (the cards also refresh by themselves).",
		Callback = function()
			renderCards(true)
		end,
	})

	tbl43.maps:Slider({
		Title = "Map Picker: Seconds Before Reset",
		Flag = "Slider_Map_Picker_Interval",
		Desc = "How long you stay on the detector after warping, before the character is reset right away. Lower = faster cycles. If votes do not register, raise it a little.",
		Step = 0.05,
		Value = { Min = 0.05, Max = 5, Default = 0.2 },
		Callback = function(value)
			local n = tonumber(value) or type(value) == "table" and tonumber(value.Value)

			if n then
				pick.interval = n
			end
		end,
	})

	-- ===== Vote Dupe / Map Vote system (ported from Pulse / Qwern) =====
	-- Adds: Dupe Votes (count), Auto Dupe, floating Vote Panel, Silent Respawn,
	-- Farm Priority, Explore Maps, Preferred Map + Fallback. Reuses F$VL's existing
	-- physical VotePad teleport dupe method (same core Pulse uses). Zombie/Survivor unaffected.
	do
		local Players = game:GetService("Players")
		local lp = Players.LocalPlayer
		local VD = {
			count = 10,
			auto = false,
			panel = false,
			silent = false,
			farm = false,
			explore = false,
			preferred = "Any",
			fallback = "skip", -- skip | leading | first
			priority = {}, -- Map Priority: ordered map names, first one up for vote wins
			otherMaps = true, -- dupe a map that is not in the priority list when none of them is up
			running = false,
			token = 0,
			panelGui = nil,
		}
		list2.voteDupe = VD

		local MM2_MAPS = {
			"Any", "Bank 2", "Bio Lab", "Factory", "Hospital 3", "Hotel 2", "House 2",
			"Mansion 2", "Mil Base", "Office 3", "Police Station", "Research Facility", "Workplace",
		}

		local function currentVoteMaps()
			-- reuse F$VL's scanner (same scope)
			local ok, res = pcall(scanFixed)
			if ok and type(res) == "table" then return res end
			return nil
		end

		local function padPos(cand)
			return cand and cand.pos
		end

		-- ===== Pulse-accurate dupe timing (fixed: was slower than real Pulse) =====
		-- Pulse does NOT use LoadCharacter (slower). It kills with Health=0 always;
		-- "Silent Respawn" only mutes death sounds + suppresses SpawnFade/CameraFade GUIs.
		-- After kill it POLLS for the new character (short waits) and teleports the instant
		-- the HRP exists — no fixed wait, no 0.5s retry delay. On the pad it dwells until the
		-- vote count actually increases (min 0.18s, max 1.2s) and re-teleports if drifted off.
		local FADE_GUIS = { "SpawnFade", "CameraFade", "Fade" }

		local function killCharacter()
			pcall(function()
				local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
				if hum then hum.Health = 0 end
			end)
		end

		local function silentEffects()
			if not VD.silent then return end
			pcall(function()
				local c = lp.Character
				if c then
					for _, d in ipairs(c:GetDescendants()) do
						if d:IsA("Sound") and (d.Name == "Died" or string.find(string.lower(d.Name), "death", 1, true)) then
							d.Volume = 0
							d:Stop()
						end
					end
				end
				local pg = lp:FindFirstChildOfClass("PlayerGui")
				if pg then
					for _, name in ipairs(FADE_GUIS) do
						local g = pg:FindFirstChild(name)
						if g and g:IsA("ScreenGui") and g.Enabled then
							g.Enabled = false
							task.delay(4, function()
								pcall(function() if g.Parent then g.Enabled = true end end)
							end)
						end
					end
				end
			end)
		end

		-- Pulse callback2 pattern: poll for new character + HRP, return immediately when ready
		local function waitForCharacter(timeout)
			local deadline = os.clock() + (timeout or 5)
			while os.clock() < deadline do
				local c = lp.Character
				local hrp = c and c:FindFirstChild("HumanoidRootPart")
				local hum = c and c:FindFirstChildOfClass("Humanoid")
				if hrp and hum and hum.Health > 0 then
					return c, hrp, hum
				end
				task.wait(0.05)
			end
			return nil, nil, nil
		end

		local function pickCandidate(maps)
			-- Map Priority (ported from Pulse): the first listed map that is up for vote wins
			for _, pname in ipairs(VD.priority or {}) do
				local key = string.lower(tostring(pname):match("^(%w+)") or "")
				if key ~= "" then
					for _, c in ipairs(maps) do
						if string.find(string.lower(c.name or ""), key, 1, true) then
							return c
						end
					end
				end
			end
			if VD.priority and #VD.priority > 0 and VD.otherMaps == false then
				return nil
			end
			-- Farm Priority / Preferred Map logic (Pulse-style)
			if VD.preferred ~= "Any" then
				for _, c in ipairs(maps) do
					if string.find(string.lower(c.name or ""), string.lower(VD.preferred:match("^(%w+)") or ""), 1, true) then
						return c
					end
				end
			end
			if VD.fallback == "first" then
				return maps[1]
			elseif VD.fallback == "leading" then
				local best, bestN = maps[1], -1
				for _, c in ipairs(maps) do
					local pad = votePadAt and votePadAt(c.padIndex)
					local n = 0
					pcall(function()
						if pad then
							local v = readVotes and readVotes(pad)
							if type(v) == "number" then n = v end
						end
					end)
					if n > bestN then best, bestN = c, n end
				end
				return best
			end
			return nil
		end

		-- Pulse-accurate dupe loop (handleAction2): teleport → dwell until vote counted →
		-- kill → poll for respawn → repeat immediately.
		function VD.startDupe(n)
			if VD.running then return end
			local maps = currentVoteMaps()
			if not maps or #maps == 0 then
				pcall(function() obj2:Notify({ Title = "Vote Dupe", Content = "No maps up for vote. Wait for lobby.", Duration = 4, Icon = "x" }) end)
				return
			end
			local cand = pickCandidate(maps)
			if not cand then
				pcall(function() obj2:Notify({ Title = "Vote Dupe", Content = "Preferred map not available (fallback = skip).", Duration = 4, Icon = "x" }) end)
				return
			end
			VD.running = true
			VD.token = VD.token + 1
			local token = VD.token
			local total = math.clamp(math.floor(tonumber(n) or VD.count or 10), 1, 200)
			task.spawn(function()
				local done = 0
				local fails = 0
				local c, hrp, hum = waitForCharacter(15)
				while done < total and VD.running and token == VD.token do
					if gameStarting and gameStarting() then break end
					if not hrp then
						c, hrp, hum = waitForCharacter(5)
						if not hrp then
							task.wait(0.2)
							fails = fails + 1
							if fails > 3 then break end
						else
							fails = 0
						end
					else
						fails = 0
					end
					if not hrp then
						-- still no character after wait, skip this iteration
					else
						fails = 0
						-- pre-cache pad CFrame: 1.2 studs above detector (Pulse exact offset)
						local basePos = cand.pos
						local padCFrame = CFrame.new(basePos + Vector3.new(0, 1.2, 0))
						local startVotes = 0
						pcall(function()
							local pad = votePadAt and votePadAt(cand.padIndex)
							local v = pad and readVotes and readVotes(pad)
							if type(v) == "number" then startVotes = v end
						end)
						hrp.AssemblyLinearVelocity = Vector3.zero
						hrp.CFrame = padCFrame
						local t0 = os.clock()
						local counted = false
						-- dwell until vote registers (Pulse: up to 1.2s, min 0.18s, re-teleport if drifted)
						while os.clock() - t0 < 1.2 and VD.running and token == VD.token do
							if hrp.Parent then
								local diff = hrp.Position - basePos
								if Vector3.new(diff.X, 0, diff.Z).Magnitude > 1.5 or math.abs(diff.Y) > 3.5 then
									hrp.AssemblyLinearVelocity = Vector3.zero
									hrp.CFrame = padCFrame
								end
							end
							if os.clock() - t0 >= 0.18 then
								pcall(function()
									local pad = votePadAt and votePadAt(cand.padIndex)
									local v = pad and readVotes and readVotes(pad)
									if type(v) == "number" and v > startVotes then
										counted = true
									end
								end)
								if counted then break end
							end
							if RunService_ and RunService_.Heartbeat then
								RunService_.Heartbeat:Wait()
							else
								task.wait()
							end
						end
						if counted then done = done + 1 end
						if done >= total or not (VD.running and token == VD.token) then break end
						silentEffects()
						killCharacter()
						c, hrp, hum = waitForCharacter(8)
					end
				end
				VD.running = false
				pcall(function() obj2:Notify({ Title = "Vote Dupe", Content = "Done: " .. done .. "/" .. total .. " votes.", Duration = 4, Icon = "check" }) end)
			end)
		end

		function VD.stopDupe()
			VD.token = VD.token + 1
			VD.running = false
		end

		-- Auto Dupe: watch for vote phase, auto-start
		task.spawn(function()
			while true do
				task.wait(1)
				pcall(function()
					if not VD.auto or VD.running then return end
					if gameStarting and gameStarting() then return end
					local maps = currentVoteMaps()
					if maps and #maps > 0 then
						VD.startDupe(VD.count)
					end
				end)
			end
		end)

		-- ===== Floating Vote Panel =====
		local function buildPanel()
			if VD.panelGui then return VD.panelGui end
			local pg = Instance.new("ScreenGui")
			pg.Name = "FVL_VotePanel"
			pg.ResetOnSpawn = false
			pg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			pcall(function() pg.Parent = game:GetService("CoreGui") end)
			if not pg.Parent then pcall(function() pg.Parent = lp:WaitForChild("PlayerGui") end) end

			local frame = Instance.new("Frame")
			frame.Name = "Panel"
			frame.Size = UDim2.new(0, 240, 0, 140)
			frame.Position = UDim2.new(0.5, -120, 0.1, 0)
			frame.BackgroundColor3 = Color3.fromRGB(24, 26, 33)
			frame.BorderSizePixel = 0
			frame.Active = true
			frame.Draggable = true
			pcall(function()
				local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, 8) corner.Parent = frame
				local stroke = Instance.new("UIStroke") stroke.Color = Color3.fromRGB(60, 66, 80) stroke.Parent = frame
			end)
			frame.Parent = pg

			local title = Instance.new("TextLabel")
			title.Size = UDim2.new(1, 0, 0, 24)
			title.BackgroundTransparency = 1
			title.Text = "Vote Panel (Pulse)"
			title.TextColor3 = Color3.fromRGB(220, 225, 235)
			title.TextSize = 13
			title.Font = Enum.Font.GothamBold
			title.Parent = frame

			local layout = Instance.new("UIListLayout")
			layout.Padding = UDim.new(0, 4)
			layout.Parent = frame

			local rows = {}
			for i = 1, 3 do
				local btn = Instance.new("TextButton")
				btn.Size = UDim2.new(1, -16, 0, 28)
				btn.Position = UDim2.new(0, 8, 0, 28 + (i - 1) * 32)
				btn.BackgroundColor3 = Color3.fromRGB(34, 37, 45)
				btn.BorderSizePixel = 0
				btn.Text = "Map " .. i
				btn.TextColor3 = Color3.fromRGB(220, 225, 235)
				btn.TextSize = 12
				btn.Font = Enum.Font.Gotham
				pcall(function()
					local c = Instance.new("UICorner") c.CornerRadius = UDim.new(0, 6) c.Parent = btn
				end)
				btn.Parent = frame
				btn.MouseButton1Click:Connect(function()
					local maps = currentVoteMaps()
					if maps and maps[i] then VD.startDupe(VD.count) end
				end)
				rows[i] = btn
			end

			VD.panelRows = rows
			VD.panelGui = pg
			return pg
		end

		local function destroyPanel()
			if VD.panelGui then pcall(function() VD.panelGui:Destroy() end) VD.panelGui = nil end
		end

		-- refresh panel text
		task.spawn(function()
			while true do
				task.wait(0.5)
				pcall(function()
					if not (VD.panel and VD.panelGui and VD.panelRows) then return end
					local maps = currentVoteMaps()
					for i = 1, 3 do
						local btn = VD.panelRows[i]
						if btn then
							local c = maps and maps[i]
							if c then
								local votes = ""
								pcall(function()
									local pad = votePadAt and votePadAt(c.padIndex)
									local v = pad and readVotes and readVotes(pad)
									if type(v) == "number" then votes = "  [" .. v .. " votes]" end
								end)
								btn.Text = c.name .. votes
							else
								btn.Text = "Map " .. i .. " (waiting)"
							end
						end
					end
				end)
			end
		end)

		-- cleanup on unload
		pcall(function()
			if list2.conns then
				-- store a pseudo-connection with a Destroy method
				list2.conns[#list2.conns + 1] = { Disconnect = function() destroyPanel(); VD.stopDupe() end }
			end
		end)

		-- ===== UI (Maps tab) =====
		tbl43.maps:Section({ Title = "Vote Dupe (Pulse)" })

		tbl43.maps:Slider({
			Title = "Votes to add",
			Flag = "Slider_VoteDupe_Count",
			Desc = "How many duplicate votes to cast (1-100).",
			Step = 1, Min = 1, Max = 100, Value = 10,
			Callback = function(v) VD.count = math.clamp(math.floor(tonumber(v) or 10), 1, 100) end,
		})

		tbl43.maps:Button({
			Title = "Dupe Votes",
			Icon = "lucide:vote",
			Desc = "Cast duplicate votes for the preferred map now.",
			Callback = function() VD.startDupe(VD.count) end,
		})

		tbl43.maps:Button({
			Title = "Stop Dupe",
			Icon = "lucide:square",
			Desc = "Stop the ongoing vote dupe loop.",
			Callback = function() VD.stopDupe() end,
		})

		tbl43.maps:Toggle({
			Title = "Auto Dupe",
			Flag = "Toggle_VoteDupe_Auto",
			Desc = "Automatically start duping when a vote phase begins.",
			Type = "Toggle", Value = false,
			Callback = function(v) VD.auto = v and true or false end,
		})

		tbl43.maps:Toggle({
			Title = "Vote Panel",
			Flag = "Toggle_VoteDupe_Panel",
			Desc = "Show a floating panel with the 3 maps up for vote + quick vote buttons.",
			Type = "Toggle", Value = false,
			Callback = function(v)
				VD.panel = v and true or false
				if VD.panel then buildPanel() else destroyPanel() end
			end,
		})

		tbl43.maps:Toggle({
			Title = "Silent Respawn",
			Flag = "Toggle_VoteDupe_Silent",
			Desc = "Use LoadCharacter() for faster respawn between dupes (no death animation).",
			Type = "Toggle", Value = false,
			Callback = function(v) VD.silent = v and true or false end,
		})

		tbl43.maps:Toggle({
			Title = "Farm Priority",
			Flag = "Toggle_VoteDupe_Farm",
			Desc = "Prefer maps that are best for coin autofarm (uses Preferred Map list).",
			Type = "Toggle", Value = false,
			Callback = function(v) VD.farm = v and true or false end,
		})

		tbl43.maps:Toggle({
			Title = "Explore Maps",
			Flag = "Toggle_VoteDupe_Explore",
			Desc = "When farming, cycle through maps to measure coin rates (hooks into autofarm hop).",
			Type = "Toggle", Value = false,
			Callback = function(v)
				VD.explore = v and true or false
				pcall(function() if list2.farm then list2.farm.exploreMaps = VD.explore end end)
			end,
		})

		tbl43.maps:Dropdown({
			Title = "Preferred Map",
			Flag = "Dropdown_VoteDupe_Preferred",
			Desc = "Map to prioritize when duping (Any = first available).",
			Multi = false, Value = "Any", Values = MM2_MAPS,
			Callback = function(v) if v then VD.preferred = v end end,
		})

		tbl43.maps:Dropdown({
			Title = "Fallback",
			Flag = "Dropdown_VoteDupe_Fallback",
			Desc = "What to dupe if the preferred map is not up for vote.",
			Multi = false, Value = "Don't dupe",
			Values = { "Don't dupe", "Dupe most voted", "Dupe first map" },
			Callback = function(v)
				if v == "Dupe most voted" then VD.fallback = "leading"
				elseif v == "Dupe first map" then VD.fallback = "first"
				else VD.fallback = "skip" end
			end,
		})

		-- ===== Map Priority (ported from Pulse): ordered choices for the dupe =====
		do
			local picks = { "None", "None", "None" }
			local els = {}
			local values = { "None" }
			for _, m in ipairs(MM2_MAPS) do
				if m ~= "Any" then
					values[#values + 1] = m
				end
			end

			local function rebuild()
				local out, seen = {}, {}
				for _, m in ipairs(picks) do
					if m ~= "None" and not seen[m] then
						seen[m] = true
						out[#out + 1] = m
					end
				end
				VD.priority = out
			end

			tbl43.maps:Section({ Title = "Map Priority" })

			for i = 1, 3 do
				els[i] = tbl43.maps:Dropdown({
					Title = "Priority " .. i,
					Flag = "Dropdown_VoteDupe_Priority" .. i,
					Desc = i == 1 and "First choice. The dupe votes for the first map in this list that is up for vote." or "Used when the maps above it are not up for vote.",
					Multi = false,
					Value = "None",
					Values = values,
					Callback = function(v)
						if type(v) == "table" then
							v = v[1] or v.Value
						end
						picks[i] = tostring(v or "None")
						rebuild()
					end,
				})
			end

			tbl43.maps:Toggle({
				Title = "Other maps",
				Flag = "Toggle_VoteDupe_OtherMaps",
				Desc = "On: if none of the priority maps is up for vote, fall back to Preferred Map / Fallback. Off: skip the dupe instead.",
				Type = "Toggle",
				Value = true,
				Callback = function(v)
					VD.otherMaps = v and true or false
				end,
			})

			tbl43.maps:Button({
				Title = "Reset Priority",
				Icon = "lucide:rotate-ccw",
				Desc = "Clears the three priority choices.",
				Callback = function()
					for i = 1, 3 do
						picks[i] = "None"
						list2.setToggle(els[i], "None")
					end
					rebuild()
				end,
			})
		end
	end

	-- the picking stops when the UI is closed
	pcall(function()
		obj3:OnDestroy(function()
			pcall(stopPicking, "UI closed.")
		end)
	end)

	-- live vote counts + crown: re-read the vote pads twice a second (also while a pick is running)
	task.spawn(function()
		while not obj3.Destroyed do
			task.wait(0.5)

			if pick.holder and not pick.holder.Parent then
				break
			end

			local visible = true
			pcall(function()
				local root = obj3._oasis and obj3._oasis.Root
				if root then
					visible = root.Visible
				end
			end)

			if visible and next(pick.cells) ~= nil then
				pcall(updateVotes)

				-- lock / unlock the cards when the round starts / ends
				local okLock, locked = pcall(gameStarting)

				if okLock and locked ~= (pick.locked or false) then
					pick.locked = locked
					pcall(refreshCells)
				end
			end
		end
	end)

	-- draw the cards now, then keep them in sync with the vote pads (not while a pick is running or in a round)
	task.spawn(function()
		pcall(renderCards, true)

		while not obj3.Destroyed do
			task.wait(4)

			if pick.holder and not pick.holder.Parent then
				break
			end

			local visible = true
			pcall(function()
				local root = obj3._oasis and obj3._oasis.Root
				if root then
					visible = root.Visible
				end
			end)

			local inLobby = true
			pcall(function()
				inLobby = list2.inLobbyNow()
			end)

			if visible and inLobby and not pick.running then
				pcall(renderCards, false)
			end
		end
	end)
end

-- ===== Invisible =====
-- Same principle as the invisibility script you sent: every frame, right after the physics step (when your
-- position is sent to the other players), the character's root part is moved 200000 studs straight down and the
-- camera offset is raised by the same amount; right before the next frame is drawn both are put back. You see
-- and control yourself normally, while the server and other players only ever receive a position far under the
-- map. Your body is also drawn half transparent on YOUR screen so you can tell it is on.
-- Side effects: others see you far away, so touching things on the map (coins, doors) and your own hits may not
-- register while it is on.
-- Shift Lock fix: the camera and Shift Lock read your character's position every frame at their own point in the
-- frame. The "put back where I really am" step is therefore bound at the very FIRST render priority (before the
-- camera and before Shift Lock turn your character), so they always see the real, normal position and never the
-- spot far under the map.
do
	local RunService_ = game:GetService("RunService")
	local DEPTH = 200000
	local inv = { on = false, saved = nil, conns = {}, parts = {} }
	list2.invis = inv

	local function restoreSaved()
		local saved = inv.saved
		inv.saved = nil

		if saved and saved.hrp.Parent and saved.hum.Parent then
			saved.hrp.CFrame = saved.cf
			saved.hum.CameraOffset = saved.off
		end
	end

	local function restoreParts()
		for i = #inv.parts, 1, -1 do
			local part = inv.parts[i]

			if part.Parent then
				part.Transparency = 0
			end

			inv.parts[i] = nil
		end
	end

	local function collectParts(character)
		if not character then
			return
		end

		for _, item in ipairs(character:GetDescendants()) do
			if item:IsA("BasePart") and item.Name ~= "HumanoidRootPart" and item.Transparency == 0 then
				item.Transparency = 0.5
				inv.parts[#inv.parts + 1] = item
			end
		end
	end

	list2.setInvisible = function(on)
		on = on and true or false

		if inv.on == on then
			return
		end

		inv.on = on

		for i = #inv.conns, 1, -1 do
			pcall(function()
				inv.conns[i]:Disconnect()
			end)

			inv.conns[i] = nil
		end

		pcall(function()
			RunService_:UnbindFromRenderStep("FVLInvisRestore")
		end)

		restoreSaved()
		restoreParts()

		if on then
			collectParts(localPlayer.Character)

			-- after physics: what gets sent to everyone is the position far under the map
			inv.conns[#inv.conns + 1] = RunService_.Heartbeat:Connect(function()
				pcall(function()
					local character = localPlayer.Character
					local hrp = character and character:FindFirstChild("HumanoidRootPart")
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if not hrp or not humanoid or humanoid.Health <= 0 then
						return
					end

					local cf, off = hrp.CFrame, humanoid.CameraOffset
					inv.saved = { hrp = hrp, hum = humanoid, cf = cf, off = off }
					hrp.CFrame = cf * CFrame.new(0, -DEPTH, 0)
					humanoid.CameraOffset = off + Vector3.new(0, DEPTH, 0)
				end)
			end)

			-- before the camera / Shift Lock / the next frame: back to where we really are (first render priority)
			RunService_:BindToRenderStep("FVLInvisRestore", Enum.RenderPriority.First.Value, restoreSaved)

			-- a new character (respawn): pick up its parts again
			inv.conns[#inv.conns + 1] = localPlayer.CharacterAdded:Connect(function(character)
				task.wait(1)

				if inv.on and localPlayer.Character == character then
					restoreParts()
					collectParts(character)
				end
			end)
		end

		-- keep the floating button and the tab switch in step with each other
		pcall(function()
			num15.setActive("Invis", on)
		end)

		pcall(function()
			list2.setToggle(list2.invisToggle, on)
		end)
	end
end

