-- ===== Imported cursors (from the Noir hub): Gothic Spear / Gothic Wings / Shadow Sigil + 9 artwork cursors =====
-- They are added to CURSORS / CURSOR_ORDER so they appear in the normal Crosshair grid. The 9 artwork cursors are
-- embedded PNGs: written once into FVLV2_cursors/ and loaded with getcustomasset (needs writefile + getcustomasset).
do
	CURSORS["Gothic Spear"] = "rbxassetid://77559278786615"
	CURSORS["Gothic Wings"] = "rbxassetid://73847458193538"
	CURSORS["Shadow Sigil"] = "rbxassetid://130499812243487"

	local BUNDLES = {
		{ "Dark Seraph", "noir_cursor_v2_01_dark_seraph.png", "" },
		{ "Thorn Gun", "noir_cursor_v2_02_thorn_gun.png", "" },
		{ "Crimson Halo", "noir_cursor_v2_03_crimson_halo.png", "" },
		{ "Radiant Halo", "noir_cursor_v2_04_radiant_halo.png", "" },
		{ "Moonblade", "noir_cursor_v2_05_moonblade.png", "" },
		{ "Void Slash", "noir_cursor_v2_06_void_slash.png", "" },
		{ "Script Blade", "noir_cursor_v2_07_script_blade.png", "" },
		{ "Light Seraph", "noir_cursor_v2_08_light_seraph.png", "" },
		{ "Infinity", "noir_cursor_v2_09_infinity.png", "" },
	}

	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lookup = {}
	for i = 1, 64 do lookup[alphabet:byte(i)] = i - 1 end

	local function b64decode(data)
		data = data:gsub("[^%w%+/=]", "")
		local out, n = {}, 0
		for i = 1, #data, 4 do
			local a, b, c, d = data:byte(i, i + 3)
			local x = (lookup[a] or 0) * 262144 + (lookup[b] or 0) * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
			local b1, b2, b3 = math.floor(x / 65536) % 256, math.floor(x / 256) % 256, x % 256
			n = n + 1
			if c == 61 then out[n] = string.char(b1)
			elseif d == 61 then out[n] = string.char(b1, b2)
			else out[n] = string.char(b1, b2, b3) end
		end
		return table.concat(out)
	end

	local loader = (type(getcustomasset) == "function" and getcustomasset) or (type(getsynasset) == "function" and getsynasset) or nil
	local folder = "FVLV2_cursors"
	pcall(function()
		if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder(folder) then makefolder(folder) end
	end)

	for _, bundle in ipairs(BUNDLES) do
		local name, file, data = bundle[1], bundle[2], bundle[3]
		local image = nil
		if loader and type(writefile) == "function" then
			pcall(function()
				local path = folder .. "/" .. file
				if not (type(isfile) == "function" and isfile(path)) then writefile(path, b64decode(data)) end
				local asset = loader(path)
				if type(asset) == "string" and asset ~= "" then image = asset end
			end)
		end
		-- no file support in this executor: fall back to the default gun icon so the grid slot is not blank
		CURSORS[name] = image or CURSORS.Default
	end
end
