-- ===== Server extras (ported from Pulse): Job ID + live Server Info =====
xpcall(function()
	local TeleportServiceS = game:GetService("TeleportService")
	local PlayersS = game:GetService("Players")
	local lpS = PlayersS.LocalPlayer
	local jobInput = ""
	local joining = false
	local alive = true

	local function say(title, text, icon)
		pcall(function()
			obj2:Notify({ Title = title, Content = text, Duration = 3, Icon = icon or "check" })
		end)
	end

	tbl43.settings:Section({ Title = "Job ID" })

	tbl43.settings:Button({
		Title = "Copy Job ID",
		Desc = "Copies the Job ID of the server you are in right now.",
		Icon = "lucide:copy",
		Callback = function()
			local copy = setclipboard or toclipboard or (syn and syn.set_clipboard)
			local ok = copy ~= nil and pcall(copy, tostring(game.JobId))
			if ok then
				say("Job ID", "Copied!", "check")
			else
				say("Job ID", "Your executor has no setclipboard.", "x")
			end
		end,
	})

	tbl43.settings:Input({
		Title = "Job ID",
		Flag = "Input_Server_JobId",
		Desc = "Paste the Job ID of another server of this game, then press Join Job ID.",
		Placeholder = "Job ID...",
		Callback = function(value)
			jobInput = tostring(value or "")
		end,
	})

	tbl43.settings:Button({
		Title = "Join Job ID",
		Desc = "Teleports you to the server with the Job ID above.",
		Icon = "lucide:log-in",
		Callback = function()
			local id = jobInput:gsub("^%s+", ""):gsub("%s+$", "")
			if id == "" then
				say("Job ID", "Paste a Job ID first.", "x")
				return
			end
			if id == tostring(game.JobId) then
				say("Job ID", "You are already on this server.", "x")
				return
			end
			if joining then
				return
			end
			joining = true
			say("Job ID", "Joining...", "loader")
			task.spawn(function()
				local ok, err = pcall(function()
					TeleportServiceS:TeleportToPlaceInstance(game.PlaceId, id, lpS)
				end)
				if not ok then
					joining = false
					say("Job ID", "Error: " .. tostring(err), "x")
				end
			end)
		end,
	})

	local failConn = TeleportServiceS.TeleportInitFailed:Connect(function(_player, _result, msg)
		joining = false
		say("Job ID", "Teleport failed: " .. tostring(msg), "x")
	end)

	tbl43.settings:Section({ Title = "Server Info" })
	local infoLabel = tbl43.settings:Label({ Text = "..." })

	task.spawn(function()
		while alive do
			pcall(function()
				local ping = 0
				pcall(function()
					ping = math.floor(lpS:GetNetworkPing() * 1000 + 0.5)
				end)
				infoLabel:Set(string.format("Players: %d/%d   Ping: %d ms\nJob: %s", #PlayersS:GetPlayers(), PlayersS.MaxPlayers, ping, tostring(game.JobId)))
			end)
			task.wait(2)
		end
	end)

	obj3:OnDestroy(function()
		alive = false
		pcall(function()
			failConn:Disconnect()
		end)
	end)
end, function(err)
	warn("[FVL] Server extras failed to load: " .. tostring(err))
end)

-- ===== Fade Watchdog (ported from Pulse) =====
-- If a black fade screen (SpawnFade / CameraFade / DeathFade) stays on top while you are alive, it is cleared.
xpcall(function()
	local TweenServiceW = game:GetService("TweenService")
	local lpW = game:GetService("Players").LocalPlayer
	local FW = { on = true, alive = true, dark = {}, aliveAt = nil, fixes = 0, log = {} }
	_G.FVLFadeWatch = FW
	local WATCHED = { SpawnFade = true, CameraFade = true, DeathFade = true }

	tbl43.settings:Section({ Title = "Fade Watchdog" })

	local fwLabel = tbl43.settings:Label({ Text = "Stuck fades cleared: 0" })

	tbl43.settings:Toggle({
		Title = "Fade Watchdog",
		Flag = "Toggle_Fade_Watchdog",
		Desc = "If a black fade screen stays on for more than 5 seconds while you are alive, it is removed and the camera is given back to you.",
		Type = "Toggle",
		Value = true,
		Callback = function(value)
			FW.on = value == true
			if not FW.on then
				FW.dark = {}
				FW.aliveAt = nil
			end
		end,
	})

	task.spawn(function()
		while FW.alive do
			task.wait(0.5)
			if FW.on then
				pcall(function()
					local playerGui = lpW:FindFirstChildOfClass("PlayerGui")
					if not playerGui then
						return
					end
					local character = lpW.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					local isAlive = humanoid ~= nil and humanoid.Health > 0 and character:FindFirstChild("HumanoidRootPart") ~= nil
					if isAlive then
						FW.aliveAt = FW.aliveAt or os.clock()
					else
						FW.aliveAt = nil
					end
					local now, seen = os.clock(), {}
					for _, gui in ipairs(playerGui:GetChildren()) do
						if WATCHED[gui.Name] and gui:IsA("ScreenGui") and gui.Enabled then
							local fade = gui:FindFirstChild("Fade")
							if fade and fade:IsA("GuiObject") and fade.Visible and fade.BackgroundTransparency < 0.05 then
								seen[fade] = true
								FW.dark[fade] = FW.dark[fade] or now
								if isAlive and now - FW.aliveAt > 2 and now - FW.dark[fade] > 5 then
									FW.fixes = FW.fixes + 1
									if #FW.log < 30 then
										FW.log[#FW.log + 1] = os.date("%H:%M:%S") .. " " .. gui.Name
									end
									if gui.Name == "DeathFade" then
										pcall(function()
											gui:Destroy()
										end)
									else
										pcall(function()
											TweenServiceW:Create(fade, TweenInfo.new(0.3), { BackgroundTransparency = 1 }):Play()
										end)
									end
									FW.dark[fade] = nil
									local camera = workspace.CurrentCamera
									if camera and camera.CameraType == Enum.CameraType.Scriptable then
										pcall(function()
											camera.CameraType = Enum.CameraType.Custom
											camera.CameraSubject = humanoid
										end)
									end
								end
							end
						end
					end
					for key in pairs(FW.dark) do
						if not seen[key] then
							FW.dark[key] = nil
						end
					end
				end)
			end
		end
	end)

	task.spawn(function()
		while FW.alive do
			pcall(function()
				fwLabel:Set("Stuck fades cleared: " .. tostring(FW.fixes))
			end)
			task.wait(2)
		end
	end)

	obj3:OnDestroy(function()
		FW.alive = false
	end)
end, function(err)
	warn("[FVL] Fade Watchdog failed to load: " .. tostring(err))
end)

