-- ============================================================================
--  Meow mascots
--  Ported from the Mimka build. UI lives in  Settings & Configs  ->  "Meow".
--  An animated mascot (Mimi / Furry / Koti / Protogen Bongo, or your own
--  image via Custom) that sits on the top-right corner of the menu.
-- ============================================================================
do
	local RunService_ = game:GetService("RunService")
	local GuiService_ = game:GetService("GuiService")

	local ASSET_BASE = "https://raw.githubusercontent.com/Royal-Script-hub/mimka/main/"
	local FRAME_INTERVAL = 0.12

	local canAssets = (writefile and getcustomasset) and true or false

	-- one entry per mascot. dx/dy = how far the mascot sits in from the menu's
	-- top-right corner (dy is how far it rises above the top edge), w/h in px at 100%.
	local MASCOTS = {
		Mimi = { file = "mimka.png", kind = "sheet", cols = 5, rows = 5, frames = 23, w = 128, h = 160, dx = 120, dy = 100 },
		Furry = { file = "furryan.png", kind = "sheet", cols = 5, rows = 4, frames = 18, w = 128, h = 128, dx = 135, dy = 57 },
		Koti = { file = "koti1.png", kind = "static", w = 230, h = 230, dx = 230, dy = 90 },
		["Protogen Bongo"] = { file = "protogen-bongo.png", kind = "strip", cols = 5, frames = 2, w = 128, h = 128, dx = 150, dy = 23 },
		Custom = { kind = "static", w = 230, h = 230, dx = 230, dy = 90 },
	}

	local M = {
		choice = "None",
		scale = 1,
		offX = 0,
		offY = 0,
		customUrl = "",
		token = 0,
		gui = nil,
		cur = nil,
		acc = 0,
		alpha = 0,
		conn = nil,
		sq = 0, -- squash amount (1 = fully squashed, below 0 = stretched past normal)
		sqVel = 0,
		sqGoal = 0,
	}

	-- remove an overlay left behind by a crashed run
	pcall(function()
		for _, child in ipairs(hui:GetChildren()) do
			if child.Name == "FVLMeowOverlay" then
				child:Destroy()
			end
		end
	end)

	local function say(content, icon)
		pcall(function()
			obj2:Notify({ Title = "Meow", Content = content, Duration = 3, Icon = icon or "check" })
		end)
	end

	-- images -----------------------------------------------------------------
	local assetCache = {}

	-- downloads a PNG and turns it into a local asset id (cached per url)
	local function fetchAsset(url, tag)
		if assetCache[url] then
			return assetCache[url]
		end
		if not canAssets then
			return nil
		end

		local okGet, data = pcall(function()
			return game:HttpGet(url)
		end)
		if not okGet or type(data) ~= "string" or data == "" then
			return nil
		end

		local file = ("fvl_%s_%d.png"):format(tag, math.random(100000, 999999))
		if not pcall(writefile, file, data) then
			return nil
		end

		local okAsset, asset = pcall(getcustomasset, file)
		task.delay(5, function()
			pcall(function()
				if delfile then
					delfile(file)
				end
			end)
		end)

		if okAsset and type(asset) == "string" and asset ~= "" then
			assetCache[url] = asset
			return asset
		end
		return nil
	end

	-- the menu window -------------------------------------------------------------
	local rootCache
	local lastScan = 0

	local function viewport()
		local cam = workspace.CurrentCamera
		return cam and cam.ViewportSize or Vector2.new(1920, 1080)
	end

	local function isFullScreen(inst)
		local v, sz = viewport(), inst.AbsoluteSize
		return sz.X >= v.X * 0.95 and sz.Y >= v.Y * 0.95
	end

	-- climb up to the outermost frame that is still a window (not a full-screen layer)
	local function outerFrame(inst)
		local cur = inst
		while cur.Parent and cur.Parent:IsA("GuiObject") and not isFullScreen(cur.Parent) do
			cur = cur.Parent
		end
		return cur
	end

	local function findRoot()
		local r = oasisWindow and oasisWindow.Root
		if typeof(r) == "Instance" and r:IsA("GuiObject") then
			return outerFrame(r)
		end

		-- fallback: the biggest non-full-screen frame inside the UI library's GUIs
		local best, bestArea = nil, 200 * 200
		for _, g in ipairs(_FVL.libGuis or {}) do
			for _, d in ipairs(g:GetDescendants()) do
				if d:IsA("Frame") and not isFullScreen(d) then
					local area = d.AbsoluteSize.X * d.AbsoluteSize.Y
					if area > bestArea then
						best, bestArea = d, area
					end
				end
			end
		end
		return best and outerFrame(best)
	end

	local function getRoot()
		local now = os.clock()
		if rootCache and rootCache.Parent and now - lastScan < 3 then
			return rootCache
		end
		lastScan = now
		rootCache = findRoot() or (rootCache and rootCache.Parent and rootCache) or nil
		return rootCache
	end

	local function isShown(inst)
		local cur = inst
		while cur and cur ~= game do
			if cur:IsA("GuiObject") and not cur.Visible then
				return false
			end
			if cur:IsA("LayerCollector") and not cur.Enabled then
				return false
			end
			cur = cur.Parent
		end
		local size = inst.AbsoluteSize
		return size.X > 40 and size.Y > 40
	end

	-- mascot -------------------------------------------------------------------
	local function ensureOverlay()
		if M.gui and M.gui.Parent then
			return
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "FVLMeowOverlay"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
		gui.DisplayOrder = 10000
		gui.Parent = hui
		M.gui = gui
	end

	local function clearMascot()
		local cur = M.cur
		M.cur = nil
		if cur and cur.clip then
			pcall(function()
				cur.clip:Destroy()
			end)
		end
	end

	local function buildMascot(name, asset)
		local def = MASCOTS[name]
		if not def or not M.gui then
			return
		end

		local clip = Instance.new("Frame")
		clip.Name = (name:gsub("%s", "")) .. "Clip"
		clip.BackgroundTransparency = 1
		clip.BorderSizePixel = 0
		clip.ClipsDescendants = def.kind ~= "static"
		clip.ZIndex = 10000
		clip.Visible = false
		clip.Parent = M.gui

		local cur = { def = def, clip = clip, images = {}, idx = 0 }

		if def.kind == "static" then
			local img = Instance.new("ImageLabel")
			img.Name = "MeowImage"
			img.BackgroundTransparency = 1
			img.Size = UDim2.fromScale(1, 1)
			img.ScaleType = Enum.ScaleType.Fit
			img.Image = asset
			img.ZIndex = 10001
			img.Parent = clip
			cur.images[1] = img
		elseif def.kind == "sheet" then
			-- sprite sheet: cols x rows cells, we slide it around inside the clip
			local sheet = Instance.new("ImageLabel")
			sheet.Name = "MeowSheet"
			sheet.BackgroundTransparency = 1
			sheet.Size = UDim2.fromScale(def.cols, def.rows)
			sheet.Image = asset
			sheet.ZIndex = 10001
			sheet.Parent = clip
			cur.images[1] = sheet
			cur.sheet = sheet
		else
			-- strip: one label per frame, each showing one cell of the strip
			for i = 0, def.frames - 1 do
				local img = Instance.new("ImageLabel")
				img.Name = "MeowFrame" .. (i + 1)
				img.BackgroundTransparency = 1
				img.Size = UDim2.fromScale(def.cols, 1)
				img.Position = UDim2.fromScale(-i, 0)
				img.ScaleType = Enum.ScaleType.Stretch
				img.Image = asset
				img.Visible = (i == 0)
				img.ZIndex = 10001
				img.Parent = clip
				cur.images[i + 1] = img
			end
		end

		-- invisible button over the mascot: press = squash, release = spring back (a little bigger first)
		local btn = Instance.new("TextButton")
		btn.Name = "MeowButton"
		btn.BackgroundTransparency = 1
		btn.BorderSizePixel = 0
		btn.Text = ""
		btn.AutoButtonColor = false
		btn.Size = UDim2.fromScale(1, 1)
		btn.ZIndex = 10005
		btn.Parent = clip

		local function isPress(input)
			return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
		end

		btn.InputBegan:Connect(function(input)
			if isPress(input) then
				M.sqGoal = 1
			end
		end)

		btn.InputEnded:Connect(function(input)
			if isPress(input) then
				M.sqGoal = 0
			end
		end)

		btn.MouseLeave:Connect(function()
			M.sqGoal = 0
		end)

		cur.button = btn
		M.acc = 0
		M.cur = cur
	end

	local function applyChoice()
		M.token += 1
		local token = M.token
		clearMascot()

		local name = M.choice
		local def = MASCOTS[name]
		if not def then
			return
		end

		if not canAssets then
			say("Your executor can't load custom images (writefile / getcustomasset).", "x")
			return
		end

		task.spawn(function()
			local url
			if name == "Custom" then
				url = M.customUrl
				if url == "" then
					return
				end
			else
				url = ASSET_BASE .. def.file
			end

			local asset = fetchAsset(url, "meow")
			if token ~= M.token then
				return
			end
			if not asset then
				warn("[Meow] image failed to download:", url)
				say("Could not download the " .. name .. " image.", "x")
				return
			end

			ensureOverlay()
			buildMascot(name, asset)
		end)
	end

	local function step(dt)
		local cur = M.cur
		if not cur then
			return
		end

		local root = getRoot()
		local goal = (root and isShown(root)) and 1 or 0
		M.alpha = M.alpha + (goal - M.alpha) * math.min(1, dt * 12)
		if math.abs(goal - M.alpha) < 0.01 then
			M.alpha = goal
		end

		local clip, def = cur.clip, cur.def
		if not root or M.alpha <= 0 then
			clip.Visible = false
			return
		end

		-- the overlay ignores the top-bar inset; the menu's GUI may not
		local inset = Vector2.zero
		local rootGui = root:FindFirstAncestorOfClass("ScreenGui")
		if rootGui then
			if not rootGui.IgnoreGuiInset then
				inset = GuiService_:GetGuiInset()
			end
			if M.gui and M.gui.DisplayOrder <= rootGui.DisplayOrder then
				M.gui.DisplayOrder = rootGui.DisplayOrder + 1
			end
		end

		local s = M.scale
		local pos = root.AbsolutePosition + inset
		local size = root.AbsoluteSize
		-- squash / release spring (underdamped, so letting go overshoots into a small "expand" before settling)
		M.sqVel = M.sqVel + (M.sqGoal - M.sq) * 260 * dt
		M.sqVel = M.sqVel * math.exp(-14 * dt)
		M.sq = M.sq + M.sqVel * dt
		if math.abs(M.sq - M.sqGoal) < 0.002 and math.abs(M.sqVel) < 0.02 then
			M.sq = M.sqGoal
			M.sqVel = 0
		end

		local baseW, baseH = def.w * s, def.h * s
		local newW, newH

		if M.sq >= 0 then
			-- pressed: wider and flatter
			newW = baseW * (1 + 0.10 * M.sq)
			newH = baseH * (1 - 0.22 * M.sq)
		else
			-- released: pops out bigger than normal before settling
			newW = baseW * (1 - 0.14 * M.sq)
			newH = baseH * (1 - 0.14 * M.sq)
		end

		local baseX = pos.X + size.X - def.dx * s + M.offX
		local baseY = pos.Y - def.dy * s + M.offY

		-- keep the bottom-center of the mascot fixed so it squashes into the menu edge
		clip.Size = UDim2.fromOffset(math.floor(newW), math.floor(newH))
		clip.Position = UDim2.fromOffset(math.floor(baseX + (baseW - newW) / 2), math.floor(baseY + (baseH - newH)))
		clip.Visible = true

		local transparency = 1 - M.alpha
		for _, img in ipairs(cur.images) do
			img.ImageTransparency = transparency
		end

		if def.kind ~= "static" then
			M.acc = M.acc + dt
			if M.acc >= FRAME_INTERVAL then
				M.acc = 0
				cur.idx = (cur.idx + 1) % def.frames
				if def.kind == "sheet" then
					cur.sheet.Position = UDim2.fromScale(-(cur.idx % def.cols), -math.floor(cur.idx / def.cols))
				else
					for i, img in ipairs(cur.images) do
						img.Visible = (i - 1 == cur.idx)
					end
				end
			end
		end
	end

	M.conn = RunService_.RenderStepped:Connect(step)

	-- UI --------------------------------------------------------------------------
	tbl43.settings:Section({ Title = "Meow" })

	tbl43.settings:Dropdown({
		Title = "Meow",
		Flag = "Dropdown_Meow",
		Multi = false,
		Value = "None",
		Desc = "An animated mascot that sits on the corner of the menu window.",
		Values = { "None", "Mimi", "Furry", "Koti", "Protogen Bongo", "Custom" },
		Callback = function(v)
			if type(v) == "table" then
				v = v[1] or v.Value
			end
			v = tostring(v or "None")
			if not MASCOTS[v] then
				v = "None"
			end
			if v == M.choice then
				return
			end
			M.choice = v
			applyChoice()
		end,
	})

	tbl43.settings:Slider({
		Title = "Meow Size",
		Flag = "Slider_Meow_Size",
		Desc = "How big the mascot is.",
		Step = 5,
		Suffix = "%",
		Value = { Min = 50, Max = 200, Default = 100 },
		Callback = function(v)
			local n = tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or 100
			M.scale = math.clamp(n, 50, 200) / 100
		end,
	})

	tbl43.settings:Slider({
		Title = "Meow Left / Right",
		Flag = "Slider_Meow_X",
		Desc = "Nudge the mascot sideways if it is not on the edge of the menu.",
		Step = 5,
		Value = { Min = -400, Max = 400, Default = 0 },
		Callback = function(v)
			M.offX = tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or 0
		end,
	})

	tbl43.settings:Slider({
		Title = "Meow Up / Down",
		Flag = "Slider_Meow_Y",
		Desc = "Nudge the mascot up (minus) or down (plus).",
		Step = 5,
		Value = { Min = -400, Max = 400, Default = 0 },
		Callback = function(v)
			M.offY = tonumber(v) or (type(v) == "table" and tonumber(v.Value)) or 0
		end,
	})

	tbl43.settings:Input({
		Title = "Custom Meow Image",
		Flag = "Input_Meow_Custom_Url",
		Placeholder = "Direct link to a .png / .jpg",
		Default = "",
		Desc = "Used when Meow is set to Custom.",
		Callback = function(v)
			v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if v == M.customUrl then
				return
			end
			M.customUrl = v
			task.delay(0.8, function()
				if M.customUrl == v and M.choice == "Custom" then
					applyChoice()
				end
			end)
		end,
	})

	obj3:OnDestroy(function()
		M.token += 1
		if M.conn then
			pcall(function()
				M.conn:Disconnect()
			end)
			M.conn = nil
		end
		clearMascot()
		if M.gui then
			pcall(function()
				M.gui:Destroy()
			end)
			M.gui = nil
		end
	end)
end

-- ===== Lobby Effects + Lobby NPC (lean port of Pulse's lobby module, Pulse branding removed) =====
-- Only you see these. Lobby Sign swaps the "Vote for The Next Map Here!" board text, Lobby Banner floats text
-- above the lobby, Lobby NPC puts a dancing copy of your avatar next to the radio board.
xpcall(function()
	local PlayersL = game:GetService("Players")
	local lpL = PlayersL.LocalPlayer
	local ORIG = "Vote for The Next Map Here!"

	local COLORS = {
		Red = Color3.fromRGB(255, 43, 43),
		Orange = Color3.fromRGB(255, 122, 26),
		Yellow = Color3.fromRGB(255, 220, 60),
		Green = Color3.fromRGB(60, 220, 110),
		Cyan = Color3.fromRGB(56, 220, 245),
		Blue = Color3.fromRGB(60, 120, 255),
		Purple = Color3.fromRGB(168, 85, 247),
		Pink = Color3.fromRGB(255, 105, 180),
		White = Color3.fromRGB(255, 255, 255),
	}
	local DANCES = {
		["Dance 1"] = 507771019,
		["Dance 2"] = 507776043,
		["Dance 3"] = 507777268,
		Wave = 507770239,
		Cheer = 507770677,
	}
	local RANDOM_DANCES = { "Dance 1", "Dance 2", "Dance 3" }
	local IDLE_ANIM = 507766388

	local LB = {
		alive = true,
		sign = false,
		signText = "Vote for the next map!",
		applied = nil,
		lbl = nil,
		signConn = nil,
		lastScan = 0,
		banner = false,
		bannerText = "F$VL",
		bannerColor = "Red",
		bannerPart = nil,
		bannerLabel = nil,
		npc = false,
		npcName = "F$VL",
		npcMsg = "",
		dances = true,
		dance = "Random",
		building = false,
		model = nil,
		hum = nil,
		nameLabel = nil,
		msgLabel = nil,
		track = nil,
		idleTrack = nil,
	}

	local function pickValue(v)
		if type(v) == "table" then
			v = v[1] or v.Value
		end
		return tostring(v or "")
	end

	local function flat(v)
		v = Vector3.new(v.X, 0, v.Z)
		return v.Magnitude > 0.1 and v.Unit or nil
	end

	local function lobbyModel()
		return workspace:FindFirstChild("RegularLobby") or workspace:FindFirstChild("Lobby")
	end

	local function lobbyCenter()
		local lobby = lobbyModel()
		if not lobby then
			return nil
		end
		local spawns = lobby:FindFirstChild("Spawns")
		local part = (spawns and spawns:FindFirstChildWhichIsA("BasePart")) or lobby:FindFirstChildWhichIsA("SpawnLocation", true)
		return part and part.Position or nil
	end

	-- ---------------------------------------------------------------- Lobby Sign
	local function findSign()
		if LB.lbl and LB.lbl.Parent then
			return LB.lbl
		end
		local lobby = workspace:FindFirstChild("RegularLobby")
		local main = lobby and lobby:FindFirstChild("MainLobby")
		local parts = main and main:FindFirstChild("Parts")
		if parts then
			for _, inst in ipairs(parts:GetChildren()) do
				local sg = inst:FindFirstChildOfClass("SurfaceGui")
				local title = sg and sg:FindFirstChild("Title")
				if title and title:IsA("TextLabel") and (title.Text == ORIG or title.Text == LB.applied) then
					return title
				end
			end
		end
		if lobby and os.clock() - LB.lastScan > 30 then
			LB.lastScan = os.clock()
			for _, inst in ipairs(lobby:GetDescendants()) do
				if inst:IsA("TextLabel") and (inst.Text == ORIG or inst.Text == LB.applied) then
					return inst
				end
			end
		end
		return nil
	end

	local function applySign()
		local lbl = findSign()
		if not lbl then
			return
		end
		if LB.lbl ~= lbl then
			LB.lbl = lbl
			if LB.signConn then
				LB.signConn:Disconnect()
			end
			LB.signConn = lbl:GetPropertyChangedSignal("Text"):Connect(function()
				if LB.sign and lbl.Text == ORIG then
					lbl.Text = LB.signText
					LB.applied = LB.signText
				end
			end)
		end
		if LB.sign and (lbl.Text == ORIG or lbl.Text == LB.applied) then
			lbl.Text = LB.signText
			LB.applied = LB.signText
		end
	end

	local function restoreSign()
		local lbl = LB.lbl
		if lbl and lbl.Parent and lbl.Text == LB.applied then
			lbl.Text = ORIG
		end
		LB.applied = nil
	end

	-- ---------------------------------------------------------------- Lobby Banner
	local function destroyBanner()
		if LB.bannerPart then
			pcall(function()
				LB.bannerPart:Destroy()
			end)
		end
		LB.bannerPart, LB.bannerLabel = nil, nil
	end

	local function paintBanner()
		if LB.bannerLabel then
			LB.bannerLabel.Text = LB.bannerText
			if LB.bannerColor ~= "Rainbow" then
				LB.bannerLabel.TextColor3 = COLORS[LB.bannerColor] or COLORS.Red
			end
		end
	end

	local function ensureBanner()
		if LB.bannerPart and LB.bannerPart.Parent then
			return
		end
		local center = lobbyCenter()
		if not center then
			return
		end
		local part = Instance.new("Part")
		part.Name = "FVLLobbyBanner"
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Transparency = 1
		part.Size = Vector3.new(1, 1, 1)
		part.Position = center + Vector3.new(0, 24, 0)
		local gui = Instance.new("BillboardGui")
		gui.Size = UDim2.fromScale(46, 8)
		gui.AlwaysOnTop = false
		gui.LightInfluence = 0
		gui.MaxDistance = 500
		gui.Parent = part
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.TextScaled = true
		label.TextStrokeTransparency = 0.35
		label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
		label.Text = LB.bannerText
		label.TextColor3 = COLORS[LB.bannerColor] or COLORS.Red
		label.Parent = gui
		part.Parent = workspace
		LB.bannerPart, LB.bannerLabel = part, label
	end

	-- ---------------------------------------------------------------- Lobby NPC
	local function stopTracks()
		for _, key in ipairs({ "track", "idleTrack" }) do
			local t = LB[key]
			if t then
				pcall(function()
					t:Stop(0.1)
				end)
				pcall(function()
					t:Destroy()
				end)
			end
			LB[key] = nil
		end
	end

	local function playAnim(id)
		local hum = LB.hum
		if not (hum and hum.Parent) then
			return nil
		end
		local animator = hum:FindFirstChildOfClass("Animator")
		if not animator then
			animator = Instance.new("Animator")
			animator.Parent = hum
		end
		local anim = Instance.new("Animation")
		anim.AnimationId = "rbxassetid://" .. tostring(id)
		local ok, track = pcall(function()
			return animator:LoadAnimation(anim)
		end)
		if not ok or not track then
			return nil
		end
		track.Looped = true
		track:Play(0.2)
		return track
	end

	local function refreshNpcAnim()
		stopTracks()
		if not LB.model then
			return
		end
		if LB.dances then
			local name = LB.dance
			if name == "Random" then
				name = RANDOM_DANCES[math.random(1, #RANDOM_DANCES)]
			end
			LB.track = playAnim(DANCES[name] or DANCES["Dance 1"])
		else
			LB.idleTrack = playAnim(IDLE_ANIM)
		end
	end

	local function paintTag()
		if LB.nameLabel then
			LB.nameLabel.Text = LB.npcName
		end
		if LB.msgLabel then
			LB.msgLabel.Text = LB.npcMsg
			LB.msgLabel.Visible = LB.npcMsg ~= ""
		end
	end

	local function destroyNpc()
		stopTracks()
		if LB.model then
			pcall(function()
				LB.model:Destroy()
			end)
		end
		LB.model, LB.hum, LB.nameLabel, LB.msgLabel = nil, nil, nil, nil
	end

	local function ignoreList()
		local list = {}
		for _, p in ipairs(PlayersL:GetPlayers()) do
			if p.Character then
				list[#list + 1] = p.Character
			end
		end
		if LB.model then
			list[#list + 1] = LB.model
		end
		if LB.bannerPart then
			list[#list + 1] = LB.bannerPart
		end
		return list
	end

	-- where the NPC stands: next to the radio board (same spot Pulse uses), else beside the lobby spawn
	local function npcSpot()
		local lobby = workspace:FindFirstChild("RegularLobby")
		local board = lobby and lobby:FindFirstChild("RadioBoard")
		local screen = board and board:FindFirstChild("Screen")
		local pos, face
		if screen and screen:IsA("BasePart") then
			local look, right = flat(screen.CFrame.LookVector), flat(screen.CFrame.RightVector)
			if look and right then
				pos = screen.Position - right * 18.2 - look * 0.7
				face = look
			end
		end
		if not pos then
			local center = lobbyCenter()
			if not center then
				return nil
			end
			pos = center + Vector3.new(12, 0, 0)
			face = Vector3.new(-1, 0, 0)
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = ignoreList()
		local hit = workspace:Raycast(pos + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
		if not hit then
			return nil
		end
		return hit.Position, face
	end

	local function buildNpc()
		if LB.building then
			return
		end
		LB.building = true
		pcall(function()
			local ground, face = npcSpot()
			if not ground then
				return
			end
			local desc
			pcall(function()
				desc = PlayersL:GetHumanoidDescriptionFromUserId(lpL.UserId)
			end)
			if not desc then
				desc = Instance.new("HumanoidDescription")
			end
			local made, model = pcall(function()
				return PlayersL:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R15)
			end)
			if not made or not model then
				return
			end
			if not (LB.npc and LB.alive) then
				model:Destroy()
				return
			end
			local hum = model:FindFirstChildOfClass("Humanoid")
			local root = model:FindFirstChild("HumanoidRootPart")
			local head = model:FindFirstChild("Head")
			if not (hum and root and head) then
				model:Destroy()
				return
			end
			model.Name = "FVLLobbyNpc"
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			for _, inst in ipairs(model:GetDescendants()) do
				if inst:IsA("BasePart") then
					inst.CanCollide = false
					inst.CanQuery = false
					inst.CanTouch = false
				end
			end
			root.Anchored = true
			local p = Vector3.new(ground.X, ground.Y + hum.HipHeight + root.Size.Y / 2, ground.Z)
			model:PivotTo(CFrame.lookAt(p, p + face))

			-- name tag (name + optional message line)
			local gui = Instance.new("BillboardGui")
			gui.Name = "FVLNpcTag"
			gui.Size = UDim2.fromScale(10, 2.4)
			gui.StudsOffset = Vector3.new(0, 3, 0)
			gui.AlwaysOnTop = false
			gui.LightInfluence = 0
			gui.MaxDistance = 160
			gui.Adornee = head
			gui.Parent = head
			local nameLabel = Instance.new("TextLabel")
			nameLabel.Size = UDim2.fromScale(1, 0.55)
			nameLabel.BackgroundTransparency = 1
			nameLabel.Font = Enum.Font.GothamBlack
			nameLabel.TextScaled = true
			nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			nameLabel.TextStrokeTransparency = 0.4
			nameLabel.Parent = gui
			local msgLabel = Instance.new("TextLabel")
			msgLabel.Position = UDim2.fromScale(0, 0.55)
			msgLabel.Size = UDim2.fromScale(1, 0.4)
			msgLabel.BackgroundTransparency = 1
			msgLabel.Font = Enum.Font.GothamMedium
			msgLabel.TextScaled = true
			msgLabel.TextColor3 = Color3.fromRGB(235, 235, 240)
			msgLabel.TextStrokeTransparency = 0.5
			msgLabel.Parent = gui

			model.Parent = workspace
			LB.model, LB.hum, LB.nameLabel, LB.msgLabel = model, hum, nameLabel, msgLabel
			paintTag()
			refreshNpcAnim()
		end)
		LB.building = false
	end

	local function ensureNpc()
		if LB.model and LB.model.Parent then
			return
		end
		destroyNpc()
		buildNpc()
	end

	-- ---------------------------------------------------------------- UI (Maps tab)
	tbl43.maps:Section({ Title = "Lobby Effects" })

	tbl43.maps:Toggle({
		Title = "Custom Lobby Sign",
		Flag = "Toggle_Lobby_Sign",
		Desc = "Replaces the text of the map-vote board in the lobby with your own (only you see it).",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			LB.sign = v == true
			if LB.sign then
				pcall(applySign)
			else
				pcall(restoreSign)
			end
		end,
	})

	tbl43.maps:Input({
		Title = "Lobby Sign Text",
		Flag = "Input_Lobby_Sign_Text",
		Desc = "What the lobby board should say.",
		Placeholder = "Vote for the next map!",
		Callback = function(v)
			v = tostring(v or "")
			if v ~= "" then
				LB.signText = v
				if LB.sign then
					pcall(applySign)
				end
			end
		end,
	})

	tbl43.maps:Toggle({
		Title = "Lobby Banner",
		Flag = "Toggle_Lobby_Banner",
		Desc = "Floats a big line of text high above the lobby.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			LB.banner = v == true
			if LB.banner then
				pcall(ensureBanner)
			else
				destroyBanner()
			end
		end,
	})

	tbl43.maps:Input({
		Title = "Banner Text",
		Flag = "Input_Lobby_Banner_Text",
		Desc = "The text of the lobby banner.",
		Placeholder = "F$VL",
		Callback = function(v)
			v = tostring(v or "")
			if v ~= "" then
				LB.bannerText = v
				paintBanner()
			end
		end,
	})

	tbl43.maps:Dropdown({
		Title = "Banner Color",
		Flag = "Dropdown_Lobby_Banner_Color",
		Desc = "Color of the lobby banner. Rainbow cycles through all colors.",
		Multi = false,
		Value = "Red",
		Values = { "Red", "Orange", "Yellow", "Green", "Cyan", "Blue", "Purple", "Pink", "White", "Rainbow" },
		Callback = function(v)
			LB.bannerColor = pickValue(v)
			paintBanner()
		end,
	})

	tbl43.maps:Section({ Title = "Lobby NPC" })

	tbl43.maps:Toggle({
		Title = "Lobby NPC",
		Flag = "Toggle_Lobby_Npc",
		Desc = "Puts an NPC with your avatar in the lobby, next to the radio board. Only you see it.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			LB.npc = v == true
			if LB.npc then
				task.spawn(ensureNpc)
			else
				destroyNpc()
			end
		end,
	})

	tbl43.maps:Input({
		Title = "NPC Name",
		Flag = "Input_Lobby_Npc_Name",
		Desc = "Name shown above the NPC.",
		Placeholder = "F$VL",
		Callback = function(v)
			v = tostring(v or "")
			if v ~= "" then
				LB.npcName = v
				paintTag()
			end
		end,
	})

	tbl43.maps:Input({
		Title = "NPC Message",
		Flag = "Input_Lobby_Npc_Message",
		Desc = "Small line shown under the NPC name. Empty = hidden.",
		Placeholder = "Welcome to the lobby",
		Callback = function(v)
			LB.npcMsg = tostring(v or "")
			paintTag()
		end,
	})

	tbl43.maps:Toggle({
		Title = "NPC Dances",
		Flag = "Toggle_Lobby_Npc_Dances",
		Desc = "On: the NPC dances. Off: it just stands idle.",
		Type = "Toggle",
		Value = true,
		Callback = function(v)
			LB.dances = v == true
			refreshNpcAnim()
		end,
	})

	tbl43.maps:Dropdown({
		Title = "NPC Dance",
		Flag = "Dropdown_Lobby_Npc_Dance",
		Desc = "Which animation the NPC plays.",
		Multi = false,
		Value = "Random",
		Values = { "Random", "Dance 1", "Dance 2", "Dance 3", "Wave", "Cheer" },
		Callback = function(v)
			LB.dance = pickValue(v)
			refreshNpcAnim()
		end,
	})

	-- keeps everything alive: the lobby board / banner / NPC are re-applied if the game rebuilds them
	task.spawn(function()
		while LB.alive do
			pcall(function()
				if LB.sign then
					applySign()
				end
				if LB.banner then
					ensureBanner()
				end
				if LB.npc then
					ensureNpc()
				end
			end)
			task.wait(3)
		end
	end)

	task.spawn(function()
		local hue = 0
		while LB.alive do
			task.wait(0.06)
			if LB.banner and LB.bannerColor == "Rainbow" and LB.bannerLabel then
				hue = (hue + 0.01) % 1
				pcall(function()
					LB.bannerLabel.TextColor3 = Color3.fromHSV(hue, 0.9, 1)
				end)
			end
		end
	end)

	obj3:OnDestroy(function()
		LB.alive = false
		pcall(restoreSign)
		pcall(function()
			if LB.signConn then
				LB.signConn:Disconnect()
			end
		end)
		destroyBanner()
		destroyNpc()
	end)
end, function(err)
	warn("[FVL] Lobby Effects / NPC failed to load: " .. tostring(err))
end)

obj3:OnDestroy(function()
	list2.farewell()
	fvlV2Cleanup()
	local list46 = {}

	pcall(function()
		local hui = gethui and gethui() or CoreGui

		for _, child in ipairs(hui:GetChildren()) do
			if child.Name == "WindUI" or child.Name:match("^WindUI/") then
				list46[#list46 + 1] = child
			end
		end
	end)

	task.delay(0.6, function()
		for _, item67 in ipairs(list46) do
			pcall(function()
				item67:Destroy()
			end)
		end
	end)

	if _G.FVLAntiVoidCleanup then
		pcall(_G.FVLAntiVoidCleanup)
	end

	if _G.FVLV2 == obj3 then
		_G.FVLV2 = nil
	end

	if _G.FVLV2Cleanup == fvlV2Cleanup then
		_G.FVLV2Cleanup = nil
	end
end)

_G.FVLV2Cleanup = fvlV2Cleanup
obj3:Open()
list2.pinOpenPill()
obj3:SelectTab(1)

task.spawn(function()
	for i = 1, 60 do
		RunService.RenderStepped:Wait()

		if obj3.CurrentTab ~= 1 then
			obj3:SelectTab(1)
		end
	end
end)

list2.captureHud = function()
	local tbl114 = {}

	-- keep saved positions of anything not currently on screen (toggled off buttons etc.)
	for k, v in next, list2.hudPos, nil do
		if type(v) == "table" and #v == 4 then
			tbl114[k] = v
		end
	end

	for k, value226 in next, list2.hudBtns, nil do
		if value226 and value226.Parent then
			local position = value226.Position
			local pos = { position.X.Scale, position.X.Offset, position.Y.Scale, position.Y.Offset }
			tbl114[k] = pos

			-- extra draggable frames ("__name") are remembered for when they get rebuilt
			if type(k) == "string" and k:sub(1, 2) == "__" then
				list2.hudPos[k] = pos
			end
		end
	end

	return tbl114
end

list2.applyHud = function()
	for k, value227 in next, list2.hudPos, nil do
		local flag204 = list2.hudBtns[k]

		if flag204 and flag204.Parent and type(value227) == "table" and #value227 == 4 then
			flag204.Position = UDim2.new(value227[1], value227[2], value227[3], value227[4])
		end
	end
end

list2.snapshot = function()
	if not list2.config then
		return ""
	end

	local ok, result = pcall(function()
		return HttpService:JSONEncode({ data = list2.config:GetData(), hud = list2.captureHud() })
	end)

	return ok and result or ""
end

list2.saveNow = function()
	if list2.cfgWiped then
		return
	end

	pcall(function()
		if writefile then
			writefile(list2.hudFile, HttpService:JSONEncode(list2.captureHud()))
		end
	end)

	if list2.config then
		pcall(function()
			list2.config:Save()
		end)
	end

	list2.cfgSnapshot = list2.snapshot()
end

--[[ ===== MERGED FROM SOURCE: Duel Tracker =====
	Ported from Pulse source constructors.createDuelTracker (native_id 72).
	Tracks active duels / infection rounds (Zombie, Vampire, Freezer, Team1/Team2)
	and exposes getgenv().__pulseDuel with isFoe / pick / alive helpers so other
	features (Silent Aim, Kill All, ESP) can restrict targets to duel foes only.
	Dependencies wired to target equivalents:
	  - roles source  -> list2.pulseRoles
	  - remotes       -> ReplicatedStorage.Remotes
	  - connectSignal -> direct :Connect() stored in local conns table
	  - cleanup       -> local conns, disconnected on disable
]]
do
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer
	local RS = game:GetService("ReplicatedStorage")
	local UIS = game:GetService("UserInputService")

	local duelState = {
		on = false,
		mates = {},
		foes = {},
		at = 0,
		cur = nil,
		mine = nil,
		mode = nil,
		stick = 0.06,
		seen = {},
		enabled = false, -- master toggle from UI
	}
	getgenv().__pulseDuel = duelState

	local duel_conns = {}

	local function duel_apply(data)
		if type(data) ~= "table" then return end
		local mine
		for _, team in ipairs({ "Team1", "Team2" }) do
			if type(data[team]) == "table" and data[team][lp.Name] ~= nil then
				mine = team
			end
		end
		local mates, foes = {}, {}
		for _, team in ipairs({ "Team1", "Team2" }) do
			if type(data[team]) == "table" then
				for key in pairs(data[team]) do
					if key ~= lp.Name then
						if mine then
							if team == mine then mates[key] = true else foes[key] = true end
						else
							foes[key] = true
						end
					end
				end
			end
		end
		duelState.mates = mates
		duelState.foes = foes
		duelState.mine = mine
		duelState.at = os.clock()
		duelState.cur = nil
		duelState.on = next(foes) ~= nil
	end

	local function duel_stop()
		duelState.on = false
		duelState.mates = {}
		duelState.foes = {}
		duelState.cur = nil
		duelState.mode = nil
	end
	duelState.stop = duel_stop
	duelState.apply = duel_apply

	-- Special game-mode hunt/prey role mappings (infection rounds)
	local duel_modeEntries = {
		{ hunt = { Zombie = true }, prey = { Survivor = true, Sheriff = true, Hero = true, Innocent = true }, tag = "Zombie" },
		{ hunt = { Vampire = true }, prey = { Hunter = true, Villager = true, Sheriff = true, Hero = true, Innocent = true }, tag = "Vampire" },
		{ hunt = { Freezer = true }, prey = { Runner = true, Innocent = true }, tag = "Freeze" },
	}

	local function duel_detectMode(roles)
		for _, entry in ipairs(duel_modeEntries) do
			for _, rec in pairs(roles) do
				if type(rec) == "table" and rec.Role ~= nil then
					local r = tostring(rec.Role)
					if entry.hunt[r] then return entry end
					if entry.prey[r] and r ~= "Sheriff" and r ~= "Hero" and r ~= "Innocent" then return entry end
				end
			end
		end
		return nil
	end

	local function duel_fromRoles(roles)
		local teamMode = false
		for _, rec in pairs(roles) do
			if type(rec) == "table" and (rec.Team == "Team1" or rec.Team == "Team2") then
				teamMode = true
				break
			end
		end
		local mates, foes, mine = {}, {}
		if teamMode then
			local myRec = roles[lp.Name]
			mine = type(myRec) == "table" and myRec.Team or nil
			for key, rec in pairs(roles) do
				if key ~= lp.Name and type(rec) == "table" then
					if mine then
						if rec.Team == mine then mates[key] = true else foes[key] = true end
					else
						foes[key] = true
					end
				end
			end
			duelState.mode = "Team"
		else
			local modeEntry = duel_detectMode(roles)
			if not modeEntry then return false end
			local function classify(rec)
				if type(rec) ~= "table" or rec.Role == nil then return nil end
				local r = tostring(rec.Role)
				if modeEntry.hunt[r] then return "hunt" end
				if modeEntry.prey[r] then return "prey" end
				return nil
			end
			mine = classify(roles[lp.Name])
			for key, rec in pairs(roles) do
				if key ~= lp.Name then
					local c = classify(rec)
					if c then
						if mine then
							if c == mine then mates[key] = true else foes[key] = true end
						end
					end
				end
			end
			duelState.mode = modeEntry.tag
		end
		if not duelState.on then
			duelState.at = os.clock()
			duelState.cur = nil
		end
		duelState.mates = mates
		duelState.foes = foes
		duelState.mine = mine
		duelState.on = next(foes) ~= nil
		return true
	end
	duelState.fromRoles = duel_fromRoles

	duelState.alive = function(plr)
		local char = plr.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not char or not hum or hum.Health <= 0 then return nil end
		if not char:FindFirstChild("HumanoidRootPart") then return nil end
		local roles = list2 and list2.pulseRoles or {}
		local entry = roles and roles[plr.Name]
		if entry and (entry.Dead == true or entry.Killed == true) then
			local r = entry.Role ~= nil and tostring(entry.Role) or ""
			if duelState.mode ~= "Team" then
				if r ~= "Zombie" and r ~= "Vampire" and r ~= "Freezer" then return nil end
			else
				return nil
			end
		end
		return char
	end

	duelState.isFoe = function(plr)
		return duelState.on and duelState.enabled and plr ~= lp and duelState.foes[plr.Name] == true
	end

	duelState.pick = function(filterFn)
		if not duelState.on or not duelState.enabled then return nil end
		local cam = workspace.CurrentCamera
		if not cam then return nil end
		local origin, lookDir = cam.CFrame.Position, cam.CFrame.LookVector
		if UIS.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
			local ok, ray = pcall(function()
				local ml = UIS:GetMouseLocation()
				return cam:ViewportPointToRay(ml.X, ml.Y)
			end)
			if ok and ray then origin, lookDir = ray.Origin, ray.Direction.Unit end
		end
		local bestAngle, bestPlr, bestChar, curAngle
		for _, plr in ipairs(Players:GetPlayers()) do
			if duelState.isFoe(plr) then
				local char = duelState.alive(plr)
				if char and (not filterFn or filterFn(char)) then
					local hrp = char:FindFirstChild("HumanoidRootPart")
					if hrp then
						local diff = hrp.Position - origin
						local mag = diff.Magnitude
						if mag > 0.01 then
							local ang = math.acos(math.clamp(lookDir:Dot(diff / mag), -1, 1)) + mag * 5.0e-4
							if plr == duelState.cur then curAngle = ang end
							if not bestAngle or ang < bestAngle then
								bestAngle, bestPlr, bestChar = ang, plr, char
							end
						end
					end
				end
			end
		end
		if duelState.cur and curAngle and bestPlr ~= duelState.cur and bestAngle > curAngle - duelState.stick then
			return duelState.cur, duelState.cur.Character
		end
		if not filterFn then duelState.cur = bestPlr end
		return bestPlr, bestChar
	end

	-- Remote hooks: DuelStarted / DuelFinished / RoundEndFade
	task.spawn(function()
		local remotes = RS:WaitForChild("Remotes", 20)
		local customGames = remotes and remotes:WaitForChild("CustomGames", 20)
		if customGames then
			local ds = customGames:FindFirstChild("DuelStarted")
			if ds then
				local c = ds.OnClientEvent:Connect(function(data) pcall(duel_apply, data) end)
				duel_conns[#duel_conns + 1] = c
			end
			local df = customGames:FindFirstChild("DuelFinished")
			if df then
				local c = df.OnClientEvent:Connect(function() task.delay(0.5, duel_stop) end)
				duel_conns[#duel_conns + 1] = c
			end
		end
		local gameplay = remotes and remotes:FindFirstChild("Gameplay")
		local roundEnd = gameplay and gameplay:FindFirstChild("RoundEndFade")
		if roundEnd then
			local c = roundEnd.OnClientEvent:Connect(function() duel_stop() end)
			duel_conns[#duel_conns + 1] = c
		end
	end)

	-- Polling loop: detect infection / team duels from roles every 0.5s
	task.spawn(function()
		local lastSeenReset = 0
		while true do
			task.wait(0.5)
			if not duelState.enabled then
				if duelState.on then duel_stop() end
			else
			pcall(function()
				local roles = list2 and list2.pulseRoles or {}
				local hasRoles = type(roles) == "table" and next(roles) ~= nil
				if hasRoles then
					-- Log newly-seen non-standard roles to file (same as source)
					duelState.seen = duelState.seen or {}
					for key, rec in pairs(roles) do
						local r = type(rec) == "table" and rec.Role ~= nil and tostring(rec.Role) or nil
						if r and not duelState.seen[r] then
							duelState.seen[r] = true
							if r ~= "Murderer" and r ~= "Sheriff" and r ~= "Innocent" and r ~= "Hero" then
								pcall(function()
									local plr = Players:FindFirstChild(key)
									local tools = {}
									local containers = { plr and plr.Character, plr and plr:FindFirstChild("Backpack") }
									for _, cont in ipairs(containers) do
										if cont then
											for _, inst in ipairs(cont:GetChildren()) do
												if inst:IsA("Tool") then
													tools[#tools + 1] = inst.Name .. "{" .. table.concat(inst:GetTags(), "/") .. "}"
												end
											end
										end
									end
									local line = os.date("%d.%m %H:%M:%S") .. " " .. r .. " " .. tostring(key)
										.. " tools=" .. table.concat(tools, ",") .. "\n"
									if writefile then
										if isfile and isfile("FVL/mm2_roles_seen.txt") then
											appendfile("FVL/mm2_roles_seen.txt", line)
										else
											writefile("FVL/mm2_roles_seen.txt", line)
										end
									end
								end)
							end
						end
					end
					if not duel_fromRoles(roles) then
						if duelState.on and os.clock() - duelState.at > 2 then duel_stop() end
					end
				elseif duelState.on then
					lastSeenReset = lastSeenReset or os.clock()
					if os.clock() - lastSeenReset > 3 then duel_stop() end
				else
					lastSeenReset = nil
				end
			end)
			end -- close else (was continue in Luau)
		end
	end)

	-- ===== UI (Combat tab) =====
	pcall(function() tbl43.combat:Section({ Title = "Duel Tracker" }) end)

	tbl43.combat:Toggle({
		Title = "Duel Tracker",
		Flag = "Toggle_DuelTracker",
		Desc = "Track active duels / infection rounds. Restricts aim targets to foes only. Exposes getgenv().__pulseDuel.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			duelState.enabled = v
			if not v then duel_stop() end
		end,
	})

	tbl43.combat:Toggle({
		Title = "Log Seen Roles",
		Flag = "Toggle_DuelLogRoles",
		Desc = "Log newly detected non-standard roles (Zombie/Vampire/Freezer) to FVL/mm2_roles_seen.txt.",
		Type = "Toggle",
		Value = true,
		Callback = function(v) duelState.logRoles = v end,
	})
end

--[[ ===== MERGED FROM SOURCE: Standalone Desync + Ghost Leak Detection =====
	Ported from Pulse source:
	  - constructors.createDesyncController (standalone fakepos/desync)
	  - pulseDesyncGhost / getgenv().__pulseDesyncGhost (leak detection via GunFired)
	Target already has Velocity Desync as ONE mode inside Anti-Aim. This adds a
	complementary INDEPENDENT desync toggle (can combine with Anti-Aim Side Profile,
	or run alone) plus ghost leak-detection (shows where your real position leaked
	when someone fires at you during desync).
	State table renamed DS (target Anti-Aim uses AA). All locals prefixed desync_.
]]
do
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer
	local RunSvc = game:GetService("RunService")
	local RepStorage = game:GetService("ReplicatedStorage")

	local DS = {
		on = false,
		power = 5,          -- 1..10
		dir = "Random",     -- Random | Spin | Jitter | Sky | Underground
		vel = true,         -- spoof AssemblyLinearVelocity
		md = true,          -- spoof Humanoid MoveDirection
		smart = true,       -- pause while holding tool
		ghost = true,       -- ghost leak detection
		sideDir = 1,
		spinA = 0,
		jitterDir = nil,
		jitterUntil = 0,
		jitterFlip = 1,
		mdDir = nil,
		mdUntil = 0,
		toolAt = 0,
		realVel = nil,
		realMD = nil,
		hrp = nil,
		hum = nil,
	}
	getgenv().__pulseFakePos = { active = false, off = Vector3.new(0, 0, 0) }
	getgenv().__pulseAntiAim = { standalone = true, frames = 0, restores = 0 }

	local desync_conns = {}

	local BAD_STATES = {
		[Enum.HumanoidStateType.Dead] = true,
		[Enum.HumanoidStateType.Seated] = true,
		[Enum.HumanoidStateType.Swimming] = true,
		[Enum.HumanoidStateType.Climbing] = true,
		[Enum.HumanoidStateType.Physics] = true,
		[Enum.HumanoidStateType.Ragdoll] = true,
		[Enum.HumanoidStateType.PlatformStanding] = true,
		[Enum.HumanoidStateType.FallingDown] = true,
		[Enum.HumanoidStateType.GettingUp] = true,
	}

	local function desync_getChar()
		local c = lp.Character
		if not c then return nil, nil end
		local hrp = c:FindFirstChild("HumanoidRootPart")
		local hum = c:FindFirstChildOfClass("Humanoid")
		if not hrp or not hum or hum.Health <= 0 then return nil, nil end
		if BAD_STATES[hum:GetState()] then return nil, nil end
		return hrp, hum
	end

	local function desync_isBusy()
		if not DS.smart then return false end
		if os.clock() - DS.toolAt < 0.35 then return true end
		local c = lp.Character
		if c then
			for _, t in ipairs(c:GetChildren()) do
				if t:IsA("Tool") then return true end
			end
		end
		return false
	end

	local function desync_clampVec(v)
		return Vector3.new(
			math.clamp(v.X, -32767, 32767),
			math.clamp(v.Y, -32767, 32767),
			math.clamp(v.Z, -32767, 32767)
		)
	end

	local function desync_rand() return math.random() * 2 - 1 end

	local function desync_spoofVec(mag)
		local d = DS.dir
		if d == "Underground" then
			return Vector3.new(desync_rand() * mag * 0.15, -mag, desync_rand() * mag * 0.15)
		elseif d == "Sky" then
			return Vector3.new(desync_rand() * mag * 0.15, mag, desync_rand() * mag * 0.15)
		elseif d == "Spin" then
			DS.spinA = (DS.spinA + 0.9 + math.random() * 0.6) % (math.pi * 2)
			return Vector3.new(math.cos(DS.spinA) * mag, desync_rand() * mag * 0.35, math.sin(DS.spinA) * mag)
		elseif d == "Jitter" then
			local now = os.clock()
			if now > DS.jitterUntil then
				DS.jitterFlip = -DS.jitterFlip
				DS.jitterUntil = now + 0.15 + math.random() * 0.2
				DS.jitterDir = Vector3.new(desync_rand(), desync_rand() * 0.3, desync_rand()).Unit
			end
			return DS.jitterDir * mag * DS.jitterFlip
		else -- Random
			return Vector3.new(desync_rand() * mag, desync_rand() * mag * 0.5, desync_rand() * mag)
		end
	end

	-- Track tool equip for Smart Pause
	pcall(function()
		local c = lp.CharacterAdded:Connect(function(char)
			local c1 = char.ChildAdded:Connect(function(child)
				if child:IsA("Tool") then DS.toolAt = os.clock() end
			end)
			local c2 = char.ChildRemoved:Connect(function(child)
				if child:IsA("Tool") then DS.toolAt = os.clock() end
			end)
			desync_conns[#desync_conns + 1] = c1
			desync_conns[#desync_conns + 1] = c2
		end)
		desync_conns[#desync_conns + 1] = c
		-- initial character
		if lp.Character then
			local c1 = lp.Character.ChildAdded:Connect(function(child)
				if child:IsA("Tool") then DS.toolAt = os.clock() end
			end)
			local c2 = lp.Character.ChildRemoved:Connect(function(child)
				if child:IsA("Tool") then DS.toolAt = os.clock() end
			end)
			desync_conns[#desync_conns + 1] = c1
			desync_conns[#desync_conns + 1] = c2
		end
	end)

	-- Main desync loop: spoof on Stepped (before physics), restore on Heartbeat
	local steppedConn, heartbeatConn
	local function desync_startLoops()
		if steppedConn then return end
		steppedConn = RunSvc.Stepped:Connect(function()
			if not DS.on then return end
			if desync_isBusy() then return end
			local hrp, hum = desync_getChar()
			if not hrp then return end
			DS.hrp, DS.hum = hrp, hum
			local mag = DS.power * 25
			if DS.vel then
				DS.realVel = hrp.AssemblyLinearVelocity
				hrp.AssemblyLinearVelocity = desync_clampVec(DS.realVel + desync_spoofVec(mag))
			end
			if DS.md and hum then
				DS.realMD = hum.MoveDirection
				local now = os.clock()
				if not DS.mdDir or now > DS.mdUntil then
					DS.mdUntil = now + 0.3
					DS.mdDir = Vector3.new(desync_rand(), 0, desync_rand()).Unit
				end
				hum:Move(DS.mdDir, false)
			end
			getgenv().__pulseFakePos.active = true
			getgenv().__pulseAntiAim.frames = (getgenv().__pulseAntiAim.frames or 0) + 1
		end)
		heartbeatConn = RunSvc.Heartbeat:Connect(function()
			if not DS.on then
				getgenv().__pulseFakePos.active = false
				return
			end
			local hrp = DS.hrp
			if hrp and hrp.Parent then
				if DS.realVel and DS.vel then
					local cur = hrp.AssemblyLinearVelocity
					if (cur - DS.realVel).Magnitude < 0.5 then
						hrp.AssemblyLinearVelocity = DS.realVel
					end
				end
			end
			DS.realVel = nil
			DS.realMD = nil
			getgenv().__pulseFakePos.active = false
			getgenv().__pulseAntiAim.restores = (getgenv().__pulseAntiAim.restores or 0) + 1
		end)
		desync_conns[#desync_conns + 1] = steppedConn
		desync_conns[#desync_conns + 1] = heartbeatConn
	end

	local function desync_stopLoops()
		if steppedConn then pcall(function() steppedConn:Disconnect() end) steppedConn = nil end
		if heartbeatConn then pcall(function() heartbeatConn:Disconnect() end) heartbeatConn = nil end
		-- restore real velocity on disable
		local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
		if hrp and DS.realVel then
			pcall(function() hrp.AssemblyLinearVelocity = DS.realVel end)
		end
		DS.realVel = nil
		DS.realMD = nil
		getgenv().__pulseFakePos.active = false
	end

	-- ===== Ghost Leak Detection (pulseDesyncGhost, simplified standalone) =====
	-- Source version hooks into pulseESP2.extraPlayers to render ghost chams.
	-- Target has no pulseESP2, so we render standalone: Highlight + BillboardGui
	-- tag at the leaked position. Limitation noted in merge report.
	local ghostState = { by = {}, last = {}, leak = {}, far = 1000000, keep = 20 }
	getgenv().__pulseDesyncGhost = ghostState

	local function ghost_isBad(v)
		return v.X ~= v.X or v.Y ~= v.Y or v.Z ~= v.Z or v.Magnitude > ghostState.far
	end

	local function ghost_makeTag(plr, pos, seconds)
		-- remove old tag for this player
		local old = ghostState.by[plr]
		if old and old.gui then pcall(function() old.gui:Destroy() end) end
		local gui = Instance.new("BillboardGui")
		gui.Name = "DesyncLeakTag"
		gui.Size = UDim2.new(0, 200, 0, 50)
		gui.StudsOffset = Vector3.new(0, 3, 0)
		gui.AlwaysOnTop = true
		gui.Adornee = workspace.Terrain
		local tl = Instance.new("TextLabel")
		tl.Size = UDim2.new(1, 0, 1, 0)
		tl.BackgroundTransparency = 1
		tl.TextColor3 = Color3.fromRGB(255, 80, 80)
		tl.TextStrokeTransparency = 0.4
		tl.Font = Enum.Font.GothamBold
		tl.TextSize = 14
		tl.Text = plr.Name .. " DESYNC" .. (seconds and seconds >= 1 and " " .. math.floor(seconds) .. "s" or "")
		tl.Parent = gui
		-- anchor part at leaked pos
		local anchor = Instance.new("Part")
		anchor.Name = "DesyncLeakAnchor"
		anchor.Size = Vector3.new(1, 1, 1)
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanQuery = false
		anchor.CanTouch = false
		anchor.Transparency = 1
		anchor.CFrame = CFrame.new(pos)
		anchor.Parent = workspace.Terrain
		gui.Adornee = anchor
		gui.Parent = game:GetService("CoreGui")
		local hl = Instance.new("Highlight")
		hl.Name = "DesyncLeakHL"
		hl.FillColor = Color3.fromRGB(255, 60, 60)
		hl.OutlineColor = Color3.fromRGB(255, 120, 120)
		hl.FillTransparency = 0.6
		hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		hl.Adornee = anchor
		hl.Parent = anchor
		ghostState.by[plr] = { gui = gui, anchor = anchor, at = pos, t = os.clock() }
	end

	local function ghost_clear(plr)
		local entry = ghostState.by[plr]
		if entry then
			pcall(function() if entry.gui then entry.gui:Destroy() end end)
			pcall(function() if entry.anchor then entry.anchor:Destroy() end end)
		end
		ghostState.by[plr] = nil
	end

	-- Listen to GunFired to detect real position leaks
	task.spawn(function()
		local cs = RepStorage:WaitForChild("ClientServices", 30)
		cs = cs and cs:WaitForChild("WeaponService", 30)
		cs = cs and cs:WaitForChild("GunFired", 30)
		if not cs then return end
		local c = cs.OnClientEvent:Connect(function(rootPart, arg1, arg2)
			if not DS.ghost or not DS.on then return end
			if typeof(rootPart) ~= "Instance" then return end
			local shotPos = typeof(arg1) == "CFrame" and arg1.Position or arg1
			if typeof(shotPos) ~= "Vector3" or ghost_isBad(shotPos) then return end
			-- find shooter player from rootPart ancestry
			local parent = rootPart
			local shooter
			for _ = 1, 6 do
				if not parent then break end
				shooter = Players:GetPlayerFromCharacter(parent)
				if shooter then break end
				parent = parent.Parent
			end
			if not shooter or shooter == lp then return end
			local shooterHRP = parent and parent:FindFirstChild("HumanoidRootPart")
			if shooterHRP and not ghost_isBad(shooterHRP.Position) then return end -- not desyncing
			-- compute leaked real position (adjusted for shooter offset)
			local leakPos = shotPos - Vector3.new(0, 1.25, 0)
			if typeof(arg2) == "Vector3" then
				local dir = Vector3.new(arg2.X - shotPos.X, 0, arg2.Z - shotPos.Z)
				if dir.Magnitude > 0.1 then
					dir = dir.Unit
					leakPos = leakPos - dir * 3.45 - Vector3.new(-dir.Z, 0, dir.X) * 1.4
				end
			end
			ghostState.leak[shooter] = { p = leakPos, t = os.clock(), ch = parent }
			ghost_makeTag(shooter, leakPos, 0)
		end)
		desync_conns[#desync_conns + 1] = c
	end)

	-- Heartbeat: maintain ghost tags, GC stale entries
	local ghostHB = RunSvc.Heartbeat:Connect(function()
		if not DS.ghost then return end
		local now = os.clock()
		-- update tag seconds / expire old leaks
		for plr, entry in pairs(ghostState.by) do
			if not plr.Parent then
				ghost_clear(plr)
			else
				local leak = ghostState.leak[plr]
				if leak and now - leak.t > ghostState.keep then
					ghost_clear(plr)
					ghostState.leak[plr] = nil
				elseif leak and entry.gui then
					local secs = math.floor(now - leak.t)
					local tl = entry.gui:FindFirstChildOfClass("TextLabel")
					if tl then
						tl.Text = plr.Name .. " DESYNC" .. (secs >= 1 and " " .. secs .. "s" or "")
					end
				end
			end
		end
		-- GC last/leak for leaving players
		if now - (ghostState.gcAt or 0) > 1 then
			ghostState.gcAt = now
			for plr in pairs(ghostState.last) do
				if not plr.Parent then
					ghostState.last[plr] = nil
					ghostState.leak[plr] = nil
				end
			end
		end
	end)
	desync_conns[#desync_conns + 1] = ghostHB

	-- Cleanup on player removing
	local prConn = Players.PlayerRemoving:Connect(function(plr) ghost_clear(plr) end)
	desync_conns[#desync_conns + 1] = prConn

	-- ===== UI (Combat tab) =====
	pcall(function() tbl43.combat:Section({ Title = "Standalone Desync" }) end)

	tbl43.combat:Toggle({
		Title = "Standalone Desync",
		Flag = "Toggle_StandaloneDesync",
		Desc = "Independent velocity/MoveDirection spoof (not tied to Anti-Aim mode). Can combine with Anti-Aim Side Profile.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			DS.on = v
			if v then desync_startLoops() else desync_stopLoops() end
		end,
	})

	tbl43.combat:Dropdown({
		Title = "Desync Direction",
		Flag = "Dropdown_Desync_Dir",
		Desc = "Spoof direction for standalone desync.",
		Multi = false,
		Value = "Random",
		Values = { "Random", "Spin", "Jitter", "Sky", "Underground" },
		Callback = function(v) if v then DS.dir = v end end,
	})

	tbl43.combat:Slider({
		Title = "Desync Power",
		Flag = "Slider_Desync_Power",
		Desc = "Strength of the velocity spoof (1-10).",
		Step = 1, Min = 1, Max = 10, Value = 5,
		Callback = function(v) DS.power = v end,
	})

	tbl43.combat:Toggle({
		Title = "Spoof Velocity",
		Flag = "Toggle_Desync_Vel",
		Desc = "Spoof AssemblyLinearVelocity (main desync).",
		Type = "Toggle",
		Value = true,
		Callback = function(v) DS.vel = v end,
	})

	tbl43.combat:Toggle({
		Title = "Spoof Move Direction",
		Flag = "Toggle_Desync_MD",
		Desc = "Spoof Humanoid MoveDirection.",
		Type = "Toggle",
		Value = true,
		Callback = function(v) DS.md = v end,
	})

	tbl43.combat:Toggle({
		Title = "Smart Pause",
		Flag = "Toggle_Desync_Smart",
		Desc = "Pause desync while holding a tool (gun/knife) so Silent Aim works.",
		Type = "Toggle",
		Value = true,
		Callback = function(v) DS.smart = v end,
	})

	tbl43.combat:Toggle({
		Title = "Ghost Leak Detection",
		Flag = "Toggle_Desync_Ghost",
		Desc = "Show red tag at position where a desyncing player's real location leaked via GunFired.",
		Type = "Toggle",
		Value = true,
		Callback = function(v)
			DS.ghost = v
			if not v then
				for plr in pairs(ghostState.by) do ghost_clear(plr) end
			end
		end,
	})
end

--[[ ===== MERGED FROM SOURCE: Anti Idle (Anti AFK) =====
	Ported from Pulse source constructors.createAntiIdle (native_id 51, source line 68662).
	Prevents the game from kicking you for being AFK / idle.
	Source logic: on LocalPlayer.Idled event, if enabled, call VirtualUser:CaptureController()
	+ VirtualUser:ClickButton2() to simulate player activity.
	Added: Heartbeat fallback timer (every 60s) as backup for executors where Idled
	does not fire reliably. All locals prefixed antiIdle_.
]]
do
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer
	local RunSvc = game:GetService("RunService")
	local VirtualUser = game:GetService("VirtualUser")

	local antiIdle = {
		on = false,
		lastActivity = 0,
		idleConn = nil,
		heartbeatConn = nil,
	}

	local function antiIdle_poke()
		pcall(function()
			VirtualUser:CaptureController()
			VirtualUser:ClickButton2(Vector2.new())
		end)
		antiIdle.lastActivity = os.clock()
	end

	local function antiIdle_start()
		if antiIdle.idleConn then return end
		-- Primary: respond to the Idled event (same as source)
		antiIdle.idleConn = lp.Idled:Connect(function()
			if antiIdle.on then
				antiIdle_poke()
			end
		end)
		-- Fallback: periodic poke in case Idled doesn't fire
		antiIdle.interval = 60
		antiIdle.heartbeatConn = RunSvc.Heartbeat:Connect(function()
			if not antiIdle.on then return end
			if os.clock() - antiIdle.lastActivity > (antiIdle.interval or 60) then
				antiIdle_poke()
			end
		end)
	end

	local function antiIdle_stop()
		if antiIdle.idleConn then
			pcall(function() antiIdle.idleConn:Disconnect() end)
			antiIdle.idleConn = nil
		end
		if antiIdle.heartbeatConn then
			pcall(function() antiIdle.heartbeatConn:Disconnect() end)
			antiIdle.heartbeatConn = nil
		end
	end

	-- Start connections immediately (they no-op when toggle is off)
	antiIdle_start()

	-- ===== UI (Settings tab — matches source placement) =====
	pcall(function() tbl43.settings:Section({ Title = "Anti Idle" }) end)

	tbl43.settings:Toggle({
		Title = "Anti Idle",
		Flag = "Toggle_AntiIdle",
		Desc = "Prevents AFK kick by simulating activity (VirtualUser). Source: createAntiIdle.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			antiIdle.on = v
			if v then
				antiIdle.lastActivity = os.clock()
				antiIdle_poke()
			end
		end,
	})

	tbl43.settings:Slider({
		Title = "Poke Interval",
		Flag = "Slider_AntiIdle_Interval",
		Desc = "Fallback poke interval in seconds (backup for Idled event).",
		Step = 5, Min = 15, Max = 180, Value = 60,
		Callback = function(v)
			-- stored via closure; heartbeat reads antiIdle.interval
			antiIdle.interval = tonumber(v) or 60
		end,
	})
end

--[[ ===== MERGED FROM SOURCE: SkyFX (Sky Effects) =====
	Ported from Pulse source uiPage:Sub("SkyFX") (source line 35489-37695).
	Self-contained sky particle system: stars, meteors, net.
	Base only had a "PulseSkyFX" Folder reference inside another feature (line 23689)
	— no actual SkyFX toggle/effects. This adds a working subset: Stars, Meteors,
	Net (node network), with all original texture asset IDs. Runes/Dust/Comets
	omitted to keep port manageable — limitation noted in report.
	All locals prefixed skyfx_. State table: SKYFX (no collision with AA/DS/antiIdle).
]]
do
	local RunSvc = game:GetService("RunService")
	local Lighting = game:GetService("Lighting")
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer

	local skyfx_TX = {
		dot = "rbxassetid://16512006463",
		soft = "rbxassetid://1075864321",
		spark = "rbxassetid://14590086212",
		sharp = "rbxassetid://17391818367",
		bright = "rbxassetid://16515551397",
		runes = "rbxassetid://11910560348",
		glyphs = "rbxassetid://10713705343",
		const1 = "rbxassetid://14101033134",
		const2 = "rbxassetid://14101036795",
		beam = "rbxassetid://12781750620",
		rays = "rbxassetid://4553095322",
	}

	local SKYFX = {
		on = false,
		folder = nil,
		conn = nil,
		R = 180,
		t = 0,
		stars = { on = false, density = 60, size = 100, twinkle = 60, parts = {} },
		meteors = { on = false, rate = 45, length = 100, nextAt = 0, beams = {} },
		net = { on = false, nodes = 40, reach = 60, speed = 40, parts = {}, beams = {}, velocities = {} },
	}

	local skyfx_rng = Random.new(os.time())

	local function skyfx_makeStarPart()
		local p = Instance.new("Part")
		p.Name = "SkyFX_Star"
		p.Size = Vector3.new(1, 1, 1)
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.Transparency = 1
		local bg = Instance.new("BillboardGui")
		bg.Name = "StarGui"
		bg.Size = UDim2.new(0, 8, 0, 8)
		bg.AlwaysOnTop = false
		bg.LightInfluence = 0
		local img = Instance.new("ImageLabel")
		img.Size = UDim2.new(1, 0, 1, 0)
		img.BackgroundTransparency = 1
		img.Image = skyfx_TX.dot
		img.ImageColor3 = Color3.fromRGB(232, 240, 255)
		img.Parent = bg
		bg.Parent = p
		return p, img
	end

	local function skyfx_placeInSphere(radius)
		local theta = skyfx_rng:NextNumber(0, math.pi * 2)
		local phi = math.acos(skyfx_rng:NextNumber(-1, 1))
		return Vector3.new(
			math.sin(phi) * math.cos(theta) * radius,
			math.cos(phi) * radius * 0.6,
			math.sin(phi) * math.sin(theta) * radius
		)
	end

	local function skyfx_ensureFolder()
		if SKYFX.folder and SKYFX.folder.Parent then return SKYFX.folder end
		local f = Instance.new("Folder")
		f.Name = "SkyFX_PulsePort"
		f.Parent = workspace
		SKYFX.folder = f
		return f
	end

	local function skyfx_clearStars()
		for _, p in ipairs(SKYFX.stars.parts) do
			pcall(function() p:Destroy() end)
		end
		SKYFX.stars.parts = {}
	end

	local function skyfx_buildStars()
		skyfx_clearStars()
		local folder = skyfx_ensureFolder()
		local cam = workspace.CurrentCamera
		local origin = cam and cam.CFrame.Position or Vector3.new(0, 50, 0)
		local count = math.floor(SKYFX.stars.density * 1.5)
		for i = 1, count do
			local p, img = skyfx_makeStarPart()
			local offset = skyfx_placeInSphere(SKYFX.R)
			p.Position = origin + offset
			p:SetAttribute("seed", skyfx_rng:NextNumber(0, math.pi * 2))
			p:SetAttribute("baseSize", 6 + skyfx_rng:NextNumber(0, 8))
			img.ImageTransparency = skyfx_rng:NextNumber(0, 0.6)
			p.Parent = folder
			SKYFX.stars.parts[#SKYFX.stars.parts + 1] = p
		end
	end

	local function skyfx_spawnMeteor()
		local folder = skyfx_ensureFolder()
		local cam = workspace.CurrentCamera
		if not cam then return end
		local origin = cam.CFrame.Position
		local startPos = origin + skyfx_placeInSphere(SKYFX.R * 0.8)
		local dir = Vector3.new(
			skyfx_rng:NextNumber(-1, 1),
			skyfx_rng:NextNumber(-0.8, -0.2),
			skyfx_rng:NextNumber(-1, 1)
		).Unit
		local a0 = Instance.new("Attachment")
		local a1 = Instance.new("Attachment")
		local beam = Instance.new("Beam")
		beam.Name = "SkyFX_Meteor"
		beam.Texture = skyfx_TX.beam
		beam.TextureMode = Enum.TextureMode.Wrap
		beam.TextureSpeed = 2
		beam.Width0 = 0.8
		beam.Width1 = 0.1
		beam.FaceCamera = true
		beam.Color = ColorSequence.new(Color3.fromRGB(190, 225, 255))
		beam.LightEmission = 1
		beam.Transparency = NumberSequence.new(0.3)
		local holder = Instance.new("Part")
		holder.Name = "SkyFX_MeteorHolder"
		holder.Anchored = true
		holder.CanCollide = false
		holder.CanQuery = false
		holder.CanTouch = false
		holder.Transparency = 1
		holder.Position = startPos
		a0.Parent = holder
		a1.Parent = holder
		beam.Attachment0 = a0
		beam.Attachment1 = a1
		beam.Parent = holder
		holder.Parent = folder
		SKYFX.meteors.beams[#SKYFX.meteors.beams + 1] = {
			holder = holder, a0 = a0, a1 = a1, beam = beam,
			pos = startPos, dir = dir, speed = 120 + skyfx_rng:NextNumber(0, 80),
			life = 0, maxLife = 1.5,
		}
	end

	local function skyfx_clearMeteors()
		for _, m in ipairs(SKYFX.meteors.beams) do
			pcall(function() m.holder:Destroy() end)
		end
		SKYFX.meteors.beams = {}
	end

	local function skyfx_clearNet()
		for _, p in ipairs(SKYFX.net.parts) do pcall(function() p:Destroy() end) end
		for _, b in ipairs(SKYFX.net.beams) do pcall(function() b:Destroy() end) end
		SKYFX.net.parts = {}
		SKYFX.net.beams = {}
		SKYFX.net.velocities = {}
	end

	local function skyfx_buildNet()
		skyfx_clearNet()
		local folder = skyfx_ensureFolder()
		local cam = workspace.CurrentCamera
		local origin = cam and cam.CFrame.Position or Vector3.new(0, 50, 0)
		for i = 1, SKYFX.net.nodes do
			local p = Instance.new("Part")
			p.Name = "SkyFX_NetNode"
			p.Size = Vector3.new(0.5, 0.5, 0.5)
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Transparency = 1
			p.Position = origin + skyfx_placeInSphere(SKYFX.R * 0.6)
			p.Parent = folder
			SKYFX.net.parts[#SKYFX.net.parts + 1] = p
			SKYFX.net.velocities[#SKYFX.net.velocities + 1] = Vector3.new(
				skyfx_rng:NextNumber(-1, 1), skyfx_rng:NextNumber(-0.3, 0.3), skyfx_rng:NextNumber(-1, 1)
			).Unit * (SKYFX.net.speed * 0.01)
		end
	end

	local function skyfx_destroyAll()
		skyfx_clearStars()
		skyfx_clearMeteors()
		skyfx_clearNet()
		if SKYFX.folder then pcall(function() SKYFX.folder:Destroy() end) end
		SKYFX.folder = nil
	end

	local function skyfx_step(dt)
		SKYFX.t = SKYFX.t + dt
		local cam = workspace.CurrentCamera
		if not cam then return end
		local origin = cam.CFrame.Position

		if SKYFX.stars.on then
			for _, p in ipairs(SKYFX.stars.parts) do
				if p.Parent then
					local bg = p:FindFirstChild("StarGui")
					local img = bg and bg:FindFirstChildOfClass("ImageLabel")
					if img then
						local seed = p:GetAttribute("seed") or 0
						local tw = 0.5 + 0.5 * math.sin(SKYFX.t * (2 + SKYFX.stars.twinkle * 0.05) + seed)
						img.ImageTransparency = 0.7 - tw * 0.6
						local baseSize = p:GetAttribute("baseSize") or 4
						bg.Size = UDim2.new(0, baseSize * (0.7 + tw * 0.6), 0, baseSize * (0.7 + tw * 0.6))
					end
					local target = origin + (p.Position - origin).Unit * SKYFX.R
					p.Position = p.Position:Lerp(target, 0.01)
				end
			end
		end

		if SKYFX.meteors.on then
			if SKYFX.t > SKYFX.meteors.nextAt then
				SKYFX.meteors.nextAt = SKYFX.t + (100 / SKYFX.meteors.rate) * skyfx_rng:NextNumber(0.5, 1.5)
				skyfx_spawnMeteor()
			end
			local alive = {}
			for _, m in ipairs(SKYFX.meteors.beams) do
				m.life = m.life + dt
				if m.life > m.maxLife then
					pcall(function() m.holder:Destroy() end)
				else
					m.pos = m.pos + m.dir * m.speed * dt
					m.holder.Position = m.pos
					m.a0.Position = Vector3.new(0, 0, 0)
					m.a1.Position = -m.dir * (SKYFX.meteors.length * 0.15)
					m.beam.Transparency = NumberSequence.new(m.life / m.maxLife * 0.8)
					alive[#alive + 1] = m
				end
			end
			SKYFX.meteors.beams = alive
		end

		if SKYFX.net.on then
			for i, p in ipairs(SKYFX.net.parts) do
				if p.Parent then
					local v = SKYFX.net.velocities[i]
					if v then
						p.Position = p.Position + v
						if (p.Position - origin).Magnitude > SKYFX.R then
							p.Position = origin + skyfx_placeInSphere(SKYFX.R * 0.5)
						end
					end
				end
			end
			for _, b in ipairs(SKYFX.net.beams) do pcall(function() b:Destroy() end) end
			SKYFX.net.beams = {}
			if SKYFX.t % 0.1 < dt then
				for i = 1, #SKYFX.net.parts do
					for j = i + 1, #SKYFX.net.parts do
						local pi, pj = SKYFX.net.parts[i], SKYFX.net.parts[j]
						if pi and pj and pi.Parent and pj.Parent then
							local dist = (pi.Position - pj.Position).Magnitude
							if dist < SKYFX.net.reach then
								local a0 = Instance.new("Attachment")
								local a1 = Instance.new("Attachment")
								a0.Parent = pi
								a1.Parent = pj
								local beam = Instance.new("Beam")
								beam.Name = "SkyFX_NetBeam"
								beam.Texture = skyfx_TX.beam
								beam.Width0 = 0.15
								beam.Width1 = 0.15
								beam.FaceCamera = true
								beam.Color = ColorSequence.new(Color3.fromRGB(150, 205, 255))
								beam.Transparency = NumberSequence.new(0.6 + (dist / SKYFX.net.reach) * 0.3)
								beam.LightEmission = 0.8
								beam.Attachment0 = a0
								beam.Attachment1 = a1
								beam.Parent = pi
								SKYFX.net.beams[#SKYFX.net.beams + 1] = beam
							end
						end
					end
				end
			end
		end
	end

	local function skyfx_start()
		if SKYFX.conn then return end
		SKYFX.conn = RunSvc.RenderStepped:Connect(function(dt)
			if not SKYFX.on then return end
			pcall(skyfx_step, dt)
		end)
	end

	local function skyfx_stop()
		if SKYFX.conn then pcall(function() SKYFX.conn:Disconnect() end) end
		SKYFX.conn = nil
		skyfx_destroyAll()
	end

	pcall(function() tbl43.visuals:Section({ Title = "SkyFX (Pulse)" }) end)

	tbl43.visuals:Toggle({
		Title = "SkyFX Master",
		Flag = "Toggle_SkyFX",
		Desc = "Pulse sky effects: stars, meteors, net. Creates SkyFX folder in Workspace.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			SKYFX.on = v
			if v then
				skyfx_ensureFolder()
				skyfx_start()
				if not (SKYFX.stars.on or SKYFX.meteors.on or SKYFX.net.on) then
					SKYFX.stars.on = true
				end
				if SKYFX.stars.on then skyfx_buildStars() end
			else
				skyfx_stop()
			end
		end,
	})

	tbl43.visuals:Toggle({
		Title = "Stars",
		Flag = "Toggle_SkyFX_Stars",
		Desc = "Twinkling stars in the sky.",
		Type = "Toggle",
		Value = true,
		Callback = function(v)
			SKYFX.stars.on = v
			if v and SKYFX.on then skyfx_buildStars() else skyfx_clearStars() end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Star Density",
		Flag = "Slider_SkyFX_Stars_Density",
		Desc = "Number of stars.",
		Step = 10, Min = 20, Max = 200, Value = 60,
		Callback = function(v)
			SKYFX.stars.density = tonumber(v) or 60
			if SKYFX.stars.on and SKYFX.on then skyfx_buildStars() end
		end,
	})

	tbl43.visuals:Toggle({
		Title = "Meteors",
		Flag = "Toggle_SkyFX_Meteors",
		Desc = "Shooting stars across the sky.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			SKYFX.meteors.on = v
			if not v then skyfx_clearMeteors() end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Meteor Rate",
		Flag = "Slider_SkyFX_Meteors_Rate",
		Desc = "How often meteors spawn.",
		Step = 5, Min = 10, Max = 100, Value = 45,
		Callback = function(v) SKYFX.meteors.rate = tonumber(v) or 45 end,
	})

	tbl43.visuals:Toggle({
		Title = "Net (Node Network)",
		Flag = "Toggle_SkyFX_Net",
		Desc = "Connected node network floating in the sky.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			SKYFX.net.on = v
			if v and SKYFX.on then skyfx_buildNet() else skyfx_clearNet() end
		end,
	})

	tbl43.visuals:Slider({
		Title = "Net Nodes",
		Flag = "Slider_SkyFX_Net_Nodes",
		Desc = "Number of net nodes.",
		Step = 5, Min = 10, Max = 100, Value = 40,
		Callback = function(v)
			SKYFX.net.nodes = tonumber(v) or 40
			if SKYFX.net.on and SKYFX.on then skyfx_buildNet() end
		end,
	})
end

--[[ ===== MERGED FROM SOURCE: Weapon Skins (Pulse Wskins) — PARTIAL PORT =====
	Source: uiPage:Sub("WSkins") (source line 15837), uses getgenv().__pulseWeaponSkins
	and __pulseSkins (source lines 1376, 16551).
	LIMITATION (disclosed honestly): The full Pulse weapon skin system is deeply
	tied to the Nova UI catalog (search, rarity filter, "load more" pagination) and
	loads its skin database externally. Base already has a working Visual Skin Changer
	(tbl43.skins, _G.__MM2Viz, local-only). This port exposes the Pulse globals
	(__pulseWeaponSkins / __pulseSkins) for cross-script compatibility and adds a
	basic toggle that applies a small set of known knife/gun texture IDs to tool
	handles. The full rarity catalog is NOT included — needs external data.
	All locals prefixed wskin_. State table: WSKIN.
]]
do
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer
	local RunSvc = game:GetService("RunService")

	local wskin_KNOWN = {
		knife = {
			{ name = "Default", tex = nil },
			{ name = "Chroma Blue", tex = "rbxassetid://112614436" },
			{ name = "Gold", tex = "rbxassetid://265654512" },
			{ name = "Void", tex = "rbxassetid://15724452084" },
		},
		gun = {
			{ name = "Default", tex = nil },
			{ name = "Gold", tex = "rbxassetid://265654512" },
			{ name = "Laser", tex = "rbxassetid://953281928" },
		},
	}

	local WSKIN = {
		on = false,
		knifeSkin = 1,
		gunSkin = 1,
		conn = nil,
		original = {},
	}

	getgenv().__pulseWeaponSkins = WSKIN
	getgenv().__pulseSkins = { enabled = false, knife = nil, gun = nil }

	local function wskin_getToolHandle(tool)
		if not tool then return nil end
		local handle = tool:FindFirstChild("Handle")
		if handle then return handle end
		for _, c in ipairs(tool:GetChildren()) do
			if c:IsA("Part") or c:IsA("MeshPart") then return c end
		end
		return nil
	end

	local function wskin_applyToTool(tool, skinTable, skinIdx)
		if not tool then return end
		local handle = wskin_getToolHandle(tool)
		if not handle then return end
		local skin = skinTable[skinIdx]
		if not skin then return end
		local key = tool:GetFullName()
		if not WSKIN.original[key] then
			local sm = handle:IsA("MeshPart") and handle or handle:FindFirstChildOfClass("SpecialMesh")
			WSKIN.original[key] = {
				textureId = sm and sm.TextureID or nil,
				color = handle.Color,
				material = handle.Material,
			}
		end
		if skin.tex then
			local sm = handle:FindFirstChildOfClass("SpecialMesh")
			if sm then
				sm.TextureID = skin.tex
			elseif handle:IsA("MeshPart") then
				handle.TextureID = skin.tex
			end
			handle.Material = Enum.Material.SmoothPlastic
		else
			local orig = WSKIN.original[key]
			if orig then
				local sm = handle:FindFirstChildOfClass("SpecialMesh")
				if sm and orig.textureId then sm.TextureID = orig.textureId end
				handle.Color = orig.color
				handle.Material = orig.material
			end
		end
	end

	local function wskin_applyAll()
		if not WSKIN.on then return end
		local char = lp.Character
		local bp = lp:FindFirstChildOfClass("Backpack")
		local containers = { char, bp }
		for _, cont in ipairs(containers) do
			if cont then
				for _, tool in ipairs(cont:GetChildren()) do
					if tool:IsA("Tool") then
						local lname = tool.Name:lower()
						if lname:find("knife") then
							wskin_applyToTool(tool, wskin_KNOWN.knife, WSKIN.knifeSkin)
						elseif lname:find("gun") then
							wskin_applyToTool(tool, wskin_KNOWN.gun, WSKIN.gunSkin)
						end
					end
				end
			end
		end
	end

	local function wskin_restoreAll()
		for key, orig in pairs(WSKIN.original) do
			pcall(function()
				local tool = game
				for seg in key:gmatch("[^%.]+") do
					tool = tool and tool:FindFirstChild(seg)
				end
				if tool then
					local handle = wskin_getToolHandle(tool)
					if handle then
						local sm = handle:FindFirstChildOfClass("SpecialMesh")
						if sm and orig.textureId then sm.TextureID = orig.textureId end
						handle.Color = orig.color
						handle.Material = orig.material
					end
				end
			end)
		end
		WSKIN.original = {}
	end

	local function wskin_start()
		if WSKIN.conn then return end
		WSKIN.conn = RunSvc.Heartbeat:Connect(function()
			if not WSKIN.on then return end
			pcall(wskin_applyAll)
		end)
	end

	local function wskin_stop()
		if WSKIN.conn then pcall(function() WSKIN.conn:Disconnect() end) end
		WSKIN.conn = nil
		wskin_restoreAll()
	end

	pcall(function() tbl43.skins:Section({ Title = "Pulse Weapon Skins (Partial)" }) end)

	tbl43.skins:Toggle({
		Title = "Pulse Weapon Skins",
		Flag = "Toggle_PulseWeaponSkins",
		Desc = "Exposes __pulseWeaponSkins/__pulseSkins globals + applies small built-in skin set. Full catalog needs external Pulse data.",
		Type = "Toggle",
		Value = false,
		Callback = function(v)
			WSKIN.on = v
			getgenv().__pulseSkins.enabled = v
			if v then wskin_start() else wskin_stop() end
		end,
	})

	local knifeNames = {}
	for _, s in ipairs(wskin_KNOWN.knife) do knifeNames[#knifeNames + 1] = s.name end
	tbl43.skins:Dropdown({
		Title = "Knife Skin",
		Flag = "Dropdown_PulseWSkin_Knife",
		Desc = "Choose knife skin (small built-in set).",
		Multi = false,
		Value = "Default",
		Values = knifeNames,
		Callback = function(v)
			for i, s in ipairs(wskin_KNOWN.knife) do
				if s.name == v then WSKIN.knifeSkin = i end
			end
			getgenv().__pulseSkins.knife = v
		end,
	})

	local gunNames = {}
	for _, s in ipairs(wskin_KNOWN.gun) do gunNames[#gunNames + 1] = s.name end
	tbl43.skins:Dropdown({
		Title = "Gun Skin",
		Flag = "Dropdown_PulseWSkin_Gun",
		Desc = "Choose gun skin (small built-in set).",
		Multi = false,
		Value = "Default",
		Values = gunNames,
		Callback = function(v)
			for i, s in ipairs(wskin_KNOWN.gun) do
				if s.name == v then WSKIN.gunSkin = i end
			end
			getgenv().__pulseSkins.gun = v
		end,
	})
end

task.spawn(function()
	if not list2.config then
		list2.notifyReady = true
		list2.sfxReady = true

		list2.notifyNow({
			Title = "Config",
			Content = "ConfigManager unavailable - settings will not persist.",
			Duration = 5,
			Icon = "x",
		})

		return
	end

	pcall(function()
		return list2.config:Load()
	end)

	list2.applyHud()
	task.wait(1)
	list2.cfgSnapshot = list2.snapshot()
	list2.notifyReady = true
	list2.sfxReady = true

	while _G.FVLV2 == obj3 do
		task.wait(2)

		if not list2.cfgWiped then
			local flag205 = list2.snapshot()

			if flag205 ~= "" and flag205 ~= list2.cfgSnapshot then
				list2.saveNow()
			end
		end
	end
end)


list2.notifyNow({
	Title = "F$VL",
	Content = "Loaded. G toggles the window.",
	Duration = 10,
	Icon = "rbxassetid://103877612231883",
})